//! V09-S34 / S35 / S36 (V09-0070): the new functions of tool expansion
//! groups 1, 2 and 3, each against the oracle its catalog rubric names
//! (closed forms, brute-force counts, invariants). One section per tool.

use plumspirit_engine::history::{History, Operation};
use plumspirit_engine::model::Division;
use plumspirit_engine::model::TrackId;
use plumspirit_engine::model::tempo::{TempoMap, TempoValue};
use plumspirit_engine::model::{
    Bpm, NoteAttrs, NoteOffKind, NoteRecord, PlumDocument, Subchannel, SubchannelId,
};
use plumspirit_engine::transform::param::{Curve, ParamValue};
use plumspirit_engine::transform::registry::BuildCtx;
use plumspirit_engine::transform::run::{collect_for, collect_with};
use plumspirit_engine::transform::source::SourceTrack;
use plumspirit_engine::transform::{
    Ctx, Limits, Output, ParamSet, Source, TEMPO_RATE, TNote, TrackScope, run_kernel, tool,
};
use plumspirit_engine::view::grid::MeterMap;
use std::sync::Arc;

fn rec(start: u64, dur: u64, pitch: u8) -> NoteRecord {
    NoteRecord {
        start_tick: start,
        duration_ticks: dur,
        attrs: NoteAttrs::new(pitch, 100, 0, 0, NoteOffKind::NoteOff).unwrap(),
        sub: SubchannelId(0),
        group: 0,
    }
}

/// Runs tool `id` on `notes` (all selected, one track, 960 PPQN) with `set`
/// in `ctx` (`Ctx::simple(960)`: 120 BPM, 4/4, snap 1/16 when `None`).
fn run_in(
    id: &str,
    notes: &[(u64, u64, u8)],
    set: &[(&str, ParamValue)],
    ctx: Option<Ctx>,
) -> Vec<TNote> {
    let mut d = PlumDocument::new_project("s34".into(), Bpm::DEFAULT, 960);
    let mut v: Vec<NoteRecord> = notes.iter().map(|&(s, l, p)| rec(s, l, p)).collect();
    v.sort_by_key(|r| r.start_tick);
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&v, true)
        .unwrap();
    let t = tool(id).unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let src = collect_for(t, &d, &sc, 1 << 24).unwrap();
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)
        .unwrap()
        .notes
}

fn run(id: &str, notes: &[(u64, u64, u8)], set: &[(&str, ParamValue)]) -> Vec<TNote> {
    run_in(id, notes, set, None)
}

fn on(id: &'static str) -> (&'static str, ParamValue) {
    (id, ParamValue::Bool(true))
}
fn int(k: &'static str, v: i64) -> (&'static str, ParamValue) {
    (k, ParamValue::Int(v))
}
fn fl(k: &'static str, v: f64) -> (&'static str, ParamValue) {
    (k, ParamValue::Float(v))
}
fn ch(k: &'static str, v: u32) -> (&'static str, ParamValue) {
    (k, ParamValue::Choice(v))
}
fn list(k: &'static str, v: &[i64]) -> (&'static str, ParamValue) {
    (k, ParamValue::List(v.to_vec()))
}
fn curve(k: &'static str, c: Curve) -> (&'static str, ParamValue) {
    (k, ParamValue::Curve(c))
}

/// (start, pitch, length) in time order.
fn spd(v: &[TNote]) -> Vec<(u64, u8, u64)> {
    let mut o: Vec<(u64, u8, u64)> = v.iter().map(|n| (n.start, n.pitch, n.dur)).collect();
    o.sort_unstable();
    o
}

fn pitches(v: &[TNote]) -> Vec<u8> {
    let mut o: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.pitch)).collect();
    o.sort_unstable();
    o.into_iter().map(|x| x.1).collect()
}

/// C E G, two beats (eight 1/16 steps at the default settings).
const CEG: &[(u64, u64, u8)] = &[(0, 1920, 60), (0, 1920, 64), (0, 1920, 67)];

// ================================================================ Arpeggiator

#[test]
fn arp_euclidean_gate_plays_bjorklund_steps_and_handles_rests() {
    // E(3,8) = x..x..x. over the eight steps.
    let base = [on("n01"), int("n01.steps", 8), int("n01.pulses", 3)];
    let silence = run("arpeggiate", CEG, &base);
    assert_eq!(
        spd(&silence),
        vec![(0, 60, 216), (720, 60, 216), (1440, 60, 216)]
    );
    // Hold: each played note sustains over the rests after it.
    let mut hold = base.to_vec();
    hold.push(ch("n01.rest", 1));
    assert_eq!(
        spd(&run("arpeggiate", CEG, &hold)),
        vec![(0, 60, 720), (720, 60, 720), (1440, 60, 480)]
    );
    // Tie: a played note starts at the first rest before it.
    let mut tie = base.to_vec();
    tie.push(ch("n01.rest", 2));
    assert_eq!(
        spd(&run("arpeggiate", CEG, &tie)),
        vec![(0, 60, 216), (240, 60, 696), (960, 60, 696)]
    );
    // Rotation 1: ..x..x.x.
    let mut rot = base.to_vec();
    rot.push(int("n01.rot", 1));
    let starts: Vec<u64> = spd(&run("arpeggiate", CEG, &rot))
        .iter()
        .map(|x| x.0)
        .collect();
    assert_eq!(starts, vec![480, 1200, 1680]);
    // Run on across chords: E(1,4) restarts per chord (A: steps 0, 4; B:
    // step 0) or counts on (A: 0, 4; B: its third step = count 8).
    let two = &[(0, 1440, 60), (1440, 960, 62)];
    let e14 = [on("n01"), int("n01.steps", 4), int("n01.pulses", 1)];
    let starts = |v: Vec<TNote>| -> Vec<u64> { spd(&v).iter().map(|x| x.0).collect() };
    assert_eq!(starts(run("arpeggiate", two, &e14)), vec![0, 960, 1440]);
    let mut across = e14.to_vec();
    across.push(ch("n01.phase", 1));
    assert_eq!(starts(run("arpeggiate", two, &across)), vec![0, 960, 1920]);
    // Pulses 0: nothing plays.
    assert!(run("arpeggiate", CEG, &[on("n01"), int("n01.pulses", 0)]).is_empty());
}

#[test]
fn arp_ratchets_split_steps_into_decaying_repeats() {
    let set = [
        on("n02"),
        list("n02.repeats", &[2]),
        fl("n02.decay", 50.0),
        fl("n02.gate", 100.0),
    ];
    let v = run("arpeggiate", CEG, &set);
    assert_eq!(v.len(), 16);
    let mut by_start: Vec<(u64, u8, u64, u8)> =
        v.iter().map(|n| (n.start, n.pitch, n.dur, n.vel)).collect();
    by_start.sort_unstable();
    for (k, &(s, _, d, vel)) in by_start.iter().enumerate() {
        assert_eq!((s, d), (k as u64 * 120, 120));
        assert_eq!(vel, if k % 2 == 0 { 100 } else { 50 });
    }
    // A cycled list: 1, 3 repeats.
    let v = run(
        "arpeggiate",
        CEG,
        &[
            on("n02"),
            list("n02.repeats", &[1, 3]),
            fl("n02.gate", 100.0),
        ],
    );
    assert_eq!(v.len(), 4 + 4 * 3);
    // Burst amount 0 across the selection: plain steps.
    let v = run(
        "arpeggiate",
        CEG,
        &[
            on("n02"),
            list("n02.repeats", &[4]),
            curve("n02.amount", Curve::flat(0.0)),
        ],
    );
    assert_eq!(spd(&v), spd(&run("arpeggiate", CEG, &[])));
}

#[test]
fn arp_real_time_rate_keeps_its_speed_through_tempo_changes() {
    // 4 Hz at 120 BPM = 480 ticks.
    let v = run(
        "arpeggiate",
        CEG,
        &[on("n03"), fl("n03.from", 4.0), fl("n03.to", 4.0)],
    );
    assert_eq!(
        spd(&v),
        vec![
            (0, 60, 432),
            (480, 64, 432),
            (960, 67, 432),
            (1440, 60, 432)
        ]
    );
    // 250 ms per step is the same.
    let ms = run(
        "arpeggiate",
        CEG,
        &[
            on("n03"),
            ch("n03.unit", 1),
            fl("n03.from", 250.0),
            fl("n03.to", 250.0),
        ],
    );
    assert_eq!(spd(&ms), spd(&v));
    // 60 BPM from tick 960: 250 ms = 240 ticks there.
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[
            (0, TempoValue::Micros(500_000)),
            (960, TempoValue::Micros(1_000_000)),
        ],
    )));
    let v = run_in(
        "arpeggiate",
        CEG,
        &[on("n03"), fl("n03.from", 4.0), fl("n03.to", 4.0)],
        Some(ctx),
    );
    let starts: Vec<u64> = spd(&v).iter().map(|x| x.0).collect();
    assert_eq!(starts, vec![0, 480, 960, 1200, 1440, 1680]);
    // A glide from 2 to 8 Hz: the steps get closer.
    let v = run(
        "arpeggiate",
        &[(0, 3840, 60)],
        &[
            on("n03"),
            fl("n03.from", 2.0),
            fl("n03.to", 8.0),
            curve("n03.curve", Curve::line(0.0, 1.0)),
        ],
    );
    let starts: Vec<u64> = spd(&v).iter().map(|x| x.0).collect();
    assert!(
        starts.windows(3).all(|w| w[2] - w[1] <= w[1] - w[0]),
        "{starts:?}"
    );
}

/// A five-note ladder: C D E G A.
const PENTA: &[(u64, u64, u8)] = &[
    (0, 1920, 60),
    (0, 1920, 62),
    (0, 1920, 64),
    (0, 1920, 67),
    (0, 1920, 69),
];

#[test]
fn arp_stride_walks_the_ladder_by_its_stride() {
    let v = run("arpeggiate", PENTA, &[on("n04"), int("n04.stride", 2)]);
    assert_eq!(pitches(&v), vec![60, 64, 69, 62, 67, 60, 64, 69]); // 0 2 4 1 3 0 2 4
    // Bounce by 1 over C E G = up-down.
    let v = run(
        "arpeggiate",
        CEG,
        &[on("n04"), int("n04.stride", 1), ch("n04.ends", 1)],
    );
    assert_eq!(pitches(&v), vec![60, 64, 67, 64, 60, 64, 67, 64]);
    // Start index 1, stride 1 (wrap) shifts the pattern.
    let v = run(
        "arpeggiate",
        CEG,
        &[on("n04"), int("n04.stride", 1), int("n04.start", 1)],
    );
    assert_eq!(pitches(&v), vec![64, 67, 60, 64, 67, 60, 64, 67]);
    // The stride grows by one each pattern cycle (5 steps): 1 × 5, then 2.
    let v = run(
        "arpeggiate",
        PENTA,
        &[on("n04"), int("n04.stride", 1), int("n04.change", 1)],
    );
    // Positions 0 1 2 3 4 | 5 7 9 over a cycle of 5: 0 1 2 3 4 0 2 4.
    assert_eq!(pitches(&v), vec![60, 62, 64, 67, 69, 60, 64, 69]);
}

#[test]
fn arp_passing_tones_fill_the_ladder_from_the_lattice() {
    // Chromatic, up to 12: a chromatic run from C to G.
    let v = run(
        "arpeggiate",
        CEG,
        &[on("n05"), ch("n05.fill", 2), int("n05.most", 12)],
    );
    assert_eq!(pitches(&v), vec![60, 61, 62, 63, 64, 65, 66, 67]);
    // C major, up to 2 per gap: C D E F G.
    let v = run("arpeggiate", CEG, &[on("n05"), int("n05.most", 2)]);
    assert_eq!(&pitches(&v)[..5], &[60, 62, 64, 65, 67]);
    // Fill notes at 80 % velocity; chord tones keep theirs.
    let vel: Vec<(u8, u8)> = v.iter().map(|n| (n.pitch, n.vel)).collect();
    assert!(vel.contains(&(62, 80)) && vel.contains(&(60, 100)));
    // Evenly chosen: 2 of the 6 semitones between C and G (positions 2 and
    // 4 of 6: D, E).
    let v = run(
        "arpeggiate",
        &[(0, 1920, 60), (0, 1920, 67)],
        &[on("n05"), ch("n05.fill", 2), int("n05.most", 2)],
    );
    assert_eq!(&pitches(&v)[..4], &[60, 62, 64, 67]);
    // Most 0: no change.
    let v = run("arpeggiate", CEG, &[on("n05"), int("n05.most", 0)]);
    assert_eq!(spd(&v), spd(&run("arpeggiate", CEG, &[])));
}

#[test]
fn arp_glide_walks_the_last_steps_toward_the_next_chord() {
    // C E G (8 steps), then F A C: the last three steps glide from G to F.
    let notes = &[
        (0, 1920, 60),
        (0, 1920, 64),
        (0, 1920, 67),
        (1920, 960, 65),
        (1920, 960, 69),
        (1920, 960, 72),
    ];
    let v = run("arpeggiate", notes, &[on("n06"), int("n06.steps", 3)]);
    let p = pitches(&v);
    assert_eq!(&p[..5], &[60, 64, 67, 60, 64]);
    assert_eq!(&p[5..8], &[66, 66, 65]); // 67 + round(−2 · ¼, ½, ¾)
    assert_eq!(&p[8..], &[65, 69, 72, 65]); // the last chord has no glide
    // Nearest chord tone: on F A C pitch classes, G → F in one lattice step.
    let v = run(
        "arpeggiate",
        notes,
        &[on("n06"), int("n06.steps", 3), ch("n06.path", 2)],
    );
    assert!(
        pitches(&v)[5..8]
            .iter()
            .all(|p| [65, 67, 69, 72].contains(p))
    );
}

#[test]
fn arp_pedal_anchors_hold_or_restrike_under_the_arpeggio() {
    let v = run("arpeggiate", CEG, &[on("n07")]);
    let pedal: Vec<(u64, u8, u64, u8)> = v
        .iter()
        .filter(|n| n.pitch == 48)
        .map(|n| (n.start, n.pitch, n.dur, n.vel))
        .collect();
    assert_eq!(pedal, vec![(0, 48, 1920, 90)]);
    assert_eq!(v.len(), 9);
    let v = run(
        "arpeggiate",
        CEG,
        &[
            on("n07"),
            int("n07.every", 4),
            ch("n07.anchor", 2),
            int("n07.oct", 0),
        ],
    );
    let mut anchors: Vec<(u64, u8, u64)> = v
        .iter()
        .filter(|n| n.dur == 864)
        .map(|n| (n.start, n.pitch, n.dur))
        .collect();
    anchors.sort_unstable();
    assert_eq!(
        anchors,
        vec![(0, 60, 864), (0, 67, 864), (960, 60, 864), (960, 67, 864)]
    );
}

#[test]
fn arp_fit_cycles_divide_each_chord_into_whole_cycles() {
    // 2 cycles of 3 over 1,920 ticks: steps of 320.
    let v = run(
        "arpeggiate",
        CEG,
        &[on("n08"), fl("n08.cycles", 2.0), fl("gate", 100.0)],
    );
    assert_eq!(
        spd(&v).iter().map(|x| x.0).collect::<Vec<_>>(),
        vec![0, 320, 640, 960, 1280, 1600]
    );
    // Exact ticks over 1,000: ⌊k · 1000 / 3⌋.
    let v = run(
        "arpeggiate",
        &[(0, 1000, 60), (0, 1000, 64), (0, 1000, 67)],
        &[on("n08"), fl("n08.cycles", 1.0)],
    );
    assert_eq!(
        spd(&v).iter().map(|x| x.0).collect::<Vec<_>>(),
        vec![0, 333, 666]
    );
    // Nearest grid (1/16 = 240): 320 → 240.
    let v = run(
        "arpeggiate",
        CEG,
        &[on("n08"), fl("n08.cycles", 2.0), ch("n08.round", 1)],
    );
    assert_eq!(v.len(), 8);
    // At least one cycle: a shortest step of 1,000 leaves one cycle (640).
    let v = run(
        "arpeggiate",
        CEG,
        &[
            on("n08"),
            fl("n08.cycles", 2.0),
            ch("n08.round", 2),
            int("n08.min", 1000),
        ],
    );
    assert_eq!(
        spd(&v).iter().map(|x| x.0).collect::<Vec<_>>(),
        vec![0, 640, 1280]
    );
    // Exact ticks never go below the shortest step.
    let v = run(
        "arpeggiate",
        CEG,
        &[on("n08"), fl("n08.cycles", 64.0), int("n08.min", 480)],
    );
    assert_eq!(v.len(), 4);
}

#[test]
fn arp_fit_drives_the_chord_in_every_rounding_mode_even_with_a_real_time_rate() {
    // n08 decides layer 0's clock whenever it is on — its uniform steps
    // (nearest grid step, or the shortest step) as well as exact ticks —
    // so n03's real time (here 400 Hz) never adds steps the cycles do not
    // ask for (S34 gate: 737,437 notes against a preflight of 498,658, and a
    // whole-range note that ran until the output cap).
    let rate = [on("n03"), fl("n03.from", 400.0), fl("n03.to", 400.0)];
    for fit in [
        vec![on("n08"), fl("n08.cycles", 2.0), ch("n08.round", 1)],
        vec![on("n08"), fl("n08.cycles", 64.0), int("n08.min", 480)],
        vec![on("n08"), fl("n08.cycles", 2.0)],
        vec![
            on("n08"),
            fl("n08.cycles", 2.0),
            ch("n08.round", 2),
            int("n08.min", 1000),
        ],
    ] {
        let alone = run("arpeggiate", CEG, &fit);
        let mut both = fit.clone();
        both.extend(rate.iter().cloned());
        assert_eq!(spd(&run("arpeggiate", CEG, &both)), spd(&alone));
    }
    // Without n08 the rate still clocks the chord: 1,920 ticks at 120 BPM
    // = 1 s = 400 steps.
    assert_eq!(run("arpeggiate", CEG, &rate).len(), 400);
}

#[test]
fn arp_markov_walk_follows_its_weights_and_memory() {
    // Always up (bounce): the up-down line.
    let up = run(
        "arpeggiate",
        CEG,
        &[on("n09"), list("n09.w", &[0, 100, 0, 0])],
    );
    assert_eq!(pitches(&up), vec![60, 64, 67, 64, 60, 64, 67, 64]);
    // Always stay.
    let stay = run(
        "arpeggiate",
        CEG,
        &[on("n09"), list("n09.w", &[100, 0, 0, 0])],
    );
    assert!(pitches(&stay).iter().all(|&p| p == 60));
    // Memory 1 with stay / up only: the moves alternate.
    for seed in 1..6 {
        let v = run(
            "arpeggiate",
            PENTA,
            &[
                on("n09"),
                list("n09.w", &[50, 50, 0, 0]),
                int("n09.mem", 1),
                ("seed", ParamValue::Int(seed)),
            ],
        );
        let p = pitches(&v);
        let moved: Vec<bool> = p.windows(2).map(|w| w[0] != w[1]).collect();
        assert!(moved.windows(2).all(|m| m[0] != m[1]), "{p:?}");
    }
    // The same seed gives the same walk.
    let a = run("arpeggiate", PENTA, &[on("n09")]);
    let b = run("arpeggiate", PENTA, &[on("n09")]);
    assert_eq!(spd(&a), spd(&b));
}

#[test]
fn arp_latch_runs_on_through_short_rests_and_fades() {
    // A: 0–960 (4 steps), B at 1,440: the 480-tick rest is latched.
    let notes = &[(0, 960, 60), (1440, 960, 62)];
    let v = run("arpeggiate", notes, &[on("n10")]);
    let mut a: Vec<(u64, u8, u8)> = v.iter().map(|n| (n.start, n.pitch, n.vel)).collect();
    a.sort_unstable();
    assert_eq!(
        &a[..6],
        &[
            (0, 60, 100),
            (240, 60, 100),
            (480, 60, 100),
            (720, 60, 100),
            (960, 60, 100),
            (1200, 60, 65), // fade 1 → 0.3 at ½
        ]
    );
    // Rests not shorter than the threshold stay silent.
    let v = run("arpeggiate", notes, &[on("n10"), int("n10.below", 480)]);
    assert_eq!(v.len(), 8);
    // Bar end: to 3,840 (bar 1's end) with the next chord at 4,800.
    let far = &[(0, 960, 60), (4800, 240, 62)];
    let v = run(
        "arpeggiate",
        far,
        &[on("n10"), ch("n10.until", 1), int("n10.below", 5000)],
    );
    assert_eq!(v.iter().filter(|n| n.pitch == 60).count(), 16);
    // Longest fill 480 after the chord.
    let v = run(
        "arpeggiate",
        far,
        &[
            on("n10"),
            ch("n10.until", 2),
            int("n10.fill", 480),
            int("n10.below", 5000),
        ],
    );
    assert_eq!(v.iter().filter(|n| n.pitch == 60).count(), 6);
    // The last chord never latches.
    let v = run("arpeggiate", &[(0, 960, 60)], &[on("n10")]);
    assert_eq!(v.len(), 4);
}

/// Trailing counts of `starts` (ticks at 120 BPM / 960 PPQN) in windows of
/// `ms`: the largest.
fn worst_window(v: &[TNote], ms: u64) -> usize {
    let mut us: Vec<u64> = v.iter().map(|n| n.start * 500_000 / 960).collect();
    us.sort_unstable();
    us.iter()
        .map(|&t| us.iter().filter(|&&s| s <= t && s + ms * 1000 > t).count())
        .max()
        .unwrap_or(0)
}

#[test]
fn arp_nps_ceiling_holds_in_every_window() {
    // 10-tick steps over one second: 192 notes.
    let dense = [ch("step", 11), int("step.ticks", 10)];
    let all = run("arpeggiate", CEG, &dense);
    assert_eq!(all.len(), 192);
    for how in 0..3 {
        let mut set = dense.to_vec();
        set.extend([on("n11"), int("n11.nps", 100), ch("n11.how", how)]);
        let v = run("arpeggiate", CEG, &set);
        assert!(
            worst_window(&v, 1000) <= 100,
            "strategy {how}: {}",
            worst_window(&v, 1000)
        );
        match how {
            // Lengthen: the first 100 kept, the last one held to the end.
            0 => {
                assert_eq!(v.len(), 100);
                assert_eq!(
                    v.iter().map(|n| n.end()).max(),
                    all.iter().map(|n| n.end()).max()
                );
            }
            // Off-steps go first: every on-step stays (96 ≤ 100).
            1 => {
                assert_eq!(v.len(), 96);
                assert!(v.iter().all(|n| (n.start / 10) % 2 == 0));
            }
            _ => assert_eq!(v.len(), 100),
        }
    }
    // A ceiling above the density changes nothing.
    let mut set = dense.to_vec();
    set.extend([on("n11"), int("n11.nps", 500)]);
    assert_eq!(spd(&run("arpeggiate", CEG, &set)), spd(&all));
}

#[test]
fn arp_new_functions_off_leave_v08_results_unchanged() {
    // Every new switch present but off = the v0.8 tool (the preset fixtures
    // and the v0.7 FL suites check the rest).
    let base = run("arpeggiate", PENTA, &[]);
    let mut set = Vec::new();
    for k in [
        "n01", "n02", "n03", "n04", "n05", "n06", "n07", "n08", "n09", "n10", "n11",
    ] {
        set.push((k, ParamValue::Bool(false)));
    }
    assert_eq!(spd(&run("arpeggiate", PENTA, &set)), spd(&base));
}

// ================================================================ Articulate

/// A note for hand-built sources (track slot 0, velocity `vel`).
fn tn(start: u64, dur: u64, pitch: u8, vel: u8) -> TNote {
    TNote {
        start,
        dur,
        pitch,
        vel,
        rel: 64,
        ..Default::default()
    }
}

/// Runs tool `id` on a hand-built source: `notes` selected, `context` the
/// track's unselected notes, `subs` its subchannel table (ids).
fn run_src(
    id: &str,
    notes: Vec<TNote>,
    context: Vec<TNote>,
    subs: &[u32],
    set: &[(&str, ParamValue)],
    ctx: Option<Ctx>,
) -> Vec<TNote> {
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: subs.iter().map(|&s| (s, 0)).collect(),
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(notes, vec![track]);
    let mut c = context;
    c.sort_by_key(|n| (n.start, n.pitch));
    src.context = Arc::new(c);
    let t = tool(id).unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)
        .unwrap()
        .notes
}

/// Lengths in (start, pitch) order.
fn lens(v: &[TNote]) -> Vec<u64> {
    spd(v).iter().map(|x| x.2).collect()
}

fn flag(k: &'static str, v: bool) -> (&'static str, ParamValue) {
    (k, ParamValue::Bool(v))
}

/// One second at 120 BPM / 960 PPQN = 1920 ticks; 1 ms = 1.92 ticks.
const STEPS3: &[(u64, u64, u8)] = &[(0, 100, 60), (960, 100, 62), (1920, 100, 64)];

#[test]
fn art_real_time_gap_leaves_milliseconds_before_the_next_onset_at_any_tempo() {
    // Legato (960) minus 125 ms = 240 ticks at 120 BPM; the last note has
    // no next onset and keeps its length.
    let gap = [on("n01"), fl("n01.gap", 125.0), fl("n01.short", 0.0)];
    assert_eq!(lens(&run("articulate", STEPS3, &gap)), vec![720, 720, 100]);
    // A 0 ms gap changes nothing.
    let zero = [on("n01"), fl("n01.gap", 0.0), fl("n01.short", 0.0)];
    assert_eq!(lens(&run("articulate", STEPS3, &zero)), vec![960, 960, 100]);
    // The shortest length wins over the gap: 480 ms leaves 38 ticks, 20 ms
    // = 38.4 ticks rounds up to 39.
    let short = [on("n01"), fl("n01.gap", 480.0), fl("n01.short", 20.0)];
    assert_eq!(lens(&run("articulate", STEPS3, &short)), vec![39, 39, 100]);
    // At 60 BPM from tick 960, 125 ms is 120 ticks there: the same gap in
    // real time, other ticks.
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[
            (0, TempoValue::Micros(500_000)),
            (960, TempoValue::Micros(1_000_000)),
        ],
    )));
    assert_eq!(
        lens(&run_in("articulate", STEPS3, &gap, Some(ctx))),
        vec![720, 840, 100]
    );
    // Measured to the next onset of the same key: C at 0 and 960 with a D
    // between — the C keeps its legato 480 (the gap to the next C is far).
    let keys = &[(0, 100, 60), (480, 100, 62), (960, 100, 60)];
    assert_eq!(lens(&run("articulate", keys, &gap)), vec![240, 240, 100]);
    let mut same = gap.to_vec();
    same.push(ch("n01.to", 1));
    assert_eq!(lens(&run("articulate", keys, &same)), vec![480, 480, 100]);
}

#[test]
fn art_metric_gates_give_each_grid_position_its_gate() {
    // Quarter grid in 4/4, gates 100 / 50 / 75 / 25 %; legato bases 960.
    let beats: Vec<(u64, u64, u8)> = (0..6).map(|k| (k * 960, 100, 60)).collect();
    let set = [
        on("n02"),
        ch("n02.grid", 2),
        list("n02.gates", &[100, 50, 75, 25]),
    ];
    // The bar-2 downbeat starts the list again; the last note (no next
    // onset) is measured against its own 100 ticks.
    assert_eq!(
        lens(&run("articulate", &beats, &set)),
        vec![960, 480, 720, 240, 960, 50]
    );
    // A shorter list cycles over the positions.
    let two = [on("n02"), ch("n02.grid", 2), list("n02.gates", &[100, 50])];
    assert_eq!(
        lens(&run("articulate", &beats, &two)),
        vec![960, 480, 960, 480, 960, 50]
    );
    // Between positions: tick 720 is nearest to position 2 (50 %), or
    // interpolated 3/4 of the way from 100 % to 50 % = 62.5 %, of its
    // distance 240 to the next onset.
    let off = &[(0, 10, 60), (720, 10, 60), (960, 10, 60)];
    assert_eq!(lens(&run("articulate", off, &set)), vec![720, 120, 5]);
    let mut lerp = set.to_vec();
    lerp.push(ch("n02.between", 1));
    assert_eq!(lens(&run("articulate", off, &lerp)), vec![720, 150, 5]);
    // Bars follow the time signature: 3/4 for one bar, then 4/4 — the
    // fourth beat is bar 2's downbeat (100 %), the list restarts there.
    let mut ctx = Ctx::simple(960);
    ctx.meter = MeterMap::new(Division::from_raw(960), &[(0, 3, 2), (2880, 4, 2)]);
    assert_eq!(
        lens(&run_in("articulate", &beats, &set, Some(ctx))),
        vec![960, 480, 720, 960, 480, 75]
    );
}

#[test]
fn art_phrase_end_lengthens_last_notes_up_to_the_next_phrase() {
    // Two phrases split by a long rest; lengths from the notes' own (Use
    // lengths), 400 each.
    let notes = &[
        (0, 400, 60),
        (480, 400, 62),
        (960, 400, 64),
        (3840, 400, 60),
        (4320, 400, 62),
    ];
    let set = [
        flag("use_lengths", true),
        on("n03"),
        int("n03.rest", 480),
        fl("n03.last", 200.0),
        int("n03.approach", 2),
    ];
    // Last notes × 2; approach onsets × (1 + 1·x), x = 2/3 and 1/3 along
    // the default line.
    assert_eq!(
        lens(&run("articulate", notes, &set)),
        vec![533, 667, 800, 667, 800]
    );
    // × 8 reaches the next phrase (3840 − 960 = 2880) and stops there; the
    // song's last note has no next phrase.
    let mut big = set.to_vec();
    big.extend([fl("n03.last", 800.0), int("n03.approach", 0)]);
    assert_eq!(
        lens(&run("articulate", notes, &big)),
        vec![400, 400, 2880, 400, 3200]
    );
    // Bar lines split too: the notes of bar 1 (0 … 3360) and bar 2; half
    // length on each bar's last note.
    let run_on: Vec<(u64, u64, u8)> = (0..10).map(|k| (k * 480, 480, 60)).collect();
    let bars = [
        flag("use_lengths", true),
        on("n03"),
        ch("n03.split", 1),
        fl("n03.last", 50.0),
        int("n03.approach", 0),
    ];
    let v = lens(&run("articulate", &run_on, &bars));
    assert_eq!(v, vec![480, 480, 480, 480, 480, 480, 480, 240, 480, 240]);
    // Without bar lines it is one phrase.
    let mut rests = bars.to_vec();
    rests.push(ch("n03.split", 0));
    let v = lens(&run("articulate", &run_on, &rests));
    assert_eq!(v, vec![480, 480, 480, 480, 480, 480, 480, 480, 480, 240]);
}

#[test]
fn art_density_gate_maps_notes_per_window_to_a_gate() {
    // Window 960: counts 1, 1, 1, 2, 3, 4, 5, 1; sparse at 1 (100 %), dense
    // at 4 (50 %), linear between.
    let notes = &[
        (0, 60, 60),
        (1920, 60, 60),
        (3840, 60, 60),
        (3900, 60, 60),
        (3960, 60, 60),
        (4020, 60, 60),
        (4080, 60, 60),
        (6000, 60, 60),
    ];
    let set = [
        flag("use_lengths", true),
        on("n04"),
        int("n04.window", 960),
        fl("n04.sparse", 100.0),
        fl("n04.dense", 50.0),
        int("n04.sparse_at", 1),
        int("n04.dense_at", 4),
    ];
    assert_eq!(
        lens(&run("articulate", notes, &set)),
        vec![60, 60, 60, 50, 40, 30, 30, 60]
    );
    // The reverse mapping lengthens the dense part.
    let mut rev = set.to_vec();
    rev.extend([fl("n04.sparse", 50.0), fl("n04.dense", 150.0)]);
    assert_eq!(
        lens(&run("articulate", notes, &rev)),
        vec![30, 30, 30, 50, 70, 90, 90, 30]
    );
}

#[test]
fn art_interval_legato_connects_steps_and_shortens_leaps() {
    // Staccato (45 %); steps of ≤ 2 semitones legato, leaps × (1 − 0.7·x),
    // x = interval / 12.
    let notes = &[
        (0, 100, 60),
        (480, 100, 62),
        (960, 100, 69),
        (1440, 100, 81),
        (1920, 100, 60),
        (2400, 100, 61),
    ];
    let set = [ch("style", 2), on("n05")];
    assert_eq!(
        lens(&run("articulate", notes, &set)),
        vec![480, 128, 65, 65, 480, 45]
    );
    // The next onset as a chord: its lowest note (a 10-semitone leap) or the
    // nearest pitch (one semitone: legato).
    let chord = &[
        (0, 100, 60),
        (480, 100, 50),
        (480, 100, 61),
        (480, 100, 72),
        (960, 100, 60),
    ];
    assert_eq!(lens(&run("articulate", chord, &set))[0], 90);
    let mut near = set.to_vec();
    near.push(ch("n05.next", 1));
    assert_eq!(lens(&run("articulate", chord, &near))[0], 480);
}

#[test]
fn art_tempo_gate_follows_the_tempo_map() {
    // 60 BPM until tick 1920, then 240 BPM: 100 % and 50 %.
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[
            (0, TempoValue::Micros(1_000_000)),
            (1920, TempoValue::Micros(250_000)),
        ],
    )));
    let notes = &[
        (0, 100, 60),
        (960, 100, 60),
        (1920, 100, 60),
        (2880, 100, 60),
        (3840, 100, 60),
    ];
    let set = [
        on("n06"),
        fl("n06.slow", 60.0),
        fl("n06.fast", 240.0),
        fl("n06.at_slow", 100.0),
        fl("n06.at_fast", 50.0),
    ];
    assert_eq!(
        lens(&run_in("articulate", notes, &set, Some(ctx))),
        vec![960, 960, 480, 480, 50]
    );
    // Without a tempo map: 120 BPM, a third of the way: 83.3 %.
    assert_eq!(
        lens(&run("articulate", notes, &set)),
        vec![800, 800, 800, 800, 83]
    );
}

#[test]
fn art_ratio_palette_snaps_gates_to_the_allowed_set() {
    // Custom 60 %: ratio 0.6 → 0.5 (nearest / down) or 1.0 (up); strength
    // 50 % goes half way.
    let set = [ch("style", 3), fl("multiply", 60.0), on("n07")];
    assert_eq!(lens(&run("articulate", STEPS3, &set)), vec![480, 480, 50]);
    let mut up = set.to_vec();
    up.push(ch("n07.round", 2));
    assert_eq!(lens(&run("articulate", STEPS3, &up)), vec![960, 960, 100]);
    let mut down = set.to_vec();
    down.extend([ch("n07.round", 1), list("n07.ratios", &[55, 100])]);
    assert_eq!(lens(&run("articulate", STEPS3, &down)), vec![528, 528, 55]);
    // Below every allowed ratio, Down takes the smallest one.
    down.push(list("n07.ratios", &[70, 100]));
    assert_eq!(lens(&run("articulate", STEPS3, &down)), vec![672, 672, 70]);
    let mut half = set.to_vec();
    half.push(fl("n07.strength", 50.0));
    assert_eq!(lens(&run("articulate", STEPS3, &half)), vec![528, 528, 55]);
    // A tie (0.75 between 0.5 and 1.0) takes the lower.
    let tie = [ch("style", 3), fl("multiply", 75.0), on("n07")];
    assert_eq!(lens(&run("articulate", STEPS3, &tie)), vec![480, 480, 50]);
}

#[test]
fn art_voice_rank_gates_each_voice_of_a_chord() {
    // C E G then a single note: bass 150 %, inner 60 %, top 100 % of 960.
    let notes = &[(0, 100, 60), (0, 100, 64), (0, 100, 67), (960, 100, 72)];
    let set = [
        on("n08"),
        list("n08.ranks", &[150, 60]),
        fl("n08.top", 100.0),
    ];
    assert_eq!(
        lens(&run("articulate", notes, &set)),
        vec![1440, 576, 960, 100]
    );
    // Counted from the top: the voice under the top is rank 0 (150 %).
    let mut top = set.to_vec();
    top.extend([ch("n08.from", 1), fl("n08.top", 50.0)]);
    assert_eq!(
        lens(&run("articulate", notes, &top)),
        vec![576, 1440, 480, 100]
    );
    // A rolled chord is one chord only within the tolerance.
    let rolled = &[(0, 100, 60), (5, 100, 64), (10, 100, 67)];
    let mut tol = set.to_vec();
    tol.extend([flag("use_lengths", true), int("n08.tol", 10)]);
    assert_eq!(lens(&run("articulate", rolled, &tol)), vec![150, 60, 100]);
    tol.push(int("n08.tol", 0));
    assert_eq!(lens(&run("articulate", rolled, &tol)), vec![100, 100, 100]);
}

#[test]
fn art_repetition_decay_shapes_repeated_keys_and_resets_after_rests() {
    // Four repeats, a rest of 1480, two more: × 0.9 per repeat.
    let notes = &[
        (0, 200, 60),
        (240, 200, 60),
        (480, 200, 60),
        (720, 200, 60),
        (2400, 200, 60),
        (2640, 200, 60),
    ];
    let set = [
        flag("use_lengths", true),
        on("n09"),
        fl("n09.change", -10.0),
        int("n09.reset", 480),
        fl("n09.floor", 1.0),
    ];
    assert_eq!(
        lens(&run("articulate", notes, &set)),
        vec![200, 180, 162, 146, 200, 180]
    );
    // The floor stops the decay; a long reset rest keeps one chain.
    let mut floor = set.to_vec();
    floor.extend([fl("n09.floor", 75.0), int("n09.reset", 2000)]);
    assert_eq!(
        lens(&run("articulate", notes, &floor)),
        vec![200, 180, 162, 150, 150, 150]
    );
    // Lengthening stops at the floor's reciprocal (50 % → 200 %).
    let mut grow = set.to_vec();
    grow.extend([fl("n09.change", 50.0), fl("n09.floor", 50.0)]);
    assert_eq!(
        lens(&run("articulate", notes, &grow)),
        vec![200, 300, 400, 400, 200, 300]
    );
    // Another key in between is its own chain.
    let mixed = &[(0, 200, 60), (240, 200, 62), (480, 200, 60), (720, 200, 62)];
    assert_eq!(
        lens(&run("articulate", mixed, &set)),
        vec![200, 200, 180, 180]
    );
    // Key and subchannel: subchannels 0 and 1 alternate on one key.
    let alt: Vec<TNote> = (0..4)
        .map(|k| TNote {
            sub: (k % 2) as u32,
            ..tn(k * 240, 200, 60, 100)
        })
        .collect();
    let v = run_src("articulate", alt.clone(), vec![], &[0, 1], &set, None);
    assert_eq!(lens(&v), vec![200, 180, 162, 146]);
    let mut by_sub = set.to_vec();
    by_sub.push(ch("n09.key", 2));
    let v = run_src("articulate", alt, vec![], &[0, 1], &by_sub, None);
    assert_eq!(lens(&v), vec![200, 200, 180, 180]);
}

#[test]
fn art_reference_match_copies_the_nearest_reference_gate() {
    // Reference (unselected): ratios 0.5, 0.25, 1.0 at 0, 960, 1920 (the
    // last onset at 2880 has no next onset and no ratio).
    let reference = vec![
        tn(0, 480, 48, 100),
        tn(960, 240, 48, 100),
        tn(1920, 960, 48, 100),
        tn(2880, 10, 48, 100),
    ];
    let targets = || {
        vec![
            tn(10, 10, 72, 100),
            tn(970, 10, 72, 100),
            tn(1930, 10, 72, 100),
            tn(2890, 10, 72, 100),
        ]
    };
    let set = [on("n10"), int("n10.window", 240)];
    let v = run_src("articulate", targets(), reference.clone(), &[0], &set, None);
    assert_eq!(lens(&v), vec![480, 240, 960, 10]);
    // Blend 50 % with the own legato ratio 1.0.
    let mut half = set.to_vec();
    half.push(fl("n10.blend", 50.0));
    let v = run_src(
        "articulate",
        targets(),
        reference.clone(),
        &[0],
        &half,
        None,
    );
    assert_eq!(lens(&v), vec![720, 600, 960, 10]);
    // Outside the window nothing matches.
    let mut narrow = set.to_vec();
    narrow.push(int("n10.window", 5));
    let v = run_src(
        "articulate",
        targets(),
        reference.clone(),
        &[0],
        &narrow,
        None,
    );
    assert_eq!(lens(&v), vec![960, 960, 960, 10]);
    // A subchannel as the reference (its place 2 in the track's list = id
    // 7): its notes stay, the others match it.
    let mut mixed: Vec<TNote> = reference.iter().map(|n| TNote { sub: 7, ..*n }).collect();
    mixed.extend(targets());
    let mut sub = set.to_vec();
    sub.extend([ch("n10.ref", 1), int("n10.num", 2)]);
    let v = run_src("articulate", mixed, vec![], &[0, 7], &sub, None);
    let got: Vec<(u64, u64)> = spd(&v).iter().map(|x| (x.0, x.2)).collect();
    // Legato among all selected notes: each onset 10 ticks after the
    // previous one; references keep it, targets take the matched ratio of
    // their distance to the next onset (950).
    assert_eq!(
        got,
        vec![
            (0, 10),
            (10, 475),
            (960, 10),
            (970, 238),
            (1920, 10),
            (1930, 950),
            (2880, 10),
            (2890, 10),
        ]
    );
}

#[test]
fn art_reference_match_reads_another_track() {
    // Track 1 = targets (selected), track 2 = reference (read by prepare).
    let mut d = PlumDocument::new_project("s34".into(), Bpm::DEFAULT, 960);
    d.add_track().unwrap();
    let t: Vec<NoteRecord> = [10u64, 970, 1930, 2890]
        .iter()
        .map(|&s| rec(s, 10, 72))
        .collect();
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&t, true)
        .unwrap();
    let r = vec![
        rec(0, 480, 48),
        rec(960, 240, 48),
        rec(1920, 960, 48),
        rec(2880, 10, 48),
    ];
    d.track_mut(1)
        .unwrap()
        .notes
        .insert_sorted_batch(&r, false)
        .unwrap();
    let def = tool("articulate").unwrap();
    let mut ps = ParamSet::defaults(&(def.spec)().params);
    for (k, v) in [
        on("n10"),
        ch("n10.ref", 2),
        int("n10.num", 2),
        int("n10.window", 240),
    ] {
        ps.set(k, v);
    }
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let src = collect_with(def, &d, &sc, &ps, 1 << 24).unwrap();
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = def.kernel(&ps, &b).unwrap();
    let v = run_kernel(
        k.as_ref(),
        &src,
        def.boundary(&ps),
        &Limits::default(),
        None,
    )
    .unwrap()
    .notes;
    assert_eq!(lens(&v), vec![480, 240, 960, 10]);
    // A track that does not exist is refused with a sentence.
    ps.set("n10.num", ParamValue::Int(9));
    let e = collect_with(def, &d, &sc, &ps, 1 << 24).unwrap_err();
    assert!(
        e.user_message().contains("Track 9 does not exist"),
        "{}",
        e.user_message()
    );
}

/// Poly at every tick that matters (each start) of `v`.
fn worst_poly(v: &[TNote]) -> usize {
    v.iter()
        .map(|n| {
            v.iter()
                .filter(|m| m.start <= n.start && n.start < m.end())
                .count()
        })
        .max()
        .unwrap_or(0)
}

#[test]
fn art_polyphony_ceiling_trims_ends_without_deleting_notes() {
    // Five held notes entering every 240 ticks; at most 2 sound.
    let held: Vec<(u64, u64, u8)> = (0..5).map(|k| (k * 240, 3840, 60 + k as u8)).collect();
    let set = [
        flag("use_lengths", true),
        on("n11"),
        int("n11.most", 2),
        ch("n11.first", 1),
    ];
    let v = run("articulate", &held, &set);
    assert_eq!(lens(&v), vec![480, 480, 480, 3840, 3840]);
    assert_eq!(worst_poly(&v), 2);
    // Quietest first: the quiet note goes even when it is the newest that
    // may be cut.
    let quiet = vec![
        tn(0, 3840, 60, 100),
        tn(240, 3840, 62, 20),
        tn(480, 3840, 64, 100),
    ];
    let mut q = set.to_vec();
    q.push(ch("n11.first", 2));
    let v = run_src("articulate", quiet, vec![], &[0], &q, None);
    assert_eq!(lens(&v), vec![3840, 240, 3840]);
    // A shortest length longer than any note has sounded leaves the stack.
    let mut s = set.to_vec();
    s.push(int("n11.short", 5000));
    assert_eq!(lens(&run("articulate", &held, &s)), vec![3840; 5]);
    // A dense random stack: no note removed, never longer, Poly ≤ 3 at
    // every onset where some sounding note was cuttable (all are after 30
    // ticks: the starts are 37 apart at least).
    let dense: Vec<(u64, u64, u8)> = (0..200)
        .map(|k| (k * 37, 100 + (k * 7919) % 2000, 40 + (k % 40) as u8))
        .collect();
    for first in 0..3 {
        let set = [
            flag("use_lengths", true),
            on("n11"),
            int("n11.most", 3),
            ch("n11.first", first),
        ];
        let v = run("articulate", &dense, &set);
        assert_eq!(v.len(), dense.len());
        assert!(worst_poly(&v) <= 3, "first {first}: {}", worst_poly(&v));
        let orig = spd(&run("articulate", &dense, &[flag("use_lengths", true)]));
        for (a, b) in spd(&v).iter().zip(&orig) {
            assert!(a.2 <= b.2 && a.2 > 0);
        }
    }
}

#[test]
fn art_new_functions_off_leave_v08_results_unchanged() {
    let notes = &[
        (0, 100, 60),
        (0, 100, 64),
        (480, 300, 67),
        (960, 50, 60),
        (1440, 900, 72),
        (3000, 100, 48),
    ];
    for style in 0..4 {
        let base = run("articulate", notes, &[ch("style", style)]);
        let mut set = vec![ch("style", style)];
        for k in [
            "n01", "n02", "n03", "n04", "n05", "n06", "n07", "n08", "n09", "n10", "n11",
        ] {
            set.push((k, ParamValue::Bool(false)));
        }
        assert_eq!(spd(&run("articulate", notes, &set)), spd(&base));
    }
}

// ================================================================ Chopper

/// (start, length) in time order (pitch ignored).
fn sl(v: &[TNote]) -> Vec<(u64, u64)> {
    spd(v).iter().map(|x| (x.0, x.2)).collect()
}

/// One note of two beats: eight 1/16 units (240 ticks) at the defaults.
const LONG: &[(u64, u64, u8)] = &[(0, 1920, 60)];

#[test]
fn chop_euclidean_rhythm_slices_at_bjorklund_onsets() {
    // E(3,8) = x..x..x. over eight units: onsets at units 0, 3, 6.
    let set = [on("n01"), int("n01.steps", 8), int("n01.pulses", 3)];
    assert_eq!(
        sl(&run("chop", LONG, &set)),
        vec![(0, 720), (720, 720), (1440, 480)]
    );
    // Rotation 1: ..x..x.x — onsets at units 2, 5, 7.
    let mut rot = set.to_vec();
    rot.push(int("n01.rot", 1));
    assert_eq!(
        sl(&run("chop", LONG, &rot)),
        vec![(0, 480), (480, 720), (1200, 480), (1680, 240)]
    );
    // Rotated per note: the second note of the track by one more step.
    let two = &[(0, 1920, 60), (1920, 1920, 60)];
    let mut per = set.to_vec();
    per.push(ch("n01.by", 1));
    let v = sl(&run("chop", two, &per));
    assert_eq!(
        v,
        vec![
            (0, 720),
            (720, 720),
            (1440, 480),
            (1920, 480),
            (2400, 720),
            (3120, 480),
            (3600, 240)
        ]
    );
    // Per semitone: pitch 61 is rotated one step further than pitch 60.
    let mut semi = set.to_vec();
    semi.push(ch("n01.by", 2));
    let a = sl(&run("chop", &[(0, 1920, 61)], &semi));
    let b = sl(&run(
        "chop",
        &[(0, 1920, 60)],
        &[
            on("n01"),
            int("n01.steps", 8),
            int("n01.pulses", 3),
            int("n01.rot", 61),
        ],
    ));
    assert_eq!(a, b);
}

#[test]
fn chop_real_time_rate_keeps_its_speed_through_tempo_changes() {
    // 4 Hz on one second at 120 BPM: four slices of 480; 250 ms the same.
    let hz = [on("n02"), fl("n02.from", 4.0), fl("n02.to", 4.0)];
    assert_eq!(
        sl(&run("chop", LONG, &hz)),
        vec![(0, 480), (480, 480), (960, 480), (1440, 480)]
    );
    let ms = [
        on("n02"),
        ch("n02.unit", 1),
        fl("n02.from", 250.0),
        fl("n02.to", 250.0),
    ];
    assert_eq!(sl(&run("chop", LONG, &ms)), sl(&run("chop", LONG, &hz)));
    // At 60 BPM the note lasts two seconds: eight slices of 240.
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[(0, TempoValue::Micros(1_000_000))],
    )));
    let v = sl(&run_in("chop", LONG, &hz, Some(ctx)));
    assert_eq!(v.len(), 8);
    assert!(v.iter().all(|x| x.1 == 240));
    // A glide from 2 to 8 Hz: every slice shorter than the one before.
    let glide = [on("n02"), fl("n02.from", 2.0), fl("n02.to", 8.0)];
    let v = sl(&run("chop", LONG, &glide));
    assert!(v.windows(2).all(|w| w[1].1 < w[0].1), "{v:?}");
    // Along the selection: the first of two far-apart notes at 2 Hz, the
    // last at 8 Hz.
    let far = &[(0, 1920, 60), (19200, 1920, 60)];
    let mut along = glide.to_vec();
    along.push(ch("n02.along", 1));
    let v = sl(&run("chop", far, &along));
    let first = v.iter().filter(|x| x.0 < 1920).count();
    let last = v.iter().filter(|x| x.0 >= 19200).count();
    assert_eq!((first, last), (3, 8), "{v:?}");
}

#[test]
fn chop_glissando_steps_the_slices_toward_the_interval() {
    let pitches = |v: &[TNote]| -> Vec<u8> { spd(v).iter().map(|x| x.1).collect() };
    // Eight slices, a fifth up chromatically: 0 … 7 semitones.
    let set = [on("n03"), int("n03.interval", 7)];
    assert_eq!(
        pitches(&run("chop", LONG, &set)),
        vec![60, 61, 62, 63, 64, 65, 66, 67]
    );
    // An octave in C major: the scale.
    let scale = [on("n03"), int("n03.interval", 12), ch("n03.path", 1)];
    assert_eq!(
        pitches(&run("chop", LONG, &scale)),
        vec![60, 62, 64, 65, 67, 69, 71, 72]
    );
    // Two octaves by octaves: 12 · round(2 · i / 7).
    let oct = [on("n03"), int("n03.interval", 24), ch("n03.path", 2)];
    assert_eq!(
        pitches(&run("chop", LONG, &oct)),
        vec![60, 60, 72, 72, 72, 72, 84, 84]
    );
    // Downwards, and the note count never changes.
    let down = [on("n03"), int("n03.interval", -3)];
    let v = run("chop", LONG, &down);
    assert_eq!(v.len(), 8);
    assert_eq!(pitches(&v), vec![60, 60, 59, 59, 58, 58, 57, 57]);
}

#[test]
fn chop_voice_hocket_hands_slices_from_voice_to_voice() {
    let ceg = &[(0, 960, 60), (0, 960, 64), (0, 960, 67)];
    let pairs = |v: &[TNote]| -> Vec<(u64, u8)> { spd(v).iter().map(|x| (x.0, x.1)).collect() };
    // One voice per slice, up: C E G C.
    let up = [on("n04")];
    assert_eq!(
        pairs(&run("chop", ceg, &up)),
        vec![(0, 60), (240, 64), (480, 67), (720, 60)]
    );
    // Down: G E C G.
    let down = [on("n04"), ch("n04.order", 1)];
    assert_eq!(
        pairs(&run("chop", ceg, &down)),
        vec![(0, 67), (240, 64), (480, 60), (720, 67)]
    );
    // Two voices: {C,E} {G,C} {E,G} {C,E}.
    let two = [on("n04"), int("n04.voices", 2)];
    assert_eq!(
        pairs(&run("chop", ceg, &two)),
        vec![
            (0, 60),
            (0, 64),
            (240, 60),
            (240, 67),
            (480, 64),
            (480, 67),
            (720, 60),
            (720, 64)
        ]
    );
    // Outside-in over C E G B: C B E G.
    let cegb = &[(0, 960, 60), (0, 960, 64), (0, 960, 67), (0, 960, 71)];
    let out = [on("n04"), ch("n04.order", 2)];
    assert_eq!(
        pairs(&run("chop", cegb, &out)),
        vec![(0, 60), (240, 71), (480, 64), (720, 67)]
    );
    // A listed order (bass, top, middle): C G E C.
    let listed = [on("n04"), ch("n04.order", 3), list("n04.list", &[0, 2, 1])];
    assert_eq!(
        pairs(&run("chop", ceg, &listed)),
        vec![(0, 60), (240, 67), (480, 64), (720, 60)]
    );
    // A single note is never thinned.
    assert_eq!(run("chop", LONG, &up).len(), 8);
}

/// Most starts in any trailing window of `ms` (120 BPM, 960 PPQN).
fn max_nps(v: &[TNote], ms: u64) -> usize {
    worst_window(v, ms)
}

#[test]
fn chop_target_nps_spreads_the_target_over_the_polyphony() {
    let set = [on("n05"), int("n05.nps", 100), int("n05.most", 1000)];
    // One note of a second: 100 slices.
    assert_eq!(run("chop", LONG, &set).len(), 100);
    // Four voices together share it: 25 each.
    let four: Vec<(u64, u64, u8)> = (0..4).map(|k| (0, 1920, 60 + k)).collect();
    let v = run("chop", &four, &set);
    assert_eq!(v.len(), 100);
    assert!(max_nps(&v, 1000) <= 100);
    // A sparse second then a dense one: about the target in each.
    let mut mixed: Vec<(u64, u64, u8)> = vec![(0, 1920, 48)];
    mixed.extend((0..4).map(|k| (1920, 1920, 60 + k)));
    let v = run("chop", &mixed, &set);
    let a = v.iter().filter(|n| n.start < 1920).count();
    let b = v.iter().filter(|n| n.start >= 1920).count();
    assert_eq!((a, b), (100, 100));
    // The most slices per note caps it.
    let mut cap = set.to_vec();
    cap.push(int("n05.most", 10));
    assert_eq!(run("chop", LONG, &cap).len(), 10);
}

#[test]
fn chop_velocity_bridge_ramps_into_the_next_note() {
    let by_start = |v: &[TNote]| -> Vec<(u64, u8)> {
        let mut o: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.vel)).collect();
        o.sort_unstable();
        o
    };
    let notes = vec![tn(0, 960, 60, 100), tn(960, 960, 60, 20)];
    let set = [on("n06")];
    let v = run_src("chop", notes.clone(), vec![], &[0], &set, None);
    assert_eq!(
        by_start(&v),
        vec![
            (0, 100),
            (240, 80),
            (480, 60),
            (720, 40),
            (960, 20),
            (1200, 20),
            (1440, 20),
            (1680, 20)
        ]
    );
    let mut half = set.to_vec();
    half.push(fl("n06.amount", 50.0));
    let v = run_src("chop", notes, vec![], &[0], &half, None);
    assert_eq!(
        &by_start(&v)[..4],
        &[(0, 100), (240, 90), (480, 80), (720, 70)]
    );
    // The next onset of the track (an E at 480) or the next C.
    let three = vec![
        tn(0, 960, 60, 100),
        tn(480, 100, 64, 50),
        tn(960, 960, 60, 20),
    ];
    let v = run_src("chop", three.clone(), vec![], &[0], &set, None);
    let c: Vec<(u64, u8)> = by_start(&v).into_iter().filter(|x| x.0 < 960).collect();
    assert_eq!(&c[..1], &[(0, 100)]);
    assert!(c.contains(&(240, 88)) && c.contains(&(720, 63)), "{c:?}");
    let mut key = set.to_vec();
    key.push(ch("n06.next", 1));
    let v = run_src("chop", three, vec![], &[0], &key, None);
    let c: Vec<(u64, u8)> = v
        .iter()
        .filter(|n| n.pitch == 60 && n.start < 960)
        .map(|n| (n.start, n.vel))
        .collect();
    let mut c = c;
    c.sort_unstable();
    assert_eq!(c, vec![(0, 100), (240, 80), (480, 60), (720, 40)]);
}

#[test]
fn chop_phase_spiral_moves_the_grid_per_step() {
    // 25 % of the unit per semitone from C: D (2 semitones) moves by 120.
    let set = [on("n07"), fl("n07.phase", 25.0)];
    assert_eq!(
        sl(&run("chop", &[(0, 960, 60)], &set)),
        vec![(0, 240), (240, 240), (480, 240), (720, 240)]
    );
    assert_eq!(
        sl(&run("chop", &[(0, 960, 62)], &set)),
        vec![(0, 120), (120, 240), (360, 240), (600, 240), (840, 120)]
    );
    // Gallop 1+1+2, one unit per two semitones: wrapped in the unit it is
    // no move; accumulated through the pattern it starts one unit in.
    let gallop = [ch("pattern", 2), on("n07"), fl("n07.phase", 50.0)];
    assert_eq!(
        sl(&run("chop", &[(0, 960, 62)], &gallop)),
        vec![(0, 240), (240, 240), (480, 480)]
    );
    let mut acc = gallop.to_vec();
    acc.push(ch("n07.mode", 1));
    assert_eq!(
        sl(&run("chop", &[(0, 960, 62)], &acc)),
        vec![(0, 240), (240, 480), (720, 240)]
    );
    // By chord rank: the chord's second voice by 25 % of a unit.
    let ceg = &[(0, 960, 60), (0, 960, 64), (0, 960, 67)];
    let rank = [on("n07"), fl("n07.phase", 25.0), ch("n07.by", 2)];
    let v = run("chop", ceg, &rank);
    let e: Vec<(u64, u64)> = spd(&v)
        .iter()
        .filter(|x| x.1 == 64)
        .map(|x| (x.0, x.2))
        .collect();
    assert_eq!(
        e,
        vec![(0, 180), (180, 240), (420, 240), (660, 240), (900, 60)]
    );
}

#[test]
fn chop_rest_fill_runs_into_short_rests_and_fades() {
    let notes = &[(0, 480, 60), (960, 480, 62)];
    let set = [on("n08"), int("n08.longest", 960), int("n08.below", 960)];
    let v = run("chop", notes, &set);
    let a: Vec<(u64, u64, u8)> = {
        let mut o: Vec<(u64, u64, u8)> = v
            .iter()
            .filter(|n| n.pitch == 60)
            .map(|n| (n.start, n.dur, n.vel))
            .collect();
        o.sort_unstable();
        o
    };
    // Two slices in the note, two in the rest fading 1.0 → 0.65.
    assert_eq!(
        a,
        vec![
            (0, 240, 100),
            (240, 240, 100),
            (480, 240, 100),
            (720, 240, 65)
        ]
    );
    assert_eq!(v.iter().filter(|n| n.pitch == 62).count(), 2);
    // The longest fill stops it; a rest not shorter than the threshold or
    // no next onset of the same key leaves it.
    let mut short = set.to_vec();
    short.push(int("n08.longest", 240));
    assert_eq!(run("chop", notes, &short).len(), 5);
    let mut wide = set.to_vec();
    wide.push(int("n08.below", 480));
    assert_eq!(run("chop", notes, &wide).len(), 4);
    let mut key = set.to_vec();
    key.push(ch("n08.next", 1));
    assert_eq!(run("chop", notes, &key).len(), 4);
}

#[test]
fn chop_metric_unit_map_divides_by_position() {
    // Quarter grid, factors 1 2 2 2: the downbeat note keeps 1/16, the
    // second beat's note halves it.
    let notes = &[(0, 960, 60), (960, 960, 62)];
    let set = [on("n09")];
    let v = run("chop", notes, &set);
    assert_eq!(v.iter().filter(|n| n.pitch == 60).count(), 4);
    assert_eq!(v.iter().filter(|n| n.pitch == 62).count(), 8);
    let mut mul = set.to_vec();
    mul.push(ch("n09.factor", 1));
    let v = run("chop", notes, &mul);
    assert_eq!(v.iter().filter(|n| n.pitch == 62).count(), 2);
}

#[test]
fn chop_onset_sync_cuts_at_reference_onsets() {
    // A held note and short notes at 960, 1500, 1520 (merged), 2880.
    let notes = &[
        (0, 3840, 48),
        (960, 100, 72),
        (1500, 100, 72),
        (1520, 100, 74),
        (2880, 100, 72),
    ];
    let set = [on("n10"), int("n10.merge", 30), int("n10.short", 1)];
    let v = run("chop", notes, &set);
    let held: Vec<(u64, u64)> = spd(&v)
        .iter()
        .filter(|x| x.1 == 48)
        .map(|x| (x.0, x.2))
        .collect();
    assert_eq!(held, vec![(0, 960), (960, 540), (1500, 1380), (2880, 960)]);
    // The note at 1500 holds the onset at 1520 (another selected note).
    let at1500: Vec<(u64, u64)> = spd(&v)
        .iter()
        .filter(|x| x.1 == 72 && (1500..1600).contains(&x.0))
        .map(|x| (x.0, x.2))
        .collect();
    assert_eq!(at1500, vec![(1500, 20), (1520, 80)]);
    assert_eq!(v.len(), 4 + 5);
    // The shortest slice drops cuts too close to the last one.
    let mut short = set.to_vec();
    short.push(int("n10.short", 600));
    let held: Vec<(u64, u64)> = spd(&run("chop", notes, &short))
        .iter()
        .filter(|x| x.1 == 48)
        .map(|x| (x.0, x.2))
        .collect();
    assert_eq!(held, vec![(0, 960), (960, 1920), (2880, 960)]);
}

#[test]
fn chop_onset_sync_reads_unselected_notes_and_other_tracks() {
    // Track 1: a held note (selected) and unselected notes at 960 / 1920;
    // track 2: notes at 480 and 2880.
    let mut d = PlumDocument::new_project("s34".into(), Bpm::DEFAULT, 960);
    d.add_track().unwrap();
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(0, 3840, 48)], true)
        .unwrap();
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(960, 100, 72), rec(1920, 100, 72)], false)
        .unwrap();
    d.track_mut(1)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(480, 100, 60), rec(2880, 100, 60)], false)
        .unwrap();
    let def = tool("chop").unwrap();
    let run_with = |mode: u32| -> Vec<(u64, u64)> {
        let mut ps = ParamSet::defaults(&(def.spec)().params);
        for (k, v) in [on("n10"), ch("n10.ref", mode), int("n10.short", 1)] {
            ps.set(k, v);
        }
        let sc = [TrackScope {
            index: 0,
            all: false,
            content: None,
        }];
        let src = collect_with(def, &d, &sc, &ps, 1 << 24).unwrap();
        let ctx = Ctx::simple(960);
        let b = BuildCtx {
            ctx: &ctx,
            stats: &src.stats,
            tracks: &src.tracks,
        };
        let k = def.kernel(&ps, &b).unwrap();
        sl(&run_kernel(
            k.as_ref(),
            &src,
            def.boundary(&ps),
            &Limits::default(),
            None,
        )
        .unwrap()
        .notes)
    };
    assert_eq!(run_with(1), vec![(0, 960), (960, 960), (1920, 1920)]);
    assert_eq!(
        run_with(3),
        vec![(0, 480), (480, 480), (960, 960), (1920, 960), (2880, 960)]
    );
    // Only itself selected: nothing to cut at.
    assert_eq!(run_with(0), vec![(0, 3840)]);
}

#[test]
fn chop_running_phase_carries_the_pattern_from_note_to_note() {
    // Gallop 1+1+2 on two half-beat notes: the second starts at the
    // pattern's third slot (two units long) instead of again at the first.
    let notes = &[(0, 480, 60), (960, 480, 60)];
    let gallop = [ch("pattern", 2)];
    assert_eq!(
        sl(&run("chop", notes, &gallop)),
        vec![(0, 240), (240, 240), (960, 240), (1200, 240)]
    );
    let set = [ch("pattern", 2), on("n11")];
    assert_eq!(
        sl(&run("chop", notes, &set)),
        vec![(0, 240), (240, 240), (960, 480)]
    );
    // Reset after rests longer than 100 ticks (the rest is 480).
    let mut rest = set.to_vec();
    rest.extend([ch("n11.reset", 2), int("n11.rest", 100)]);
    assert_eq!(
        sl(&run("chop", notes, &rest)),
        sl(&run("chop", notes, &gallop))
    );
    // Reset at bar lines: the same bar carries, the next bar restarts.
    let bars = &[(0, 480, 60), (960, 480, 60), (3840, 480, 60)];
    let mut bar = set.to_vec();
    bar.push(ch("n11.reset", 1));
    assert_eq!(
        sl(&run("chop", bars, &bar)),
        vec![(0, 240), (240, 240), (960, 480), (3840, 240), (4080, 240)]
    );
    // A chord's notes start together; per key each key runs on its own.
    let chord = &[(0, 480, 60), (0, 480, 64), (960, 480, 60)];
    let v = run("chop", chord, &set);
    assert_eq!(v.iter().filter(|n| n.start < 480).count(), 4);
    assert_eq!(v.iter().filter(|n| n.start >= 960).count(), 1);
    let mut key = set.to_vec();
    key.push(ch("n11.per", 1));
    let two_keys = &[(0, 480, 60), (480, 480, 64), (960, 480, 60)];
    let v = run("chop", two_keys, &key);
    assert_eq!(v.iter().filter(|n| n.start >= 960).count(), 1);
    assert_eq!(v.iter().filter(|n| n.pitch == 64).count(), 2);
}

#[test]
fn chop_new_functions_off_leave_v08_results_unchanged() {
    let notes = &[
        (0, 1920, 60),
        (0, 960, 64),
        (480, 1440, 67),
        (2000, 300, 72),
    ];
    for pattern in [0u32, 2, 6] {
        let base = run("chop", notes, &[ch("pattern", pattern)]);
        let mut set = vec![ch("pattern", pattern)];
        for k in [
            "n01", "n02", "n03", "n04", "n05", "n06", "n07", "n08", "n09", "n10", "n11",
        ] {
            set.push((k, ParamValue::Bool(false)));
        }
        let v = run("chop", notes, &set);
        let full = |v: &[TNote]| -> Vec<(u64, u64, u8, u8)> {
            let mut o: Vec<_> = v.iter().map(|n| (n.start, n.dur, n.pitch, n.vel)).collect();
            o.sort_unstable();
            o
        };
        assert_eq!(full(&v), full(&base));
    }
}

// ================================================================ Claw Machine

/// 240 notes over eight bars: chords, repeated keys, lengths 30 – 1,200
/// (a fixed LCG, so the fixture never changes).
fn claw_fixture() -> Vec<(u64, u64, u8)> {
    let mut x: u64 = 0x5EED_C1A3;
    let mut next = |m: u64| {
        x = x
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (x >> 33) % m
    };
    let mut v = Vec::new();
    for _ in 0..240 {
        let start = next(8 * 3840 / 30) * 30;
        let dur = 30 + next(40) * 30;
        let pitch = 40 + next(50) as u8;
        v.push((start, dur, pitch));
    }
    v.sort_unstable();
    v.dedup_by_key(|n| (n.0, n.2));
    v
}

/// Order-independent fingerprint of a result: (count, FNV-1a over the
/// sorted (start, length, pitch, velocity, subchannel)).
fn fingerprint(v: &[TNote]) -> (usize, u64) {
    let mut o: Vec<(u64, u64, u8, u8, u32)> = v
        .iter()
        .map(|n| (n.start, n.dur, n.pitch, n.vel, n.sub))
        .collect();
    o.sort_unstable();
    let mut h: u64 = 0xCBF2_9CE4_8422_2325;
    let mut eat = |w: u64| {
        for b in w.to_le_bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0100_0000_01B3);
        }
    };
    for (s, d, p, vel, sub) in o {
        eat(s);
        eat(d);
        eat(u64::from(p) | u64::from(vel) << 8 | u64::from(sub) << 16);
    }
    (v.len(), h)
}

