/// The Claw's warp of `u` at distortion `d` % (CLAW_REFERENCE.md).
fn claw_g(u: f64, d: f64) -> f64 {
    let a = -3.93 * d / 100.0;
    if a.abs() < 1e-9 {
        u
    } else {
        ((a * u).exp() - 1.0) / (a.exp() - 1.0)
    }
}

/// Period starts from 0 by `len(b)` until past `until`.
fn starts_by(until: u64, len: impl Fn(u64) -> u64) -> Vec<u64> {
    let mut v = vec![0];
    while *v.last().unwrap() <= until {
        let b = *v.last().unwrap();
        v.push(b + len(b));
    }
    v
}

/// Whether Trash every 1/2 keeps a note starting at `t` on period starts `b`.
fn first_half(b: &[u64], t: u64) -> bool {
    let i = b.partition_point(|&x| x <= t) - 1;
    (t - b[i]) * 2 < b[i + 1] - b[i]
}

#[test]
fn claw_period_morph_tiles_periods_from_the_period_to_the_end_period() {
    // Period 4 beats (3840) → 2 beats (1920) linearly across the starts 0 …
    // 30,720; Trash every 1/2 shows where each period's halves are.
    let last = 30_720u64;
    for (snap, unit) in [(0u32, 1u64), (2, 960)] {
        let b = starts_by(last, |b| {
            let u = (b as f64 / last as f64).min(1.0);
            let x = 3840.0 - 1920.0 * u;
            ((x / unit as f64).round().max(1.0) as u64) * unit
        });
        let mut notes = vec![(0, 10, 58), (last, 10, 60)];
        for w in b.windows(2).filter(|w| w[0] < last) {
            let len = w[1] - w[0];
            notes.push((w[0] + len / 4, 10, 62));
            notes.push((w[0] + 3 * len / 4, 10, 64));
        }
        let set = [on("n01"), ch("trash", 1), ch("n01.snap", snap)];
        let v = run("claw", &notes, &set);
        let mut want: Vec<u64> = notes
            .iter()
            .map(|n| n.0)
            .filter(|&t| first_half(&b, t))
            .collect();
        want.sort_unstable();
        let mut got: Vec<u64> = v.iter().map(|n| n.start).collect();
        got.sort_unstable();
        assert_eq!(got, want, "snap {snap}");
        if unit == 960 {
            assert!(b.windows(2).all(|w| (w[1] - w[0]) % 960 == 0));
        }
        // Without the morph the halves fall elsewhere.
        let plain = run("claw", &notes, &[ch("trash", 1)]);
        assert_ne!(spd(&plain), spd(&v));
    }
}

#[test]
fn claw_warp_dynamics_follow_the_maps_slope() {
    // Distortion 100 %: the map stretches time at the period's start
    // (slope ≈ 4: dragged) and compresses it near the end (rushed).
    let notes = &[(0, 96, 60), (3456, 96, 62), (3840 * 2, 10, 64)];
    let set = [
        fl("dist", 100.0),
        on("n02"),
        fl("n02.vel", 25.0),
        fl("n02.len", 50.0),
    ];
    let v = run("claw", notes, &set);
    let a = -3.93f64;
    let slope = |u: f64| a * (a * u).exp() / (a.exp() - 1.0);
    let c = |u: f64| (-slope(u).log2() / 2.0).clamp(-1.0, 1.0);
    let at = |t: u64| v.iter().find(|n| n.start == t).copied().unwrap();
    // u = 0: c = −1 → velocity × 2^(−0.25), length × 2^(0.5).
    assert_eq!(c(0.0), -1.0);
    let first = at(0);
    assert_eq!(first.vel, (100.0 * 2f64.powf(-0.25)).round() as u8);
    let mapped = (claw_g(96.0 / 3840.0, 100.0) * 3840.0).round();
    assert_eq!(first.dur, (mapped * 2f64.sqrt()).round() as u64);
    // u = 0.9: rushed → louder and shorter.
    let s = (claw_g(0.9, 100.0) * 3840.0).round() as u64;
    let e = (claw_g(3552.0 / 3840.0, 100.0) * 3840.0).round() as u64;
    let second = at(s);
    let cr = c(0.9);
    assert!(cr > 0.0);
    assert_eq!(second.vel, (100.0 * (0.25 * cr).exp2()).round() as u8);
    assert_eq!(
        second.dur,
        (((e - s) as f64 * (-0.5 * cr).exp2()).round() as u64).max(1)
    );
    // A flat response changes nothing.
    let mut flat = set.to_vec();
    flat.push(curve("n02.curve", Curve::flat(0.0)));
    assert_eq!(
        spd(&run("claw", notes, &flat)),
        spd(&run("claw", notes, &[fl("dist", 100.0)]))
    );
}

#[test]
fn claw_period_sequence_cycles_its_lengths() {
    // 3 + 3 + 2 sixteenths: periods 720, 720, 480 from bar 1.
    let b = starts_by(10_000, |b| match (b % 1920) / 720 {
        0 | 1 => 720,
        _ => 480,
    });
    assert_eq!(&b[..7], &[0, 720, 1440, 1920, 2640, 3360, 3840]);
    let notes: Vec<(u64, u64, u8)> = (0..80).map(|i| (i * 120 + 7, 10, 60)).collect();
    let v = run("claw", &notes, &[on("n03"), ch("trash", 1)]);
    let want: Vec<u64> = notes
        .iter()
        .map(|n| n.0)
        .filter(|&t| first_half(&b, t))
        .collect();
    let mut got: Vec<u64> = v.iter().map(|n| n.start).collect();
    got.sort_unstable();
    assert_eq!(got, want);
    // Beats: 2 + 1 beats.
    let v = run(
        "claw",
        &[(0, 10, 60), (1100, 10, 60), (2000, 10, 60), (2500, 10, 60)],
        &[
            on("n03"),
            list("n03.periods", &[2, 1]),
            ch("n03.unit", 0),
            ch("trash", 1),
        ],
    );
    let mut got: Vec<u64> = v.iter().map(|n| n.start).collect();
    got.sort_unstable();
    // Periods [0, 1920) and [1920, 2880): 1100 and 2500 are second halves.
    assert_eq!(got, vec![0, 2000]);
}

#[test]
fn claw_map_morph_blends_toward_map_b_across_the_selection() {
    let b_map = Curve::new(vec![(0.0, 0.0), (0.5, 0.75), (1.0, 1.0)]);
    let notes: Vec<(u64, u64, u8)> = (0..5).map(|k| (k * 3840 + 1920, 10, 60)).collect();
    // Map B everywhere: the period's middle goes to 3/4.
    let full = run(
        "claw",
        &notes,
        &[
            on("n04"),
            curve("n04.map", b_map.clone()),
            curve("n04.curve", Curve::flat(1.0)),
        ],
    );
    let starts: Vec<u64> = spd(&full).iter().map(|x| x.0).collect();
    assert_eq!(starts, (0..5).map(|k| k * 3840 + 2880).collect::<Vec<_>>());
    // A (identity at 0 %) → B across the selection (first start 1920, last
    // 17,280): the weight is the period start's place.
    let v = run("claw", &notes, &[on("n04"), curve("n04.map", b_map)]);
    let starts: Vec<u64> = spd(&v).iter().map(|x| x.0).collect();
    let want: Vec<u64> = (0..5u64)
        .map(|k| {
            let p0 = k * 3840;
            let w = ((p0 as f64 - 1920.0) / (17_280.0 - 1920.0)).clamp(0.0, 1.0);
            p0 + (((1.0 - w) * 0.5 + w * 0.75) * 3840.0).round() as u64
        })
        .collect();
    assert_eq!(starts, want);
}

#[test]
fn claw_slice_permutation_moves_slices_to_their_slots() {
    // 4 slices of 960: order 0 2 1 3 swaps the middle two.
    let notes = &[
        (100, 50, 60),
        (1000, 50, 61),
        (2000, 50, 62),
        (3000, 50, 63),
        (3840 + 1000, 50, 64),
    ];
    let v = run("claw", notes, &[on("n05")]);
    assert_eq!(
        spd(&v),
        vec![
            (100, 60, 50),
            (1040, 62, 50),
            (1960, 61, 50),
            (3000, 63, 50),
            (3840 + 1960, 64, 50)
        ]
    );
    // Seeded: each period a permutation of the slots, the same for the same
    // seed; Seeded once: one permutation for every period.
    let grid: Vec<(u64, u64, u8)> = (0..32)
        .map(|i| (i * 960 + 10, 20, 60 + (i % 4) as u8))
        .collect();
    for mode in [1u32, 2] {
        let set = [on("n05"), ch("n05.shuffle", mode)];
        let v = run("claw", &grid, &set);
        assert_eq!(spd(&v), spd(&run("claw", &grid, &set)));
        let mut slots: Vec<Vec<u64>> = vec![Vec::new(); 8];
        for n in &v {
            slots[(n.start / 3840) as usize].push((n.start % 3840) / 960);
        }
        for s in &mut slots {
            s.sort_unstable();
            assert_eq!(s, &vec![0, 1, 2, 3]);
        }
        // The slot each slice (by its pitch) went to, per period.
        let order = |k: u64| -> Vec<u64> {
            let mut o: Vec<(u8, u64)> = v
                .iter()
                .filter(|n| n.start / 3840 == k)
                .map(|n| (n.pitch, n.start % 3840 / 960))
                .collect();
            o.sort_unstable();
            o.into_iter().map(|x| x.1).collect()
        };
        let same = (1..8).all(|k| order(k) == order(0));
        assert_eq!(same, mode == 2, "mode {mode}");
    }
}

#[test]
fn claw_content_trash_keeps_the_slices_that_rank_first() {
    // Eight slices of 480 with 3, 1, 2, 0, 5, 1, 0, 0 notes.
    let counts = [3u64, 1, 2, 0, 5, 1, 0, 0];
    let mut notes = Vec::new();
    for (j, &c) in counts.iter().enumerate() {
        for i in 0..c {
            notes.push((j as u64 * 480 + i * 40, 20, 50 + (j as u8) * 5 + i as u8));
        }
    }
    let slices_of = |v: &[TNote]| -> Vec<u64> {
        let mut s: Vec<u64> = v.iter().map(|n| n.start / 480).collect();
        s.sort_unstable();
        s.dedup();
        s
    };
    let keep = |by: u32, k: i64| {
        slices_of(&run(
            "claw",
            &notes,
            &[on("n06"), int("n06.keep", k), ch("n06.by", by)],
        ))
    };
    assert_eq!(keep(0, 2), vec![0, 4]); // densest
    assert_eq!(keep(1, 2), vec![1, 5]); // sparsest (ties: earlier first)
    assert_eq!(keep(3, 3), vec![2, 4, 5]); // highest mean pitch
    // Every note of a kept slice stays; no slice is half trashed.
    let v = run("claw", &notes, &[on("n06"), int("n06.keep", 2)]);
    assert_eq!(v.len(), 8);
}

#[test]
fn claw_trash_refill_copies_a_neighbouring_slice_into_trashed_slices() {
    // Trash every 1/4: slice 3 (2880 – 3840) of each period is trashed.
    let notes = &[
        (100, 50, 60),
        (1000, 50, 61),
        (2000, 50, 62),
        (3000, 50, 63),
        (3840 + 100, 50, 64),
    ];
    let base = [ch("trash", 3), on("n07")];
    let with = |from: u32| {
        let mut s = base.to_vec();
        s.push(ch("n07.from", from));
        s.push(fl("n07.vel", 50.0));
        s.push(int("n07.semis", 12));
        spd(&run("claw", notes, &s))
    };
    let kept = vec![
        (100, 60, 50),
        (1000, 61, 50),
        (2000, 62, 50),
        (3940, 64, 50),
    ];
    let mut prev = kept.clone();
    prev.push((2960, 74, 50));
    prev.sort_unstable();
    assert_eq!(with(0), prev);
    let mut first = kept.clone();
    first.push((2980, 72, 50));
    first.sort_unstable();
    assert_eq!(with(1), first);
    let mut next = kept.clone();
    next.push((2980, 76, 50));
    next.sort_unstable();
    assert_eq!(with(2), next);
    let v = run(
        "claw",
        notes,
        &[ch("trash", 3), on("n07"), fl("n07.vel", 50.0)],
    );
    assert_eq!(v.iter().find(|n| n.start == 2960).unwrap().vel, 50);
    // Only slices that lost notes are refilled (period 1's slice 3 lost
    // nothing).
    assert_eq!(v.len(), 5);
}

#[test]
fn claw_phase_drift_moves_each_period_start_later() {
    let at = |v: &[TNote], t: u64| v.iter().any(|n| n.start == t);
    // Drift 2,000 per period, distortion 100 %: a note on a period start
    // stays, a note inside a period moves.
    let notes = &[
        (0, 10, 60),
        (5840, 10, 60),
        (7840, 10, 60),
        (11_680, 10, 60),
        (13_680, 10, 60),
        (17_520, 10, 60),
    ];
    let set = |mode: u32| {
        vec![
            fl("dist", 100.0),
            on("n08"),
            int("n08.drift", 2000),
            ch("n08.mode", mode),
        ]
    };
    // Wrap: starts 0, 3840 + 2000, 7680 + 160, 11,520 + 2160, …
    let wrap = run("claw", notes, &set(0));
    for t in [0, 5840, 7840, 13_680] {
        assert!(at(&wrap, t), "wrap {t}");
    }
    assert!(!at(&wrap, 11_680) && !at(&wrap, 17_520));
    // Accumulate: periods of 3840 + 2000.
    let acc = run("claw", notes, &set(1));
    for t in [0, 5840, 11_680, 17_520] {
        assert!(at(&acc, t), "accumulate {t}");
    }
    assert!(!at(&acc, 7840) && !at(&acc, 13_680));
    // A drift curve at 0 is the plain grid.
    let mut flat = set(0);
    flat.push(curve("n08.curve", Curve::flat(0.0)));
    assert_eq!(
        spd(&run("claw", notes, &flat)),
        spd(&run("claw", notes, &[fl("dist", 100.0)]))
    );
}

#[test]
fn claw_period_rescale_closes_up_the_timeline() {
    // 4/4 bars into 3/4: 3840 → 2880.
    let notes = &[
        (0, 480, 60),
        (1920, 480, 62),
        (3840, 480, 64),
        (4800, 480, 65),
    ];
    assert_eq!(
        spd(&run("claw", notes, &[on("n09")])),
        vec![
            (0, 60, 360),
            (1440, 62, 360),
            (2880, 64, 360),
            (3600, 65, 360)
        ]
    );
    assert_eq!(
        spd(&run("claw", notes, &[on("n09"), ch("n09.lengths", 1)])),
        vec![
            (0, 60, 480),
            (1440, 62, 480),
            (2880, 64, 480),
            (3600, 65, 480)
        ]
    );
    // Anchored at the end: the first period's contents end where it ended.
    let end = spd(&run("claw", notes, &[on("n09"), ch("n09.anchor", 2)]));
    assert_eq!(end[0].0, 960);
    assert_eq!(end[2].0, 960 + 2880);
    let centre = spd(&run("claw", notes, &[on("n09"), ch("n09.anchor", 1)]));
    assert_eq!(centre[0].0, 480);
    // Stretched: 3840 → 4800 (5/4).
    let v = spd(&run("claw", notes, &[on("n09"), int("n09.period", 4800)]));
    assert_eq!(v[2], (4800, 64, 600));
}

#[test]
fn claw_onset_equalizer_spreads_dense_onsets_by_their_histogram() {
    // Four bins of 960: three onsets in bin 0, one at the middle (bin 2).
    let notes = &[(0, 10, 60), (60, 10, 61), (120, 10, 62), (1920, 10, 63)];
    let he = |u: f64, s: f64| -> u64 {
        let counts = [3.0, 0.0, 1.0, 0.0];
        let x = u * 4.0;
        let b = (x.floor() as usize).min(3);
        let c: f64 = counts[..b].iter().sum();
        let f = (c + (x - b as f64) * counts[b]) / 4.0;
        (((1.0 - s) * u + s * f) * 3840.0).round() as u64
    };
    for s in [100.0, 50.0] {
        let v = run(
            "claw",
            notes,
            &[on("n10"), int("n10.bins", 4), fl("n10.strength", s)],
        );
        let starts: Vec<u64> = spd(&v).iter().map(|x| x.0).collect();
        let want: Vec<u64> = notes
            .iter()
            .map(|n| he(n.0 as f64 / 3840.0, s / 100.0))
            .collect();
        assert_eq!(starts, want, "strength {s}");
    }
    // At 100 %: 0, 180, 360, 2880 — the cluster opens, order kept.
    let v = run("claw", notes, &[on("n10"), int("n10.bins", 4)]);
    assert_eq!(
        spd(&v).iter().map(|x| x.0).collect::<Vec<_>>(),
        vec![0, 180, 360, 2880]
    );
    // Per key: each key's onsets equalized alone (one onset → its bin
    // spans the period).
    let keys = &[(0, 10, 60), (480, 10, 60), (960, 10, 72)];
    let per_key = run(
        "claw",
        keys,
        &[on("n10"), int("n10.bins", 4), ch("n10.per", 1)],
    );
    let p72 = per_key.iter().find(|n| n.pitch == 72).unwrap();
    assert_eq!(p72.start, 0);
    let together = run("claw", keys, &[on("n10"), int("n10.bins", 4)]);
    assert_ne!(spd(&per_key), spd(&together));
}

#[test]
fn claw_dry_wet_layers_keep_the_originals_on_the_next_subchannel() {
    let mut d = PlumDocument::new_project("s34".into(), Bpm::DEFAULT, 960);
    History::default()
        .apply(
            &mut d,
            Operation::AddSubchannels {
                track: 0,
                subs: vec![Subchannel::new(SubchannelId(1), 1)],
            },
        )
        .unwrap();
    let v: Vec<NoteRecord> = [(0u64, 480u64, 60u8), (1920, 480, 64)]
        .iter()
        .map(|&(s, l, p)| rec(s, l, p))
        .collect();
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&v, true)
        .unwrap();
    let t = tool("claw").unwrap();
    let go = |set: &[(&str, ParamValue)]| -> Vec<TNote> {
        let mut ps = ParamSet::defaults(&(t.spec)().params);
        for (k, val) in set {
            ps.set(k, val.clone());
        }
        let sc = [TrackScope {
            index: 0,
            all: false,
            content: None,
        }];
        let src = collect_for(t, &d, &sc, 1 << 24).unwrap();
        let ctx = Ctx::simple(960);
        let b = BuildCtx {
            ctx: &ctx,
            stats: &src.stats,
            tracks: &src.tracks,
        };
        let k = t.kernel(&ps, &b).unwrap();
        run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)
            .unwrap()
            .notes
    };
    let base = [
        fl("dist", 100.0),
        on("n11"),
        fl("n11.dry", 50.0),
        fl("n11.wet", 120.0),
    ];
    let out = go(&base);
    assert_eq!(out.len(), 4);
    let mut dry: Vec<(u64, u64, u8, u8, u32)> = out
        .iter()
        .filter(|n| n.sub == 1)
        .map(|n| (n.start, n.dur, n.pitch, n.vel, n.sub))
        .collect();
    dry.sort_unstable();
    assert_eq!(dry, vec![(0, 480, 60, 50, 1), (1920, 480, 64, 50, 1)]);
    let mut wet: Vec<(u64, u8, u8, u32)> = out
        .iter()
        .filter(|n| n.sub == 0)
        .map(|n| (n.start, n.pitch, n.vel, n.sub))
        .collect();
    wet.sort_unstable();
    let mid = (claw_g(0.5, 100.0) * 3840.0).round() as u64;
    assert_eq!(wet, vec![(0, 60, 120, 0), (mid, 64, 120, 0)]);
    // Velocity 0 % leaves a layer out; offset 0 keeps the subchannel.
    let mut no_dry = base.to_vec();
    no_dry.push(fl("n11.dry", 0.0));
    assert_eq!(go(&no_dry).len(), 2);
    let mut no_wet = base.to_vec();
    no_wet.push(fl("n11.wet", 0.0));
    assert!(go(&no_wet).iter().all(|n| n.sub == 1));
    let mut same = base.to_vec();
    same.push(int("n11.sub", 0));
    assert!(go(&same).iter().all(|n| n.sub == 0));
}

// ================================================================ Quantizer

/// 300 notes over eight bars at irregular ticks (played timing), chords,
/// repeated keys, lengths 17 – 1,193 (a fixed LCG, so the fixture never
/// changes).
fn qnt_fixture() -> Vec<(u64, u64, u8)> {
    let mut x: u64 = 0x0005_EED0_0A17;
    let mut next = |m: u64| {
        x = x
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (x >> 33) % m
    };
    let mut v = Vec::new();
    for _ in 0..300 {
        let start = next(8 * 3840);
        let dur = 17 + next(1177);
        let pitch = 36 + next(60) as u8;
        v.push((start, dur, pitch));
    }
    v.sort_unstable();
    v.dedup_by_key(|n| (n.0, n.2));
    v
}

/// Settings of the v0.8 Quantizer (base controls and each frozen function).
fn qnt_v08_settings() -> Vec<Vec<(&'static str, ParamValue)>> {
    vec![
        vec![],
        vec![
            ch("grid", 3),
            fl("start", 60.0),
            fl("sens", 50.0),
            ch("mode", 0),
            fl("dur", 70.0),
        ],
        vec![on("groove"), fl("levels", 0.5), ch("mode", 1)],
        vec![on("a1"), fl("a1.amount", -0.7)],
        vec![on("a2"), fl("a2.late", 10.0)],
        vec![on("a3"), ch("mode", 0)],
        vec![on("a4"), list("a4.grids", &[12, 16, 9])],
        vec![
            on("a5"),
            list("a5.offsets", &[0, 3, -2, 0, 5, 0, -6, 0, 1, 0, 0, 2]),
        ],
        vec![on("groove"), on("a6"), fl("a6.mix", 0.3), fl("levels", 1.0)],
        vec![on("a7"), ("a7.tol", ParamValue::Int(40)), ch("mode", 1)],
        vec![on("a8"), list("a8.phase", &[7, -3])],
        vec![on("a9"), fl("a9.keep", 30.0)],
        vec![on("a10"), fl("a10.from", 20.0), fl("a10.to", 90.0)],
        vec![
            ch("grid", 9),
            ch("mode", 3),
            fl("start", 80.0),
            fl("sens", 30.0),
        ],
    ]
}

