#[test]
fn qnt_new_functions_off_leave_v08_results_unchanged() {
    let notes = qnt_fixture();
    for (i, s) in qnt_v08_settings().into_iter().enumerate() {
        let mut set = s.clone();
        for k in ALL11 {
            set.push((k, ParamValue::Bool(false)));
        }
        assert_eq!(
            fingerprint(&run("quantize", &notes, &set)),
            QNT_V08[i],
            "setting {i}"
        );
    }
}

/// Starts in (start, pitch) order.
fn starts(v: &[TNote]) -> Vec<u64> {
    spd(v).iter().map(|x| x.0).collect()
}

/// Start of each pitch (one note per pitch).
fn start_of(v: &[TNote], pitch: u8) -> u64 {
    v.iter().find(|n| n.pitch == pitch).unwrap().start
}

/// The swung position of `x` (the v0.8 grid point) with unit `u` and the
/// off-step at `f` of the pair (closed form of n01).
fn swung(x: u64, u: u64, f: f64) -> u64 {
    let base = x / (2 * u) * (2 * u);
    let r = (x - base) as f64;
    let y = if r < u as f64 {
        r * 2.0 * f
    } else {
        f * 2.0 * u as f64 + (r - u as f64) * (2.0 - 2.0 * f)
    };
    base + y.round() as u64
}

#[test]
fn qnt_swing_delays_every_second_unit_by_the_swing_amount() {
    // Grid and unit 1/8 (480), swing 66 %: the off-steps sit at 0.66 of the
    // pair (634); notes are matched against the swung grid, so a note
    // already played swung (700) lands on the swung off-step.
    let set = [ch("grid", 3), on("n01"), fl("n01.swing", 66.0)];
    let notes = &[
        (0, 50, 60),
        (470, 50, 61),
        (700, 50, 62),
        (900, 50, 63),
        (1500, 50, 64),
    ];
    let v = run("quantize", notes, &set);
    assert_eq!(
        [60, 61, 62, 63, 64].map(|p| start_of(&v, p)),
        [0, 634, 634, 960, 960 + 634]
    );
    assert_eq!(swung(480, 480, 0.66), 634);
    // Swing over the selection: 0 % → 100 % of the amount from the first to
    // the last start (50 % straight at the first, 58 % in the middle).
    let mut ramp = set.to_vec();
    ramp.push(curve("n01.curve", Curve::line(0.0, 1.0)));
    let notes = &[(480, 50, 60), (3840 + 480, 50, 61), (7680 + 480, 50, 62)];
    let v = run("quantize", notes, &ramp);
    assert_eq!(
        [60, 61, 62].map(|p| start_of(&v, p)),
        [
            480,
            3840 + swung(480, 480, 0.58),
            7680 + swung(480, 480, 0.66)
        ]
    );
    // 1/16 grid under a 1/8 swing: every grid point is warped (the pair's
    // first half stretched, the second compressed) and each note goes to
    // the nearest point of the swung grid.
    let set = [ch("grid", 4), on("n01"), fl("n01.swing", 75.0)];
    let grid: Vec<u64> = (0..40).map(|k| swung(k * 240, 480, 0.75)).collect();
    assert_eq!(&grid[..5], &[0, 360, 720, 840, 960]);
    let notes: Vec<(u64, u64, u8)> = (0..60u64)
        .map(|k| (k * 131 % 7000, 10, 40 + (k % 60) as u8))
        .collect();
    let v = run("quantize", &notes, &set);
    // The nearest swung point (the later one on a tie, as the v0.8 grid).
    let nearest = |t: u64| -> u64 {
        let k = grid.partition_point(|&g| g < t);
        match k.checked_sub(1) {
            Some(j) if t - grid[j] < grid[k] - t => grid[j],
            _ => grid[k],
        }
    };
    let mut want: Vec<(u64, u8)> = notes.iter().map(|n| (nearest(n.0), n.2)).collect();
    want.sort_unstable();
    let mut got: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.pitch)).collect();
    got.sort_unstable();
    assert_eq!(got, want);
}

/// 120 BPM until tick 1920 (one second), then 60 BPM.
fn qnt_stepped_tempo() -> Ctx {
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[
            (0, TempoValue::Micros(500_000)),
            (1920, TempoValue::Micros(1_000_000)),
        ],
    )));
    ctx
}

/// The first tick at or after `us` µs under [`qnt_stepped_tempo`].
fn qnt_tick_at(us: f64) -> u64 {
    if us <= 1e6 {
        (us * 1920.0 / 1e6 - 1e-9).ceil() as u64
    } else {
        1920 + ((us - 1e6) * 960.0 / 1e6 - 1e-9).ceil() as u64
    }
}

/// µs of `tick` under [`qnt_stepped_tempo`].
fn qnt_us_at(tick: u64) -> f64 {
    if tick <= 1920 {
        tick as f64 * 1e6 / 1920.0
    } else {
        1e6 + (tick - 1920) as f64 * 1e6 / 960.0
    }
}

#[test]
fn qnt_frame_grid_snaps_to_video_frames_through_the_tempo_map() {
    // 50 fps (20 ms) across a tempo change: 38.4 ticks per frame at 120 BPM,
    // 19.2 after tick 1920 at 60 BPM.
    let notes: Vec<(u64, u64, u8)> = [7u64, 50, 700, 1900, 1930, 2020, 3001]
        .iter()
        .enumerate()
        .map(|(i, &s)| (s, 10, 60 + i as u8))
        .collect();
    let set = [on("n02"), ch("n02.grid", 3)];
    let v = run_in("quantize", &notes, &set, Some(qnt_stepped_tempo()));
    let want: Vec<u64> = notes
        .iter()
        .map(|n| qnt_tick_at((qnt_us_at(n.0) / 20_000.0).round() * 20_000.0))
        .collect();
    assert_eq!(starts(&v), want);
    assert_eq!(want[5], 2016, "1.1 s after the change");
    // Every result lies on a frame: its time is within a tick of k · 20 ms.
    for n in &v {
        let us = qnt_us_at(n.start);
        let off = us - (us / 20_000.0).round() * 20_000.0;
        assert!(off.abs() < 1e6 / 960.0, "{} at {us} µs", n.start);
    }
    // Milliseconds with a phase: 100 ms grid from 30 ms (120 BPM, 1.92
    // ticks per ms): 300 ticks = 156.25 ms → 130 ms → tick 250 (249.6).
    let set = [
        on("n02"),
        ch("n02.grid", 6),
        fl("n02.ms", 100.0),
        fl("n02.phase", 30.0),
    ];
    assert_eq!(starts(&run("quantize", &[(300, 10, 60)], &set)), vec![250]);
    // 60 fps at 120 BPM = exactly 32 ticks.
    let set = [on("n02"), ch("n02.grid", 4)];
    let v = run(
        "quantize",
        &[(15, 10, 60), (17, 10, 61), (100, 10, 62)],
        &set,
    );
    assert_eq!(starts(&v), vec![0, 32, 96]);
}

#[test]
fn qnt_collision_free_slots_move_stacked_keys_to_free_steps() {
    // 1/16 grid (240): two notes of one key at 0 and 10 both land on 0 —
    // the later one moves to the nearest free step.
    let set = [on("n03")];
    let v = run("quantize", &[(0, 100, 60), (10, 100, 60)], &set);
    assert_eq!(starts(&v), vec![0, 240]);
    // Without the function they stack.
    assert_eq!(
        starts(&run("quantize", &[(0, 100, 60), (10, 100, 60)], &[])),
        vec![0, 0]
    );
    // Overlap: 250 → 240 would sit inside the long note [0, 500): 480 still
    // overlaps, 0 too, so 720 (two steps on).
    let v = run("quantize", &[(0, 500, 60), (250, 100, 60)], &set);
    assert_eq!(starts(&v), vec![0, 720]);
    // Previous free step: 470 → 480 collides with the note at 480; 240 is
    // free.
    let mut prev = set.to_vec();
    prev.push(ch("n03.free", 2));
    let v = run("quantize", &[(480, 100, 60), (470, 100, 60)], &prev);
    assert_eq!(starts(&v), vec![240, 480]);
    // Next free step only goes forward.
    let mut next = set.to_vec();
    next.push(ch("n03.free", 1));
    let v = run("quantize", &[(480, 100, 60), (470, 100, 60)], &next);
    assert_eq!(starts(&v), vec![480, 720]);
    // Leave unquantized: the later note keeps its own start and length.
    let mut leave = set.to_vec();
    leave.push(ch("n03.free", 3));
    let v = run("quantize", &[(0, 100, 60), (10, 77, 60)], &leave);
    assert_eq!(spd(&v), vec![(0, 60, 100), (10, 60, 77)]);
    // Radius 1: 0 and 240 taken (and −240 impossible), so the third goes
    // back to its own start.
    let mut r1 = set.to_vec();
    r1.push(int("n03.radius", 1));
    let v = run("quantize", &[(0, 50, 60), (5, 50, 60), (10, 60, 60)], &r1);
    assert_eq!(spd(&v), vec![(0, 60, 50), (10, 60, 60), (240, 60, 50)]);
    // Other keys never collide.
    let v = run("quantize", &[(0, 100, 60), (10, 100, 61)], &set);
    assert_eq!(starts(&v), vec![0, 0]);
    // Key and channel: the same key on two channels shares the tick.
    let notes = vec![
        tn(0, 100, 60, 100),
        TNote {
            ch: 3,
            ..tn(10, 100, 60, 100)
        },
    ];
    let mut kc = set.to_vec();
    kc.push(ch("n03.key", 1));
    assert_eq!(
        starts(&run_src("quantize", notes.clone(), vec![], &[0], &kc, None)),
        vec![0, 0]
    );
    assert_eq!(
        starts(&run_src("quantize", notes, vec![], &[0], &set, None)),
        vec![0, 240]
    );
    // A dense brute-force check: no two notes of one key overlap afterwards
    // (when every note found a step).
    let notes: Vec<(u64, u64, u8)> = (0..200u64)
        .map(|i| (i * 37 % 3000, 60, 60 + (i % 3) as u8))
        .collect();
    let mut wide = set.to_vec();
    wide.push(int("n03.radius", 64));
    let v = run("quantize", &notes, &wide);
    assert_eq!(v.len(), notes.len());
    for a in &v {
        for b in &v {
            if !std::ptr::eq(a, b) && a.pitch == b.pitch {
                assert!(a.end() <= b.start || b.end() <= a.start, "{a:?} {b:?}");
            }
        }
    }
}

#[test]
fn qnt_cluster_snap_gathers_onsets_without_a_grid() {
    // A flammed chord 130 / 142 / 155 (the 1/16 grid would put it on 240)
    // and a note 100 ticks later; window 40.
    let notes = || {
        vec![
            tn(130, 50, 60, 70),
            tn(142, 50, 64, 120),
            tn(155, 50, 67, 90),
            tn(255, 50, 72, 100),
        ]
    };
    let go = |target: u32, largest: i64| {
        let set = [
            on("n04"),
            int("n04.window", 40),
            ch("n04.target", target),
            int("n04.largest", largest),
        ];
        let v = run_src("quantize", notes(), vec![], &[0], &set, None);
        [60, 64, 67, 72].map(|p| start_of(&v, p))
    };
    assert_eq!(go(0, 128), [130, 130, 130, 255]);
    assert_eq!(go(1, 128), [142, 142, 142, 255], "the loudest");
    assert_eq!(
        go(2, 128),
        [142, 142, 142, 255],
        "(130 + 142 + 155) / 3 = 142.3"
    );
    assert_eq!(go(3, 128), [155, 155, 155, 255]);
    // Largest cluster 2: 130 + 142, then 155 starts the next (with 255? no:
    // 100 ticks apart).
    assert_eq!(go(0, 2), [130, 130, 155, 255]);
    // The start strength mixes: 50 % goes half way to the earliest (−12.5
    // rounds away from zero).
    let set = [on("n04"), int("n04.window", 40), fl("start", 50.0)];
    let v = run_src("quantize", notes(), vec![], &[0], &set, None);
    assert_eq!([60, 64, 67].map(|p| start_of(&v, p)), [130, 136, 142]);
}

/// n05's elastic points (the definition, re-derived): from `lo`, spacing
/// `a → b` linearly over `lo … hi`, until one widest spacing past `end`.
fn elastic_points(lo: u64, hi: u64, end: u64, a: f64, b: f64) -> Vec<u64> {
    let mut v = Vec::new();
    let mut p = lo as f64;
    let stop = end + a.max(b) as u64;
    loop {
        let t = p.round() as u64;
        if v.last() != Some(&t) {
            v.push(t);
        }
        if t >= stop {
            return v;
        }
        let x = ((p - lo as f64) / (hi - lo) as f64).clamp(0.0, 1.0);
        p += (a + (b - a) * x).max(1.0);
    }
}

#[test]
fn qnt_elastic_grid_follows_its_integrated_spacing() {
    // Spacing 480 → 120 across 0 … 7,680 (linear): every note goes to the
    // nearest point of the integrated grid, and the steps shrink.
    let notes: Vec<(u64, u64, u8)> = (0..60u64)
        .map(|k| (k * 7680 / 59 + (k * 13) % 50, 20, 40 + (k % 40) as u8))
        .collect();
    let set = [on("n05"), int("n05.from", 480), int("n05.to", 120)];
    let v = run("quantize", &notes, &set);
    let lo = notes[0].0;
    let hi = notes.iter().map(|n| n.0).max().unwrap();
    let end = notes.iter().map(|n| n.0 + n.1).max().unwrap();
    let pts = elastic_points(lo, hi, end, 480.0, 120.0);
    let nearest = |t: u64| -> u64 {
        let k = pts.partition_point(|&p| p < t);
        match (k.checked_sub(1).map(|j| pts[j]), pts.get(k)) {
            (Some(d), Some(&u)) => {
                if t - d < u - t {
                    d
                } else {
                    u
                }
            }
            (Some(d), None) => d,
            (None, Some(&u)) => u,
            _ => t,
        }
    };
    let mut want: Vec<(u64, u8)> = notes.iter().map(|n| (nearest(n.0), n.2)).collect();
    want.sort_unstable();
    let mut got: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.pitch)).collect();
    got.sort_unstable();
    assert_eq!(got, want);
    let gaps: Vec<u64> = pts.windows(2).map(|w| w[1] - w[0]).collect();
    assert_eq!(gaps[0], 480);
    assert!(gaps.windows(2).all(|w| w[1] <= w[0]), "spacing shrinks");
    assert!(*gaps.last().unwrap() <= 125);
    // Too many points across the selection: refused with a sentence.
    let t = tool("quantize").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in [on("n05"), int("n05.from", 1), int("n05.to", 1)] {
        ps.set(k, val);
    }
    let src = Source::from_notes(
        vec![tn(0, 10, 60, 100), tn(10_000_000, 10, 60, 100)],
        vec![SourceTrack {
            id: TrackId(1),
            index: 0,
            content: None,
            revision: 0,
            subs: vec![(0, 0)],
            all: false,
            insert_only: false,
            frame: 0,
        }],
    );
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let e = t.kernel(&ps, &b).err().expect("refused");
    assert!(
        e.user_message().contains("elastic grid"),
        "{}",
        e.user_message()
    );
}

#[test]
fn qnt_register_grid_gives_each_register_its_grid() {
    // Pivots C3 (48) → C6 (84), 960 → 120: octave steps halve per octave
    // (960, 480, 240, 120); linear interpolates (66 → 540).
    let notes: Vec<(u64, u64, u8)> = [36u8, 48, 60, 66, 72, 84, 100]
        .iter()
        .map(|&p| (310, 10, p))
        .collect();
    let set = [on("n06")];
    let v = run("quantize", &notes, &set);
    // 310 on 960 → 0, on 480 → 480, on 240 → 240, on 120 → 360.
    assert_eq!(
        [36, 48, 60, 66, 72, 84, 100].map(|p| start_of(&v, p)),
        [0, 0, 480, 480, 240, 360, 360]
    );
    let mut lin = set.to_vec();
    lin.push(ch("n06.between", 1));
    let v = run("quantize", &notes, &lin);
    // Linear grids 960, 960, 680, 540, 400, 120, 120: 310 → 0, 0, 0, 540,
    // 400, 360, 360.
    assert_eq!(
        [36, 48, 60, 66, 72, 84, 100].map(|p| start_of(&v, p)),
        [0, 0, 0, 540, 400, 360, 360]
    );
    // The grid also sets quantized durations (Mode: Quantize duration).
    let mut dur = set.to_vec();
    dur.push(ch("mode", 0));
    let v = run("quantize", &[(0, 300, 48), (0, 300, 84)], &dur);
    assert_eq!(lens(&v), vec![960, 360]);
}

#[test]
fn qnt_self_groove_tightens_each_slot_to_its_mean_offset() {
    // Groove of 1 beat, 4 slots (240): slot 0 played at −10 / +10 (mean 0),
    // slot 1 at +20 / +40 (mean +30), slot 2 at −30 / −10 (mean −20); slot 3
    // once at +5.
    let notes = vec![
        tn(10, 50, 60, 100),
        tn(260, 50, 61, 60),
        tn(450, 50, 62, 90),
        tn(725, 50, 63, 80),
        tn(950, 50, 64, 120),
        tn(1240, 50, 65, 80),
        tn(1430, 50, 66, 70),
    ];
    let set = [on("n07"), int("n07.beats", 1), int("n07.slots", 4)];
    let v = run_src("quantize", notes.clone(), vec![], &[0], &set, None);
    assert_eq!(
        (60..=66).map(|p| start_of(&v, p)).collect::<Vec<_>>(),
        vec![0, 270, 460, 725, 960, 1230, 1420]
    );
    // Strength 50 % and the slot's mean velocity at that strength.
    let mut half = set.to_vec();
    half.extend([fl("n07.strength", 50.0), ch("n07.vel", 1)]);
    let v = run_src("quantize", notes, vec![], &[0], &half, None);
    assert_eq!(
        (60..=66).map(|p| start_of(&v, p)).collect::<Vec<_>>(),
        vec![5, 265, 455, 725, 955, 1235, 1425]
    );
    // Slot means: 0 → 110, 1 → 70, 2 → 80, 3 → 80.
    let vel = |p: u8| v.iter().find(|n| n.pitch == p).unwrap().vel;
    assert_eq!(
        (60..=66).map(vel).collect::<Vec<_>>(),
        vec![105, 65, 85, 80, 115, 75, 75]
    );
}

#[test]
fn qnt_meter_anchor_restarts_the_grid_at_bars_beats_and_markers() {
    // 7/8 (3,360 ticks), then 4/4; grid 1/4 (960).
    let mut ctx = Ctx::simple(960);
    ctx.meter = MeterMap::new(Division::ppqn(960), &[(0, 7, 3), (3360, 4, 2)]);
    let notes = &[
        (3400, 10, 60),
        (3300, 10, 61),
        (2200, 10, 62),
        (4400, 10, 63),
    ];
    let set = [ch("grid", 2), on("n08"), list("n08.odd", &[])];
    let v = run_in("quantize", notes, &[ch("grid", 2)], Some(ctx.clone()));
    // From the song start: 3400 → 3840, 3300 → 2880, 2200 → 1920, 4400 → 4800.
    assert_eq!(
        [60, 61, 62, 63].map(|p| start_of(&v, p)),
        [3840, 2880, 1920, 4800]
    );
    let v = run_in("quantize", notes, &set, Some(ctx.clone()));
    // Every bar: bar 2 starts at 3360 (3400 → 3360, 4400 → 4320); 3300 is
    // nearer the next bar line than any grid point of its bar.
    assert_eq!(
        [60, 61, 62, 63].map(|p| start_of(&v, p)),
        [3360, 3360, 1920, 4320]
    );
    // Odd meters: the 7/8 bar takes 1/8 (480): 2200 → 2400, 3300 → 3360.
    let mut odd = set.to_vec();
    odd.push(list("n08.odd", &[7]));
    let v = run_in("quantize", notes, &odd, Some(ctx.clone()));
    assert_eq!(
        [60, 61, 62, 63].map(|p| start_of(&v, p)),
        [3360, 3360, 2400, 4320]
    );
    // Every beat (eighths in 7/8): 700 → 480 (its beat), never past 960.
    let mut beat = set.to_vec();
    beat.push(ch("n08.anchor", 2));
    let v = run_in(
        "quantize",
        &[(700, 10, 60), (900, 10, 61)],
        &beat,
        Some(ctx),
    );
    assert_eq!(starts(&v), vec![480, 960]);
    // Every marker: a marker at 1000 restarts the grid — 1500 → 1960 (1920
    // without it); 900 is before it (song-start grid: 960, nearer than the
    // marker).
    let mut mctx = Ctx::simple(960);
    mctx.markers = Arc::new(vec![1000]);
    let mut mk = set.to_vec();
    mk.push(ch("n08.anchor", 3));
    let v = run_in(
        "quantize",
        &[(1500, 10, 60), (900, 10, 61)],
        &mk,
        Some(mctx.clone()),
    );
    assert_eq!([60, 61].map(|p| start_of(&v, p)), [1960, 960]);
    // 980 is nearer the marker than 960's grid point… no: 20 vs 20 — a tie
    // goes to the later point (the marker).
    let v = run_in("quantize", &[(980, 10, 60)], &mk, Some(mctx.clone()));
    assert_eq!(starts(&v), vec![1000]);
    // In an opened clip (tick 0 = song tick 400) the marker is at 600.
    mctx.shift = 400;
    let v = run_in("quantize", &[(1100, 10, 60)], &mk, Some(mctx));
    assert_eq!(starts(&v), vec![1560]);
}

#[test]
fn qnt_onset_magnet_pulls_starts_to_reference_onsets() {
    // Unselected reference notes at 100 and 1000; distance 120.
    let reference = vec![tn(100, 50, 48, 100), tn(1000, 50, 48, 100)];
    let targets = || {
        vec![
            tn(130, 10, 72, 100),
            tn(500, 10, 73, 100),
            tn(900, 10, 74, 100),
        ]
    };
    let set = [on("n09")];
    let v = run_src("quantize", targets(), reference.clone(), &[0], &set, None);
    // 130 → 100, 900 → 1000; 500 has none within 120: the 1/16 grid (480).
    assert_eq!([72, 73, 74].map(|p| start_of(&v, p)), [100, 480, 1000]);
    // Strength 50 % (the start strength still quantizes the rest).
    let mut half = set.to_vec();
    half.push(fl("n09.strength", 50.0));
    let v = run_src("quantize", targets(), reference.clone(), &[0], &half, None);
    assert_eq!([72, 73, 74].map(|p| start_of(&v, p)), [115, 480, 950]);
    // A subchannel as the reference (place 2 = id 7): its notes lead and are
    // not pulled (the grid quantizes them).
    let mut mixed: Vec<TNote> = vec![
        TNote {
            sub: 7,
            ..tn(110, 50, 48, 100)
        },
        TNote {
            sub: 7,
            ..tn(990, 50, 48, 100)
        },
    ];
    mixed.extend(targets());
    let mut sub = set.to_vec();
    sub.extend([ch("n09.ref", 1), int("n09.num", 2)]);
    let v = run_src("quantize", mixed, vec![], &[0, 7], &sub, None);
    assert_eq!(
        [48, 72, 73, 74].map(|p| {
            let mut s: Vec<u64> = v.iter().filter(|n| n.pitch == p).map(|n| n.start).collect();
            s.sort_unstable();
            s[0]
        }),
        [0, 110, 480, 990]
    );
}

#[test]
fn qnt_onset_magnet_reads_unselected_notes_before_the_selection_and_other_tracks() {
    // Track 1: selected 130 and 900, unselected 100 (before the selection)
    // and 1000; track 2 (reference track) onsets 140 and 880.
    let mut d = PlumDocument::new_project("s34".into(), Bpm::DEFAULT, 960);
    d.add_track().unwrap();
    let sel: Vec<NoteRecord> = [130u64, 900].iter().map(|&s| rec(s, 10, 72)).collect();
    let uns: Vec<NoteRecord> = [100u64, 1000].iter().map(|&s| rec(s, 10, 48)).collect();
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&sel, true)
        .unwrap();
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&uns, false)
        .unwrap();
    let r: Vec<NoteRecord> = [140u64, 880].iter().map(|&s| rec(s, 10, 50)).collect();
    d.track_mut(1)
        .unwrap()
        .notes
        .insert_sorted_batch(&r, false)
        .unwrap();
    let def = tool("quantize").unwrap();
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let go = |set: &[(&str, ParamValue)]| -> Vec<u64> {
        let mut ps = ParamSet::defaults(&(def.spec)().params);
        for (k, v) in set {
            ps.set(k, v.clone());
        }
        let src = collect_with(def, &d, &sc, &ps, 1 << 24).unwrap();
        let ctx = Ctx::simple(960);
        let b = BuildCtx {
            ctx: &ctx,
            stats: &src.stats,
            tracks: &src.tracks,
        };
        let k = def.kernel(&ps, &b).unwrap();
        starts(
            &run_kernel(
                k.as_ref(),
                &src,
                def.boundary(&ps),
                &Limits::default(),
                None,
            )
            .unwrap()
            .notes,
        )
    };
    assert_eq!(go(&[on("n09")]), vec![100, 1000]);
    assert_eq!(
        go(&[on("n09"), ch("n09.ref", 2), int("n09.num", 2)]),
        vec![140, 880]
    );
    let mut ps = ParamSet::defaults(&(def.spec)().params);
    for (k, v) in [on("n09"), ch("n09.ref", 2), int("n09.num", 9)] {
        ps.set(k, v);
    }
    let e = collect_with(def, &d, &sc, &ps, 1 << 24).unwrap_err();
    assert!(e.user_message().contains("Track 9 does not exist"));
}

#[test]
fn qnt_ioi_cleanup_snaps_intervals_and_keeps_the_drift() {
    // Unit 240, multiples 1, 2, 4: intervals 250 / 220 / 260 → 240 each,
    // from the first note's own start (10, not the grid's 0).
    let set = [on("n10"), list("n10.mult", &[1, 2, 4])];
    let v = run(
        "quantize",
        &[(10, 50, 60), (260, 50, 61), (480, 50, 62), (740, 50, 63)],
        &set,
    );
    assert_eq!(starts(&v), vec![10, 250, 490, 730]);
    // 500 → 480 (2 units), 900 → 960 (4 units, the nearest allowed), 30 →
    // 0 (shorter than half a unit: one onset); a chord moves together.
    let v = run(
        "quantize",
        &[
            (0, 50, 60),
            (30, 50, 61),
            (530, 50, 62),
            (530, 50, 66),
            (1430, 50, 63),
        ],
        &set,
    );
    assert_eq!(starts(&v), vec![0, 0, 480, 480, 1440]);
    // A rest longer than the longest interval: every phrase re-anchors at its
    // own start; from the first note the drift (−40) carries on.
    let notes = &[
        (0, 100, 60),
        (260, 100, 61),
        (520, 100, 62),
        (3000, 100, 63),
        (3250, 100, 64),
    ];
    let v = run("quantize", notes, &set);
    assert_eq!(starts(&v), vec![0, 240, 480, 3000, 3240]);
    let mut first = set.to_vec();
    first.push(ch("n10.anchor", 0));
    let v = run("quantize", notes, &first);
    assert_eq!(starts(&v), vec![0, 240, 480, 2960, 3200]);
    // The start strength mixes toward the cleaned onsets.
    let mut half = set.to_vec();
    half.push(fl("start", 50.0));
    let v = run(
        "quantize",
        &[(10, 50, 60), (260, 50, 61), (530, 50, 62)],
        &half,
    );
    assert_eq!(starts(&v), vec![10, 255, 510]);
}

#[test]
fn qnt_velocity_level_snap_rounds_to_levels_or_a_list() {
    // 8 levels: 1, 19, 37, 55, 73, 91, 109, 127.
    let notes = vec![
        tn(0, 10, 60, 100),
        tn(0, 10, 61, 60),
        tn(0, 10, 62, 127),
        tn(0, 10, 63, 2),
    ];
    let go = |set: &[(&str, ParamValue)]| -> Vec<u8> {
        let v = run_src("quantize", notes.clone(), vec![], &[0], set, None);
        (60..=63)
            .map(|p| v.iter().find(|n| n.pitch == p).unwrap().vel)
            .collect()
    };
    assert_eq!(go(&[on("n11")]), vec![91, 55, 127, 1], "a tie goes down");
    assert_eq!(go(&[on("n11"), ch("n11.round", 2)]), vec![109, 73, 127, 19]);
    assert_eq!(go(&[on("n11"), ch("n11.round", 1)]), vec![91, 55, 127, 1]);
    assert_eq!(
        go(&[on("n11"), fl("n11.strength", 50.0)]),
        vec![96, 58, 127, 2]
    );
    assert_eq!(
        go(&[on("n11"), list("n11.allowed", &[40, 80, 120])]),
        vec![80, 40, 120, 40]
    );
    assert_eq!(go(&[on("n11"), int("n11.levels", 2)]), vec![127, 1, 127, 1]);
}

#[test]
fn qnt_new_functions_compose_in_their_declared_places() {
    // Magnet beats IOI beats self-groove beats cluster; n03 runs after the
    // starts are decided, n11 last; per-note-only settings stay pointwise.
    let reference = vec![tn(1000, 50, 48, 100)];
    let notes = vec![
        tn(0, 50, 60, 100),
        tn(260, 50, 60, 100),
        tn(500, 50, 60, 100),
        tn(930, 50, 60, 100),
    ];
    let set = [
        on("n04"),
        on("n07"),
        on("n09"),
        on("n10"),
        list("n10.mult", &[1, 2]),
        on("n03"),
        on("n11"),
    ];
    let v = run_src("quantize", notes, reference, &[0], &set, None);
    // IOI: 0, 240, 480, then 430 → 480 → 960; the magnet pulls 930 to 1000.
    assert_eq!(starts(&v), vec![0, 240, 480, 1000]);
    assert!(v.iter().all(|n| n.vel == 91));
    // Per-note functions only: the kernel is pointwise (lazy preview).
    let t = tool("quantize").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for k in ["n01", "n02", "n05", "n06", "n08", "n11"] {
        ps.set(k, ParamValue::Bool(true));
    }
    let src = Source::from_notes(
        vec![tn(0, 10, 60, 100), tn(3000, 10, 60, 100)],
        vec![SourceTrack {
            id: TrackId(1),
            index: 0,
            content: None,
            revision: 0,
            subs: vec![(0, 0)],
            all: false,
            insert_only: false,
            frame: 0,
        }],
    );
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    assert!(t.kernel(&ps, &b).unwrap().as_point().is_some());
    for k in ["n03", "n04", "n07", "n09", "n10"] {
        let mut whole = ps.clone();
        whole.set(k, ParamValue::Bool(true));
        assert!(t.kernel(&whole, &b).unwrap().as_point().is_none(), "{k}");
    }
}

