#[test]
fn flam_new_functions_off_leave_v08_results_unchanged() {
    let notes = flam_fixture();
    for (i, s) in flam_v08_settings().into_iter().enumerate() {
        let mut set = s.clone();
        for k in ALL11 {
            set.push((k, ParamValue::Bool(false)));
        }
        assert_eq!(
            fingerprint(&run_vel("flam", &notes, &set)),
            FLAM_V08[i],
            "setting {i}"
        );
    }
}

/// Flam in ticks (no milliseconds): `time` ticks per stroke, `count`
/// strokes (a1), plus `extra`.
fn flam_ticks(
    time: f64,
    count: i64,
    extra: &[(&'static str, ParamValue)],
) -> Vec<(&'static str, ParamValue)> {
    let mut v = vec![
        flag("absolute", false),
        fl("time", time),
        on("a1"),
        int("a1.count", count),
    ];
    v.extend(extra.iter().cloned());
    v
}

/// The strokes (notes at velocity `vel`) as (start, pitch), by start then
/// pitch.
fn strokes_at(v: &[TNote], vel: u8) -> Vec<(u64, u8)> {
    let mut o: Vec<(u64, u8)> = v
        .iter()
        .filter(|n| n.vel == vel)
        .map(|n| (n.start, n.pitch))
        .collect();
    o.sort_unstable();
    o
}

#[test]
fn flam_approach_path_walks_from_the_previous_note_or_an_interval() {
    let notes = [(960, 200, 60, 100), (1920, 200, 67, 100)];
    // From the previous note (C → G, 7 semitones in 4 strokes: 0, 2, 4, 5);
    // the first note has none and starts the fixed interval below (−5).
    let set = flam_ticks(40.0, 4, &[on("n01")]);
    assert_eq!(
        strokes_at(&run_vel("flam", &notes, &set), 60),
        vec![
            (800, 55),
            (840, 56),
            (880, 58),
            (920, 59),
            (1760, 60),
            (1800, 62),
            (1840, 64),
            (1880, 65)
        ]
    );
    // A fixed interval of an octave below: 12 steps in 4 → 0, 3, 6, 9.
    let set = flam_ticks(
        40.0,
        4,
        &[on("n01"), ch("n01.from", 1), int("n01.interval", -12)],
    );
    let s = strokes_at(&run_vel("flam", &notes, &set), 60);
    assert_eq!(
        s[4..].to_vec(),
        vec![(1760, 55), (1800, 58), (1840, 61), (1880, 64)]
    );
    // In C major: G3 (55) → G4 (67) is 7 degrees: 0, 2, 4, 5 → G A? no:
    // degrees from G: 55, 59 (B), 62 (D), 64 (E).
    let set = flam_ticks(
        40.0,
        4,
        &[
            on("n01"),
            ch("n01.from", 1),
            int("n01.interval", -12),
            ch("n01.path", 1),
        ],
    );
    let s = strokes_at(&run_vel("flam", &notes, &set), 60);
    assert_eq!(
        s[4..].iter().map(|x| x.1).collect::<Vec<_>>(),
        vec![55, 59, 62, 64]
    );
    // Repeat the start.
    let set = flam_ticks(40.0, 3, &[on("n01"), ch("n01.path", 2)]);
    let s = strokes_at(&run_vel("flam", &notes, &set), 60);
    assert_eq!(
        s[3..].iter().map(|x| x.1).collect::<Vec<_>>(),
        vec![60, 60, 60]
    );
}

#[test]
fn flam_metric_mask_flams_chosen_grid_positions_with_their_counts() {
    // Beats 1 – 4 of a 4/4 bar (one a little early); grid 1/4.
    let notes = [
        (0, 100, 60, 100),
        (945, 100, 62, 100),
        (1920, 100, 64, 100),
        (2880, 100, 65, 100),
    ];
    let starts = |set: &[(&'static str, ParamValue)]| -> Vec<u64> {
        strokes_at(&run_vel("flam", &notes, set), 60)
            .into_iter()
            .map(|x| x.0)
            .collect()
    };
    // Default mask 0, 1: beats 2 and 4 only, one stroke each.
    let set = flam_ticks(40.0, 1, &[on("n02")]);
    assert_eq!(starts(&set), vec![905, 2840]);
    // Strokes per position 1, 2, 3, 4: beat 2 gets 2, beat 4 gets 4.
    let set = flam_ticks(40.0, 1, &[on("n02"), list("n02.strokes", &[1, 2, 3, 4])]);
    assert_eq!(starts(&set), vec![865, 905, 2720, 2760, 2800, 2840]);
    // Every position flams, 0 strokes on beats 1 and 3.
    let set = flam_ticks(
        40.0,
        1,
        &[
            on("n02"),
            list("n02.mask", &[1]),
            list("n02.strokes", &[0, 1]),
        ],
    );
    assert_eq!(starts(&set), vec![905, 2840]);
}

#[test]
fn flam_accent_gate_scales_strokes_and_spacing_above_the_threshold() {
    let notes = [
        (960, 100, 60, 60),
        (1920, 100, 62, 90),
        (2880, 100, 64, 109),
        (3840, 100, 65, 127),
    ];
    let set = flam_ticks(
        40.0,
        1,
        &[
            on("n03"),
            int("n03.threshold", 90),
            int("n03.strokes", 5),
            fl("n03.spacing", 200.0),
        ],
    );
    let out = run_vel("flam", &notes, &set);
    let strokes: Vec<(u64, u8)> = {
        let mut s: Vec<(u64, u8)> = out
            .iter()
            .filter(|n| !notes.iter().any(|m| m.0 == n.start && m.2 == n.pitch))
            .map(|n| (n.start, n.pitch))
            .collect();
        s.sort_unstable();
        s
    };
    // vel 60: none; 90: t = 0 → 1 stroke 40 before; 109: t = 19 / 37 →
    // round(1 + 4t) = 3 strokes, spacing 40 (1 + t) = 60.54; 127: 5 strokes
    // 80 apart.
    let sp = 40.0 * (1.0 + 19.0 / 37.0);
    let mut want = vec![(1880, 62)];
    for j in (1..=3).rev() {
        want.push((2880 - (sp * j as f64).round() as u64, 64));
    }
    for j in (1..=5).rev() {
        want.push((3840 - 80 * j, 65));
    }
    want.sort_unstable();
    assert_eq!(strokes, want);
}

#[test]
fn flam_stroke_channels_cycle_per_stroke_or_per_note() {
    let notes = [
        (960, 100, 60, 100),
        (1920, 100, 62, 100),
        (2880, 100, 64, 100),
    ];
    let chans = |set: &[(&'static str, ParamValue)]| -> Vec<(u64, u8)> {
        let mut o: Vec<(u64, u8)> = run_vel("flam", &notes, set)
            .iter()
            .map(|n| (n.start, n.ch))
            .collect();
        o.sort_unstable();
        o
    };
    let set = flam_ticks(40.0, 3, &[on("n04"), list("n04.channels", &[10, 11])]);
    let c = chans(&set);
    // Per stroke: nearest (j = 1) → 10, j = 2 → 11, j = 3 → 10; the notes
    // keep channel 1.
    assert_eq!(&c[0..4], &[(840, 9), (880, 10), (920, 9), (960, 0)]);
    let set = flam_ticks(
        40.0,
        3,
        &[on("n04"), list("n04.channels", &[10, 11]), ch("n04.per", 1)],
    );
    let c = chans(&set);
    assert_eq!(
        c.iter()
            .filter(|x| x.0 % 960 != 0)
            .map(|x| x.1)
            .collect::<Vec<_>>(),
        vec![9, 9, 9, 10, 10, 10, 9, 9, 9]
    );
}

#[test]
fn flam_cluster_strokes_stack_lattice_neighbours_along_a_curve() {
    let notes = [(960, 100, 60, 100)];
    let pitches = |set: &[(&'static str, ParamValue)]| -> Vec<(u64, u8)> {
        strokes_at(&run_vel("flam", &notes, set), 60)
    };
    let set = flam_ticks(40.0, 1, &[on("n05"), int("n05.size", 3)]);
    assert_eq!(pitches(&set), vec![(920, 60), (920, 61), (920, 62)]);
    let set = flam_ticks(
        40.0,
        1,
        &[on("n05"), int("n05.size", 3), ch("n05.place", 1)],
    );
    assert_eq!(pitches(&set), vec![(920, 58), (920, 59), (920, 60)]);
    let set = flam_ticks(
        40.0,
        1,
        &[on("n05"), int("n05.size", 4), ch("n05.place", 2)],
    );
    assert_eq!(
        pitches(&set),
        vec![(920, 59), (920, 60), (920, 61), (920, 62)]
    );
    // C major above C: C D E; octaves: C C' C''.
    let set = flam_ticks(40.0, 1, &[on("n05"), int("n05.size", 3), ch("n05.kind", 1)]);
    assert_eq!(pitches(&set), vec![(920, 60), (920, 62), (920, 64)]);
    let set = flam_ticks(40.0, 1, &[on("n05"), int("n05.size", 3), ch("n05.kind", 2)]);
    assert_eq!(pitches(&set), vec![(920, 60), (920, 72), (920, 84)]);
    // Size 4 along a rising line over 3 strokes: 1, 2, 4 notes (farthest
    // first).
    let set = flam_ticks(
        40.0,
        3,
        &[
            on("n05"),
            int("n05.size", 4),
            curve("n05.curve", Curve::line(0.0, 1.0)),
        ],
    );
    let s = pitches(&set);
    let per = |t: u64| s.iter().filter(|x| x.0 == t).count();
    assert_eq!((per(840), per(880), per(920)), (1, 2, 4));
}

#[test]
fn flam_offset_list_places_strokes_in_ticks_milliseconds_or_percent() {
    let notes = [(9600, 100, 60, 100)];
    let starts_lens = |set: &[(&'static str, ParamValue)]| -> Vec<(u64, u64)> {
        let mut o: Vec<(u64, u64)> = run_vel("flam", &notes, set)
            .iter()
            .filter(|n| n.vel == 60)
            .map(|n| (9600 - n.start, n.dur))
            .collect();
        o.sort_unstable();
        o
    };
    // 30, 50, 120, then the cycle again 120 further: 150, 170; lengths 0.9
    // × the gap to the next stroke toward the note.
    let set = flam_ticks(40.0, 5, &[on("n06"), list("n06.offsets", &[30, 50, 120])]);
    assert_eq!(
        starts_lens(&set),
        vec![(30, 27), (50, 18), (120, 63), (150, 27), (170, 18)]
    );
    // Milliseconds at 120 BPM / 960 PPQN (1.92 ticks per ms, first tick at
    // or after): 10 ms → 19, 25 ms → 48.
    let set = flam_ticks(
        40.0,
        2,
        &[on("n06"), list("n06.offsets", &[10, 25]), ch("n06.unit", 1)],
    );
    assert_eq!(
        starts_lens(&set).iter().map(|x| x.0).collect::<Vec<_>>(),
        vec![19, 48]
    );
    // % of the time (40 ticks): 50 % → 20, 100 % → 40.
    let set = flam_ticks(
        40.0,
        2,
        &[
            on("n06"),
            list("n06.offsets", &[50, 100]),
            ch("n06.unit", 2),
        ],
    );
    assert_eq!(
        starts_lens(&set).iter().map(|x| x.0).collect::<Vec<_>>(),
        vec![20, 40]
    );
}

#[test]
fn flam_mirrored_strokes_open_like_a_fan_around_the_note() {
    let notes = [(960, 100, 60, 100)];
    let set = flam_ticks(40.0, 2, &[on("n07"), int("n07.spread", 2)]);
    let out = run_vel("flam", &notes, &set);
    let mut s: Vec<(u64, u8, u8)> = out
        .iter()
        .filter(|n| n.start < 960)
        .map(|n| (n.start, n.pitch, n.vel))
        .collect();
    s.sort_unstable();
    // j = 2 (880): 64 and its twin 56 at 80 %; j = 1 (920): 62 and 58.
    assert_eq!(
        s,
        vec![(880, 56, 48), (880, 64, 60), (920, 58, 48), (920, 62, 60)]
    );
    // In C major, one degree per stroke: D / B, E / A.
    let set = flam_ticks(40.0, 2, &[on("n07"), int("n07.spread", 1), ch("n07.in", 1)]);
    let mut p: Vec<u8> = run_vel("flam", &notes, &set)
        .iter()
        .filter(|n| n.start < 960)
        .map(|n| n.pitch)
        .collect();
    p.sort_unstable();
    assert_eq!(p, vec![57, 59, 62, 64]);
}

#[test]
fn flam_roll_rate_fills_the_lead_in_at_a_gliding_rate_in_real_time() {
    // At 120 BPM / 960 PPQN 1 µs = 0.00192 ticks; the note at 2 s.
    let notes = [(3840, 100, 60, 100)];
    let dists = |set: &[(&'static str, ParamValue)]| -> Vec<u64> {
        let mut d: Vec<u64> = run_vel("flam", &notes, set)
            .iter()
            .filter(|n| n.vel == 60)
            .map(|n| n.start.abs_diff(3840))
            .collect();
        d.sort_unstable();
        d
    };
    let roll = |from: f64, to: f64, most: i64| {
        flam_ticks(
            40.0,
            1,
            &[
                on("n08"),
                fl("n08.lead", 500.0),
                fl("n08.from", from),
                fl("n08.to", to),
                int("n08.most", most),
            ],
        )
    };
    // 10 Hz for 0.5 s: 5 strokes, 100 ms apart.
    assert_eq!(dists(&roll(10.0, 10.0, 64)), vec![192, 384, 576, 768, 960]);
    // 10 → 30 Hz: phase 10 τ + 20 τ² reaches k = 0 … 9 at
    // τ = (−10 + √(100 + 80 k)) / 40; each stroke at the first tick at or
    // after its time.
    let want: Vec<u64> = {
        let mut w: Vec<u64> = (0..10)
            .map(|k| {
                let tau = (-10.0 + (100.0 + 80.0 * f64::from(k)).sqrt()) / 40.0;
                let us = 2_000_000 - ((0.5 - tau) * 1e6).round() as u64;
                3840 - (us * 960).div_ceil(500_000)
            })
            .collect();
        w.sort_unstable();
        w
    };
    let got = dists(&roll(10.0, 30.0, 64));
    assert_eq!(got, want);
    // The gaps shrink toward the note (the rate rises).
    assert!(
        got.windows(3).all(|w| w[1] - w[0] <= w[2] - w[1] + 1),
        "{got:?}"
    );
    // Most 4: the 4 nearest the note.
    assert_eq!(dists(&roll(10.0, 30.0, 4)), want[..4].to_vec());
    // After the note (Before off): the same distances after it.
    let mut set = roll(10.0, 10.0, 64);
    set.push(flag("before", false));
    let after: Vec<u64> = run_vel("flam", &notes, &set)
        .iter()
        .filter(|n| n.vel == 60)
        .map(|n| n.start)
        .collect();
    assert!(after.iter().all(|&s| s > 3840));
    assert_eq!(dists(&set), vec![192, 384, 576, 768, 960]);
}

#[test]
fn flam_stroke_grid_snaps_strokes_toward_the_bar_grid() {
    let notes = [(1000, 100, 60, 100)];
    let starts = |set: &[(&'static str, ParamValue)]| -> Vec<u64> {
        strokes_at(&run_vel("flam", &notes, set), 60)
            .into_iter()
            .map(|x| x.0)
            .collect()
    };
    // Strokes at 960 and 920; grid 1/64 = 60 ticks: 960, 900.
    let set = flam_ticks(40.0, 2, &[on("n09"), ch("n09.grid", 6)]);
    assert_eq!(starts(&set), vec![900, 960]);
    // Half strength: 920 → 910.
    let set = flam_ticks(
        40.0,
        2,
        &[on("n09"), ch("n09.grid", 6), fl("n09.strength", 50.0)],
    );
    assert_eq!(starts(&set), vec![910, 960]);
    // Bars of 3/4 restart the grid: a 1/2 grid in bar 2 (from 2880) has
    // 2880, 4800 — not the song's 1920, 3840.
    let mut ctx = Ctx::simple(960);
    ctx.meter = MeterMap::new(Division::ppqn(960), &[(0, 3, 2)]);
    let notes = [(3400, 100, 60, 100)];
    let set = flam_ticks(100.0, 1, &[on("n09"), ch("n09.grid", 1)]);
    let s: Vec<u64> = strokes_at(&run_vel_in("flam", &notes, &set, Some(ctx)), 60)
        .into_iter()
        .map(|x| x.0)
        .collect();
    // 3300 → 2880 (the song grid would give 3840).
    assert_eq!(s, vec![2880]);
}

#[test]
fn flam_chord_tone_graces_break_the_chord_before_the_note() {
    let notes = [
        (960, 100, 60, 100),
        (960, 100, 64, 100),
        (960, 100, 67, 100),
        (1920, 100, 62, 100),
    ];
    let base = flam_ticks(40.0, 3, &[on("n10")]);
    // Up: C E G before every chord note (each note has its own 3 strokes
    // at 840 / 880 / 920 → grouped by time).
    let out = run_vel("flam", &notes, &base);
    let at = |t: u64| -> Vec<u8> {
        let mut p: Vec<u8> = out
            .iter()
            .filter(|n| n.start == t)
            .map(|n| n.pitch)
            .collect();
        p.sort_unstable();
        p
    };
    assert_eq!(
        (at(840), at(880), at(920)),
        (vec![60, 60, 60], vec![64, 64, 64], vec![67, 67, 67])
    );
    // The single D: its own chord is D alone.
    assert_eq!(at(1800), vec![62]);
    // Previous chord: D's strokes are C E G.
    let mut set = base.clone();
    set.push(ch("n10.source", 1));
    let out = run_vel("flam", &notes, &set);
    let d: Vec<u8> = {
        let mut s: Vec<(u64, u8)> = out
            .iter()
            .filter(|n| n.start > 1000 && n.start < 1920)
            .map(|n| (n.start, n.pitch))
            .collect();
        s.sort_unstable();
        s.into_iter().map(|x| x.1).collect()
    };
    assert_eq!(d, vec![60, 64, 67]);
    // Down, and nearest last (for E: C (4 away), G (3), E).
    let mut set = base.clone();
    set.push(ch("n10.order", 1));
    let out = run_vel("flam", &notes, &set);
    let p = |t: u64| {
        out.iter()
            .filter(|n| n.start == t)
            .map(|n| n.pitch)
            .collect::<Vec<_>>()
    };
    assert!(p(840).iter().all(|&x| x == 67) && p(920).iter().all(|&x| x == 60));
    let mut set = flam_ticks(40.0, 3, &[on("n10"), ch("n10.order", 2)]);
    set.push(on("a9"));
    set.push(ch("a9.from", 2));
    let only_e = [
        (960, 100, 60, 100),
        (960, 100, 64, 100),
        (960, 100, 67, 100),
    ];
    let out = run_vel("flam", &only_e, &set);
    // Every chord note shares the timing; E's strokes: 60, 67, 64.
    let mut e: Vec<(u64, u8)> = out
        .iter()
        .filter(|n| n.start < 960 && n.vel == 60)
        .map(|n| (n.start, n.pitch))
        .collect();
    e.sort_unstable();
    assert!(e.contains(&(840, 60)) && e.contains(&(880, 67)) && e.contains(&(920, 64)));
    // Triad of the note in C major: D → D F A.
    let set = flam_ticks(40.0, 3, &[on("n10"), ch("n10.source", 2)]);
    let out = run_vel("flam", &[(1920, 100, 62, 100)], &set);
    let mut s: Vec<(u64, u8)> = out
        .iter()
        .filter(|n| n.vel == 60)
        .map(|n| (n.start, n.pitch))
        .collect();
    s.sort_unstable();
    assert_eq!(s, vec![(1800, 62), (1840, 65), (1880, 69)]);
}

#[test]
fn flam_nps_budget_keeps_every_window_within_the_budget_dropping_strokes_only() {
    // 40 notes 50 ms apart (96 ticks at 120 BPM), 3 strokes each 10 ticks
    // apart: 160 notes in 2 s.
    let notes: Vec<(u64, u64, u8, u8)> = (0..40u64)
        .map(|k| (960 + 96 * k, 60, 60 + (k % 12) as u8, 100))
        .collect();
    let us = |t: u64| t * 500_000 / 960;
    let check = |out: &[TNote], cap: usize, w: u64| {
        let mut t: Vec<u64> = out.iter().map(|n| us(n.start)).collect();
        t.sort_unstable();
        for &e in &t {
            let c = t.iter().filter(|&&s| s <= e && s + w > e).count();
            assert!(c <= cap, "{c} > {cap} in the window ending at {e} µs");
        }
    };
    for how in 0..3u32 {
        let set = flam_ticks(
            10.0,
            3,
            &[
                on("a3"),
                on("n11"),
                int("n11.nps", 60),
                fl("n11.window", 500.0),
                ch("n11.drop", how),
            ],
        );
        let out = run_vel("flam", &notes, &set);
        // Every source note stays.
        for n in &notes {
            assert!(
                out.iter()
                    .any(|m| m.start == n.0 && m.pitch == n.2 && m.vel == 100)
            );
        }
        // 60 per second over 0.5 s: at most 30 per window.
        check(&out, 30, 500_000);
        // Something was dropped (160 > what fits), not everything.
        assert!(out.len() < 160 && out.len() > 40, "{how}: {}", out.len());
        if how == 2 {
            // The earliest strokes go first: the strokes left are the later
            // ones (no stroke kept before one dropped in the same window).
            let kept: Vec<u64> = out
                .iter()
                .filter(|n| n.vel != 100)
                .map(|n| n.start)
                .collect();
            assert!(kept.iter().min().unwrap() > &960);
        }
    }
    // The quietest first: a3 ramps 30 % (nearest) → 90 % (farthest); with
    // room for one stroke per note the loud far stroke stays.
    let set = flam_ticks(
        10.0,
        3,
        &[
            on("a3"),
            on("n11"),
            int("n11.nps", 40),
            fl("n11.window", 1000.0),
            ch("n11.drop", 1),
        ],
    );
    let out = run_vel("flam", &notes, &set);
    let quiet = out.iter().filter(|n| n.vel == 30).count();
    let loud = out.iter().filter(|n| n.vel == 90).count();
    assert!(loud > quiet, "loud {loud} quiet {quiet}");
    // A budget the notes alone exceed keeps them all and drops every stroke
    // in those windows.
    let set = flam_ticks(
        10.0,
        3,
        &[on("n11"), int("n11.nps", 1), fl("n11.window", 1000.0)],
    );
    assert_eq!(run_vel("flam", &notes, &set).len(), 40);
}

// ================================================================ Limit

/// 160 notes: singles and chords of 2 – 5 voices on a 1/16 grid with up to
/// 20 ticks of looseness, pitches 20 – 110, velocities 1 – 127, lengths 10 –
/// 2,400, and repeated keys a few ticks apart (a fixed LCG, so the fixture
/// never changes).
fn limit_fixture() -> Vec<(u64, u64, u8, u8)> {
    let mut x: u64 = 0x11A1_7035;
    let mut next = |m: u64| {
        x = x
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (x >> 33) % m
    };
    let mut v: Vec<(u64, u64, u8, u8)> = Vec::new();
    let mut at = 0u64;
    while v.len() < 160 {
        let size = if next(3) == 0 { 2 + next(4) } else { 1 };
        let start = at + next(21);
        let mut pitches: Vec<u8> = Vec::new();
        while (pitches.len() as u64) < size {
            let p = 20 + next(91) as u8;
            if !pitches.contains(&p) {
                pitches.push(p);
            }
        }
        for &p in &pitches {
            v.push((start, 10 + next(2391), p, 1 + next(127) as u8));
        }
        // Now and then the first key again a few ticks later.
        if next(5) == 0 {
            v.push((
                start + 5 + next(40),
                10 + next(200),
                pitches[0],
                1 + next(127) as u8,
            ));
        }
        at += 240;
    }
    v.sort_unstable();
    v.dedup_by_key(|n| (n.0, n.2));
    v
}

/// Settings of the v0.8 Limit (base controls and each frozen function).
