#[test]
fn limit_new_functions_off_leave_v08_results_unchanged() {
    let notes = limit_fixture();
    for (i, s) in limit_v08_settings().into_iter().enumerate() {
        let mut set = s.clone();
        for k in ALL11 {
            set.push((k, ParamValue::Bool(false)));
        }
        assert_eq!(
            fingerprint(&run_vel("limit", &notes, &set)),
            LIMIT_V08[i],
            "setting {i}"
        );
    }
}

/// The v0.8 rule made neutral (chromatic, the whole keyboard) plus `extra`.
fn limit_neutral(extra: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut v = vec![ch("scale", 19), int("lo", 0), int("hi", 127)];
    v.extend(extra.iter().cloned());
    v
}

/// Runs Limit on hand-built notes over `tracks` track slots (each with the
/// subchannel ids `subs`).
fn limit_src(
    notes: Vec<TNote>,
    tracks: usize,
    subs: &[u32],
    set: &[(&'static str, ParamValue)],
    ctx: Option<Ctx>,
) -> Vec<TNote> {
    let tracks: Vec<SourceTrack> = (0..tracks)
        .map(|i| SourceTrack {
            id: TrackId(i as u32 + 1),
            index: i,
            content: None,
            revision: 0,
            subs: subs.iter().map(|&s| (s, 0)).collect(),
            all: false,
            insert_only: false,
            frame: 0,
        })
        .collect();
    let src = Source::from_notes(notes, tracks);
    let t = tool("limit").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in limit_neutral(set) {
        ps.set(k, val);
    }
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r.notes
}

/// (start, pitch, velocity) in time order.
fn spv(v: &[TNote]) -> Vec<(u64, u8, u8)> {
    let mut o: Vec<(u64, u8, u8)> = v.iter().map(|n| (n.start, n.pitch, n.vel)).collect();
    o.sort_unstable();
    o
}

#[test]
fn limit_velocity_range_clamps_compresses_and_folds() {
    let vels = [1u8, 10, 20, 64, 110, 120, 127];
    let notes: Vec<(u64, u64, u8, u8)> = vels
        .iter()
        .enumerate()
        .map(|(i, &v)| (i as u64 * 240, 100, 60, v))
        .collect();
    let out = |mode: u32| -> Vec<u8> {
        let set = limit_neutral(&[
            on("n01"),
            int("n01.lo", 20),
            int("n01.hi", 110),
            ch("n01.mode", mode),
            fl("n01.ratio", 4.0),
        ]);
        spv(&run_vel("limit", &notes, &set))
            .iter()
            .map(|x| x.2)
            .collect()
    };
    assert_eq!(out(0), [20, 20, 20, 64, 110, 110, 110]);
    // Distances beyond the range ÷ 4: 19 → 5 (4.75), 10 → 3 (2.5), 10 → 3,
    // 17 → 4.
    assert_eq!(out(1), [15, 17, 20, 64, 110, 113, 114]);
    // Reflected at 20 and 110 (a triangle of period 180).
    assert_eq!(out(2), [39, 30, 20, 64, 110, 100, 93]);
    // Low above high: the same range.
    let set = limit_neutral(&[on("n01"), int("n01.lo", 110), int("n01.hi", 20)]);
    let v: Vec<u8> = spv(&run_vel("limit", &notes, &set))
        .iter()
        .map(|x| x.2)
        .collect();
    assert_eq!(v, [20, 20, 20, 64, 110, 110, 110]);
}

#[test]
fn limit_length_limits_lengthen_cut_remove_and_split() {
    let notes: Vec<(u64, u64, u8, u8)> = [10u64, 60, 500, 1920, 5000]
        .iter()
        .enumerate()
        .map(|(i, &d)| (i as u64 * 10_000, d, 60, 100))
        .collect();
    let run_with = |short: u32, long: u32| {
        let set = limit_neutral(&[
            on("n02"),
            int("n02.shortest", 60),
            int("n02.longest", 1920),
            ch("n02.short", short),
            ch("n02.long", long),
        ]);
        run_vel("limit", &notes, &set)
    };
    assert_eq!(lens(&run_with(0, 0)), [60, 60, 500, 1920, 1920]);
    assert_eq!(lens(&run_with(1, 0)), [60, 500, 1920, 1920]);
    // 5,000 = 1,920 + 1,920 + 1,160, back to back.
    let v = run_with(0, 1);
    assert_eq!(lens(&v), [60, 60, 500, 1920, 1920, 1920, 1160]);
    let tail: Vec<u64> = spd(&v)[4..].iter().map(|x| x.0).collect();
    assert_eq!(tail, [40_000, 41_920, 43_840]);
    // A remainder shorter than the shortest: lengthened or removed.
    let odd = [(0u64, 3860u64, 60u8, 100u8)];
    for (short, want) in [(0u32, vec![1920u64, 1920, 60]), (1, vec![1920, 1920])] {
        let set = limit_neutral(&[
            on("n02"),
            int("n02.shortest", 60),
            int("n02.longest", 1920),
            ch("n02.short", short),
            ch("n02.long", 1),
        ]);
        assert_eq!(lens(&run_vel("limit", &odd, &set)), want);
    }
    // The preflight counts the pieces exactly: one long note among many
    // short ones is not refused by the worst case.
    let mut many: Vec<TNote> = (0..1000).map(|i| tn(i * 100, 10, 60, 100)).collect();
    many.push(tn(200_000, 1_000_000, 64, 100));
    let set = [
        on("n02"),
        int("n02.shortest", 1),
        int("n02.longest", 10),
        ch("n02.long", 1),
    ];
    assert_eq!(limit_src(many, 1, &[0], &set, None).len(), 1000 + 100_000);
}

#[test]
fn limit_polyphony_cap_removes_by_priority_until_n_sound() {
    // A chord of five: pitch, velocity, length.
    let chord: Vec<TNote> = [
        (60u8, 50u8, 960u64),
        (64, 40, 900),
        (67, 30, 800),
        (72, 20, 700),
        (76, 10, 600),
    ]
    .iter()
    .map(|&(p, v, d)| tn(0, d, p, v))
    .collect();
    let cap = |first: u32| -> Vec<u8> {
        let set = [on("n03"), int("n03.most", 3), ch("n03.first", first)];
        let mut p: Vec<u8> = limit_src(chord.clone(), 1, &[0], &set, None)
            .iter()
            .map(|n| n.pitch)
            .collect();
        p.sort_unstable();
        p
    };
    assert_eq!(cap(0), [60, 64, 67], "quietest");
    // The middle of five (67), then the lower middle of four (64).
    assert_eq!(cap(1), [60, 72, 76], "inner voices");
    assert_eq!(cap(2), [60, 64, 67], "shortest");
    // Newest: staggered starts, two at a time.
    let stairs: Vec<TNote> = (0..4)
        .map(|k| tn(k * 100, 2000, 60 + k as u8, 100))
        .collect();
    let set = [on("n03"), int("n03.most", 2), ch("n03.first", 3)];
    let v = limit_src(stairs, 1, &[0], &set, None);
    assert_eq!(spd(&v).iter().map(|x| x.0).collect::<Vec<_>>(), [0, 100]);
    // Per track or over all selected.
    let mut two: Vec<TNote> = Vec::new();
    for t in 0..2u16 {
        for p in [60u8, 64] {
            two.push(TNote {
                track: t,
                ..tn(0, 480, p + t as u8 * 12, 100)
            });
        }
    }
    let set = [on("n03"), int("n03.most", 2)];
    assert_eq!(limit_src(two.clone(), 2, &[0], &set, None).len(), 4);
    let set = [on("n03"), int("n03.most", 2), ch("n03.scope", 1)];
    assert_eq!(limit_src(two, 2, &[0], &set, None).len(), 2);
    // Muted notes never sound and always stay.
    let mut m = chord.clone();
    m[4].flags = 2;
    let set = [on("n03"), int("n03.most", 3), ch("n03.first", 0)];
    let mut p: Vec<u8> = limit_src(m, 1, &[0], &set, None)
        .iter()
        .map(|n| n.pitch)
        .collect();
    p.sort_unstable();
    assert_eq!(p, [60, 64, 67, 76]);
    // On the fixture, every order and cap: the brute-force replay of the
    // rule, Poly ≤ the cap; a cap the notes already hold changes nothing.
    let notes = limit_fixture();
    let base = run_vel("limit", &notes, &limit_neutral(&[]));
    let worst = worst_poly(&base);
    for first in 0..4 {
        for most in [1i64, 2, 3, 5] {
            let set = limit_neutral(&[on("n03"), int("n03.most", most), ch("n03.first", first)]);
            let v = run_vel("limit", &notes, &set);
            assert!(worst_poly(&v) <= most as usize, "{first} {most}");
            let want = poly_replay(&base, most as usize, first);
            assert_eq!(spd(&v), spd(&want), "{first} {most}");
        }
        let set = limit_neutral(&[
            on("n03"),
            int("n03.most", worst as i64),
            ch("n03.first", first),
        ]);
        assert_eq!(spd(&run_vel("limit", &notes, &set)), spd(&base));
    }
}

/// The polyphony cap's rule replayed by brute force: at each onset, while
/// more than `cap` sound, remove the quietest / the newest at the middle
/// pitch / the shortest / the newest (ties: the later start, the higher
/// pitch — the source's order).
fn poly_replay(notes: &[TNote], cap: usize, first: u32) -> Vec<TNote> {
    let mut keep = vec![true; notes.len()];
    let mut onsets: Vec<u64> = notes.iter().map(|n| n.start).collect();
    onsets.sort_unstable();
    onsets.dedup();
    for t in onsets {
        loop {
            let sounding: Vec<usize> = (0..notes.len())
                .filter(|&i| keep[i] && notes[i].start <= t && t < notes[i].end())
                .collect();
            if sounding.len() <= cap {
                break;
            }
            let x = |i: usize| &notes[i];
            let v = match first {
                0 => *sounding
                    .iter()
                    .max_by_key(|&&i| (255 - x(i).vel, x(i).start, x(i).pitch))
                    .unwrap(),
                1 => {
                    let mut by: Vec<u8> = sounding.iter().map(|&i| x(i).pitch).collect();
                    by.sort_unstable();
                    let p = by[(by.len() - 1) / 2];
                    *sounding
                        .iter()
                        .filter(|&&i| x(i).pitch == p)
                        .max_by_key(|&&i| x(i).start)
                        .unwrap()
                }
                2 => *sounding
                    .iter()
                    .max_by_key(|&&i| (u64::MAX - x(i).dur, x(i).start, x(i).pitch))
                    .unwrap(),
                _ => *sounding
                    .iter()
                    .max_by_key(|&&i| (x(i).start, x(i).pitch))
                    .unwrap(),
            };
            keep[v] = false;
        }
    }
    notes
        .iter()
        .zip(&keep)
        .filter(|x| *x.1)
        .map(|x| *x.0)
        .collect()
}

#[test]
fn limit_onset_rate_limit_caps_starts_per_tick_and_per_window() {
    // Per tick: five starts at 0, two at 100; at most two per tick.
    let mut v: Vec<TNote> = (0..5).map(|k| tn(0, 50, 60 + k, 10 + 10 * k)).collect();
    v.push(tn(100, 50, 70, 5));
    v.push(tn(100, 50, 71, 6));
    let set = [on("n04"), int("n04.most", 2), ch("n04.per", 0)];
    let out = limit_src(v.clone(), 1, &[0], &set, None);
    assert_eq!(
        spv(&out),
        [(0, 63, 40), (0, 64, 50), (100, 70, 5), (100, 71, 6)]
    );
    // The highest / lowest / shortest first.
    for (first, want) in [(2u32, [60u8, 61]), (3, [63, 64])] {
        let set = [
            on("n04"),
            int("n04.most", 2),
            ch("n04.per", 0),
            ch("n04.first", first),
        ];
        let p: Vec<u8> = spv(&limit_src(v.clone(), 1, &[0], &set, None))
            .iter()
            .filter(|x| x.0 == 0)
            .map(|x| x.1)
            .collect();
        assert_eq!(p, want);
    }
    // Per window: 192 starts per second (every 10 ticks at 120 BPM); at
    // most 50 in any 1,000 ms — about 50 a second stay, removed evenly
    // even where the order ties (one length everywhere).
    let dense: Vec<TNote> = (0..400)
        .map(|k| tn(k * 10, 5, 40 + (k * 7 % 40) as u8, 1 + (k * 13 % 127) as u8))
        .collect();
    for first in 0..4 {
        let set = [
            on("n04"),
            int("n04.most", 50),
            fl("n04.window", 1000.0),
            ch("n04.first", first),
        ];
        let out = limit_src(dense.clone(), 1, &[0], &set, None);
        assert!(worst_window(&out, 1000) <= 50, "{first}");
        assert!(out.len() >= 50 * 2, "{first}: {}", out.len());
    }
    // The window is real time: at 60 BPM the same ticks hold half the
    // starts per second, so a cap of 100 removes nothing.
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[(0, TempoValue::Micros(1_000_000))],
    )));
    let set = [on("n04"), int("n04.most", 100), fl("n04.window", 1000.0)];
    assert_eq!(
        limit_src(dense.clone(), 1, &[0], &set, Some(ctx)).len(),
        400
    );
    assert!(limit_src(dense, 1, &[0], &set, None).len() < 400);
}

#[test]
fn limit_leap_limit_moves_folds_or_removes_by_the_previous_onset() {
    let line = [
        (0u64, 100u64, 60u8, 100u8),
        (240, 100, 79, 100),
        (480, 100, 62, 100),
        (720, 100, 40, 100),
    ];
    let fix = |how: u32| -> Vec<u8> {
        let set = limit_neutral(&[on("n05"), int("n05.leap", 12), ch("n05.fix", how)]);
        pitches(&run_vel("limit", &line, &set))
    };
    // Against the previous ORIGINAL pitch: 79 vs 60 → 67; 62 vs 79 → 74;
    // 40 vs 62 → 52.
    assert_eq!(fix(0), [60, 67, 74, 52]);
    // Reflected at the limit: 72 − 7, 67 + 5, 50 + 10.
    assert_eq!(fix(1), [60, 65, 72, 60]);
    assert_eq!(fix(2), [60]);
    // Below an octave the octave nearest it.
    let set = limit_neutral(&[on("n05"), int("n05.leap", 3)]);
    assert_eq!(
        pitches(&run_vel(
            "limit",
            &[(0, 10, 60, 100), (10, 10, 75, 100)],
            &set
        )),
        [60, 63]
    );
    // The previous onset's nearest pitch: a chord {48, 72} then 70.
    let set = limit_neutral(&[on("n05"), int("n05.leap", 5)]);
    let v = run_vel(
        "limit",
        &[(0, 10, 48, 100), (0, 10, 72, 100), (10, 10, 70, 100)],
        &set,
    );
    assert_eq!(pitches(&v), [48, 72, 70]);
    // Lines per MIDI channel: two interleaved lines far apart.
    let two: Vec<TNote> = (0..6)
        .map(|k| TNote {
            ch: (k % 2) as u8,
            ..tn(k * 100, 50, if k % 2 == 0 { 40 } else { 90 }, 100)
        })
        .collect();
    let by_track = limit_src(
        two.clone(),
        1,
        &[0],
        &[on("n05"), int("n05.leap", 12), ch("n05.fix", 2)],
        None,
    );
    assert_eq!(by_track.len(), 1);
    let by_channel = limit_src(
        two,
        1,
        &[0],
        &[
            on("n05"),
            int("n05.leap", 12),
            ch("n05.fix", 2),
            ch("n05.line", 2),
        ],
        None,
    );
    assert_eq!(by_channel.len(), 6);
}

#[test]
fn limit_chord_span_limit_moves_outer_voices_by_octaves() {
    let chord = [36u8, 60, 64, 67, 84];
    let notes: Vec<(u64, u64, u8, u8)> = chord.iter().map(|&p| (0, 480, p, 100)).collect();
    let span = |s: i64, keep: u32| -> Vec<u8> {
        let set = limit_neutral(&[on("n06"), int("n06.span", s), ch("n06.keep", keep)]);
        let mut p = pitches(&run_vel("limit", &notes, &set));
        p.sort_unstable();
        p
    };
    assert_eq!(span(24, 0), [36, 52, 55, 60, 60], "bass");
    assert_eq!(span(24, 1), [60, 60, 64, 67, 84], "top");
    assert_eq!(span(24, 2), [48, 60, 64, 67, 72], "centre");
    // Narrower than an octave: the octave nearest the window [36, 41].
    assert_eq!(span(5, 0), [36, 36, 36, 40, 43]);
    // Every chord fits; single notes stay.
    let fx = limit_fixture();
    let set = limit_neutral(&[on("n06"), int("n06.span", 12), int("n06.tol", 0)]);
    let v = run_vel("limit", &fx, &set);
    let mut by: std::collections::BTreeMap<u64, Vec<u8>> = Default::default();
    for n in &v {
        by.entry(n.start).or_default().push(n.pitch);
    }
    for (t, ps) in by {
        let (lo, hi) = (ps.iter().min().unwrap(), ps.iter().max().unwrap());
        assert!(hi - lo <= 12, "{t}: {ps:?}");
    }
    // The tolerance joins a strum into one chord.
    let strum = [
        (0u64, 480u64, 36u8, 100u8),
        (10, 480, 60, 100),
        (20, 480, 84, 100),
    ];
    for (tol, want) in [(30i64, vec![36u8, 48, 48]), (5, vec![36, 60, 84])] {
        let set = limit_neutral(&[on("n06"), int("n06.span", 12), int("n06.tol", tol)]);
        assert_eq!(pitches(&run_vel("limit", &strum, &set)), want);
    }
}

#[test]
fn limit_retrigger_spacing_removes_or_merges_close_repeats() {
    let notes = [
        (0u64, 100u64, 60u8, 100u8),
        (20, 100, 60, 100),
        (50, 300, 60, 100),
        (200, 50, 60, 100),
        (30, 100, 64, 100),
    ];
    let run_with = |action: u32| {
        let set = limit_neutral(&[on("n07"), int("n07.dist", 100), ch("n07.action", action)]);
        spd(&run_vel("limit", &notes, &set))
    };
    assert_eq!(run_with(0), [(0, 60, 100), (30, 64, 100), (200, 60, 50)]);
    // Merged: the kept note lasts to the latest end (350).
    assert_eq!(run_with(1), [(0, 60, 350), (30, 64, 100), (200, 60, 50)]);
    // Measured from the previous KEPT note: 60 goes, 120 stays.
    let set = limit_neutral(&[on("n07"), int("n07.dist", 100)]);
    let v = run_vel(
        "limit",
        &[(0, 10, 60, 100), (60, 10, 60, 100), (120, 10, 60, 100)],
        &set,
    );
    assert_eq!(spd(&v).iter().map(|x| x.0).collect::<Vec<_>>(), [0, 120]);
    // Same key: the pitch alone, with the MIDI channel, or the subchannel.
    let pair = vec![
        tn(0, 50, 60, 100),
        TNote {
            ch: 1,
            sub: 7,
            ..tn(20, 50, 60, 100)
        },
    ];
    for (same, n) in [(0u32, 1usize), (1, 2), (2, 2)] {
        let set = [on("n07"), int("n07.dist", 100), ch("n07.same", same)];
        assert_eq!(limit_src(pair.clone(), 1, &[0, 7], &set, None).len(), n);
    }
    // Across tracks too (one key on the synth).
    let tracks = vec![
        tn(0, 50, 60, 100),
        TNote {
            track: 1,
            ..tn(20, 50, 60, 100)
        },
    ];
    let set = [on("n07"), int("n07.dist", 100)];
    assert_eq!(limit_src(tracks, 2, &[0], &set, None).len(), 1);
}

#[test]
fn limit_time_window_wraps_folds_clamps_or_removes() {
    let starts = [200u64, 1000, 1499, 1500, 2300];
    let notes: Vec<(u64, u64, u8, u8)> = starts
        .iter()
        .enumerate()
        .map(|(i, &s)| (s, 10, 60 + i as u8, 100))
        .collect();
    let place = |how: u32| -> Vec<(u8, u64)> {
        let set = limit_neutral(&[
            on("n08"),
            int("n08.start", 1000),
            int("n08.len", 500),
            ch("n08.outside", how),
        ]);
        let mut v: Vec<(u8, u64)> = run_vel("limit", &notes, &set)
            .iter()
            .map(|n| (n.pitch, n.start))
            .collect();
        v.sort_unstable();
        v
    };
    // Wrap: modulo the length from the start.
    assert_eq!(
        place(0),
        [(60, 1200), (61, 1000), (62, 1499), (63, 1000), (64, 1300)]
    );
    // Fold: a triangle of period 1,000 ticks (1,500 → 1,499, its mirror).
    let fold = place(1);
    assert_eq!(fold[3], (63, 1499));
    for &(p, s) in &fold {
        let k = starts[usize::from(p - 60)] as i64 - 1000;
        let m = k.rem_euclid(1000);
        assert_eq!(s as i64, 1000 + if m < 500 { m } else { 999 - m });
    }
    assert_eq!(
        place(2),
        [(60, 1000), (61, 1000), (62, 1499), (63, 1499), (64, 1499)]
    );
    assert_eq!(place(3), [(61, 1000), (62, 1499)]);
}

#[test]
fn limit_allowed_channels_or_subchannels_remap_outside_notes() {
    let by_channel: Vec<TNote> = (0..8)
        .map(|c| TNote {
            ch: c,
            ..tn(u64::from(c) * 10, 5, 60, 100)
        })
        .collect();
    let remap = |list_: &[i64], how: u32| -> Vec<u8> {
        let set = [
            on("n09"),
            ch("n09.target", 0),
            list("n09.channels", list_),
            ch("n09.remap", how),
        ];
        let mut v: Vec<(u64, u8)> = limit_src(by_channel.clone(), 1, &[0], &set, None)
            .iter()
            .map(|n| (n.start, n.ch + 1))
            .collect();
        v.sort_unstable();
        v.into_iter().map(|x| x.1).collect()
    };
    // Channels 1 … 8 with 2 and 5 allowed.
    assert_eq!(remap(&[2, 5], 0), [2, 2, 2, 5, 5, 5, 5, 5], "nearest");
    assert_eq!(remap(&[2, 5], 1), [2, 2, 5, 5, 5, 2, 2, 2], "next in turn");
    assert_eq!(remap(&[5, 2], 2), [5, 2, 5, 5, 5, 5, 5, 5], "first allowed");
    // Subchannels by position in the track's list; the MIDI channel stays.
    let subs = [0u32, 10, 20, 30];
    let notes: Vec<TNote> = subs
        .iter()
        .enumerate()
        .map(|(i, &s)| TNote {
            sub: s,
            ch: 3,
            ..tn(i as u64 * 10, 5, 60, 100)
        })
        .collect();
    let run_subs = |allowed: &[i64], how: u32| -> Vec<(u32, u8)> {
        let set = [
            on("n09"),
            ch("n09.target", 1),
            list("n09.subs", allowed),
            ch("n09.remap", how),
        ];
        let mut v: Vec<(u64, u32, u8)> = limit_src(notes.clone(), 1, &subs, &set, None)
            .iter()
            .map(|n| (n.start, n.sub, n.ch))
            .collect();
        v.sort_unstable();
        v.into_iter().map(|x| (x.1, x.2)).collect()
    };
    assert_eq!(
        run_subs(&[1, 3], 0),
        [(10, 3), (10, 3), (10, 3), (30, 3)],
        "position 2: a tie, the lower"
    );
    assert_eq!(run_subs(&[1, 3], 1), [(10, 3), (10, 3), (30, 3), (30, 3)]);
    // Positions the track does not have: the notes stay.
    assert_eq!(run_subs(&[9], 0), [(0, 3), (10, 3), (20, 3), (30, 3)]);
    // Nothing allowed: refused with a sentence.
    let t = tool("limit").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    ps.set("n09", ParamValue::Bool(true));
    ps.set("n09.target", ParamValue::Choice(0));
    ps.set("n09.channels", ParamValue::List(vec![]));
    let src = Source::from_notes(vec![tn(0, 5, 60, 100)], vec![]);
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    assert!(t.kernel(&ps, &b).is_err());
}

#[test]
fn limit_range_compression_scales_distances_beyond_the_knee() {
    let ps = [60u8, 66, 72, 84, 48, 30, 73, 47];
    let notes: Vec<(u64, u64, u8, u8)> = ps
        .iter()
        .enumerate()
        .map(|(i, &p)| (i as u64 * 100, 50, p, 100))
        .collect();
    let squeeze = |snap: u32| -> Vec<u8> {
        let set = limit_neutral(&[
            on("n10"),
            int("n10.centre", 60),
            int("n10.knee", 6),
            fl("n10.ratio", 2.0),
            ch("n10.snap", snap),
            ch("key", 0),
        ]);
        pitches(&run_vel("limit", &notes, &set))
    };
    // 60 + 6 + (d − 6) / 2; 69.5 and 50.5 round toward the centre.
    assert_eq!(squeeze(0), [60, 66, 69, 75, 51, 42, 69, 51]);
    // In C major (the tool's key and scale, which the v0.8 rule then snaps
    // to, Above: 66 → 67): 75 → 74 or 76, a tie toward the centre; 51 → 50
    // or 52, a tie → 52; 42 → 41 or 43, a tie → 43; 50.5 → 50 (D).
    let set = limit_neutral(&[
        on("n10"),
        int("n10.centre", 60),
        int("n10.knee", 6),
        fl("n10.ratio", 2.0),
        ch("n10.snap", 1),
        ch("scale", 0),
    ]);
    let v = pitches(&run_vel("limit", &notes, &set));
    assert_eq!(v, [60, 67, 69, 74, 52, 43, 69, 50]);
    // The contour is kept: the order of the pitches never changes.
    let mut wide: Vec<(u64, u64, u8, u8)> = (0..=127u8)
        .map(|p| (u64::from(p) * 10, 5, p, 100))
        .collect();
    wide.sort_unstable();
    for ratio in [1.5, 3.0, 20.0] {
        let set = limit_neutral(&[on("n10"), int("n10.knee", 0), fl("n10.ratio", ratio)]);
        let v = pitches(&run_vel("limit", &wide, &set));
        assert!(v.windows(2).all(|w| w[0] <= w[1]), "{ratio}");
        assert_eq!(v[60], 60);
    }
}

#[test]
fn limit_octave_doubling_limit_keeps_lowest_highest_or_outer() {
    let chord = [36u8, 48, 60, 72, 64, 67];
    let notes: Vec<(u64, u64, u8, u8)> = chord.iter().map(|&p| (0, 480, p, 100)).collect();
    let thin = |most: i64, keep: u32| -> Vec<u8> {
        let set = limit_neutral(&[on("n11"), int("n11.most", most), ch("n11.keep", keep)]);
        let mut p = pitches(&run_vel("limit", &notes, &set));
        p.sort_unstable();
        p
    };
    assert_eq!(thin(1, 0), [36, 64, 67]);
    assert_eq!(thin(1, 1), [64, 67, 72]);
    assert_eq!(thin(2, 2), [36, 64, 67, 72]);
    assert_eq!(thin(3, 2), [36, 48, 64, 67, 72]);
    assert_eq!(thin(4, 0), [36, 48, 60, 64, 67, 72]);
    // Unisons count as copies; chords are separate.
    let v = vec![
        tn(0, 100, 60, 100),
        TNote {
            ch: 1,
            ..tn(0, 100, 60, 100)
        },
        tn(500, 100, 60, 100),
    ];
    let set = [on("n11"), int("n11.most", 1)];
    assert_eq!(limit_src(v, 1, &[0], &set, None).len(), 2);
    // On the fixture: no chord keeps two notes of one pitch class.
    let set = limit_neutral(&[on("n11"), int("n11.most", 1), int("n11.tol", 0)]);
    let v = run_vel("limit", &limit_fixture(), &set);
    let mut seen = std::collections::BTreeSet::new();
    for n in &v {
        assert!(
            seen.insert((n.start, n.pitch % 12)),
            "{} {}",
            n.start,
            n.pitch
        );
    }
}

#[test]
fn limit_functions_compose_in_their_pipeline_order() {
    // n05 → n10 → the v0.8 rule → n06 / n11 → n01 / n09 / n08 / n02 →
    // n07 → n03 → n04: every new function at once on the fixture holds
    // every limit it sets.
    let set = vec![
        on("n01"),
        int("n01.lo", 30),
        int("n01.hi", 100),
        on("n02"),
        int("n02.shortest", 60),
        int("n02.longest", 960),
        ch("n02.long", 1),
        on("n03"),
        int("n03.most", 4),
        on("n04"),
        int("n04.most", 24),
        fl("n04.window", 500.0),
        on("n05"),
        int("n05.leap", 12),
        on("n06"),
        int("n06.span", 19),
        on("n07"),
        int("n07.dist", 60),
        on("n08"),
        int("n08.start", 960),
        int("n08.len", 15_360),
        on("n09"),
        ch("n09.target", 0),
        list("n09.channels", &[1]),
        on("n10"),
        int("n10.knee", 12),
        fl("n10.ratio", 3.0),
        on("n11"),
        int("n11.most", 2),
        on("a6"),
        on("a10"),
    ];
    let v = run_vel("limit", &limit_fixture(), &set);
    assert!(!v.is_empty());
    assert!(worst_poly(&v) <= 4);
    assert!(worst_window(&v, 500) <= 24);
    for n in &v {
        assert!((30..=100).contains(&n.vel));
        assert!((60..=960).contains(&n.dur));
        assert!((960..960 + 15_360).contains(&n.start));
        assert!((48..=72).contains(&n.pitch), "the v0.8 range");
        assert_eq!(n.ch, 0);
    }
    // Deterministic.
    assert_eq!(
        fingerprint(&v),
        fingerprint(&run_vel("limit", &limit_fixture(), &set))
    );
}

// ================================================================ Chord Progression

/// A melody over four bars of 4/4 (960 PPQN): 48 notes on an eighth grid,
/// C major with a few chromatic notes, a held note now and then (a fixed
/// LCG, so the fixture never changes).
fn cp_melody() -> Vec<(u64, u64, u8, u8)> {
    let mut x: u64 = 0xC0DE_0035;
    let mut next = |m: u64| {
        x = x
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (x >> 33) % m
    };
    const STEPS: [u8; 7] = [0, 2, 4, 5, 7, 9, 11];
    let mut v = Vec::new();
    for k in 0..32u64 {
        let pc = if next(8) == 0 {
            next(12) as u8
        } else {
            STEPS[next(7) as usize]
        };
        let len = if next(5) == 0 { 960 } else { 480 };
        v.push((k * 480, len, 72 + pc, 60 + next(60) as u8));
    }
    v
}

/// Settings of the v0.8 Chord Progression (modes, base controls and each
/// frozen function).
