#[test]
fn cp_new_functions_off_leave_v08_results_unchanged() {
    let notes = cp_melody();
    let n = cp_v08_settings().len();
    let off = |s: Vec<(&'static str, ParamValue)>| {
        let mut set = s;
        for k in ALL11 {
            set.push((k, ParamValue::Bool(false)));
        }
        set
    };
    for (i, s) in cp_v08_settings().into_iter().enumerate() {
        assert_eq!(
            fingerprint(&run_vel("chord_progression", &notes, &off(s))),
            CP_V08[i],
            "setting {i}"
        );
    }
    for (i, s) in cp_v08_settings().into_iter().take(4).enumerate() {
        assert_eq!(
            fingerprint(&run_unselected("chord_progression", &off(s))),
            CP_V08[n + i],
            "empty selection, setting {i}"
        );
    }
}

/// Runs a generator with nothing selected (one empty track, cursor 0).
fn run_unselected(id: &str, set: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    run_full(id, Vec::new(), set).notes
}

/// Runs a tool on hand-built selected notes of one track with subchannels
/// 0 – 3 (none: nothing selected): the whole result, its message included.
fn run_full(
    id: &str,
    notes: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track]);
    let t = tool(id).unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r
}

fn text(v: &str) -> (&'static str, ParamValue) {
    ("text", ParamValue::Text(v.to_owned()))
}

/// Typed chords, no bass, plus `extra` (nothing selected).
fn cp_typed(chords: &str, extra: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut v = vec![
        ch("mode", 1),
        text(chords),
        int("count", chords.split(' ').count() as i64),
        flag("bass", false),
    ];
    v.extend(extra.iter().cloned());
    v
}

/// The chord notes by onset: (start, length of the first, sorted pitches).
fn cp_chords(v: &[TNote]) -> Vec<(u64, u64, Vec<u8>)> {
    let mut by: std::collections::BTreeMap<u64, (u64, Vec<u8>)> = Default::default();
    for n in v {
        let e = by.entry(n.start).or_insert((n.dur, Vec::new()));
        e.1.push(n.pitch);
    }
    by.into_iter()
        .map(|(t, (d, mut p))| {
            p.sort_unstable();
            (t, d, p)
        })
        .collect()
}

/// Pitch classes of each chord onset, as a 12-bit mask.
fn cp_classes(v: &[TNote]) -> Vec<u16> {
    cp_chords(v)
        .iter()
        .map(|c| c.2.iter().fold(0u16, |m, &p| m | 1 << (p % 12)))
        .collect()
}

fn pcs(list: &[u8]) -> u16 {
    list.iter().fold(0u16, |m, &p| m | 1 << (p % 12))
}

#[test]
fn cp_harmonic_rhythm_cycles_beats_with_the_rate_curve() {
    let starts = |extra: &[(&'static str, ParamValue)]| -> Vec<u64> {
        let mut set = cp_typed("C F G C", &[on("n01")]);
        set.extend(extra.iter().cloned());
        cp_chords(&run_unselected("chord_progression", &set))
            .iter()
            .map(|c| c.0)
            .collect()
    };
    // 4, 2, 4, 2 beats at the listed rate (½).
    assert_eq!(starts(&[list("n01.beats", &[4, 2])]), [0, 3840, 5760, 9600]);
    // Twice as fast at 1, twice as slow at 0.
    let fast = curve("n01.rate", Curve::flat(1.0));
    assert_eq!(
        starts(&[list("n01.beats", &[4, 2]), fast]),
        [0, 1920, 2880, 4800]
    );
    let slow = curve("n01.rate", Curve::flat(0.0));
    assert_eq!(
        starts(&[list("n01.beats", &[4, 2]), slow]),
        [0, 7680, 11520, 19200]
    );
    // Snapped to bars: three beats round to one bar.
    assert_eq!(
        starts(&[list("n01.beats", &[3]), ch("n01.snap", 1)]),
        [0, 3840, 7680, 11520]
    );
    // A rising rate, eighths: 8, 5.04, 3.17, 2 beats → 7,680, 4,800,
    // 2,880 ticks.
    assert_eq!(
        starts(&[
            list("n01.beats", &[4]),
            curve("n01.rate", Curve::line(0.0, 1.0)),
            ch("n01.snap", 2),
        ]),
        [0, 7680, 12480, 15360]
    );
}

#[test]
fn cp_modal_interchange_borrows_from_the_parallel_mode() {
    let run_with = |extra: &[(&'static str, ParamValue)]| {
        cp_classes(&run_unselected(
            "chord_progression",
            &cp_typed("C Dm F G", extra),
        ))
    };
    let plain = run_with(&[]);
    assert_eq!(
        plain,
        [
            pcs(&[0, 4, 7]),
            pcs(&[2, 5, 9]),
            pcs(&[5, 9, 0]),
            pcs(&[7, 11, 2])
        ]
    );
    // Everything from C natural minor: Cm, D°, Fm, Gm.
    let minor = [
        pcs(&[0, 3, 7]),
        pcs(&[2, 5, 8]),
        pcs(&[5, 8, 0]),
        pcs(&[7, 10, 2]),
    ];
    assert_eq!(run_with(&[on("n02"), fl("n02.share", 100.0)]), minor);
    // Pre-dominants only (ii, IV).
    assert_eq!(
        run_with(&[on("n02"), fl("n02.share", 100.0), ch("n02.where", 1)]),
        [plain[0], minor[1], minor[2], plain[3]]
    );
    // Cadences: the phrase's last two.
    assert_eq!(
        run_with(&[on("n02"), fl("n02.share", 100.0), ch("n02.where", 2)]),
        [plain[0], plain[1], minor[2], minor[3]]
    );
    // From Lydian: IV becomes F♯°… on degree 3 (F A B♭? no: B), I stays C.
    let lyd = run_with(&[on("n02"), fl("n02.share", 100.0), ch("n02.from", 4)]);
    assert_eq!(lyd[0], pcs(&[0, 4, 7]));
    assert_eq!(lyd[2], pcs(&[6, 9, 0]), "F♯ A C");
    // A share of none borrows nothing.
    assert_eq!(run_with(&[on("n02"), fl("n02.share", 0.0)]), plain);
}

#[test]
fn cp_secondary_dominants_take_a_share_of_the_previous_chord() {
    let run_with = |extra: &[(&'static str, ParamValue)]| {
        let mut set = cp_typed("C F G C", &[on("n03")]);
        set.extend(extra.iter().cloned());
        run_full("chord_progression", Vec::new(), &set)
    };
    let r = run_with(&[]);
    let c = cp_chords(&r.notes);
    let got: Vec<(u64, u64, u16)> = c.iter().map(|x| (x.0, x.1, pcs(&x.2))).collect();
    assert_eq!(
        got,
        [
            (0, 1920, pcs(&[0, 4, 7])),
            (1920, 1920, pcs(&[0, 4, 7, 10])),
            (3840, 1920, pcs(&[5, 9, 0])),
            (5760, 1920, pcs(&[2, 6, 9, 0])),
            (7680, 1920, pcs(&[7, 11, 2])),
            (9600, 1920, pcs(&[7, 11, 2, 5])),
            (11520, 3840, pcs(&[0, 4, 7])),
        ]
    );
    assert!(r.message.unwrap().contains("C7"));
    // vii°7 and the tritone substitute before F.
    let dim = cp_chords(&run_with(&[ch("n03.kind", 1)]).notes);
    assert_eq!(pcs(&dim[1].2), pcs(&[4, 7, 10, 1]));
    let sub = cp_chords(&run_with(&[ch("n03.kind", 2)]).notes);
    assert_eq!(pcs(&sub[1].2), pcs(&[6, 10, 1, 4]));
    // Listed positions: before the third chord only; a 25 % share.
    let one = cp_chords(
        &run_with(&[
            ch("n03.before", 2),
            list("n03.positions", &[3]),
            fl("n03.share", 25.0),
        ])
        .notes,
    );
    let got: Vec<(u64, u64)> = one.iter().map(|x| (x.0, x.1)).collect();
    assert_eq!(
        got,
        [
            (0, 3840),
            (3840, 2880),
            (6720, 960),
            (7680, 3840),
            (11520, 3840)
        ]
    );
    // Strong beats: with two-beat chords only those on a bar line.
    let half =
        cp_chords(&run_with(&[ch("n03.before", 1), on("n01"), list("n01.beats", &[2])]).notes);
    assert_eq!(
        half.len(),
        4 + 1,
        "one dominant, before the third chord (bar 2)"
    );
}

#[test]
fn cp_cadence_control_ends_phrases_on_the_chosen_cadence() {
    let progression = |extra: &[(&'static str, ParamValue)]| {
        let mut set = vec![int("count", 8), flag("bass", false), seed_v(11)];
        set.extend(extra.iter().cloned());
        cp_classes(&run_unselected("chord_progression", &set))
    };
    let (i, iv, v, vi) = (
        pcs(&[0, 4, 7]),
        pcs(&[5, 9, 0]),
        pcs(&[7, 11, 2]),
        pcs(&[9, 0, 4]),
    );
    let plain = progression(&[]);
    for (cadence, a, b) in [(0u32, v, i), (1, iv, i), (2, iv, v), (3, v, vi)] {
        let c = progression(&[on("n04"), ch("n04.cadence", cadence)]);
        assert_eq!((c[2], c[3], c[6], c[7]), (a, b, a, b), "cadence {cadence}");
        assert_eq!(
            (c[0], c[1], c[4], c[5]),
            (plain[0], plain[1], plain[4], plain[5])
        );
    }
    // Strength 0: nothing changes. Phrases of 3: ends 2, 5 and the last pair.
    assert_eq!(progression(&[on("n04"), fl("n04.strength", 0.0)]), plain);
    let c = progression(&[on("n04"), int("n04.phrase", 3)]);
    assert_eq!((c[1], c[2], c[4], c[5], c[6], c[7]), (v, i, v, i, v, i));
}

fn seed_v(v: u64) -> (&'static str, ParamValue) {
    ("seed", ParamValue::Int(v as i64))
}

#[test]
fn cp_wall_voicing_fills_every_octave_with_chord_tones() {
    let wall = |extra: &[(&'static str, ParamValue)]| {
        let mut set = cp_typed("C", &[on("n05"), int("n05.lo", 36), int("n05.hi", 84)]);
        set.extend(extra.iter().cloned());
        run_unselected("chord_progression", &set)
    };
    let all: Vec<u8> = (36..=84)
        .filter(|p| [0, 4, 7].contains(&(p % 12)))
        .collect();
    assert_eq!(cp_chords(&wall(&[]))[0].2, all);
    let rf: Vec<u8> = (36..=84).filter(|p| [0, 7].contains(&(p % 12))).collect();
    assert_eq!(cp_chords(&wall(&[ch("n05.density", 1)]))[0].2, rf);
    let mut thin = vec![36u8, 48, 55];
    thin.extend((60..=84).filter(|p| [0, 4, 7].contains(&(p % 12))));
    assert_eq!(cp_chords(&wall(&[ch("n05.density", 2)]))[0].2, thin);
    // Velocity by register: 50 % at the bottom to 100 % at the top.
    let v = wall(&[curve("n05.vel", Curve::line(0.5, 1.0))]);
    let at = |p: u8| v.iter().find(|n| n.pitch == p).unwrap().vel;
    assert_eq!((at(36), at(60), at(84)), (50, 75, 100));
    // With n10's extensions the wall carries the ninth too.
    let ext = wall(&[on("n10"), int("n10.voices", 5), ch("n10.by", 0)]);
    assert_eq!(pcs(&cp_chords(&ext)[0].2), pcs(&[0, 4, 7, 11, 2]));
}

#[test]
fn cp_passing_chords_slide_into_each_change() {
    let run_with = |chords: &str, extra: &[(&'static str, ParamValue)]| {
        let mut set = cp_typed(chords, &[on("n06"), int("n06.len", 240)]);
        set.extend(extra.iter().cloned());
        cp_chords(&run_unselected("chord_progression", &set))
    };
    let c = run_with("C F G C", &[]);
    let got: Vec<(u64, u64, u16)> = c.iter().map(|x| (x.0, x.1, pcs(&x.2))).collect();
    assert_eq!(
        got,
        [
            (0, 3600, pcs(&[0, 4, 7])),
            (3600, 240, pcs(&[6, 10, 1])),
            (3840, 3600, pcs(&[5, 9, 0])),
            (7440, 240, pcs(&[8, 0, 3])),
            (7680, 3600, pcs(&[7, 11, 2])),
            (11280, 240, pcs(&[1, 5, 8])),
            (11520, 3840, pcs(&[0, 4, 7])),
        ]
    );
    // From below; a diatonic step above (G before F, Am before G, Dm before C).
    let below = run_with("C F G C", &[ch("n06.kind", 1)]);
    assert_eq!(pcs(&below[1].2), pcs(&[4, 8, 11]));
    let step = run_with("C F G C", &[ch("n06.kind", 2)]);
    assert_eq!(
        (pcs(&step[1].2), pcs(&step[3].2), pcs(&step[5].2)),
        (pcs(&[7, 11, 2]), pcs(&[9, 0, 4]), pcs(&[2, 5, 9]))
    );
    // No change, no passing chord; phrase ends only.
    assert_eq!(run_with("C C F", &[]).len(), 4);
    let ends = run_with("C F G C C F G C", &[ch("n06.where", 1)]);
    assert_eq!(ends.len(), 9);
    assert_eq!(ends[4].0, 4 * 3840 - 240);
}

#[test]
fn cp_suspensions_resolve_inside_the_chord() {
    // (pitch, start, length) of a one-chord run.
    let run_with = |extra: &[(&'static str, ParamValue)]| {
        let mut set = cp_typed("C", &[on("n07")]);
        set.extend(extra.iter().cloned());
        let mut v: Vec<(u8, u64, u64)> = run_unselected("chord_progression", &set)
            .iter()
            .map(|n| (n.pitch, n.start, n.dur))
            .collect();
        v.sort_unstable();
        v
    };
    // 4–3: E held as F for half the chord.
    assert_eq!(
        run_with(&[]),
        [
            (60, 0, 3840),
            (64, 1920, 1920),
            (65, 0, 1920),
            (67, 0, 3840)
        ]
    );
    // 9–8 over the octave voicing: the upper C as D for 25 %.
    assert_eq!(
        run_with(&[ch("n07.kind", 1), ch("voicing", 2), fl("n07.resolve", 25.0)]),
        [
            (60, 0, 3840),
            (64, 0, 3840),
            (67, 0, 3840),
            (72, 960, 2880),
            (74, 0, 960)
        ]
    );
    // 7–6 in first inversion (C a sixth above E), a scale step above it.
    assert_eq!(
        run_with(&[ch("n07.kind", 2), int("inversion", 1)]),
        [
            (64, 0, 3840),
            (67, 0, 3840),
            (72, 1920, 1920),
            (74, 0, 1920)
        ]
    );
    // 2–3: the bass a step above.
    let v = run_with(&[ch("n07.kind", 3), flag("bass", true)]);
    assert!(
        v.contains(&(38, 0, 1920)) && v.contains(&(36, 1920, 1920)),
        "{v:?}"
    );
    // Cadences / listed positions of a four-chord progression.
    let four = |extra: &[(&'static str, ParamValue)]| {
        let mut set = cp_typed("C F G C", &[on("n07")]);
        set.extend(extra.iter().cloned());
        cp_chords(&run_unselected("chord_progression", &set))
            .iter()
            .filter(|c| c.0 % 3840 == 0)
            .map(|c| c.2.len())
            .collect::<Vec<_>>()
    };
    // The onset holds the suspension instead of the third: still 3 notes;
    // the resolution adds an onset mid-chord.
    let cad = cp_chords(&run_unselected(
        "chord_progression",
        &cp_typed("C F G C", &[on("n07"), ch("n07.where", 1)]),
    ));
    assert_eq!(cad.len(), 5);
    assert_eq!(cad[4].0, 3 * 3840 + 1920);
    assert_eq!(
        four(&[ch("n07.where", 2), list("n07.positions", &[2])]).len(),
        4
    );
    let listed = cp_chords(&run_unselected(
        "chord_progression",
        &cp_typed(
            "C F G C",
            &[on("n07"), ch("n07.where", 2), list("n07.positions", &[2])],
        ),
    ));
    assert_eq!(listed[2].0, 3840 + 1920);
    // With hits, every hit splits at the resolution: the voice's time is
    // whole.
    let v = run_unselected(
        "chord_progression",
        &cp_typed("C", &[on("n07"), on("a9"), int("a9.hits", 4)]),
    );
    let third: u64 = v
        .iter()
        .filter(|n| n.pitch == 64 || n.pitch == 65)
        .map(|n| n.dur)
        .sum();
    assert_eq!(third, 3840);
}

#[test]
fn cp_harmonize_the_melody_picks_fitting_chords() {
    // Bar 1 C E G C, bar 2 F A C F, bar 3 G B D G, bar 4 C E G C.
    let bars: [[u8; 4]; 4] = [
        [60, 64, 67, 72],
        [65, 69, 72, 77],
        [67, 71, 74, 79],
        [60, 64, 67, 72],
    ];
    let melody: Vec<TNote> = bars
        .iter()
        .enumerate()
        .flat_map(|(b, ps)| {
            ps.iter()
                .enumerate()
                .map(move |(k, &p)| tn(b as u64 * 3840 + k as u64 * 960, 960, p, 100))
        })
        .collect();
    let chords = |notes: Vec<TNote>, extra: &[(&'static str, ParamValue)]| {
        let mut set = vec![on("n08"), flag("bass", false)];
        set.extend(extra.iter().cloned());
        run_full("chord_progression", notes, &set)
    };
    let r = chords(melody.clone(), &[ch("n08.adventure", 0)]);
    assert!(
        r.message
            .as_ref()
            .unwrap()
            .starts_with("Chords: C – F – G – C"),
        "{:?}",
        r.message
    );
    // By melody note: one chord per onset, each holding its note.
    let r = chords(melody.clone(), &[ch("n08.per", 2), int("octave", 2)]);
    let msg = r.message.unwrap();
    let names = &msg["Chords: ".len()..msg.find(" (").unwrap()];
    assert_eq!(names.matches(" – ").count() + 1, 16);
    // Each melody note is a tone of the chord starting with it (the chords
    // two octaves down).
    for m in &melody {
        let chord: u16 = r
            .notes
            .iter()
            .filter(|n| n.pitch < 60 && n.start == m.start)
            .fold(0, |a, n| a | 1 << (n.pitch % 12));
        assert!(chord & 1 << (m.pitch % 12) != 0, "{} {}", m.start, m.pitch);
    }
    // Passing notes allowed: C D E F G over one bar stays C (the strong C
    // on the bar line, D and F short and weak).
    let run5: Vec<TNote> = [60u8, 62, 64, 65, 67]
        .iter()
        .enumerate()
        .map(|(k, &p)| tn(k as u64 * 768, 768, p, 100))
        .collect();
    let r = chords(run5.clone(), &[ch("n08.fit", 1), fl("n08.adventure", 0.0)]);
    assert!(r.message.unwrap().starts_with("Chords: C ("));
    // Allowed degrees I, IV, V only.
    let r = chords(
        melody.clone(),
        &[
            list("n08.degrees", &[1, 4, 5]),
            ch("n08.per", 1),
            fl("n08.adventure", 0.0),
        ],
    );
    let msg = r.message.unwrap();
    let names: Vec<&str> = msg["Chords: ".len()..msg.find(" (").unwrap()]
        .split(" – ")
        .collect();
    assert!(
        names.iter().all(|n| ["C", "F", "G"].contains(n)),
        "{names:?}"
    );
    // A bar of rest keeps the previous chord.
    let mut gap = melody.clone();
    gap.retain(|n| !(3840..7680).contains(&n.start));
    let r = chords(gap, &[fl("n08.adventure", 0.0)]);
    assert!(r.message.unwrap().starts_with("Chords: C – C – G – C"));
}

#[test]
fn cp_root_motion_walk_follows_its_weights() {
    let walk = |weights: &[i64], extra: &[(&'static str, ParamValue)]| {
        let mut set = vec![
            int("count", 6),
            flag("bass", false),
            on("n09"),
            list("n09.weights", weights),
        ];
        set.extend(extra.iter().cloned());
        let r = run_full("chord_progression", Vec::new(), &set);
        let m = r.message.unwrap();
        m["Chords: ".len()..m.find(" (").unwrap()]
            .split(" – ")
            .map(str::to_owned)
            .collect::<Vec<_>>()
    };
    assert_eq!(
        walk(&[100, 0, 0, 0, 0, 0], &[ch("n09.qualities", 1)]),
        ["C", "F", "A#", "D#", "G#", "C#"]
    );
    assert_eq!(
        walk(&[0, 100, 0, 0, 0, 0], &[]),
        ["C", "G", "Dm", "Am", "Em", "Bdim"]
    );
    assert_eq!(
        walk(&[0, 0, 0, 0, 1, 0], &[ch("n09.qualities", 1)]),
        ["C", "F#", "C", "F#", "C", "F#"]
    );
    assert_eq!(
        walk(
            &[0, 100, 0, 0, 0, 0],
            &[int("n09.start", 5), ch("n09.qualities", 1)]
        )[0],
        "G"
    );
    // Chromatic mediants keep the quality; roots a major or minor third
    // apart.
    let med = walk(
        &[0, 0, 0, 0, 0, 1],
        &[int("n09.start", 6), ch("n09.qualities", 2)],
    );
    assert!(med.iter().all(|c| c.ends_with('m')), "{med:?}");
    // Typed chords stay; '?' walks on from them.
    let mut set = vec![
        ch("mode", 1),
        text("C ? ? ?"),
        int("count", 4),
        on("n09"),
        list("n09.weights", &[100, 0, 0, 0, 0, 0]),
        ch("n09.qualities", 1),
    ];
    let m = run_full("chord_progression", Vec::new(), &set)
        .message
        .unwrap();
    assert!(m.starts_with("Chords: C – F – A# – D#"), "{m}");
    // Every weight 0: the v0.8 generator's chords.
    set = vec![int("count", 6), seed_v(5)];
    let plain = run_full("chord_progression", Vec::new(), &set).message;
    set.push(on("n09"));
    set.push(list("n09.weights", &[0, 0, 0, 0, 0, 0]));
    assert_eq!(
        run_full("chord_progression", Vec::new(), &set).message,
        plain
    );
}

#[test]
fn cp_chord_size_grows_by_extensions_and_doublings() {
    let size = |n: i64, by: u32, order: u32| {
        let set = cp_typed(
            "C",
            &[
                on("n10"),
                int("n10.voices", n),
                ch("n10.by", by),
                ch("n10.order", order),
            ],
        );
        cp_chords(&run_unselected("chord_progression", &set))[0]
            .2
            .clone()
    };
    assert_eq!(size(5, 0, 0), [60, 64, 67, 71, 74]);
    assert_eq!(size(7, 0, 0), [60, 64, 67, 71, 74, 77, 81]);
    assert_eq!(size(9, 0, 0), [60, 64, 67, 71, 74, 77, 81, 84, 88]);
    // Both: thirds to seven pitch classes, then doublings from the bass.
    assert_eq!(size(9, 2, 0), [48, 52, 60, 64, 67, 71, 74, 77, 81]);
    assert_eq!(size(5, 1, 1), [60, 64, 67, 76, 79]);
    assert_eq!(size(6, 1, 2), [48, 52, 60, 64, 67, 79]);
    assert_eq!(size(2, 2, 0), [60, 64]);
    // 32 voices.
    assert_eq!(size(32, 2, 2).len(), 32);
}

#[test]
fn cp_neo_riemannian_chain_transforms_the_triad() {
    let chain = |list_: &[i64], repeat: i64, extra: &[(&'static str, ParamValue)]| {
        let mut set = vec![
            on("n11"),
            list("n11.chain", list_),
            int("n11.repeat", repeat),
            flag("bass", false),
        ];
        set.extend(extra.iter().cloned());
        let m = run_full("chord_progression", Vec::new(), &set)
            .message
            .unwrap();
        m["Chords: ".len()..m.find(" (").unwrap()]
            .split(" – ")
            .map(str::to_owned)
            .collect::<Vec<_>>()
    };
    assert_eq!(chain(&[0], 1, &[]), ["C", "Cm"]);
    assert_eq!(chain(&[1], 1, &[]), ["C", "Em"]);
    assert_eq!(chain(&[2], 1, &[]), ["C", "Am"]);
    assert_eq!(
        chain(&[1, 2], 3, &[]),
        ["C", "Em", "G", "Bm", "D", "F#m", "A"]
    );
    // From the first typed chord; P twice is the identity.
    assert_eq!(
        chain(&[1], 2, &[ch("n11.start", 1), text("Am F")]),
        ["Am", "F", "Am"]
    );
    assert_eq!(chain(&[0, 0], 1, &[])[2], "C");
    // One chord a bar.
    let set = vec![
        on("n11"),
        list("n11.chain", &[2]),
        int("n11.repeat", 4),
        flag("bass", false),
    ];
    let starts: Vec<u64> = cp_chords(&run_unselected("chord_progression", &set))
        .iter()
        .map(|c| c.0)
        .collect();
    assert_eq!(starts, [0, 3840, 7680, 11520, 15360]);
}

#[test]
fn cp_functions_compose_and_stay_within_the_preflight() {
    let set = vec![
        on("n01"),
        on("n02"),
        on("n03"),
        on("n04"),
        on("n05"),
        int("n05.lo", 48),
        int("n05.hi", 72),
        on("n06"),
        on("n07"),
        on("n09"),
        on("n10"),
        on("a2"),
        on("a9"),
        int("count", 8),
    ];
    let a = run_full("chord_progression", Vec::new(), &set);
    let b = run_full("chord_progression", Vec::new(), &set);
    assert_eq!(fingerprint(&a.notes), fingerprint(&b.notes));
    assert!(!a.notes.is_empty());
    // The wall stays in its range (the bass below it).
    let low = a.notes.iter().filter(|n| n.pitch < 48).count();
    assert!(
        a.notes.iter().all(|n| n.pitch <= 74),
        "the suspension a step above at most"
    );
    assert!(low > 0, "the bass");
    // With a melody, n08 decides the chords and n11 is ignored.
    let mut set2 = set.clone();
    set2.push(on("n08"));
    set2.push(on("n11"));
    let melody: Vec<TNote> = cp_melody()
        .iter()
        .map(|&(s, d, p, v)| tn(s, d, p, v))
        .collect();
    let r = run_full("chord_progression", melody, &set2);
    assert!(r.notes.len() > 32);
}

#[test]
fn cp_harmonizing_per_note_counts_its_chords_on_the_source() {
    // 4,000 notes in 100 onsets (40-note chords): one chord per onset, not
    // per note.
    let notes: Vec<TNote> = (0..100u64)
        .flat_map(|k| (0..40u8).map(move |p| tn(k * 240, 240, 40 + p, 100)))
        .collect();
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track]);
    let t = tool("chord_progression").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    ps.set("n08", ParamValue::Bool(true));
    ps.set("n08.per", ParamValue::Choice(2));
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    // Notes per chord slot: 14 voices + bass + polychord (3) + suspension.
    assert_eq!(k.estimate_source(&src).notes, 100 * 19 + 4000);
    assert!(k.estimate(&src.stats).notes > 4000 * 19);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert_eq!(r.notes.len(), 4000 + 100 * 4);
}

// ================================================================ Chord Stamp

/// The Chord Stamp ids (n04 does not exist; n12 took its place).
const CS_IDS: [&str; 11] = [
    "n01", "n02", "n03", "n12", "n05", "n06", "n07", "n08", "n09", "n10", "n11",
];

/// Settings of the v0.8 Chord Stamp (types, inversions, placement and each
/// frozen function).
fn cs_v08_settings() -> Vec<Vec<(&'static str, ParamValue)>> {
    vec![
        vec![],
        vec![ch("chord", 9), int("inversion", 2)],
        vec![ch("chord", 20), int("inversion", -3), ch("placement", 1)],
        vec![on("a1"), list("a1.intervals", &[0, 7, 14, 21])],
        vec![on("a2"), ch("a2.key", 2), ch("a2.scale", 1), ch("chord", 8)],
        vec![on("a3"), ch("chord", 7)],
        vec![on("a4"), fl("a4.spread", 0.8)],
        vec![on("a5"), int("a5.octave", 1)],
        vec![on("a6")],
        vec![on("a7")],
        vec![on("a8"), list("a8.onsets", &[0, 30, 60])],
        vec![on("a9"), ch("a9.to", 12)],
        vec![on("a10"), int("a10.copies", 2), fl("a10.decay", 50.0)],
        vec![on("a3"), on("a4"), on("a8"), on("a10"), ch("chord", 16)],
    ]
}

