#[test]
fn cs_new_functions_off_leave_v08_results_unchanged() {
    let notes = flam_fixture();
    for (i, s) in cs_v08_settings().into_iter().enumerate() {
        let mut set = s.clone();
        for k in CS_IDS {
            set.push((k, ParamValue::Bool(false)));
        }
        assert_eq!(
            fingerprint(&run_vel("chord_stamp", &notes, &set)),
            CS_V08[i],
            "setting {i}"
        );
    }
}

/// Chord Stamp on hand-built notes (one track, subchannels 0 – 3).
fn cs(notes: Vec<TNote>, set: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    run_full("chord_stamp", notes, set).notes
}

/// Sorted pitches of the stamp of the note starting at `t`.
fn cs_at(v: &[TNote], t: u64) -> Vec<u8> {
    let mut p: Vec<u8> = v.iter().filter(|n| n.start == t).map(|n| n.pitch).collect();
    p.sort_unstable();
    p
}

#[test]
fn cs_pitch_class_map_picks_the_chord_type_per_class() {
    let notes = vec![
        tn(0, 480, 60, 100),
        tn(960, 480, 62, 100),
        tn(1920, 480, 66, 100),
    ];
    let v = cs(notes.clone(), &[on("n01")]);
    assert_eq!(cs_at(&v, 0), [60, 64, 67, 71], "C: major 7");
    assert_eq!(cs_at(&v, 960), [62, 65, 69, 72, 76], "D: minor 9");
    assert_eq!(cs_at(&v, 1920), [66, 70, 73], "F♯ unlisted: the main chord");
    let v = cs(notes, &[on("n01"), ch("n01.unlisted", 1)]);
    assert_eq!(cs_at(&v, 1920), [66], "left alone");
}

#[test]
fn cs_velocity_sets_the_number_of_voices() {
    let notes = vec![
        tn(0, 480, 60, 1),
        tn(960, 480, 60, 64),
        tn(1920, 480, 60, 127),
    ];
    let v = cs(notes.clone(), &[on("n02")]);
    assert_eq!(cs_at(&v, 0), [60, 64]);
    assert_eq!(cs_at(&v, 960), [60, 64, 67, 71]);
    // Thirds alternating above the top: B, D, F♯.
    assert_eq!(cs_at(&v, 1920), [60, 64, 67, 71, 74, 78]);
    let v = cs(notes, &[on("n02"), ch("n02.by", 1)]);
    assert_eq!(cs_at(&v, 1920), [60, 64, 67, 72, 76, 79]);
}

#[test]
fn cs_cluster_stamp_fills_a_width_above_below_or_around() {
    let c = |p: u8, extra: &[(&'static str, ParamValue)]| {
        let mut set = vec![on("n03"), int("n03.width", 5)];
        set.extend(extra.iter().cloned());
        cs_at(&cs(vec![tn(0, 480, p, 100)], &set), 0)
    };
    assert_eq!(c(60, &[]), [60, 61, 62, 63, 64, 65]);
    assert_eq!(c(60, &[ch("n03.place", 1)]), [55, 56, 57, 58, 59, 60]);
    assert_eq!(c(60, &[ch("n03.place", 2)]), [58, 59, 60, 61, 62, 63]);
    assert_eq!(c(60, &[ch("n03.kind", 1)]), [60, 62, 64, 65]);
    assert_eq!(
        c(61, &[ch("n03.kind", 1)]),
        [61, 62, 64, 65],
        "the note stays"
    );
    assert_eq!(c(60, &[ch("n03.kind", 2)]), [60, 62, 64]);
}

#[test]
fn cs_interval_avoidance_moves_or_drops_clashing_voices() {
    // C11 (C E G B♭ D F): the tritone E – B♭.
    let one = vec![tn(0, 480, 60, 100)];
    let eleven = [ch("chord", 19), on("n12")];
    assert_eq!(
        cs_at(&cs(one.clone(), &eleven), 0),
        [60, 64, 67, 74, 77, 82]
    );
    let mut set = eleven.to_vec();
    set.push(ch("n12.fix", 1));
    assert_eq!(cs_at(&cs(one.clone(), &set), 0), [60, 64, 67, 74, 77]);
    // A chromatic cluster without minor seconds: the bass and top stay.
    let set = [
        on("n03"),
        int("n03.width", 2),
        on("n12"),
        list("n12.avoid", &[1]),
    ];
    assert_eq!(cs_at(&cs(one.clone(), &set), 0), [60, 62, 73]);
    // Every pair of the result is clear of the avoided distances (but the
    // kept bass and top).
    let notes: Vec<TNote> = (0..24)
        .map(|k| tn(k * 480, 240, 40 + k as u8, 100))
        .collect();
    let set = [
        ch("chord", 20),
        on("n12"),
        list("n12.avoid", &[1, 2, 6]),
        ch("n12.keep", 0),
    ];
    let v = cs(notes, &set);
    for k in 0..24u64 {
        let c = cs_at(&v, k * 480);
        for (i, &a) in c.iter().enumerate().skip(1) {
            for &b in &c[..i] {
                if b != c[0] {
                    assert!(![1, 2, 6].contains(&(a - b)), "{c:?}");
                }
            }
        }
    }
}

#[test]
fn cs_overtone_stamp_rounds_partials_to_keys() {
    let v = cs(vec![tn(0, 480, 36, 100)], &[on("n05")]);
    let mut got: Vec<(u8, u8)> = v.iter().map(|n| (n.pitch, n.vel)).collect();
    got.sort_unstable();
    // Partials 1 – 8 but the 7th: 36 48 55 60 64 67 72, 10 % less each.
    assert_eq!(
        got,
        [
            (36, 100),
            (48, 90),
            (55, 81),
            (60, 73),
            (64, 66),
            (67, 59),
            (72, 48)
        ]
    );
    // Higher partials landing on one key count once.
    let v = cs(
        vec![tn(0, 480, 24, 100)],
        &[on("n05"), int("n05.partials", 64), list("n05.skip", &[])],
    );
    let keys = cs_at(&v, 0);
    let mut d = keys.clone();
    d.dedup();
    assert_eq!(keys, d);
    assert_eq!(*keys.last().unwrap(), 24 + 72);
}

#[test]
fn cs_drop_voicings_lower_voices_from_the_top() {
    let d = |drop: u32, extra: &[(&'static str, ParamValue)]| {
        let mut set = vec![ch("chord", 8), on("n06"), ch("n06.drop", drop)];
        set.extend(extra.iter().cloned());
        cs_at(&cs(vec![tn(0, 480, 60, 100)], &set), 0)
    };
    assert_eq!(d(0, &[]), [55, 60, 64, 71]);
    assert_eq!(d(1, &[]), [52, 60, 67, 71]);
    assert_eq!(d(2, &[]), [48, 55, 64, 71]);
    assert_eq!(d(0, &[int("n06.by", 2)]), [43, 60, 64, 71]);
    assert_eq!(d(3, &[list("n06.voices", &[1])]), [59, 60, 64, 67]);
}

#[test]
fn cs_chord_type_sequence_cycles_per_note_beat_or_bar() {
    let types = |per: u32, starts: &[u64]| {
        let notes: Vec<TNote> = starts.iter().map(|&s| tn(s, 100, 60, 100)).collect();
        let v = cs(
            notes,
            &[on("n07"), list("n07.types", &[0, 9, 7]), ch("n07.per", per)],
        );
        starts.iter().map(|&s| cs_at(&v, s)).collect::<Vec<_>>()
    };
    let (maj, m7, d7) = (
        vec![60u8, 64, 67],
        vec![60u8, 63, 67, 70],
        vec![60u8, 64, 67, 70],
    );
    assert_eq!(
        types(0, &[0, 480, 960, 1440]),
        [maj.clone(), m7.clone(), d7.clone(), maj.clone()]
    );
    assert_eq!(
        types(1, &[0, 240, 960, 1920]),
        [maj.clone(), maj.clone(), m7.clone(), d7]
    );
    assert_eq!(types(2, &[0, 1920, 3840]), [maj.clone(), maj, m7]);
}

#[test]
fn cs_range_fit_inversions_keep_every_voice_in_the_range() {
    let fit = |lo: i64, hi: i64, prefer: u32| {
        cs_at(
            &cs(
                vec![tn(0, 480, 60, 100)],
                &[
                    on("n08"),
                    int("n08.lo", lo),
                    int("n08.hi", hi),
                    ch("n08.prefer", prefer),
                ],
            ),
            0,
        )
    };
    assert_eq!(fit(64, 76, 0), [64, 67, 72]);
    assert_eq!(fit(64, 76, 1), [64, 67, 72]);
    assert_eq!(fit(64, 76, 2), [67, 72, 76]);
    assert_eq!(
        fit(30, 50, 0),
        [40, 43, 48],
        "the fitting voicing nearest 60"
    );
    // Too narrow for the chord: as little outside as possible.
    let v = fit(60, 62, 0);
    assert_eq!(v.len(), 3);
    // Every stamp of the fixture inside 48 – 84.
    let notes: Vec<TNote> = (0..40)
        .map(|k| tn(k * 480, 240, 20 + 2 * k as u8, 100))
        .collect();
    let v = cs(
        notes,
        &[
            ch("chord", 9),
            on("n08"),
            int("n08.lo", 48),
            int("n08.hi", 84),
        ],
    );
    assert!(v.iter().all(|n| (48..=84).contains(&n.pitch)));
}

#[test]
fn cs_voice_polyrhythm_retriggers_each_voice_at_its_rate() {
    let v = cs(vec![tn(0, 960, 60, 100)], &[on("n09")]);
    let of = |p: u8| {
        let mut s: Vec<(u64, u64)> = v
            .iter()
            .filter(|n| n.pitch == p)
            .map(|n| (n.start, n.dur))
            .collect();
        s.sort_unstable();
        s
    };
    assert_eq!(of(60), [(0, 160), (320, 160), (640, 160)]);
    assert_eq!(of(64), [(0, 120), (240, 120), (480, 120), (720, 120)]);
    assert_eq!(
        of(67),
        [(0, 96), (192, 96), (384, 96), (576, 96), (768, 96)]
    );
    let v = cs(
        vec![tn(0, 960, 60, 100)],
        &[on("n09"), ch("n09.from", 1), fl("n09.gate", 100.0)],
    );
    assert_eq!(v.iter().filter(|n| n.pitch == 67).count(), 3);
    assert_eq!(v.iter().filter(|n| n.pitch == 60).count(), 5);
    assert!(v.iter().filter(|n| n.pitch == 67).all(|n| n.dur == 320));
}

#[test]
fn cs_voice_octave_pattern_moves_voices_fixed_or_rotating() {
    let notes = vec![tn(0, 480, 60, 100), tn(960, 480, 60, 100)];
    let v = cs(notes.clone(), &[on("n10")]);
    assert_eq!(cs_at(&v, 0), [55, 60, 76]);
    assert_eq!(cs_at(&v, 960), [55, 60, 76]);
    let v = cs(notes, &[on("n10"), ch("n10.rotate", 1)]);
    assert_eq!(cs_at(&v, 0), [55, 60, 76]);
    assert_eq!(cs_at(&v, 960), [52, 67, 72], "rotated by one voice");
}

#[test]
fn cs_voice_budget_drops_inner_quiet_or_new_voices_first() {
    // C at 0 and F at 480 overlap: six voices; four allowed.
    let notes = vec![tn(0, 960, 60, 100), tn(480, 960, 65, 60)];
    let b = |drop: u32| {
        let mut p: Vec<u8> = cs(
            notes.clone(),
            &[on("n11"), int("n11.most", 4), ch("n11.drop", drop)],
        )
        .iter()
        .map(|n| n.pitch)
        .collect();
        p.sort_unstable();
        p
    };
    assert_eq!(b(0), [60, 65, 67, 72], "the middles (A, then E) go");
    assert_eq!(
        b(1),
        [60, 64, 65, 67],
        "the quietest (F's, the newest of them) go"
    );
    assert_eq!(b(2), [60, 64, 65, 67], "the newest (F's top voices) go");
    // A quiet C under a loud F: C's upper voices go.
    let quiet_c = vec![tn(0, 960, 60, 50), tn(480, 960, 65, 100)];
    let mut p: Vec<u8> = cs(quiet_c, &[on("n11"), int("n11.most", 4), ch("n11.drop", 1)])
        .iter()
        .map(|n| n.pitch)
        .collect();
    p.sort_unstable();
    assert_eq!(p, [60, 65, 69, 72]);
    // On the fixture every order holds the budget, and only drops voices.
    let fx = flam_fixture();
    let all = run_vel("chord_stamp", &fx, &[ch("chord", 9)]);
    for drop in 0..3 {
        let v = run_vel(
            "chord_stamp",
            &fx,
            &[
                ch("chord", 9),
                on("n11"),
                int("n11.most", 6),
                ch("n11.drop", drop),
            ],
        );
        assert!(worst_poly(&v) <= 6, "{drop}");
        let a = spd(&all);
        assert!(spd(&v).iter().all(|x| a.binary_search(x).is_ok()));
    }
}

#[test]
fn cs_functions_compose_and_stay_within_the_preflight() {
    let set = vec![
        on("n02"),
        on("n12"),
        on("n06"),
        on("n07"),
        on("n08"),
        int("n08.lo", 36),
        int("n08.hi", 96),
        on("n09"),
        on("n10"),
        on("n11"),
        on("a5"),
        on("a7"),
        on("a10"),
    ];
    let fx = flam_fixture();
    let a = run_vel("chord_stamp", &fx, &set);
    assert_eq!(
        fingerprint(&a),
        fingerprint(&run_vel("chord_stamp", &fx, &set))
    );
    assert!(worst_poly(&a) <= 64);
    // Overtones and clusters (n05 wins), lazily previewed per note.
    let set = vec![on("n03"), on("n05"), int("n05.partials", 16)];
    let v = run_vel("chord_stamp", &fx, &set);
    assert!(v.len() > fx.len() * 10);
}

// ================================================================ Riff Machine

fn riff_text(k: &'static str, v: &str) -> (&'static str, ParamValue) {
    (k, ParamValue::Text(v.to_owned()))
}

/// Settings of the v0.8 Riff Machine (sources, base stages and each frozen
/// function).
fn riff_v08_settings() -> Vec<Vec<(&'static str, ParamValue)>> {
    vec![
        vec![],
        vec![ch("source", 0)],
        vec![
            int("bars", 8),
            list("s1.degrees", &[1, 4, 5, 1, 6, 2, 5, 1]),
            ch("key", 2),
            ch("scale", 0),
        ],
        vec![
            ch("s2.chord", 7),
            ch("s3.pattern", 8),
            ch("s3.step", 5),
            int("s3.range", 3),
        ],
        vec![flag("s2.on", false), flag("s3.on", false)],
        vec![ch("s4.mirror", 1)],
        vec![ch("s4.mirror", 2), fl("s5.vel", 0.0)],
        vec![
            ch("s6.style", 1),
            on("s7.on"),
            ch("s7.grid", 3),
            fl("s7.strength", 100.0),
        ],
        vec![flag("s8.on", false), int("upto", 4)],
        vec![int("s8.lo", 60), int("s8.hi", 72), int("seed", 7)],
        vec![on("a1"), list("a1.order", &[3, 2, 5, 4, 8, 7, 6])],
        vec![on("a2"), ch("a2.merge", 0)],
        vec![on("a2")],
        vec![on("a3"), ch("a3.step", 3)],
        vec![on("a4"), int("a4.gens", 5), fl("a4.rate", 40.0)],
        vec![on("a5"), int("a5.bars", 2), int("bars", 6)],
        vec![on("a6"), int("a6.per_bar", 5)],
        vec![on("a7"), list("a7.splits", &[55, 67, 79])],
        vec![on("a8"), riff_text("a8.chords", "C G Am F")],
        vec![on("a9"), fl("a9.rate", 60.0)],
        vec![on("a10")],
        vec![ch("source", 0), on("a4"), on("a9"), ch("s3.pattern", 2)],
        vec![on("a2"), on("a3"), on("a6"), on("a7"), int("bars", 3)],
    ]
}

