#[test]
fn riff_new_functions_off_leave_v08_results_unchanged() {
    let notes = cp_melody();
    let off = |s: &[(&'static str, ParamValue)]| {
        let mut set = s.to_vec();
        for k in ALL11 {
            set.push((k, ParamValue::Bool(false)));
        }
        set
    };
    let all = riff_v08_settings();
    let mut got = Vec::new();
    for s in &all {
        got.push(fingerprint(&run_vel("riff", &notes, &off(s))));
    }
    for s in all.iter().take(4) {
        got.push(fingerprint(&run_unselected("riff", &off(s))));
    }
    for i in RIFF_SUBS {
        got.push(fingerprint(
            &run_full("riff", riff_tnotes(&notes), &off(&all[i])).notes,
        ));
    }
    assert_eq!(got.len(), RIFF_V08.len());
    for (i, (g, w)) in got.iter().zip(RIFF_V08).enumerate() {
        assert_eq!(g, w, "setting {i}");
    }
}

/// Settings of [`riff_v08_settings`] also run on a track with four
/// subchannels (orchestration and the variant sheet place notes in them).
const RIFF_SUBS: [usize; 4] = [0, 1, 17, 21];

/// `notes` (start, length, pitch, velocity) as selected notes of track 0.
fn riff_tnotes(notes: &[(u64, u64, u8, u8)]) -> Vec<TNote> {
    notes
        .iter()
        .map(|&(start, dur, pitch, vel)| TNote {
            start,
            dur,
            pitch,
            vel,
            ..TNote::default()
        })
        .collect()
}

/// The Riff Machine in C major with every v0.8 stage off: the generated
/// progression (one bar-long note per degree from middle C) or the selection
/// passes through unchanged, so each function's own effect is exact.
fn riff_plain(extra: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut v = vec![
        flag("s2.on", false),
        flag("s3.on", false),
        fl("s5.vel", 0.0),
        ch("s6.style", 0),
        flag("s8.on", false),
        ch("scale", 0),
    ];
    v.extend_from_slice(extra);
    v
}

/// A generated riff (nothing selected, cursor 0, a track with subchannels
/// 0 – 3; the preflight bound asserted by [`run_full`]).
fn riff_gen(extra: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    run_full("riff", Vec::new(), &riff_plain(extra)).notes
}

/// The riff made from the selected `notes` (start, length, pitch,
/// velocity) themselves.
fn riff_sel(notes: &[(u64, u64, u8, u8)], extra: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    let mut s = riff_plain(extra);
    s.push(ch("source", 0));
    run_full("riff", riff_tnotes(notes), &s).notes
}

/// [`run_full`] in `ctx` (a time selection, another meter).
fn riff_in(notes: Vec<TNote>, set: &[(&'static str, ParamValue)], ctx: Ctx) -> Vec<TNote> {
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track]);
    let t = tool("riff").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r.notes
}

/// One phrase of four eighths and a long note in the bar after it.
const CALL: &[(u64, u64, u8, u8)] = &[
    (0, 480, 60, 100),
    (480, 480, 64, 100),
    (960, 480, 67, 100),
    (1440, 480, 62, 100),
    (3840, 3840, 50, 100),
];

#[test]
fn riff_call_and_response_answers_every_other_phrase() {
    let calls = vec![
        (0, 60, 480),
        (480, 64, 480),
        (960, 67, 480),
        (1440, 62, 480),
    ];
    let with = |answers: Vec<(u64, u8, u64)>| {
        let mut v = calls.clone();
        v.extend(answers);
        v.sort_unstable();
        v
    };
    let set = |answer: u32, interval: i64, shift: i64| {
        vec![
            on("n01"),
            ch("n01.answer", answer),
            int("n01.interval", interval),
            int("n01.shift", shift),
        ]
    };
    // Transposed: the call a fourth up in the next bar (its own note goes).
    assert_eq!(
        spd(&riff_sel(CALL, &set(0, 5, 0))),
        with(vec![
            (3840, 65, 480),
            (4320, 69, 480),
            (4800, 72, 480),
            (5280, 67, 480)
        ])
    );
    // Inverted around the call's first note (60).
    assert_eq!(
        spd(&riff_sel(CALL, &set(1, 0, 0))),
        with(vec![
            (3840, 60, 480),
            (4320, 56, 480),
            (4800, 53, 480),
            (5280, 58, 480)
        ])
    );
    // Reversed in time inside the phrase, and moved by the interval too.
    assert_eq!(
        spd(&riff_sel(CALL, &set(2, -2, 0))),
        with(vec![
            (3840 + 1920, 60, 480),
            (3840 + 2400, 65, 480),
            (3840 + 2880, 62, 480),
            (3840 + 3360, 58, 480)
        ])
    );
    // Displaced by two sixteenths (wrapping inside the phrase); −16 steps
    // is a whole bar: the call repeated.
    assert_eq!(
        spd(&riff_sel(CALL, &set(3, 0, 2))),
        with(vec![
            (4320, 60, 480),
            (4800, 64, 480),
            (5280, 67, 480),
            (5760, 62, 480)
        ])
    );
    assert_eq!(
        spd(&riff_sel(CALL, &set(3, 0, -16))),
        with(vec![
            (3840, 60, 480),
            (4320, 64, 480),
            (4800, 67, 480),
            (5280, 62, 480)
        ])
    );
    // Phrases of two bars: no answer fits in the two-bar riff.
    let mut s = set(0, 5, 0);
    s.push(int("n01.bars", 2));
    assert_eq!(spd(&riff_sel(CALL, &s)), spd(&riff_sel(CALL, &[])));
}

#[test]
fn riff_register_layers_run_their_own_stages_in_their_octaves() {
    let base = [int("bars", 2), list("s1.degrees", &[1, 5])];
    assert_eq!(spd(&riff_gen(&base)), vec![(0, 60, BAR), (BAR, 67, BAR)]);
    let mut s = base.to_vec();
    s.extend([
        on("n02"),
        int("n02.layers", 2),
        list("n02.octaves", &[-1, 1]),
        list("n02.stages", &[0, 0]),
    ]);
    assert_eq!(
        spd(&riff_gen(&s)),
        vec![(0, 48, BAR), (0, 72, BAR), (BAR, 55, BAR), (BAR, 79, BAR)]
    );
    // Layer 1 chords (major triads) an octave down, layer 2 plain above.
    s.push(flag("s2.on", true));
    s.push(list("n02.stages", &[1, 0]));
    assert_eq!(
        spd(&riff_gen(&s)),
        vec![
            (0, 48, BAR),
            (0, 52, BAR),
            (0, 55, BAR),
            (0, 72, BAR),
            (BAR, 55, BAR),
            (BAR, 59, BAR),
            (BAR, 62, BAR),
            (BAR, 79, BAR)
        ]
    );
    // Lists cycle over the layers.
    let mut s = base.to_vec();
    s.extend([
        on("n02"),
        int("n02.layers", 3),
        list("n02.octaves", &[0]),
        list("n02.stages", &[0]),
    ]);
    assert_eq!(riff_gen(&s).len(), 6);
    // The bass stage belongs to the layers whose mask has 128.
    s.extend([
        on("n05"),
        ch("n05.rhythm", 0),
        int("n02.layers", 2),
        list("n02.stages", &[0, 128]),
    ]);
    let v = riff_gen(&s);
    assert_eq!(
        spd(&v),
        vec![
            (0, 36, BAR),
            (0, 60, BAR),
            (0, 60, BAR),
            (BAR, 43, BAR),
            (BAR, 67, BAR),
            (BAR, 67, BAR)
        ]
    );
}

#[test]
fn riff_section_form_arranges_sections_from_the_degree_list() {
    let bars = |v: &[TNote]| pitches(v);
    let s = [
        list("s1.degrees", &[1, 2, 3, 4, 5, 6, 7, 1]),
        on("n03"),
        list("n03.form", &[0, 1, 0, 2]),
        int("n03.bars", 2),
        fl("n03.vary", 0.0),
    ];
    let v = riff_gen(&s);
    assert_eq!(bars(&v), vec![60, 62, 64, 65, 60, 62, 67, 69]);
    assert_eq!(
        v.iter().map(|n| n.start).collect::<Vec<_>>().iter().max(),
        Some(&(7 * BAR))
    );
    // Every note of A's repeat one scale step from A; A, B, C unchanged.
    let mut s2 = s.to_vec();
    s2.push(fl("n03.vary", 100.0));
    let w = bars(&riff_gen(&s2));
    assert_eq!(&w[..4], &[60, 62, 64, 65]);
    assert_eq!(&w[6..], &[67, 69]);
    assert!(matches!(w[4], 59 | 62), "{w:?}");
    assert!(matches!(w[5], 60 | 64), "{w:?}");
    // A list no longer than a section: each section starts one degree on.
    let s3 = [
        list("s1.degrees", &[1, 6, 4, 5]),
        on("n03"),
        list("n03.form", &[0, 1]),
        int("n03.bars", 4),
    ];
    assert_eq!(bars(&riff_gen(&s3)), vec![60, 69, 65, 67, 69, 65, 67, 60]);
    // From the selection: section A is its first bar, repeated.
    let sel = [
        (0, 960, 60, 100),
        (1920, 960, 64, 100),
        (4000, 960, 67, 100),
    ];
    let v = riff_sel(
        &sel,
        &[
            on("n03"),
            list("n03.form", &[0, 0]),
            int("n03.bars", 1),
            fl("n03.vary", 0.0),
        ],
    );
    assert_eq!(
        spd(&v),
        vec![
            (0, 60, 960),
            (1920, 64, 960),
            (BAR, 60, 960),
            (BAR + 1920, 64, 960)
        ]
    );
}

/// Sixteen quarter notes over four bars (pitch 60 + beat, velocity 64).
fn riff_quarters() -> Vec<(u64, u64, u8, u8)> {
    (0..16u64)
        .map(|k| (k * 960, 960, 60 + (k % 4) as u8, 64))
        .collect()
}

#[test]
fn riff_build_up_halves_the_step_raises_velocity_and_drops() {
    let q = riff_quarters();
    let vel = |s: u64, bs: u64, blen: u64| {
        let x = (s - bs) as f64 / blen as f64;
        (64.0 + 63.0 * x).round() as u8
    };
    let svp = |v: &[TNote]| {
        let mut o: Vec<(u64, u64, u8, u8)> =
            v.iter().map(|n| (n.start, n.dur, n.pitch, n.vel)).collect();
        o.sort_unstable();
        o
    };
    // Bars 1 – 2 build (bar 3 is the drop): bar 1 struck once, bar 2 twice.
    let set = |drop: u32, bars: i64, every: i64| {
        vec![
            on("n04"),
            int("n04.bars", bars),
            int("n04.every", every),
            fl("n04.rise", 100.0),
            ch("n04.drop", drop),
        ]
    };
    let mut want = Vec::new();
    for &(s, d, p, v) in &q {
        match s / BAR {
            0 => want.push((s, d, p, v)),
            1 => want.push((s, d, p, vel(s, BAR, 2 * BAR))),
            2 => {
                let v = vel(s, BAR, 2 * BAR);
                want.push((s, 480, p, v));
                want.push((s + 480, 480, p, v));
            }
            _ => {}
        }
    }
    want.sort_unstable();
    assert_eq!(svp(&riff_sel(&q, &set(0, 2, 1))), want);
    // A full chord: the drop bar's pitches at the build's peak velocity.
    let peak = vel(11 * 960, BAR, 2 * BAR);
    let mut want_chord = want.clone();
    want_chord.extend((60..64).map(|p| (3 * BAR, BAR, p, peak)));
    want_chord.sort_unstable();
    assert_eq!(svp(&riff_sel(&q, &set(1, 2, 1))), want_chord);
    // No drop: the last two bars build.
    let mut want = Vec::new();
    for &(s, d, p, v) in &q {
        match s / BAR {
            0 | 1 => want.push((s, d, p, v)),
            2 => want.push((s, d, p, vel(s, 2 * BAR, 2 * BAR))),
            _ => {
                let v = vel(s, 2 * BAR, 2 * BAR);
                want.push((s, 480, p, v));
                want.push((s + 480, 480, p, v));
            }
        }
    }
    want.sort_unstable();
    assert_eq!(svp(&riff_sel(&q, &set(2, 2, 1))), want);
    // Halving every two bars over the whole riff: bars 2 – 3 twice.
    let v = riff_sel(&q, &set(2, 4, 2));
    assert_eq!(v.len(), 8 + 16);
    assert!(
        v.iter()
            .filter(|n| n.start >= 2 * BAR)
            .all(|n| n.dur == 480)
    );
    // Pieces never shorter than a tick: a 3-tick note in the 8x group.
    let short = [(0, 3840, 60, 64), (3 * BAR, 3, 72, 64)];
    let v = riff_sel(&short, &set(2, 4, 1));
    let mut tail: Vec<(u64, u64)> = v
        .iter()
        .filter(|n| n.pitch == 72)
        .map(|n| (n.start, n.dur))
        .collect();
    tail.sort_unstable();
    assert_eq!(tail, vec![(3 * BAR, 1), (3 * BAR + 1, 1), (3 * BAR + 2, 1)]);
}

#[test]
fn riff_bass_stage_plays_its_pattern_from_the_progression() {
    let base = [int("bars", 2), list("s1.degrees", &[1, 6])];
    let bass = |pattern: u32| {
        let mut s = base.to_vec();
        s.extend([
            on("n05"),
            ch("n05.pattern", pattern),
            ch("n05.rhythm", 2),
            int("n05.octave", 2),
        ]);
        let mut v: Vec<(u64, u8)> = riff_gen(&s)
            .iter()
            .filter(|n| n.pitch < 60)
            .map(|n| (n.start, n.pitch))
            .collect();
        v.sort_unstable();
        v.into_iter().map(|x| x.1).collect::<Vec<_>>()
    };
    assert_eq!(bass(0), vec![36, 36, 36, 36, 45, 45, 45, 45]);
    assert_eq!(bass(1), vec![36, 43, 36, 43, 45, 52, 45, 52]);
    // Walking: root, third, fifth, then a scale step below the next root.
    assert_eq!(bass(2), vec![36, 40, 43, 43, 45, 48, 52, 43]);
    assert_eq!(bass(3), vec![36, 48, 36, 48, 45, 57, 45, 57]);
    // Placed first, the bass is chord-stamped like the progression.
    let mut s = base.to_vec();
    s.extend([
        flag("s2.on", true),
        on("n05"),
        ch("n05.rhythm", 2),
        int("n05.at", 2),
    ]);
    assert_eq!(riff_gen(&s).len(), (2 + 8) * 3);
    // Placed last, it is not; previewing up to step 3 leaves it out.
    s.push(int("n05.at", 9));
    assert_eq!(riff_gen(&s).len(), 2 * 3 + 8);
    s.push(int("upto", 3));
    assert_eq!(riff_gen(&s).len(), 2 * 3);
}

#[test]
fn riff_counter_melody_follows_the_top_voice_by_its_motion() {
    let line: Vec<(u64, u64, u8, u8)> = [72u8, 74, 76, 77, 79]
        .iter()
        .enumerate()
        .map(|(k, &p)| (k as u64 * 480, 480, p, 100))
        .collect();
    let counter = |motion: u32, offset: i64| {
        let v = riff_sel(
            &line,
            &[
                on("n06"),
                ch("n06.motion", motion),
                int("n06.offset", offset),
            ],
        );
        assert_eq!(v.len(), 10);
        // The result less the line itself, in time order.
        let mut c: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.pitch)).collect();
        for &(s, _, p, _) in &line {
            let i = c.iter().position(|&x| x == (s, p)).unwrap();
            c.remove(i);
        }
        c.sort_unstable();
        c.into_iter().map(|x| x.1).collect::<Vec<_>>()
    };
    // Thirds and sixths below on the scale (all allowed intervals).
    assert_eq!(counter(2, 0), vec![69, 71, 72, 74, 76]);
    assert_eq!(counter(3, 0), vec![64, 65, 67, 69, 71]);
    // Contrary: against each move, the nearest allowed interval when the
    // mirrored step is not one (11, 15, 17 → 12, 12, 12).
    assert_eq!(counter(0, 0), vec![69, 67, 64, 65, 67]);
    // Oblique: held while allowed (8 at 77), else the nearest allowed.
    assert_eq!(counter(1, 0), vec![69, 70, 69, 69, 70]);
    // The register offset moves the line.
    assert_eq!(counter(3, -12), vec![52, 53, 55, 57, 59]);
    // Only the top voice of a chord is answered.
    let chord = [(0, 960, 60, 100), (0, 960, 64, 100), (0, 960, 79, 100)];
    let v = riff_sel(&chord, &[on("n06"), ch("n06.motion", 2)]);
    assert_eq!(
        spd(&v),
        vec![(0, 60, 960), (0, 64, 960), (0, 76, 960), (0, 79, 960)]
    );
}

#[test]
fn riff_span_fill_loops_stretches_and_evolves_to_the_target() {
    let base = [list("s1.degrees", &[1, 6, 4, 5])];
    let fill = |f: u32, target: u32, bars: i64| {
        let mut s = base.to_vec();
        s.extend([
            on("n07"),
            ch("n07.fill", f),
            ch("n07.target", target),
            int("n07.bars", bars),
        ]);
        s
    };
    let prog = [60u8, 69, 65, 67];
    let looped: Vec<(u64, u8, u64)> = (0..10u64)
        .map(|k| (k * BAR, prog[(k % 4) as usize], BAR))
        .collect();
    assert_eq!(spd(&riff_gen(&fill(0, 2, 10))), looped);
    let stretched: Vec<(u64, u8, u64)> = (0..4u64)
        .map(|k| (k * 2 * BAR, prog[k as usize], 2 * BAR))
        .collect();
    assert_eq!(spd(&riff_gen(&fill(1, 2, 8))), stretched);
    // One evolution step per repeat ([a4]'s rate, read with [a4] off).
    let mut s = fill(2, 2, 12);
    s.push(fl("a4.rate", 100.0));
    let v = pitches(&riff_gen(&s));
    let scale = [0i64, 2, 4, 5, 7, 9, 11];
    let degree = |p: u8| {
        let p = i64::from(p);
        let d = scale.iter().position(|&x| x == p.rem_euclid(12)).unwrap() as i64;
        p.div_euclid(12) * 7 + d
    };
    assert_eq!(&v[..4], &prog);
    for k in 4..12 {
        assert_eq!((degree(v[k]) - degree(v[k - 4])).abs(), 1, "{v:?}");
    }
    // The time selection: moved there, cut at its end.
    let mut ctx = Ctx::simple(960);
    ctx.time_range = Some((2 * BAR, 2 * BAR + 2 * BAR + 1920));
    let v = riff_in(Vec::new(), &riff_plain(&fill(0, 1, 1)), ctx);
    assert_eq!(
        spd(&v),
        vec![(2 * BAR, 60, BAR), (3 * BAR, 69, BAR), (4 * BAR, 65, 1920)]
    );
    // Without a time selection the riff stays as it is.
    let mut ctx = Ctx::simple(960);
    ctx.time_range = None;
    assert_eq!(
        spd(&riff_in(Vec::new(), &riff_plain(&fill(0, 1, 1)), ctx)),
        spd(&riff_gen(&base))
    );
    // The selection's span (6 bars from bar 1); the selection is kept.
    let sel = riff_tnotes(&[(BAR, 6 * BAR, 40, 100)]);
    let v = run_full("riff", sel, &riff_plain(&fill(0, 0, 1))).notes;
    let mut want: Vec<(u64, u8, u64)> = (0..6u64)
        .map(|k| (BAR + k * BAR, prog[(k % 4) as usize], BAR))
        .collect();
    want.push((BAR, 40, 6 * BAR));
    want.sort_unstable();
    assert_eq!(spd(&v), want);
}

#[test]
fn riff_variant_sheet_lays_out_consecutive_seeds() {
    // The default stages (random levels) so seeds differ.
    let base = |seed: i64| vec![int("seed", seed), ch("s3.pattern", 8)];
    let riff = |set: &[(&'static str, ParamValue)]| run_full("riff", Vec::new(), set).notes;
    let svp = |v: &[TNote]| {
        let mut o: Vec<(u64, u64, u8, u8)> =
            v.iter().map(|n| (n.start, n.dur, n.pitch, n.vel)).collect();
        o.sort_unstable();
        o
    };
    let mut s = base(11);
    s.extend([on("n08"), int("n08.count", 3), int("n08.step", 5)]);
    let v = riff(&s);
    for j in 0..3u32 {
        let part: Vec<TNote> = v.iter().copied().filter(|n| n.sub == j).collect();
        assert!(part.iter().all(|n| u32::from(n.ch) == j));
        assert_eq!(svp(&part), svp(&riff(&base(11 + 5 * i64::from(j)))), "{j}");
    }
    assert_ne!(
        svp(&riff(&base(11))),
        svp(&riff(&base(16))),
        "the seeds must matter"
    );
    // One after another: variant j from j riff lengths (4 bars each).
    s.push(ch("n08.layout", 1));
    let v = riff(&s);
    for j in 0..3u64 {
        let part: Vec<TNote> = v
            .iter()
            .copied()
            .filter(|n| n.start / (4 * BAR) == j)
            .map(|mut n| {
                n.start -= j * 4 * BAR;
                n
            })
            .collect();
        assert!(part.iter().all(|n| n.sub == 0));
        assert_eq!(svp(&part), svp(&riff(&base(11 + 5 * j as i64))), "{j}");
    }
}

#[test]
fn riff_accent_map_sets_velocity_per_step_of_the_meter() {
    let vels = |v: &[TNote]| {
        let mut o: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.vel)).collect();
        o.sort_unstable();
        o.into_iter().map(|x| x.1).collect::<Vec<_>>()
    };
    let sixteenths: Vec<(u64, u64, u8, u8)> = (0..16u64).map(|k| (k * 240, 240, 60, 100)).collect();
    let set = [
        on("n09"),
        list("n09.accents", &[120, 70, 90, 70]),
        int("n09.steps", 4),
    ];
    let mut want = Vec::new();
    for a in [120u8, 70, 90, 70] {
        want.extend([a; 4]);
    }
    assert_eq!(vels(&riff_sel(&sixteenths, &set)), want);
    // Base velocity 50: a note at 75 gets 1.5 × its accent.
    let v = riff_sel(&[(0, 240, 60, 50), (960, 240, 60, 75)], &set);
    assert_eq!(vels(&v), vec![120, 105]);
    // 3/4: three steps per bar of three beats, the list cycled.
    let mut ctx = Ctx::simple(960);
    ctx.meter = MeterMap::new(Division::ppqn(960), &[(0, 3, 2)]);
    let quarters: Vec<TNote> = riff_tnotes(
        &(0..6u64)
            .map(|k| (k * 960, 960, 60, 100))
            .collect::<Vec<_>>(),
    );
    let mut s = riff_plain(&[
        ch("source", 0),
        on("n09"),
        list("n09.accents", &[127, 60]),
        int("n09.steps", 3),
    ]);
    s.push(ch("source", 0));
    assert_eq!(
        vels(&riff_in(quarters, &s, ctx)),
        vec![127, 60, 127, 127, 60, 127]
    );
}

#[test]
fn riff_bar_displacement_drifts_each_bar_by_more_steps() {
    let downbeats: Vec<(u64, u64, u8, u8)> = (0..4u64).map(|k| (k * BAR, 240, 60, 100)).collect();
    let starts = |shift: i64, wrap: u32| {
        let mut v: Vec<u64> = riff_sel(
            &downbeats,
            &[on("n10"), int("n10.shift", shift), ch("n10.wrap", wrap)],
        )
        .iter()
        .map(|n| n.start)
        .collect();
        v.sort_unstable();
        v
    };
    assert_eq!(
        starts(1, 0),
        vec![0, BAR + 240, 2 * BAR + 480, 3 * BAR + 720]
    );
    assert_eq!(starts(16, 0), vec![0, BAR, 2 * BAR, 3 * BAR]);
    assert_eq!(starts(16, 1), vec![0, 2 * BAR, 4 * BAR, 6 * BAR]);
    assert_eq!(
        starts(-1, 0),
        vec![0, 2 * BAR - 240, 3 * BAR - 480, 4 * BAR - 720]
    );
}

#[test]
fn riff_ending_closes_on_the_tonic() {
    let base = [list("s1.degrees", &[1, 6, 4, 5])];
    let end = |kind: u32, beats: i64, run: u32| {
        let mut s = base.to_vec();
        s.extend([
            on("n11"),
            ch("n11.kind", kind),
            int("n11.beats", beats),
            ch("n11.run", run),
        ]);
        spd(&riff_gen(&s))
    };
    // A cadence chord: the tonic triad nearest the last note (F → C).
    assert_eq!(
        end(0, 4, 0),
        vec![
            (0, 60, BAR),
            (BAR, 69, BAR),
            (2 * BAR, 65, BAR),
            (3 * BAR, 60, BAR),
            (3 * BAR, 64, BAR),
            (3 * BAR, 67, BAR)
        ]
    );
    // One beat: the G before it is cut there, the triad over G is C E G
    // an octave up (72 is nearer 67 than 60).
    assert_eq!(
        &end(0, 1, 0)[3..],
        &[
            (3 * BAR, 67, BAR - 960),
            (4 * BAR - 960, 72, 960),
            (4 * BAR - 960, 76, 960),
            (4 * BAR - 960, 79, 960)
        ]
    );
    // A run of sixteenths onto C: from D two octaves up, or B two below.
    let run: Vec<u8> = end(1, 4, 0)[3..].iter().map(|x| x.1).collect();
    let down: Vec<u8> = vec![
        86, 84, 83, 81, 79, 77, 76, 74, 72, 71, 69, 67, 65, 64, 62, 60,
    ];
    assert_eq!(run, down);
    let up: Vec<u8> = end(1, 4, 1)[3..].iter().map(|x| x.1).collect();
    assert_eq!(
        up,
        vec![
            35, 36, 38, 40, 41, 43, 45, 47, 48, 50, 52, 53, 55, 57, 59, 60
        ]
    );
    assert!(end(1, 4, 0)[3..].iter().all(|x| x.2 == 240));
    // Ritardando over the last bar: u + u²/2, lengths × (1 + u).
    let q: Vec<(u64, u64, u8, u8)> = (0..8u64).map(|k| (k * 960, 960, 60, 100)).collect();
    let v = riff_sel(&q, &[on("n11"), ch("n11.kind", 2), int("n11.beats", 4)]);
    let tail: Vec<(u64, u64)> = spd(&v)[4..].iter().map(|x| (x.0, x.2)).collect();
    assert_eq!(
        tail,
        vec![
            (BAR, 960),
            (BAR + 1080, 1200),
            (BAR + 2400, 1440),
            (BAR + 3960, 1680)
        ]
    );
}

/// Every function's switch.
const RIFF_IDS: [&str; 11] = ALL11;

#[test]
fn riff_functions_compose_and_stay_within_the_preflight() {
    // Each function alone and every pair, generated and from a selection:
    // run_full asserts the result never exceeds the preflight's bound.
    let melody = riff_tnotes(&cp_melody());
    for (i, a) in RIFF_IDS.iter().enumerate() {
        for b in &RIFF_IDS[i..] {
            for sel in [Vec::new(), melody.clone()] {
                let set = [on(a), on(b), int("n04.bars", 8), int("n05.at", 2)];
                let v = run_full("riff", sel.clone(), &set).notes;
                assert!(!v.is_empty(), "{a} {b}");
            }
        }
    }
    // All eleven together: deterministic.
    let mut all: Vec<(&'static str, ParamValue)> = RIFF_IDS.iter().map(|k| on(k)).collect();
    all.push(int("n07.bars", 24));
    let a = run_full("riff", Vec::new(), &all).notes;
    let b = run_full("riff", Vec::new(), &all).notes;
    assert_eq!(fingerprint(&a), fingerprint(&b));
    assert!(a.len() > 1000);
    // An explosive combination is refused by the preflight with a sentence,
    // before anything is generated.
    let huge = vec![
        on("n02"),
        int("n02.layers", 8),
        list("n02.stages", &[255]),
        on("n03"),
        list("n03.form", &[0; 32]),
        int("n03.bars", 16),
        on("n07"),
        int("n07.bars", 1024),
        on("n08"),
        int("n08.count", 8),
        on("n04"),
        int("n04.bars", 64),
    ];
    let t = tool("riff").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, v) in &huge {
        ps.set(k, v.clone());
    }
    let src = Source::from_notes(Vec::new(), Vec::new());
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let e = match run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None) {
        Err(e) => e.user_message(),
        Ok(r) => panic!("not refused: {} notes", r.notes.len()),
    };
    assert!(e.ends_with('.') && e.contains("notes"), "{e}");
}

#[test]
fn riff_control_sweep_generates_a_riff_per_group() {
    // A swept layer count over a selection spread over 8 bars: each group
    // generates its own riff at its start (the selection kept).
    let sel = riff_tnotes(
        &(0..8u64)
            .map(|k| (k * BAR, 480, 60, 100))
            .collect::<Vec<_>>(),
    );
    let set = vec![
        on("n02"),
        on("m.sweep"),
        on("m.sweep.layers"),
        int("bars", 1),
    ];
    let a = run_full("riff", sel.clone(), &set).notes;
    let b = run_full("riff", sel.clone(), &set).notes;
    assert_eq!(fingerprint(&a), fingerprint(&b));
    assert!(a.len() > 8);
}

// ================================================================ Slide / Portamento

/// A slide fixture note: start, length, pitch, velocity, MIDI channel,
/// selected.
type SlideNote = (u64, u64, u8, u8, u8, bool);

/// A melody on channel 1 (steps and leaps, eighths and quarters), a bass
/// line on channel 2, a chord on channel 3 and unselected notes on channel
/// 1 that some glides would bend (a fixed LCG).
fn slide_fixture() -> Vec<SlideNote> {
    let mut x: u64 = 0x511D_E035;
    let mut next = |m: u64| {
        x = x
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (x >> 33) % m
    };
    let mut v = Vec::new();
    let mut t = 0;
    let mut p: i64 = 67;
    for _ in 0..24 {
        let len = if next(3) == 0 { 960 } else { 480 };
        let step = [-7i64, -2, -1, 1, 2, 3, 5, 12][next(8) as usize];
        p = (p + step).clamp(55, 84);
        v.push((t, len, p as u8, 60 + next(60) as u8, 0, true));
        t += len;
    }
    for k in 0..8u64 {
        v.push((k * 1920, 1920, 40 + next(12) as u8, 90, 1, true));
    }
    for p in [60u8, 64, 67] {
        v.push((7680, 960, p, 80, 2, true));
    }
    for k in 0..4u64 {
        v.push((k * 3000 + 500, 700, 50 + k as u8, 70, 0, false));
    }
    v
}

/// Runs Slide on `notes` in one track (selected ones in scope, the others
/// context) with `set`: the whole result, events included.
fn slide_run(
    notes: &[SlideNote],
    set: &[(&'static str, ParamValue)],
    ctx: Option<Ctx>,
) -> plumspirit_engine::transform::TransformRun {
    let mut d = PlumDocument::new_project("s35".into(), Bpm::DEFAULT, 960);
    for sel in [true, false] {
        let mut v: Vec<NoteRecord> = notes
            .iter()
            .filter(|n| n.5 == sel)
            .map(|&(s, l, p, vel, c, _)| NoteRecord {
                start_tick: s,
                duration_ticks: l,
                attrs: NoteAttrs::new(p, vel, c, 0, NoteOffKind::NoteOff).unwrap(),
                sub: SubchannelId(0),
                group: 0,
            })
            .collect();
        v.sort_by_key(|r| r.start_tick);
        d.track_mut(0)
            .unwrap()
            .notes
            .insert_sorted_batch(&v, sel)
            .unwrap();
    }
    let t = tool("slide").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let src = collect_with(t, &d, &sc, &ps, 1 << 24).unwrap();
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r
}

/// Notes and controller points of a run, hashed.
fn slide_fingerprint(r: &plumspirit_engine::transform::TransformRun) -> (usize, usize, u64) {
    let (n, h) = fingerprint(&r.notes);
    let mut h = h;
    let mut eat = |w: u64| {
        for b in w.to_le_bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0100_0000_01B3);
        }
    };
    for e in &r.events {
        let lane = match e.lane {
            plumspirit_engine::transform::output::Lane::Cc(c) => u64::from(c),
            plumspirit_engine::transform::output::Lane::PitchBend => 1000,
        };
        eat(u64::from(e.track) | lane << 16 | u64::from(e.ch) << 32);
        eat(e.tick);
        eat(u64::from(e.value) | u64::from(r.notes.iter().map(|n| n.ch).max().unwrap_or(0)) << 16);
    }
    (n, r.events.len(), h)
}

