#[test]
fn slide_new_functions_off_leave_v08_results_unchanged() {
    let fx = slide_fixture();
    let all = slide_v08_settings();
    assert_eq!(all.len(), SLIDE_V08.len());
    for (i, s) in all.into_iter().enumerate() {
        let mut set = s;
        for k in ALL11 {
            set.push((k, ParamValue::Bool(false)));
        }
        assert_eq!(
            slide_fingerprint(&slide_run(&fx, &set, None)),
            SLIDE_V08[i],
            "setting {i}"
        );
    }
}

use plumspirit_engine::transform::output::Lane;

/// Pitch-bend points of a run: (channel, tick, value) in order.
fn slide_pb(r: &plumspirit_engine::transform::TransformRun) -> Vec<(u8, u64, u16)> {
    r.events
        .iter()
        .filter(|e| e.lane == Lane::PitchBend)
        .map(|e| (e.ch, e.tick, e.value))
        .collect()
}

/// Control Change `num` points of a run: (channel, tick, value).
fn slide_cc(r: &plumspirit_engine::transform::TransformRun, num: u8) -> Vec<(u8, u64, u16)> {
    r.events
        .iter()
        .filter(|e| e.lane == Lane::Cc(num))
        .map(|e| (e.ch, e.tick, e.value))
        .collect()
}

/// Selected notes on channel 1 (index 0): (start, length, pitch).
fn slide_line(v: &[(u64, u64, u8)]) -> Vec<SlideNote> {
    v.iter().map(|&(s, l, p)| (s, l, p, 100, 0, true)).collect()
}

/// The bend value of `semis` at range `r` (as the tool rounds it).
fn bend_of(semis: f64, r: f64) -> u16 {
    (8192.0 + semis / r * 8192.0).round().clamp(0.0, 16383.0) as u16
}

#[test]
fn slide_v09_pipeline_with_a_neutral_function_equals_v08() {
    // A window letting every interval through runs the v0.9 planner: its
    // notes and points equal the v0.8 kernel's for v0.8 settings.
    let fx = slide_fixture();
    let neutral = [
        on("n02"),
        int("n02.lo", 0),
        int("n02.hi", 48),
        ch("n02.dir", 2),
    ];
    for (i, s) in slide_v08_settings().into_iter().enumerate() {
        let a = slide_run(&fx, &s, None);
        let mut s2 = s.clone();
        s2.extend_from_slice(&neutral);
        let b = slide_run(&fx, &s2, None);
        assert_eq!(slide_fingerprint(&a), slide_fingerprint(&b), "setting {i}");
    }
}

#[test]
fn slide_real_time_glide_timing_follows_the_tempo_map() {
    let line = slide_line(&[(0, 960, 60), (960, 960, 62), (1920, 960, 67)]);
    let set = [
        on("n01"),
        fl("n01.ms", 50.0),
        fl("n01.per", 10.0),
        fl("n01.lo", 20.0),
        fl("n01.hi", 200.0),
        int("range", 12),
    ];
    // The glide's last point (the centre) ends it: 70 ms (2 semitones) and
    // 100 ms (5) at 120 BPM = 1.92 ticks per ms.
    let ends = |r: &plumspirit_engine::transform::TransformRun| {
        let pb = slide_pb(r);
        [960u64, 1920].map(|s| {
            pb.iter()
                .filter(|e| e.1 >= s && e.1 < s + 960 && e.2 == 8192)
                .map(|e| e.1 - s)
                .max()
                .unwrap()
        })
    };
    // (the first tick at or after the time: 134.4 → 135).
    assert_eq!(ends(&slide_run(&line, &set, None)), [135, 192]);
    // At 60 BPM a millisecond is half as many ticks.
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[(0, TempoValue::Micros(1_000_000))],
    )));
    assert_eq!(ends(&slide_run(&line, &set, Some(ctx))), [68, 96]);
    // Shortest / longest clamp it.
    let mut s2 = set.to_vec();
    s2.extend([fl("n01.per", 100.0), fl("n01.hi", 150.0)]);
    assert_eq!(ends(&slide_run(&line, &s2, None)), [288, 288]);
}

#[test]
fn slide_interval_window_glides_only_inside_it() {
    // 60 → 62 (up 2), → 67 (up 5), → 66 (down 1).
    let line = slide_line(&[
        (0, 480, 60),
        (480, 480, 62),
        (960, 480, 67),
        (1440, 480, 66),
    ]);
    let glided = |lo: i64, hi: i64, dir: u32| {
        let r = slide_run(
            &line,
            &[
                on("n02"),
                int("n02.lo", lo),
                int("n02.hi", hi),
                ch("n02.dir", dir),
                int("range", 12),
            ],
            None,
        );
        let mut s: Vec<u64> = slide_pb(&r).iter().map(|e| e.1 / 480 * 480).collect();
        s.dedup();
        s
    };
    assert_eq!(glided(1, 2, 0), vec![480]);
    assert_eq!(glided(1, 5, 0), vec![480, 960]);
    assert_eq!(glided(1, 5, 1), vec![1440]);
    assert_eq!(glided(1, 5, 2), vec![480, 960, 1440]);
    assert_eq!(glided(3, 48, 2), vec![960]);
}

#[test]
fn slide_release_bends_fall_doit_and_scoop() {
    let one = slide_line(&[(0, 960, 60)]);
    let rel = |kind: u32, time: f64| {
        slide_pb(&slide_run(
            &one,
            &[
                on("n03"),
                ch("n03.kind", kind),
                int("n03.depth", 2),
                fl("n03.time", time),
            ],
            None,
        ))
    };
    // A fall over the last half: 16 points 480 … 959 from 0 to −2, then
    // the centre after the note.
    let f = rel(0, 50.0);
    assert_eq!(f.len(), 17);
    assert_eq!(f[0], (0, 480, 8192));
    assert_eq!(f[15], (0, 959, 0));
    assert_eq!(f[16], (0, 960, 8192));
    for (j, e) in f[..16].iter().enumerate() {
        let u = j as f64 / 15.0;
        assert_eq!(e.1, 480 + (479.0 * u).round() as u64);
        assert_eq!(e.2, bend_of(-2.0 * u, 2.0));
    }
    // A doit goes up.
    let d = rel(1, 50.0);
    assert_eq!(d[15], (0, 959, 16383));
    // A scoop rises from −2 into the note over its first quarter.
    let s = rel(2, 25.0);
    assert_eq!(s.first(), Some(&(0, 0, 0)));
    assert_eq!(s.last(), Some(&(0, 240, 8192)));
    // After a glide the fall begins where the glide ends at the earliest.
    let two = slide_line(&[(0, 960, 60), (960, 960, 61)]);
    let r = slide_run(
        &two,
        &[on("n03"), int("n03.depth", 1), fl("n03.time", 90.0)],
        None,
    );
    let pb = slide_pb(&r);
    let glide_end = 960 + 240;
    assert!(pb.contains(&(0, glide_end, 8192)));
    assert!(pb.iter().any(|e| e.1 == 1919 && e.2 == bend_of(-1.0, 2.0)));
    // From the glide's end the bend only falls until the centre at 1920.
    let fall: Vec<u16> = pb
        .iter()
        .filter(|e| e.1 >= glide_end && e.1 < 1920)
        .map(|e| e.2)
        .collect();
    assert!(fall.windows(2).all(|w| w[1] <= w[0]), "{fall:?}");
}

#[test]
fn slide_bend_trill_alternates_without_extra_notes() {
    let one = slide_line(&[(0, 960, 60)]);
    let trill = |wave: u32, delay: i64| {
        let r = slide_run(
            &one,
            &[
                on("n04"),
                int("n04.interval", 2),
                fl("n04.rate", 4.0),
                ch("n04.wave", wave),
                int("n04.delay", delay),
            ],
            None,
        );
        assert_eq!(r.notes.len(), 1);
        slide_pb(&r)
    };
    // Square at 4 per beat: a half cycle is 120 ticks.
    let sq = trill(0, 0);
    let want: Vec<(u8, u64, u16)> = (0..8u64)
        .map(|k| (0, k * 120, if k % 2 == 1 { 16383 } else { 8192 }))
        .chain([(0, 960, 8192)])
        .collect();
    assert_eq!(sq, want);
    // After a delay of a beat.
    assert_eq!(trill(0, 960).len(), 0);
    assert_eq!(trill(0, 480)[0], (0, 480, 8192));
    // Triangle: eight points per cycle of 240 ticks, peak at its middle.
    let tri = trill(1, 0);
    assert_eq!(tri.len(), 4 * 8 + 1);
    assert_eq!(tri[4], (0, 120, 16383));
    assert_eq!(tri[2], (0, 60, bend_of(1.0, 2.0)));
    // Sine: (1 − cos)/2.
    let sine = trill(2, 0);
    assert_eq!(sine[2], (0, 60, bend_of(1.0, 2.0)));
    assert_eq!(
        sine[1],
        (
            0,
            30,
            bend_of(2.0 * (1.0 - (std::f64::consts::TAU / 8.0).cos()) / 2.0, 2.0)
        )
    );
}

#[test]
fn slide_expression_envelope_shapes_each_glide() {
    let two = slide_line(&[(0, 960, 60), (960, 960, 61)]);
    let r = slide_run(
        &two,
        &[
            on("n05"),
            ch("n05.cc", 2),
            int("n05.lo", 0),
            int("n05.hi", 100),
        ],
        None,
    );
    let want: Vec<(u8, u64, u16)> = (0..16u64)
        .map(|j| {
            (
                0,
                960 + (240.0 * j as f64 / 15.0).round() as u64,
                (100.0 * j as f64 / 15.0).round() as u16,
            )
        })
        .collect();
    assert_eq!(slide_cc(&r, 11), want);
    // CC 1 instead, a dip curve.
    let r = slide_run(
        &two,
        &[
            on("n05"),
            ch("n05.cc", 0),
            curve("n05.curve", Curve::line(1.0, 0.0)),
        ],
        None,
    );
    let c = slide_cc(&r, 1);
    assert_eq!((c[0].2, c[15].2), (127, 64));
    assert!(slide_cc(&r, 11).is_empty());
}

#[test]
fn slide_glide_source_rules() {
    // Selected 60 (ch 1) and 72 (ch 1); an unselected 70 on channel 2
    // still sounding when 72 starts.
    let notes: Vec<SlideNote> = vec![
        (0, 480, 60, 100, 0, true),
        (240, 960, 70, 100, 1, false),
        (960, 480, 72, 100, 0, true),
        (1440, 480, 64, 100, 0, true),
    ];
    let first_point = |rule: u32, window: i64| {
        let r = slide_run(
            &notes,
            &[
                on("n06"),
                ch("n06.from", rule),
                int("n06.window", window),
                int("range", 12),
            ],
            None,
        );
        let pb = slide_pb(&r);
        [960u64, 1440].map(|s| pb.iter().find(|e| e.1 == s).map(|e| e.2))
    };
    let b = |s: f64| Some(bend_of(s, 12.0));
    // Nearest previous pitch: 70 for 72 (−2); for 64, 60 (ended 960 ticks
    // before, inside the window) is nearer than 70 and 72 (−4).
    assert_eq!(first_point(0, 960), [b(-2.0), b(-4.0)]);
    // Highest previous voice: 70, then 72.
    assert_eq!(first_point(3, 960), [b(-2.0), b(8.0)]);
    // Previous on the track (latest start before it): 70, then 72.
    assert_eq!(first_point(2, 960), [b(-2.0), b(8.0)]);
    // The window: with 0 ticks 60 (ended at 480) and 70 (at 1200) no
    // longer count for 64; 72 ends exactly at its start.
    assert_eq!(first_point(0, 0), [b(-2.0), b(8.0)]);
    // v0.8's rule (previous on the channel): 60 → −12 and 72 → +8.
    let r = slide_run(&notes, &[int("range", 12)], None);
    let pb = slide_pb(&r);
    assert_eq!(pb.iter().find(|e| e.1 == 960).map(|e| e.2), b(-12.0));
}

#[test]
fn slide_bend_chain_holds_the_bend_across_glides() {
    let line = slide_line(&[
        (0, 480, 60),
        (480, 480, 61),
        (960, 480, 62),
        (1440, 480, 63),
    ]);
    let r = slide_run(&line, &[on("n07"), int("range", 2)], None);
    // 61 and 62 are played on 60's key; 63 would need +3: a new chain.
    let mut p: Vec<(u64, u8)> = r.notes.iter().map(|n| (n.start, n.pitch)).collect();
    p.sort_unstable();
    assert_eq!(p, vec![(0, 60), (480, 60), (960, 60), (1440, 63)]);
    let pb = slide_pb(&r);
    let at = |t: u64| pb.iter().find(|e| e.1 == t).map(|e| e.2);
    // Each chained glide ends on its offset and holds it.
    assert_eq!(at(480), Some(8192));
    assert_eq!(at(480 + 240), Some(bend_of(1.0, 2.0)));
    assert_eq!(at(960), Some(bend_of(1.0, 2.0)));
    assert_eq!(at(960 + 240), Some(16383));
    // 63's own glide from 62 (−1) starts the next chain, back at 0.
    assert_eq!(at(1440), Some(bend_of(-1.0, 2.0)));
    assert_eq!(at(1440 + 240), Some(8192));
    // At rests: a gap of a beat ends the chain (the next note glides in
    // normally).
    let gap = slide_line(&[(0, 480, 60), (480, 480, 61), (1920, 480, 62)]);
    let r = slide_run(
        &gap,
        &[
            on("n07"),
            ch("n07.recentre", 1),
            int("n07.rest", 960),
            int("range", 2),
        ],
        None,
    );
    let mut p: Vec<u8> = r.notes.iter().map(|n| n.pitch).collect();
    p.sort_unstable();
    assert_eq!(p, vec![60, 60, 62]);
    assert!(slide_pb(&r).contains(&(0, 960, 8192)));
    // "At rests" only: a glide out of the range is not chained and is
    // played without a glide.
    let r = slide_run(
        &line,
        &[on("n07"), ch("n07.recentre", 1), int("range", 2)],
        None,
    );
    assert!(
        !slide_pb(&r)
            .iter()
            .any(|e| e.1 >= 1440 && e.1 < 1440 + 240 && e.2 != 8192)
    );
    assert!(r.notes.iter().any(|n| n.start == 1440 && n.pitch == 63));
}

#[test]
fn slide_auto_bend_range_writes_the_smallest_range() {
    // Glides of 3 and 5 semitones on one channel.
    let line = slide_line(&[(0, 960, 60), (960, 960, 63), (1920, 960, 68)]);
    let rpn = |r: &plumspirit_engine::transform::TransformRun| slide_cc(r, 6);
    let r = slide_run(&line, &[on("n08"), int("n08.max", 12)], None);
    // RPN 0 just before the first glide (CC 6 = the range at start − 2).
    assert_eq!(rpn(&r), vec![(0, 958, 5)]);
    assert!(slide_pb(&r).contains(&(0, 960, bend_of(-3.0, 5.0))));
    assert!(slide_pb(&r).contains(&(0, 1920, bend_of(-5.0, 5.0))));
    // Before each change: 3, then 5.
    let r = slide_run(
        &line,
        &[on("n08"), int("n08.max", 12), ch("n08.write", 1)],
        None,
    );
    assert_eq!(rpn(&r), vec![(0, 958, 3), (0, 1918, 5)]);
    assert!(slide_pb(&r).contains(&(0, 960, bend_of(-3.0, 3.0))));
    // A glide beyond the largest range is skipped.
    let r = slide_run(&line, &[on("n08"), int("n08.max", 4)], None);
    assert_eq!(rpn(&r), vec![(0, 958, 3)]);
    assert!(!slide_pb(&r).iter().any(|e| e.1 >= 1920));
}

#[test]
fn slide_voice_matched_chord_glides_on_their_own_channels() {
    // C E G, then D F A on channel 1.
    let mut notes: Vec<SlideNote> = Vec::new();
    for p in [60u8, 64, 67] {
        notes.push((0, 960, p, 100, 0, true));
    }
    for p in [62u8, 65, 69] {
        notes.push((960, 960, p, 100, 0, true));
    }
    let r = slide_run(&notes, &[on("n09"), int("range", 2)], None);
    // Each voice from its rank: −2, −1, −2, each on a free channel (channel
    // 1 still holds C E G's release tail).
    let mut moved: Vec<(u8, u8)> = r
        .notes
        .iter()
        .filter(|n| n.start == 960)
        .map(|n| (n.pitch, n.ch))
        .collect();
    moved.sort_unstable();
    assert_eq!(moved, vec![(62, 1), (65, 2), (69, 3)]);
    let pb = slide_pb(&r);
    assert!(pb.contains(&(1, 960, bend_of(-2.0, 2.0))));
    assert!(pb.contains(&(2, 960, bend_of(-1.0, 2.0))));
    assert!(pb.contains(&(3, 960, bend_of(-2.0, 2.0))));
    assert!(!pb.iter().any(|e| e.0 == 0));
    // By nearest pitch: D G B from C E G — 60 (tie: lower), 67, 67 (+4 is
    // over the largest 3: no glide).
    let mut notes2 = notes[..3].to_vec();
    for p in [62u8, 67, 71] {
        notes2.push((960, 960, p, 100, 0, true));
    }
    let r = slide_run(
        &notes2,
        &[
            on("n09"),
            ch("n09.by", 1),
            int("n09.max", 3),
            int("range", 12),
        ],
        None,
    );
    let pb = slide_pb(&r);
    let first: Vec<u16> = pb.iter().filter(|e| e.1 == 960).map(|e| e.2).collect();
    assert!(first.contains(&bend_of(-2.0, 12.0)));
    assert!(first.contains(&8192));
    assert_eq!(first.len(), 2);
}

#[test]
fn slide_channel_allocation_keeps_bends_off_other_notes() {
    // A melody on channel 1 over an unselected held note on channel 1.
    let mut notes = slide_line(&[(0, 480, 60), (480, 480, 62), (960, 480, 64)]);
    notes.push((0, 1920, 48, 80, 0, false));
    let run = |extra: &[(&'static str, ParamValue)]| {
        let mut s = vec![on("n10"), int("range", 2)];
        s.extend_from_slice(extra);
        slide_run(&notes, &s, None)
    };
    // Round robin over the pool (channel 10 skipped): the two glided notes
    // go to channels 2 and 3; channel 1 gets no bend.
    let r = run(&[]);
    let mut chs: Vec<(u64, u8)> = r.notes.iter().map(|n| (n.start, n.ch)).collect();
    chs.sort_unstable();
    assert_eq!(chs, vec![(0, 0), (480, 1), (960, 2)]);
    assert!(slide_pb(&r).iter().all(|e| e.0 != 0));
    // Least recently used: channel 2 is free again after its tail.
    let r = run(&[ch("n10.policy", 1), int("n10.tail", 0)]);
    let mut chs: Vec<(u64, u8)> = r.notes.iter().map(|n| (n.start, n.ch)).collect();
    chs.sort_unstable();
    assert_eq!(chs[1..], [(480, 1), (960, 2)]);
    // A pool of channel 1 alone has no free channel: no glide, no move.
    let r = run(&[list("n10.pool", &[1])]);
    assert!(slide_pb(&r).is_empty());
    assert!(r.message.as_deref().unwrap().contains("no free channel"));
    assert!(r.notes.iter().all(|n| n.ch == 0));
    // Channel 10 used when asked: pool 10 only.
    let r = run(&[
        list("n10.pool", &[10]),
        ch("n10.ch10", 1),
        int("n10.tail", 0),
    ]);
    assert!(r.notes.iter().any(|n| n.ch == 9));
}

#[test]
fn slide_bend_thinning_keeps_the_error_and_the_rate() {
    // One slow glide: 256 points over a bar, 2 semitones.
    let two = slide_line(&[(0, 3840, 60), (3840, 3840, 62)]);
    let base = [int("steps", 256), ch("time", 0), int("range", 2)];
    let full = slide_pb(&slide_run(&two, &base, None));
    let mut s = base.to_vec();
    s.extend([on("n11"), int("n11.cents", 5), int("n11.rate", 10_000)]);
    let thin = slide_pb(&slide_run(&two, &s, None));
    assert!(
        thin.len() < full.len() / 4,
        "{} of {}",
        thin.len(),
        full.len()
    );
    // The held value never strays more than 5 cents from the full curve.
    let tol = 0.05 / 2.0 * 8192.0;
    for e in &full {
        let held = thin.iter().rev().find(|t| t.1 <= e.1).unwrap();
        assert!(
            (f64::from(held.2) - f64::from(e.2)).abs() <= tol + 0.5,
            "{e:?} {held:?}"
        );
    }
    assert_eq!(thin.first(), full.first());
    assert_eq!(thin.last(), full.last());
    // A sine trill over two seconds held to 100 points per second.
    let one = slide_line(&[(0, 3840, 60)]);
    let s = [
        on("n04"),
        ch("n04.wave", 2),
        fl("n04.rate", 16.0),
        on("n11"),
        int("n11.cents", 1),
        int("n11.rate", 100),
    ];
    let v = slide_pb(&slide_run(&one, &s, None));
    let us = |t: u64| t * 500_000 / 960;
    for e in &v {
        let n = v
            .iter()
            .filter(|x| us(x.1) <= us(e.1) && us(x.1) + 1_000_000 > us(e.1))
            .count();
        assert!(n <= 101, "{n} points in the second before {}", e.1);
    }
    assert!(v.len() > 150, "{}", v.len());
}

#[test]
fn slide_functions_compose_and_stay_within_the_preflight() {
    let fx = slide_fixture();
    // Each function alone and every pair: slide_run asserts the notes bound.
    for (i, a) in ALL11.iter().enumerate() {
        for b in &ALL11[i..] {
            let r = slide_run(&fx, &[on(a), on(b), int("range", 12)], None);
            assert_eq!(r.notes.len(), 35, "{a} {b}");
        }
    }
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|k| on(k)).collect();
    let a = slide_run(&fx, &all, None);
    let b = slide_run(&fx, &all, None);
    assert_eq!(slide_fingerprint(&a), slide_fingerprint(&b));
    // A trill too dense for the event limit is refused before writing.
    let t = tool("slide").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, v) in [on("n04"), fl("n04.rate", 64.0)] {
        ps.set(k, v);
    }
    let src = Source::from_notes(riff_tnotes(&[(0, 1 << 30, 60, 100)]), Vec::new());
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    match t.kernel(&ps, &b) {
        Err(e) => assert!(
            e.user_message().contains("pitch-bend events"),
            "{}",
            e.user_message()
        ),
        Ok(_) => panic!("not refused"),
    }
}

#[test]
fn slide_per_subchannel_allocation_and_a_control_sweep() {
    // Glides into notes of subchannels 1 and 2 (positions 1, 2): each to
    // the pool's channel at its position.
    let mk = |s: u64, p: u8, sub: u32| TNote {
        start: s,
        dur: 480,
        pitch: p,
        vel: 100,
        sub,
        ..TNote::default()
    };
    let notes = vec![mk(0, 60, 1), mk(480, 62, 1), mk(0, 67, 2), mk(480, 69, 2)];
    let set = [
        on("n10"),
        ch("n10.policy", 2),
        int("n10.tail", 0),
        on("n06"),
        ch("n06.from", 1),
        int("range", 2),
    ];
    let r = run_full("slide", notes.clone(), &set);
    let moved: Vec<(u32, u8)> = r
        .notes
        .iter()
        .filter(|n| n.start == 480)
        .map(|n| (n.sub, n.ch))
        .collect();
    assert_eq!(moved, vec![(1, 1), (2, 2)]);
    // A glide time swept over time: each group of the sweep runs on its
    // own notes (deterministic, the notes unchanged).
    let sweep = [
        on("n01"),
        on("m.sweep"),
        on("m.sweep.glide_time"),
        int("range", 12),
    ];
    let a = run_full("slide", notes.clone(), &sweep);
    let b = run_full("slide", notes, &sweep);
    assert_eq!(a.notes, b.notes);
    assert_eq!(a.events, b.events);
}

// ================================================================ Humanize

/// The Flam fixture with velocities as hand-built notes spread over
/// subchannels 0 – 3 (every fourth note in each; per-subchannel profiles
/// read them).
fn hum_fixture() -> Vec<TNote> {
    flam_fixture()
        .iter()
        .enumerate()
        .map(|(i, &(start, dur, pitch, vel))| TNote {
            start,
            dur,
            pitch,
            vel,
            sub: (i % 4) as u32,
            ch: (i % 4) as u8,
            ..TNote::default()
        })
        .collect()
}

/// Ranges every v0.8 setting below varies within.
fn hum_ranges() -> Vec<(&'static str, ParamValue)> {
    vec![
        int("tick.min", -30),
        int("tick.max", 40),
        int("gate.min", -25),
        int("gate.max", 20),
        int("vel.min", -12),
        int("vel.max", 9),
    ]
}

/// Settings of the v0.8 Humanize (base controls and each frozen function).
fn hum_v08_settings() -> Vec<Vec<(&'static str, ParamValue)>> {
    let r = hum_ranges;
    let with = |extra: Vec<(&'static str, ParamValue)>| {
        let mut v = r();
        v.extend(extra);
        v
    };
    vec![
        vec![],
        r(),
        with(vec![int("seed", 99)]),
        with(vec![
            ch("gate.unit", 1),
            int("gate.min", -30),
            int("gate.max", 50),
        ]),
        with(vec![on("a1"), int("a1.step", 12), int("a1.vstep", 3)]),
        with(vec![on("a2"), fl("a2.sigma", 0.5)]),
        with(vec![on("a3"), fl("a3.mode", 0.6)]),
        with(vec![on("a4"), int("a4.len", 700), fl("a4.mix", 0.7)]),
        with(vec![on("a5"), int("a5.tol", 20)]),
        with(vec![
            on("a6"),
            int("a6.window", 1500),
            fl("a6.amount", -0.6),
        ]),
        with(vec![on("a7"), fl("a7.amount", 0.8)]),
        with(vec![
            on("a8"),
            curve(
                "a8.curve",
                Curve::smooth(vec![(0.0, 0.2), (0.5, 1.0), (1.0, 0.0)]),
            ),
        ]),
        with(vec![
            on("a9"),
            list("a9.bias", &[0, 25, -40]),
            list("a9.scale", &[100, 0, 250, 60]),
        ]),
        with(vec![on("a10"), int("a10.period", 1920)]),
        with(vec![on("a2"), on("a4"), on("a5"), on("a7")]),
        with(vec![
            on("a3"),
            on("a6"),
            on("a8"),
            on("a9"),
            on("a10"),
            list("a9.bias", &[10, -10]),
        ]),
        with(vec![on("a1"), on("a6"), ch("gate.unit", 1)]),
    ]
}

