fn hum_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

#[test]
fn hum_new_functions_off_leave_v08_results_unchanged() {
    let got: Vec<(usize, u64)> = hum_v08_settings()
        .iter()
        .map(|s| fingerprint(&run_full("humanize", hum_fixture(), &hum_off(s)).notes))
        .collect();
    assert_eq!(got.len(), HUM_V08.len());
    for (i, (g, w)) in got.iter().zip(HUM_V08).enumerate() {
        assert_eq!(g, w, "setting {i}");
    }
}

/// Runs Humanize on hand-built notes of one track with subchannels 0 – 3
/// (MIDI channels 0 – 3) in `ctx` (`Ctx::simple(960)` when `None`); the
/// result stays within the preflight bound.
fn hum_in(notes: Vec<TNote>, set: &[(&'static str, ParamValue)], ctx: Option<Ctx>) -> Vec<TNote> {
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track]);
    let t = tool("humanize").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r.notes
}

fn hum(notes: Vec<TNote>, set: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    hum_in(notes, set, None)
}

/// A line of `n` notes every `step` ticks from `at`, length `len`, pitch
/// 40 + i % 40 and velocity 1 + i (each note found again by its velocity).
fn hum_line(n: usize, at: u64, step: u64, len: u64) -> Vec<TNote> {
    (0..n)
        .map(|i| TNote {
            start: at + i as u64 * step,
            dur: len,
            pitch: 40 + (i % 40) as u8,
            vel: 1 + i as u8,
            ..TNote::default()
        })
        .collect()
}

/// The result note of velocity `vel` (each [`hum_line`] note).
fn by_vel(v: &[TNote], vel: u8) -> TNote {
    *v.iter().find(|n| n.vel == vel).unwrap()
}

/// Order of the notes of `orig` in `out` (matched by velocity) never
/// changes: starts and ends non-decreasing in written order.
fn hum_keeps_order(orig: &[TNote], out: &[TNote]) {
    let mut w: Vec<&TNote> = orig.iter().collect();
    w.sort_by_key(|n| n.start);
    for p in w.windows(2) {
        let (a, b) = (by_vel(out, p[0].vel), by_vel(out, p[1].vel));
        assert!(a.start <= b.start, "{a:?} {b:?}");
        assert!(a.end() <= b.end() || p[0].end() > p[1].end(), "{a:?} {b:?}");
    }
}

#[test]
fn hum_rubato_warp_returns_to_bar_lines_and_never_reorders() {
    // 1/16 notes over four bars, 60 ms of smooth rubato per two beats.
    let line = hum_line(64, 0, 240, 200);
    let set = [on("n01"), fl("n01.depth", 60.0), int("n01.period", 1920)];
    let v = hum(line.clone(), &set);
    hum_keeps_order(&line, &v);
    let mut most = 0u64;
    for n in &line {
        let o = by_vel(&v, n.vel);
        if n.start % 3840 == 0 {
            assert_eq!(o.start, n.start, "a bar line stays");
        }
        // 60 ms at 120 BPM / 960 PPQN = 115.2 ticks.
        let d = o.start.abs_diff(n.start);
        assert!(d <= 116, "{n:?} {o:?}");
        most = most.max(d);
        // The end is warped by the same map: a length never goes negative.
        assert!(o.end() > o.start);
    }
    assert!(most > 20, "the warp moved notes ({most})");
    assert_eq!(v, hum(line.clone(), &set), "deterministic");
    // Through a stepped tempo map (120 → 60 BPM at beat 2): still in order,
    // bar lines kept, and every move within 60 ms of real time.
    let ctx = qnt_stepped_tempo();
    let v = hum_in(line.clone(), &set, Some(ctx.clone()));
    hum_keeps_order(&line, &v);
    for n in &line {
        let o = by_vel(&v, n.vel);
        if n.start % 3840 == 0 {
            assert_eq!(o.start, n.start);
        }
        assert!((qnt_us_at(o.start) - qnt_us_at(n.start)).abs() <= 60_000.0 + 1_100.0);
    }
    // A very short period caps the amplitude: still in order.
    let set = [on("n01"), fl("n01.depth", 500.0), int("n01.period", 7)];
    let v = hum(line.clone(), &set);
    hum_keeps_order(&line, &v);
}

#[test]
fn hum_drawn_rubato_follows_the_curve_from_its_anchors() {
    // A drawn curve (½ = in time) over cells of four bars, no other anchor:
    // displacement = depth · (2 c(u) − 1) where the curve's ends are ½.
    let c = Curve::new(vec![(0.0, 0.5), (0.5, 1.0), (1.0, 0.5)]);
    let set = [
        on("n01"),
        fl("n01.depth", 50.0),
        int("n01.period", 15_360),
        ch("n01.anchor", 2),
        ch("n01.shape", 1),
        curve("n01.curve", c.clone()),
    ];
    let line = hum_line(17, 0, 960, 100);
    let v = hum(line.clone(), &set);
    for n in &line {
        let u = (n.start % 15_360) as f64 / 15_360.0;
        // 1 ms = 1.92 ticks at 120 BPM / 960 PPQN.
        let want = n.start as f64 + 50.0 * 1.92 * (2.0 * c.eval(u) - 1.0);
        let o = by_vel(&v, n.vel);
        assert!((o.start as f64 - want).abs() <= 1.0, "{n:?} {o:?} {want}");
    }
    assert_eq!(by_vel(&v, 1).start, 0);
    assert_eq!(by_vel(&v, 5).start, 3840 + 48);
    assert_eq!(by_vel(&v, 9).start, 7680 + 96);
    // Phrase anchors: each phrase (split at rests of a beat or more)
    // starts and ends where it was written.
    let mut two = hum_line(8, 0, 240, 200);
    two.extend(hum_line(8, 4800, 240, 200).into_iter().map(|mut n| {
        n.vel += 8;
        n
    }));
    let set = [
        on("n01"),
        fl("n01.depth", 40.0),
        int("n01.period", 480),
        ch("n01.anchor", 1),
    ];
    let v = hum(two.clone(), &set);
    hum_keeps_order(&two, &v);
    assert_eq!(by_vel(&v, 1).start, 0);
    assert_eq!(by_vel(&v, 9).start, 4800);
    assert_eq!(by_vel(&v, 8).end(), 7 * 240 + 200);
    assert_eq!(by_vel(&v, 16).end(), 4800 + 7 * 240 + 200);
    assert!(two.iter().any(|n| by_vel(&v, n.vel).start != n.start));
}

#[test]
fn hum_hand_split_moves_each_hand_by_its_offset() {
    // Low hand C3 + E3, high hand C5 + E5, four onsets.
    let mut notes = Vec::new();
    for k in 0..4u64 {
        for (j, p) in [48u8, 52, 72, 76].into_iter().enumerate() {
            notes.push(TNote {
                start: 960 + k * 960,
                dur: 400,
                pitch: p,
                vel: 1 + (k * 4 + j as u64) as u8,
                ..TNote::default()
            });
        }
    }
    let set = [
        on("n02"),
        int("n02.split", 60),
        int("n02.low", 20),
        int("n02.high", -10),
        int("n02.spread", 0),
    ];
    let v = hum(notes.clone(), &set);
    for n in &notes {
        let o = by_vel(&v, n.vel);
        let want = if n.pitch < 60 { 20 } else { -10 };
        assert_eq!(o.start as i64 - n.start as i64, want);
        assert_eq!(o.dur, n.dur);
    }
    // A spread: each hand's notes of one onset move together, within it.
    let set = [on("n02"), int("n02.spread", 30)];
    let v = hum(notes.clone(), &set);
    let mut moves = std::collections::BTreeSet::new();
    for k in 0..4u8 {
        let d = |j: u8| {
            let n = notes[usize::from(k * 4 + j)];
            by_vel(&v, n.vel).start as i64 - n.start as i64
        };
        assert_eq!(d(0), d(1));
        assert_eq!(d(2), d(3));
        assert!((15 - 30..=15 + 30).contains(&d(0)));
        assert!((-30..=30).contains(&d(2)));
        moves.insert(d(0));
        moves.insert(d(2));
    }
    assert!(moves.len() > 2);
}

#[test]
fn hum_phrase_dynamics_shape_each_phrase_with_its_arc() {
    // Phrase 1: four notes; phrase 2 after a rest: three notes; then one
    // note alone.
    let mut notes = hum_line(4, 0, 480, 300);
    notes.extend(hum_line(3, 4800, 480, 300).into_iter().map(|mut n| {
        n.vel += 4;
        n
    }));
    notes.push(TNote {
        start: 9600,
        dur: 100,
        pitch: 60,
        vel: 8,
        ..TNote::default()
    });
    for n in &mut notes {
        n.rel = n.vel; // remember the note; the velocity is what changes
        n.vel = 100;
    }
    let shape = Curve::smooth(vec![(0.0, 0.0), (0.5, 1.0), (1.0, 0.0)]);
    let set = [on("n03"), int("n03.depth", 20), fl("n03.vary", 0.0)];
    let v = hum(notes.clone(), &set);
    let vel_of = |id: u8| v.iter().find(|n| n.rel == id).unwrap().vel;
    let want = |u: f64| (100.0 + (20.0 * (2.0 * shape.eval(u) - 1.0)).round()) as u8;
    for (k, id) in [1u8, 2, 3, 4].into_iter().enumerate() {
        assert_eq!(vel_of(id), want(k as f64 / 3.0), "phrase 1 note {k}");
    }
    for (k, id) in [5u8, 6, 7].into_iter().enumerate() {
        assert_eq!(vel_of(id), want(k as f64 / 2.0), "phrase 2 note {k}");
    }
    assert_eq!(vel_of(8), 120, "a phrase of one onset is its middle");
    assert_eq!(vel_of(1), 80);
    // Variation: phrases differ, each within twice the depth.
    let set = [on("n03"), int("n03.depth", 20), fl("n03.vary", 100.0)];
    let v = hum(notes.clone(), &set);
    let mid = [
        v.iter().find(|n| n.rel == 8).unwrap().vel,
        v.iter().find(|n| n.rel == 6).unwrap().vel,
    ];
    assert!(mid.iter().all(|&m| (100..=140).contains(&m)), "{mid:?}");
    // A longer split rest joins the phrases.
    let set = [
        on("n03"),
        int("n03.depth", 20),
        fl("n03.vary", 0.0),
        int("n03.rest", 100_000),
    ];
    let v = hum(notes.clone(), &set);
    assert_eq!(v.iter().find(|n| n.rel == 1).unwrap().vel, 80);
    assert_eq!(v.iter().find(|n| n.rel == 8).unwrap().vel, 80);
}

#[test]
fn hum_metric_accents_follow_the_bar_positions() {
    let line = hum_line(16, 0, 960, 400);
    let mut notes = line.clone();
    for n in &mut notes {
        n.rel = n.vel;
        n.vel = 90;
    }
    let set = [on("n04"), int("n04.spread", 0)];
    let v = hum(notes.clone(), &set);
    for n in &notes {
        let o = v.iter().find(|x| x.rel == n.rel).unwrap();
        let k = (n.start / 960 % 4) as usize;
        assert_eq!(i64::from(o.vel), 90 + [10, -4, 4, -4][k]);
    }
    // 3/4: the positions restart at every bar line.
    let mut ctx = Ctx::simple(960);
    ctx.meter = MeterMap::new(Division::ppqn(960), &[(0, 3, 2)]);
    let set = [
        on("n04"),
        int("n04.spread", 0),
        list("n04.accents", &[12, 0, -6]),
    ];
    let v = hum_in(notes.clone(), &set, Some(ctx));
    for n in &notes {
        let o = v.iter().find(|x| x.rel == n.rel).unwrap();
        assert_eq!(
            i64::from(o.vel),
            90 + [12, 0, -6][(n.start / 960 % 3) as usize]
        );
    }
    // 1/8 grid: off-beats are positions too; the spread stays within ±8.
    let eighths: Vec<TNote> = (0..16u64)
        .map(|i| TNote {
            start: i * 480,
            dur: 100,
            pitch: 60,
            vel: 90,
            rel: i as u8,
            ..TNote::default()
        })
        .collect();
    let set = [
        on("n04"),
        ch("n04.grid", 3),
        list("n04.accents", &[16, -8]),
        int("n04.spread", 8),
    ];
    let v = hum(eighths.clone(), &set);
    let mut spreads = std::collections::BTreeSet::new();
    for n in &eighths {
        let o = v.iter().find(|x| x.rel == n.rel).unwrap();
        let base = 90 + if n.start % 960 == 0 { 16 } else { -8 };
        let d = i64::from(o.vel) - base;
        assert!((-8..=8).contains(&d), "{d}");
        spreads.insert(d);
    }
    assert!(spreads.len() > 3);
}

#[test]
fn hum_repetition_fatigue_tires_fast_repeats_and_recovers_after_rests() {
    // Ten repeats at 32 per second, a rest, three more.
    let mut notes: Vec<TNote> = (0..10u64)
        .map(|i| TNote {
            start: i * 60,
            dur: 30,
            pitch: 60,
            vel: 100,
            rel: i as u8,
            ..TNote::default()
        })
        .collect();
    notes.extend((0..3u64).map(|i| TNote {
        start: 2000 + i * 60,
        dur: 30,
        pitch: 60,
        vel: 100,
        rel: 10 + i as u8,
        ..TNote::default()
    }));
    let set = [
        on("n05"),
        fl("n05.rate", 8.0),
        fl("n05.loss", 3.0),
        int("n05.rest", 480),
    ];
    let v = hum(notes.clone(), &set);
    let vel_of = |v: &[TNote], id: u8| v.iter().find(|n| n.rel == id).unwrap().vel;
    for k in 0..10u8 {
        assert_eq!(vel_of(&v, k), 100 - 3 * k, "repeat {k}");
    }
    for k in 0..3u8 {
        assert_eq!(vel_of(&v, 10 + k), 100 - 3 * k, "after the rest {k}");
    }
    // Slow repeats (2 per second) held up to the next one neither tire nor
    // recover; muted notes do not count; another key tires on its own.
    let mut held: Vec<TNote> = (0..4u64)
        .map(|i| TNote {
            start: i * 60,
            dur: 60,
            pitch: 60,
            vel: 100,
            rel: i as u8,
            ..TNote::default()
        })
        .collect();
    held.extend((0..3u64).map(|i| TNote {
        start: 240 + i * 960,
        dur: 960,
        pitch: 60,
        vel: 100,
        rel: 4 + i as u8,
        ..TNote::default()
    }));
    held.push(TNote {
        start: 30,
        dur: 10,
        pitch: 60,
        vel: 100,
        rel: 20,
        flags: 2,
        ..TNote::default()
    });
    held.extend((0..3u64).map(|i| TNote {
        start: 5 + i * 60,
        dur: 30,
        pitch: 64,
        vel: 100,
        rel: 30 + i as u8,
        ..TNote::default()
    }));
    let v = hum(held.clone(), &set);
    let got: Vec<u8> = (0..7).map(|k| vel_of(&v, k)).collect();
    assert_eq!(got, vec![100, 97, 94, 91, 88, 88, 88]);
    assert_eq!(vel_of(&v, 20), 97, "the muted note's own level");
    let got: Vec<u8> = (30..33).map(|k| vel_of(&v, k)).collect();
    assert_eq!(got, vec![100, 97, 94]);
    // Looseness: the timing jitter of repeat k grows by (1 + 50 % · k).
    let ranges = [int("tick.min", -20), int("tick.max", 20)];
    let off = hum(notes.clone(), &ranges);
    let mut s = ranges.to_vec();
    s.extend([on("n05"), fl("n05.loss", 0.0), fl("n05.loose", 50.0)]);
    let on5 = hum(notes.clone(), &s);
    for k in 0..10u8 {
        let n = notes[usize::from(k)];
        let a = off.iter().find(|x| x.rel == k).unwrap().start as f64 - n.start as f64;
        let b = on5.iter().find(|x| x.rel == k).unwrap().start as f64 - n.start as f64;
        let m = 1.0 + 0.5 * f64::from(k);
        assert!((b - a * m).abs() <= (1.0 + m) / 2.0 + 1e-9, "{k}: {a} {b}");
    }
}

#[test]
fn hum_ensemble_copies_add_players_on_their_subchannel_steps() {
    let one = vec![TNote {
        start: 960,
        dur: 480,
        pitch: 60,
        vel: 100,
        ..TNote::default()
    }];
    let set = [
        on("n06"),
        int("n06.players", 3),
        int("n06.spread", 0),
        int("n06.vel", 0),
        int("n06.step", 1),
    ];
    let v = hum(one.clone(), &set);
    let mut subs: Vec<(u64, u64, u8, u32, u8)> = v
        .iter()
        .map(|n| (n.start, n.dur, n.vel, n.sub, n.ch))
        .collect();
    subs.sort_unstable();
    assert_eq!(
        subs,
        vec![
            (960, 480, 100, 0, 0),
            (960, 480, 100, 1, 1),
            (960, 480, 100, 2, 2),
            (960, 480, 100, 3, 3)
        ]
    );
    // Eight players on four subchannels wrap; a negative step goes down.
    let set = [
        on("n06"),
        int("n06.players", 8),
        int("n06.step", -1),
        int("n06.spread", 25),
        int("n06.vel", 10),
    ];
    let v = hum(one.clone(), &set);
    assert_eq!(v.len(), 9);
    let mut per_sub = [0; 4];
    for n in &v {
        per_sub[n.sub as usize] += 1;
        assert!(n.start.abs_diff(960) <= 25);
        assert!(n.vel.abs_diff(100) <= 10);
        assert_eq!(n.dur, 480);
    }
    assert_eq!(per_sub, [3, 2, 2, 2]);
    assert!(v.iter().filter(|n| n.start != 960).count() >= 4);
    // The copies follow the humanized note (here a hand offset).
    let set = [
        on("n06"),
        int("n06.players", 2),
        int("n06.spread", 0),
        int("n06.vel", 0),
        on("n02"),
        int("n02.low", 40),
        int("n02.spread", 0),
        int("n02.split", 72),
    ];
    let v = hum(one, &set);
    assert!(v.iter().all(|n| n.start == 1000));
}

#[test]
fn hum_leap_error_delays_notes_by_their_leap() {
    let notes: Vec<TNote> = [
        (0u64, 60u8),
        (960, 72),
        (1920, 74),
        (2880, 50),
        (3840, 60),
        (3840, 64),
        (3840, 67),
        (4800, 69),
    ]
    .iter()
    .enumerate()
    .map(|(i, &(s, p))| TNote {
        start: s,
        dur: 400,
        pitch: p,
        vel: 1 + i as u8,
        ..TNote::default()
    })
    .collect();
    let set = [on("n07"), int("n07.per", 12), int("n07.most", 20)];
    let v = hum(notes.clone(), &set);
    let d: Vec<i64> = notes
        .iter()
        .map(|n| by_vel(&v, n.vel).start as i64 - n.start as i64)
        .collect();
    // 72 ← 60: 12; 74 ← 72: 2; 50 ← 74: 24 capped at 20; the chord from
    // 50: 10 / 14 / 17; 69 ← the chord's nearest (67): 2.
    assert_eq!(d, vec![0, 12, 2, 20, 10, 14, 17, 2]);
    // A muted previous onset is skipped.
    let mut m = notes.clone();
    m[2].flags = 2;
    let v = hum(m.clone(), &set);
    assert_eq!(by_vel(&v, 4).start - 2880, 20, "50 ← 72: 22 capped");
    // Early or late: the same sizes, both signs over many leaps.
    let line: Vec<TNote> = (0..40u64)
        .map(|i| TNote {
            start: 1000 + i * 480,
            dur: 100,
            pitch: if i % 2 == 0 { 48 } else { 72 },
            vel: 1 + i as u8,
            ..TNote::default()
        })
        .collect();
    let set = [
        on("n07"),
        int("n07.per", 10),
        ch("n07.dir", 1),
        int("n07.most", 1000),
    ];
    let v = hum(line.clone(), &set);
    let d: Vec<i64> = line
        .iter()
        .skip(1)
        .map(|n| by_vel(&v, n.vel).start as i64 - n.start as i64)
        .collect();
    assert!(d.iter().all(|x| x.abs() == 20));
    assert!(d.iter().any(|&x| x < 0) && d.iter().any(|&x| x > 0));
}

#[test]
fn hum_grid_relative_variance_scales_the_jitter_by_the_distance_to_the_grid() {
    let ranges = [
        int("tick.min", -40),
        int("tick.max", 40),
        int("gate.min", -30),
        int("gate.max", 30),
        int("vel.min", -20),
        int("vel.max", 20),
    ];
    // On the 1/16 grid, half a step off, a quarter step off.
    let notes: Vec<TNote> = (0..60u64)
        .map(|i| TNote {
            start: 3840 + i * 240 + [0, 120, 60][(i % 3) as usize],
            dur: 200,
            pitch: 60 + (i % 12) as u8,
            vel: 64,
            rel: i as u8,
            ..TNote::default()
        })
        .collect();
    let off = hum(notes.clone(), &ranges);
    let mut s = ranges.to_vec();
    s.extend([on("n08"), fl("n08.on", 0.0), fl("n08.off", 100.0)]);
    let v = hum(notes.clone(), &s);
    for n in &notes {
        let a = off.iter().find(|x| x.rel == n.rel).unwrap();
        let b = v.iter().find(|x| x.rel == n.rel).unwrap();
        match n.rel % 3 {
            0 => assert_eq!(
                (b.start, b.dur, b.vel),
                (n.start, n.dur, n.vel),
                "on the grid"
            ),
            1 => assert_eq!(a, b, "half a step off: the full amount"),
            _ => {
                let half = |x: i64, y: i64| (x - 2 * y).abs() <= 2;
                assert!(half(
                    a.start as i64 - n.start as i64,
                    b.start as i64 - n.start as i64
                ));
                assert!(half(i64::from(a.vel) - 64, i64::from(b.vel) - 64));
            }
        }
    }
    // The reverse (on 200 %, off 0 %): off-grid notes stay.
    let mut s = ranges.to_vec();
    s.extend([on("n08"), fl("n08.on", 200.0), fl("n08.off", 0.0)]);
    let v = hum(notes.clone(), &s);
    for n in notes.iter().filter(|n| n.rel % 3 == 1) {
        let b = v.iter().find(|x| x.rel == n.rel).unwrap();
        assert_eq!((b.start, b.dur, b.vel), (n.start, n.dur, n.vel));
    }
}

#[test]
fn hum_neutral_functions_take_the_v09_path_and_equal_v08() {
    // n08 at 100 % on and off the grid, a swing of 50 % and hands without
    // offsets send every v0.8 setting through the v0.9 pipeline unchanged.
    let neutral = [
        on("n08"),
        fl("n08.on", 100.0),
        fl("n08.off", 100.0),
        on("n09"),
        fl("n09.lo", 50.0),
        fl("n09.hi", 50.0),
        on("n02"),
        int("n02.low", 0),
        int("n02.high", 0),
        int("n02.spread", 0),
    ];
    for (i, s) in hum_v08_settings().iter().enumerate() {
        let mut set = s.clone();
        set.extend(neutral.iter().cloned());
        assert_eq!(
            fingerprint(&run_full("humanize", hum_fixture(), &set).notes),
            HUM_V08[i],
            "setting {i}"
        );
    }
}

#[test]
fn hum_swing_drift_swings_off_beats_between_its_bounds() {
    let notes: Vec<TNote> = (0..32u64)
        .map(|i| TNote {
            start: i * 240,
            dur: 100,
            pitch: 60,
            vel: 64,
            rel: i as u8,
            ..TNote::default()
        })
        .collect();
    // A fixed 60 % swing of eighths: x → 1.2 x before the off-beat, then
    // 576 + 0.8 (x − 480) in each quarter.
    let set = [on("n09"), fl("n09.lo", 60.0), fl("n09.hi", 60.0)];
    let v = hum(notes.clone(), &set);
    for n in &notes {
        let o = v.iter().find(|x| x.rel == n.rel).unwrap();
        let (q, x) = (n.start / 960 * 960, n.start % 960);
        let want = if x < 480 {
            q + x * 12 / 10
        } else {
            q + 576 + (x - 480) * 8 / 10
        };
        assert_eq!(o.start, want, "{}", n.start);
        assert_eq!(o.dur, 100);
    }
    // Drifting between 50 and 70 %: every off-beat between straight and
    // 672, both ends of the range reached over 64 bars, deterministic.
    let beats: Vec<TNote> = (0..512u64)
        .map(|i| TNote {
            start: i * 480,
            dur: 100,
            pitch: 60 + (i % 2) as u8,
            vel: 64,
            ..TNote::default()
        })
        .collect();
    let set = [
        on("n09"),
        fl("n09.lo", 50.0),
        fl("n09.hi", 70.0),
        int("n09.period", 3840),
    ];
    let v = hum(beats.clone(), &set);
    assert_eq!(v, hum(beats.clone(), &set));
    let offs: Vec<u64> = v
        .iter()
        .filter(|n| n.pitch == 61)
        .map(|n| n.start % 960)
        .collect();
    assert!(offs.iter().all(|&o| (480..=672).contains(&o)));
    assert!(offs.iter().any(|&o| o < 500) && offs.iter().any(|&o| o > 640));
    assert!(
        v.iter()
            .filter(|n| n.pitch == 60)
            .all(|n| n.start % 960 == 0)
    );
}

#[test]
fn hum_finger_overlap_lets_steps_overlap_the_next_note() {
    let notes: Vec<TNote> = [
        (0u64, 60u8),
        (480, 62),
        (960, 64),
        (1440, 72),
        (1920, 74),
        (2400, 74),
    ]
    .iter()
    .enumerate()
    .map(|(i, &(s, p))| TNote {
        start: s,
        dur: 400,
        pitch: p,
        vel: 1 + i as u8,
        ..TNote::default()
    })
    .collect();
    let set = [
        on("n10"),
        int("n10.short", 20),
        int("n10.long", 20),
        int("n10.steps", 2),
    ];
    let v = hum(notes.clone(), &set);
    let ends: Vec<u64> = notes.iter().map(|n| by_vel(&v, n.vel).end()).collect();
    // Steps overlap by 20; the leap 64 → 72 and the repeat 74 → 74 keep
    // their gap; the last note has no next one.
    assert_eq!(ends, vec![500, 980, 1360, 1940, 2320, 2800]);
    // Seeded between 10 and 30, measured to the next note's humanized
    // start.
    let line: Vec<TNote> = (0..48u64)
        .map(|i| TNote {
            start: 960 + i * 240,
            dur: 100,
            pitch: 60 + (i % 3) as u8,
            vel: 1 + i as u8,
            ..TNote::default()
        })
        .collect();
    let set = [
        on("n10"),
        int("n10.short", 10),
        int("n10.long", 30),
        int("tick.min", -15),
        int("tick.max", 15),
    ];
    let v = hum(line.clone(), &set);
    let mut seen = std::collections::BTreeSet::new();
    for w in line.windows(2) {
        let (a, b) = (by_vel(&v, w[0].vel), by_vel(&v, w[1].vel));
        let o = a.end() as i64 - b.start as i64;
        assert!((10..=30).contains(&o), "{o}");
        seen.insert(o);
    }
    assert!(seen.len() > 5);
}

#[test]
fn hum_chord_micro_roll_rolls_chords_up_or_down_within_the_spread() {
    let chord = |at: u64, base: u8| -> Vec<TNote> {
        [0u8, 4, 7, 12]
            .iter()
            .enumerate()
            .map(|(j, &d)| TNote {
                start: at + j as u64 % 2 * 3,
                dur: 400,
                pitch: base + d,
                vel: base + d,
                ..TNote::default()
            })
            .collect()
    };
    let mut notes = Vec::new();
    for k in 0..24u64 {
        notes.extend(chord(960 + k * 960, 48 + (k % 5) as u8));
    }
    notes.push(TNote {
        start: 100,
        dur: 50,
        pitch: 90,
        vel: 1,
        ..TNote::default()
    });
    let rolled = |set: &[(&'static str, ParamValue)]| -> Vec<Vec<i64>> {
        let v = hum(notes.clone(), set);
        (0..24u64)
            .map(|k| {
                let at = 960 + k * 960;
                let mut c: Vec<(u8, i64)> = v
                    .iter()
                    .filter(|n| n.start >= at && n.start < at + 500)
                    .map(|n| (n.pitch, n.start as i64 - at as i64))
                    .collect();
                c.sort_unstable();
                c.into_iter().map(|x| x.1).collect()
            })
            .collect()
    };
    // Written offsets 0 / 3 / 0 / 3: the roll replaces them (each voice
    // rolled from its own start).
    let base = [0i64, 3, 0, 3];
    let up = rolled(&[on("n11"), int("n11.spread", 40), fl("n11.up", 100.0)]);
    for c in &up {
        let r: Vec<i64> = c.iter().zip(base).map(|(a, b)| a - b).collect();
        assert_eq!(r[0], 0, "the lowest voice first");
        assert!(r.windows(2).all(|w| w[0] <= w[1]), "{r:?}");
        assert!(r[3] < 40);
    }
    assert!(up.iter().any(|c| c[3] - 3 > 10));
    let down = rolled(&[on("n11"), int("n11.spread", 40), fl("n11.up", 0.0)]);
    for c in &down {
        let r: Vec<i64> = c.iter().zip(base).map(|(a, b)| a - b).collect();
        assert_eq!(r[3], 0, "the highest voice first");
        assert!(r.windows(2).all(|w| w[0] >= w[1]), "{r:?}");
    }
    // Half and half: both directions.
    let mixed = rolled(&[on("n11"), int("n11.spread", 40), fl("n11.up", 50.0)]);
    let ups = mixed
        .iter()
        .filter(|c| c[0] - base[0] == 0 && c[3] - base[3] > 0)
        .count();
    assert!(ups > 3 && ups < 21, "{ups}");
    // A lone note does not move; a tolerance of 2 splits the chords.
    let v = hum(notes.clone(), &[on("n11"), int("n11.spread", 40)]);
    assert_eq!(by_vel(&v, 1).start, 100);
    let split = rolled(&[on("n11"), int("n11.spread", 40), int("n11.tol", 2)]);
    assert_ne!(split, up);
}

#[test]
fn hum_functions_compose_deterministically_within_the_preflight() {
    let all = [
        on("n01"),
        on("n02"),
        on("n03"),
        on("n04"),
        on("n05"),
        on("n06"),
        on("n07"),
        on("n08"),
        on("n09"),
        on("n10"),
        on("n11"),
        int("tick.min", -20),
        int("tick.max", 20),
        int("vel.min", -8),
        int("vel.max", 8),
    ];
    let a = run_full("humanize", hum_fixture(), &all).notes;
    assert_eq!(a.len(), hum_fixture().len() * 3);
    assert_eq!(
        fingerprint(&a),
        fingerprint(&run_full("humanize", hum_fixture(), &all).notes)
    );
    // Each function alone and with the density path (a6).
    for f in ALL11 {
        for a6 in [false, true] {
            let mut set = hum_ranges();
            set.push(on(f));
            if a6 {
                set.push(on("a6"));
            }
            let v = run_full("humanize", hum_fixture(), &set).notes;
            assert!(!v.is_empty(), "{f}");
            assert_eq!(v, run_full("humanize", hum_fixture(), &set).notes);
        }
    }
    // A Control Sweep over time of the rubato depth runs per segment,
    // deterministically.
    let sweep = [
        on("n01"),
        on("m.sweep"),
        on("m.sweep.rubato"),
        int("tick.min", -5),
        int("tick.max", 5),
    ];
    let a = run_full("humanize", hum_fixture(), &sweep);
    let b = run_full("humanize", hum_fixture(), &sweep);
    assert_eq!(a.notes, b.notes);
    assert_eq!(a.notes.len(), hum_fixture().len());
}

// ================================================================ Transpose

/// Settings of the v0.8 Transpose (base controls, each frozen function and
/// combinations; out-of-range results clamped so every setting runs).
fn tr_v08_settings() -> Vec<Vec<(&'static str, ParamValue)>> {
    let clamp = ch("b.pitch", 1);
    vec![
        vec![],
        vec![int("semis", 5)],
        vec![int("octaves", -1), int("semis", 3)],
        vec![on("a1"), int("a1.deg", 2), ch("key", 2), ch("scale", 1)],
        vec![on("a2"), int("a2.deg", -3), ch("scale", 4)],
        vec![on("a3"), int("a3.axis", 64)],
        vec![on("a4"), int("a4.lo", 50), int("a4.hi", 70)],
        vec![on("a5"), list("a5.table", &[0, 7, -5, 12])],
        vec![
            on("a6"),
            curve(
                "a6.curve",
                Curve::smooth(vec![(0.0, 0.0), (0.5, 1.0), (1.0, 0.25)]),
            ),
            int("a6.depth", 12),
        ],
        vec![on("a7"), int("a7.deg", 2)],
        vec![
            on("a8"),
            int("a8.lo", 30),
            int("a8.hi", 50),
            int("semis", 24),
        ],
        vec![on("a9"), list("a9.seq", &[0, 7, 0, -5, 3])],
        vec![on("a10"), list("a10.map", &[1, 2, 6, 7, 10, 11])],
        vec![
            on("a3"),
            on("a4"),
            on("a10"),
            int("semis", 2),
            int("a3.axis", 58),
        ],
        vec![
            on("a7"),
            on("a9"),
            on("a5"),
            int("octaves", 1),
            clamp.clone(),
        ],
        vec![on("a1"), on("a6"), on("a8"), ch("scale", 9)],
        vec![int("semis", 80), clamp.clone()],
        vec![int("semis", -60), ch("b.pitch", 2)],
    ]
}

/// What the v0.8 Transpose (022f521, before V09-S36 step 2) returned for
