/// A note's fields Note Properties sets: start, length, pitch, velocity,
/// release, channel, subchannel, group.
type NpFields = (u64, u64, u8, u8, u8, u8, u32, u32);

/// Every field Note Properties sets and the controller points, hashed.
fn np_fingerprint(r: &plumspirit_engine::transform::TransformRun) -> (usize, usize, u64) {
    let mut o: Vec<NpFields> = r
        .notes
        .iter()
        .map(|n| (n.start, n.dur, n.pitch, n.vel, n.rel, n.ch, n.sub, n.group))
        .collect();
    o.sort_unstable();
    let mut h: u64 = 0xCBF2_9CE4_8422_2325;
    let mut eat = |w: u64| {
        for b in w.to_le_bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0100_0000_01B3);
        }
    };
    for (s, d, p, v, rl, c, sb, g) in &o {
        eat(*s);
        eat(*d);
        eat(u64::from(*p) | u64::from(*v) << 8 | u64::from(*rl) << 16 | u64::from(*c) << 24);
        eat(u64::from(*sb) | u64::from(*g) << 32);
    }
    for e in &r.events {
        let lane = match e.lane {
            plumspirit_engine::transform::output::Lane::Cc(c) => u64::from(c),
            plumspirit_engine::transform::output::Lane::PitchBend => 1000,
        };
        eat(u64::from(e.track) | lane << 16 | u64::from(e.ch) << 32);
        eat(e.tick);
        eat(u64::from(e.value));
    }
    (o.len(), r.events.len(), h)
}

