fn np_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

#[test]
fn np_new_functions_off_leave_v08_results_unchanged() {
    let got: Vec<(usize, usize, u64)> = np_v08_settings()
        .iter()
        .map(|s| np_fingerprint(&run_full("note_props", hum_fixture(), &np_off(s))))
        .collect();
    assert_eq!(got.len(), NP_V08.len());
    for (i, (g, w)) in got.iter().zip(NP_V08).enumerate() {
        assert_eq!(g, w, "setting {i}");
    }
}

/// Runs Note Properties on hand-built notes of one track with subchannels
/// 0 – 3 in `ctx` (`Ctx::simple(960)` when `None`): the whole result.
fn np_in(
    notes: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
    ctx: Option<Ctx>,
) -> plumspirit_engine::transform::TransformRun {
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track]);
    let t = tool("note_props").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r
}

fn np(notes: Vec<TNote>, set: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    let mut v = np_in(notes, set, None).notes;
    v.sort_by_key(|n| (n.start, n.pitch, n.sub));
    v
}

/// A note at `start` of `pitch`, velocity `vel` on subchannel `sub`
/// (channel 0), 400 ticks long.
fn npn(start: u64, pitch: u8, vel: u8, sub: u32) -> TNote {
    TNote {
        sub,
        ..tn(start, 400, pitch, vel)
    }
}

/// Neutral settings of v0.9 functions (the v0.9 path, the v0.8 result).
fn np_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    vec![
        ("n02", vec![on("n02"), int("n02.amount", 0)]),
        ("n04", vec![on("n04"), fl("n04.strength", 0.0)]),
        ("n06", vec![on("n06"), int("n06.window", 1)]),
        (
            "n10",
            vec![
                on("n10"),
                ch("n10.if", 0),
                ch("n10.test", 0),
                int("n10.value", 0),
            ],
        ),
    ]
}

#[test]
fn np_neutral_functions_take_the_v09_path_and_equal_v08() {
    for (f, neutral) in np_neutral() {
        for (i, s) in np_v08_settings().iter().enumerate() {
            let mut set = np_off(s);
            set.extend(neutral.iter().cloned());
            let r = run_full("note_props", hum_fixture(), &set);
            assert_eq!(np_fingerprint(&r), NP_V08[i], "{f} setting {i}");
        }
    }
}

#[test]
fn np_cross_property_mapping_sets_one_property_from_another() {
    // Velocity from the key across the selection's range (40 … 80).
    let v: Vec<u8> = np(
        vec![npn(0, 40, 90, 0), npn(480, 60, 90, 0), npn(960, 80, 90, 0)],
        &[on("n01")],
    )
    .iter()
    .map(|n| n.vel)
    .collect();
    assert_eq!(v, vec![40, 80, 120]);
    // Length from velocity, 100 … 1,000 ticks.
    let r = np(
        vec![npn(0, 60, 1, 0), npn(480, 60, 64, 0), npn(960, 60, 127, 0)],
        &[
            on("n01"),
            ch("n01.from", 1),
            ch("n01.to", 2),
            int("n01.lo", 100),
            int("n01.hi", 1000),
        ],
    );
    assert_eq!(
        r.iter().map(|n| n.dur).collect::<Vec<_>>(),
        vec![100, 550, 1000]
    );
    // Channel from the place in the bar (1 … 4).
    let r = np(
        vec![
            npn(0, 60, 90, 0),
            npn(1920, 60, 90, 0),
            npn(2880, 60, 90, 0),
        ],
        &[
            on("n01"),
            ch("n01.from", 3),
            ch("n01.to", 3),
            int("n01.lo", 1),
            int("n01.hi", 4),
        ],
    );
    assert_eq!(r.iter().map(|n| n.ch).collect::<Vec<_>>(), vec![0, 2, 2]);
    // Release from the subchannel's place, through a falling curve.
    let r = np(
        (0..4).map(|s| npn(s as u64 * 480, 60, 90, s)).collect(),
        &[
            on("n01"),
            ch("n01.from", 4),
            ch("n01.to", 1),
            int("n01.lo", 0),
            int("n01.hi", 120),
            curve("n01.map", Curve::line(1.0, 0.0)),
        ],
    );
    assert_eq!(
        r.iter().map(|n| n.rel).collect::<Vec<_>>(),
        vec![120, 80, 40, 0]
    );
}

#[test]
fn np_accent_rules_raise_the_notes_that_start_something() {
    let vels = |notes: Vec<TNote>, set: &[(&'static str, ParamValue)]| -> Vec<u8> {
        np(notes, set).iter().map(|n| n.vel).collect()
    };
    // Downbeats (bar lines every 3,840).
    assert_eq!(
        vels(
            vec![
                npn(0, 60, 80, 0),
                npn(960, 60, 80, 0),
                npn(3840, 60, 80, 0),
                npn(4000, 60, 80, 0)
            ],
            &[on("n02")]
        ),
        vec![100, 80, 100, 80]
    );
    // Phrase starts (rests of more than 480 ticks).
    assert_eq!(
        vels(
            vec![npn(0, 60, 80, 0), npn(480, 62, 80, 0), npn(2000, 64, 80, 0)],
            &[on("n02"), ch("n02.rule", 1)]
        ),
        vec![100, 80, 100]
    );
    // Leaps of more than 7 semitones from the previous onset.
    assert_eq!(
        vels(
            vec![
                npn(0, 60, 80, 0),
                npn(480, 62, 80, 0),
                npn(960, 72, 80, 0),
                npn(1440, 71, 80, 0)
            ],
            &[on("n02"), ch("n02.rule", 2), int("n02.amount", -30)]
        ),
        vec![80, 80, 50, 80]
    );
    // Chord tops (two notes or more).
    assert_eq!(
        vels(
            vec![
                npn(0, 60, 80, 0),
                npn(0, 64, 80, 0),
                npn(0, 67, 80, 0),
                npn(480, 62, 80, 0)
            ],
            &[on("n02"), ch("n02.rule", 3)]
        ),
        vec![80, 80, 100, 80]
    );
}

#[test]
fn np_value_cycle_sets_a_property_from_a_cycled_list() {
    let vels = |notes: Vec<TNote>, set: &[(&'static str, ParamValue)]| -> Vec<u8> {
        np(notes, set).iter().map(|n| n.vel).collect()
    };
    let cyc = [on("n03"), list("n03.values", &[100, 60, 80])];
    // Per note.
    assert_eq!(
        vels((0..5).map(|i| npn(i * 480, 60, 90, 0)).collect(), &cyc),
        vec![100, 60, 80, 100, 60]
    );
    // Per beat (from the first note's beat).
    let mut beat = cyc.to_vec();
    beat.push(ch("n03.per", 1));
    assert_eq!(
        vels(
            vec![
                npn(960, 60, 90, 0),
                npn(1440, 60, 90, 0),
                npn(1920, 60, 90, 0),
                npn(2880, 60, 90, 0)
            ],
            &beat
        ),
        vec![100, 100, 60, 80]
    );
    // Per bar.
    let mut bar = cyc.to_vec();
    bar.push(ch("n03.per", 2));
    assert_eq!(
        vels(
            vec![
                npn(0, 60, 90, 0),
                npn(3000, 60, 90, 0),
                npn(3840, 60, 90, 0),
                npn(11520, 60, 90, 0)
            ],
            &bar
        ),
        vec![100, 100, 60, 100]
    );
    // Per chord.
    let mut chord = cyc.to_vec();
    chord.push(ch("n03.per", 3));
    assert_eq!(
        vels(
            vec![
                npn(0, 60, 90, 0),
                npn(0, 64, 90, 0),
                npn(480, 62, 90, 0),
                npn(960, 65, 90, 0),
                npn(960, 69, 90, 0)
            ],
            &chord
        ),
        vec![100, 100, 60, 80, 80]
    );
    // Channels (1 – 16) and lengths.
    let r = np(
        vec![npn(0, 60, 90, 0), npn(480, 60, 90, 0)],
        &[on("n03"), ch("n03.prop", 3), list("n03.values", &[1, 10])],
    );
    assert_eq!((r[0].ch, r[1].ch), (0, 9));
    let r = np(
        vec![npn(0, 60, 90, 0), npn(480, 60, 90, 0)],
        &[on("n03"), ch("n03.prop", 2), list("n03.values", &[120, 0])],
    );
    assert_eq!((r[0].dur, r[1].dur), (120, 1));
}

