#[test]
fn np_real_time_length_lasts_the_same_time_at_any_tempo() {
    // 120 BPM: 250 ms = 480 ticks, from the start or back from the end.
    let r = np(vec![tn(1000, 100, 60, 90)], &[on("n05")]);
    assert_eq!((r[0].start, r[0].dur), (1000, 480));
    let r = np(vec![tn(1000, 100, 60, 90)], &[on("n05"), ch("n05.keep", 1)]);
    assert_eq!((r[0].start, r[0].dur), (620, 480));
    // A tempo step (120 → 60 BPM at 1,920): across the step, through the
    // tempo map.
    for (start, ms) in [
        (1500u64, 500.0),
        (100, 250.0),
        (2400, 100.0),
        (1800, 1000.0),
    ] {
        let r = np_in(
            vec![tn(start, 100, 60, 90)],
            &[on("n05"), fl("n05.ms", ms)],
            Some(qnt_stepped_tempo()),
        )
        .notes;
        let want = qnt_tick_at(qnt_us_at(start) + ms * 1000.0) - start;
        assert_eq!(r[0].dur, want, "{start} {ms}");
    }
}

#[test]
fn np_velocity_smoothing_averages_the_neighbours() {
    let v: Vec<u8> = np(
        [40u8, 120, 40, 120, 40]
            .iter()
            .enumerate()
            .map(|(i, &v)| npn(i as u64 * 480, 60, v, 0))
            .collect(),
        &[on("n06"), int("n06.window", 3)],
    )
    .iter()
    .map(|n| n.vel)
    .collect();
    assert_eq!(v, vec![80, 67, 93, 67, 80]);
    // Per key: two interleaved keys smoothed apart.
    let notes: Vec<TNote> = (0..6)
        .map(|i| {
            npn(
                i * 480,
                if i % 2 == 0 { 60 } else { 72 },
                if i % 2 == 0 { 50 } else { 110 },
                0,
            )
        })
        .collect();
    let v: Vec<u8> = np(notes.clone(), &[on("n06"), ch("n06.per", 1)])
        .iter()
        .map(|n| n.vel)
        .collect();
    assert_eq!(v, vec![50, 110, 50, 110, 50, 110]);
    let v: Vec<u8> = np(
        notes,
        &[on("n06"), int("n06.window", 2), fl("n06.strength", 50.0)],
    )
    .iter()
    .map(|n| n.vel)
    .collect();
    assert_eq!(v[0], 65);
}

#[test]
fn np_outlier_clamp_pulls_outliers_to_the_bound_or_the_median() {
    let vs = [60u8, 62, 64, 66, 68, 127];
    let notes = || -> Vec<TNote> {
        vs.iter()
            .enumerate()
            .map(|(i, &v)| npn(i as u64 * 480, 60, v, 0))
            .collect()
    };
    let mean = vs.iter().map(|&v| f64::from(v)).sum::<f64>() / 6.0;
    let sd = (vs
        .iter()
        .map(|&v| (f64::from(v) - mean).powi(2))
        .sum::<f64>()
        / 6.0)
        .sqrt();
    let hi = (mean + 1.5 * sd).floor() as u8;
    let v: Vec<u8> = np(notes(), &[on("n07"), fl("n07.k", 1.5)])
        .iter()
        .map(|n| n.vel)
        .collect();
    assert_eq!(v, vec![60, 62, 64, 66, 68, hi]);
    // Set to the (lower) median.
    let v: Vec<u8> = np(notes(), &[on("n07"), fl("n07.k", 1.5), ch("n07.action", 1)])
        .iter()
        .map(|n| n.vel)
        .collect();
    assert_eq!(v, vec![60, 62, 64, 66, 68, 64]);
}

