#[test]
fn np_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&f| on(f)).collect();
    let a = run_full("note_props", hum_fixture(), &all);
    let b = run_full("note_props", hum_fixture(), &all);
    assert_eq!(a.notes, b.notes);
    assert_eq!(a.events, b.events);
    assert_eq!(a.notes.len(), hum_fixture().len());
    for f in ALL11 {
        for extra in [vec![], vec![on("a1"), on("a7"), on("a10")]] {
            let mut set = vec![on(f)];
            set.extend(extra);
            let v = run_full("note_props", hum_fixture(), &set);
            assert_eq!(v.notes.len(), hum_fixture().len(), "{f}");
            assert_eq!(
                v.notes,
                run_full("note_props", hum_fixture(), &set).notes,
                "{f}"
            );
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.ch <= 15),
                "{f}"
            );
        }
    }
    // The lock mask still wins over the new functions.
    let r = run_full("note_props", hum_fixture(), &[on("n03"), on("a7")]);
    let mut got: Vec<(u64, u8, u8)> = r.notes.iter().map(|n| (n.start, n.pitch, n.vel)).collect();
    let mut want: Vec<(u64, u8, u8)> = hum_fixture()
        .iter()
        .map(|n| (n.start, n.pitch, n.vel))
        .collect();
    got.sort_unstable();
    want.sort_unstable();
    assert_eq!(got, want);
    // A Control Sweep of the accent amount over time runs per segment.
    let sweep = [on("n02"), on("m.sweep"), on("m.sweep.accent")];
    let a = run_full("note_props", hum_fixture(), &sweep);
    let b = run_full("note_props", hum_fixture(), &sweep);
    assert_eq!(a.notes, b.notes);
}

// ================================================================ Join / Glue

/// Fragment chains for Join: six keys on subchannels 0 – 3 (channel =
/// subchannel), eight fragments each — touching, a small gap, a small or a
/// deep overlap, a medium or a long rest — with varied lengths, velocities,
/// releases, a few note groups and muted fragments (deterministic).
fn join_fixture() -> Vec<TNote> {
    let mut x: u64 = 0x9E37_79B9_7F4A_7C15;
    let mut rnd = |m: u64| {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        x % m.max(1)
    };
    let mut v = Vec::new();
    for pitch in [60u8, 62, 64, 67, 72, 48] {
        for sub in 0..4u32 {
            let mut t = rnd(480);
            for _ in 0..8 {
                let dur = 15 + rnd(470);
                let vel = 20 + rnd(100) as u8;
                let rel = 10 + rnd(100) as u8;
                let flags = if rnd(13) == 0 {
                    plumspirit_engine::transform::FLAG_MUTED
                } else {
                    0
                };
                let group = if rnd(7) == 0 { 1 + rnd(2) as u32 } else { 0 };
                v.push(TNote {
                    start: t,
                    dur,
                    pitch,
                    vel,
                    rel,
                    sub,
                    ch: sub as u8,
                    group,
                    flags,
                    ..TNote::default()
                });
                t = match rnd(8) {
                    0..=2 => t + dur,
                    3 => t + dur + 1 + rnd(80),
                    4 => t + dur - rnd(60).min(dur - 1),
                    5 => t + dur + 100 + rnd(400),
                    6 => t + dur + 600 + rnd(1500),
                    _ => t + 1 + rnd(dur - 1),
                };
            }
        }
    }
    v
}

