fn join_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

#[test]
fn join_new_functions_off_leave_v08_results_unchanged() {
    let got: Vec<(usize, usize, u64)> = join_v08_settings()
        .iter()
        .map(|s| join_fingerprint(&run_full("join", join_fixture(), &join_off(s))))
        .collect();
    assert_eq!(got.len(), JOIN_V08.len());
    for (i, (g, w)) in got.iter().zip(JOIN_V08).enumerate() {
        assert_eq!(g, w, "setting {i}");
    }
}

/// Neutral settings of v0.9 functions (the v0.9 path, the v0.8 result):
/// no run longer than 2⁴⁰ ticks, every velocity similar, a target no window
/// reaches, no other track, nothing shorter than a tick, no rest of 0
/// ticks, 1,024 fragments per bar — each alone, then all together.
fn join_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n02", vec![on("n02"), int("n02.max", 1 << 40)]),
        ("n03", vec![on("n03"), int("n03.diff", 126)]),
        ("n04", vec![on("n04"), int("n04.nps", 10_000_000)]),
        ("n07", vec![on("n07")]),
        ("n08", vec![on("n08"), int("n08.short", 1)]),
        ("n10", vec![on("n10"), int("n10.rest", 0)]),
        ("n11", vec![on("n11"), int("n11.most", 1024)]),
    ];
    let all: Vec<(&'static str, ParamValue)> =
        each.iter().flat_map(|(_, s)| s.iter().cloned()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn join_neutral_functions_take_the_v09_path_and_equal_v08() {
    for (f, neutral) in join_neutral() {
        for (i, s) in join_v08_settings().iter().enumerate() {
            let mut set = join_off(s);
            set.extend(neutral.iter().cloned());
            let r = run_full("join", join_fixture(), &set);
            assert_eq!(join_fingerprint(&r), JOIN_V08[i], "{f} setting {i}");
        }
    }
}

/// Join on hand-built notes of one track: the result by (track, start,
/// pitch, subchannel).
fn jn(notes: Vec<TNote>, set: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    let mut v = run_full("join", notes, set).notes;
    v.sort_by_key(|n| (n.track, n.start, n.pitch, n.sub));
    v
}

/// (start, end, pitch) of each note.
fn jspans(v: &[TNote]) -> Vec<(u64, u64, u8)> {
    v.iter().map(|n| (n.start, n.end(), n.pitch)).collect()
}

/// A fragment of `pitch` over `[start, end)` at velocity `vel`.
fn jf(start: u64, end: u64, pitch: u8, vel: u8) -> TNote {
    tn(start, end - start, pitch, vel)
}

/// Every fragment lies inside a result note of its key and track (joining
/// deletes no music).
fn join_covers(frags: &[TNote], out: &[TNote]) -> bool {
    frags.iter().all(|f| {
        out.iter().any(|o| {
            o.pitch == f.pitch && o.track == f.track && o.start <= f.start && f.end() <= o.end()
        })
    })
}

/// Join over two tracks (slots 0 and 1 = document tracks 0 and 1) in `ctx`.
fn join_two(
    notes: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
    ctx: Ctx,
) -> plumspirit_engine::transform::TransformRun {
    let track = |i: usize| SourceTrack {
        id: TrackId(i as u32 + 1),
        index: i,
        content: None,
        revision: 0,
        subs: vec![(0, 0)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track(0), track(1)]);
    let t = tool("join").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r
}

/// The notes of `r` as (track, start, end, pitch, velocity).
fn jt(r: &plumspirit_engine::transform::TransformRun) -> Vec<(u16, u64, u64, u8, u8)> {
    let mut v: Vec<_> = r
        .notes
        .iter()
        .map(|n| (n.track, n.start, n.end(), n.pitch, n.vel))
        .collect();
    v.sort_unstable();
    v
}

/// Brute force: each window's fragments (one chain) as one span.
fn join_window_oracle(frags: &[TNote], window: impl Fn(u64) -> u64) -> Vec<(u64, u64, u8)> {
    let mut by: std::collections::BTreeMap<u64, (u64, u64)> = Default::default();
    for f in frags {
        let e = by.entry(window(f.start)).or_insert((f.start, f.end()));
        e.0 = e.0.min(f.start);
        e.1 = e.1.max(f.end());
    }
    by.values().map(|&(s, e)| (s, e, frags[0].pitch)).collect()
}

#[test]
fn join_window_join_makes_one_note_per_window() {
    // 1/64 staccato spam (40 of every 60 ticks) over two beats: v0.8 keeps
    // every fragment (the gaps); 1/4 windows give one note per beat.
    let spam: Vec<TNote> = (0..32).map(|k| jf(k * 60, k * 60 + 40, 60, 90)).collect();
    assert_eq!(jn(spam.clone(), &[]).len(), 32);
    assert_eq!(
        jspans(&jn(spam.clone(), &[on("n01")])),
        vec![(0, 940, 60), (960, 1900, 60)]
    );
    // Legato spam: v0.8 joins it all; the windows keep a note per beat.
    let legato: Vec<TNote> = (0..32).map(|k| jf(k * 60, k * 60 + 60, 60, 90)).collect();
    assert_eq!(jspans(&jn(legato.clone(), &[])), vec![(0, 1920, 60)]);
    assert_eq!(
        jspans(&jn(legato.clone(), &[on("n01")])),
        vec![(0, 960, 60), (960, 1920, 60)]
    );
    // Custom ticks: 480-tick windows.
    let custom = [on("n01"), ch("n01.window", 11), int("n01.ticks", 480)];
    assert_eq!(
        jspans(&jn(legato.clone(), &custom)),
        join_window_oracle(&legato, |t| t / 480)
    );
    // From the bar line, or from the chain's first fragment.
    let late: Vec<TNote> = (0..32)
        .map(|k| jf(300 + k * 60, 360 + k * 60, 60, 90))
        .collect();
    assert_eq!(
        jspans(&jn(late.clone(), &[on("n01")])),
        vec![(300, 960, 60), (960, 1920, 60), (1920, 2220, 60)]
    );
    assert_eq!(
        jspans(&jn(late.clone(), &[on("n01"), ch("n01.align", 1)])),
        join_window_oracle(&late, |t| (t - 300) / 960)
    );
    assert_eq!(
        jspans(&jn(late, &[on("n01"), ch("n01.align", 1)])),
        vec![(300, 1260, 60), (1260, 2220, 60)]
    );
    // Different keys never merge.
    let two = vec![jf(0, 100, 60, 90), jf(100, 200, 62, 90)];
    assert_eq!(jn(two, &[on("n01")]).len(), 2);
}

#[test]
fn join_longest_result_splits_long_chains_within_the_limit() {
    let chain: Vec<TNote> = (0..10)
        .map(|k| jf(k * 100, k * 100 + 100, 60, 90))
        .collect();
    assert_eq!(jspans(&jn(chain.clone(), &[])), vec![(0, 1000, 60)]);
    let greedy = [on("n02"), int("n02.max", 300), ch("n02.pieces", 1)];
    assert_eq!(
        jspans(&jn(chain.clone(), &greedy)),
        vec![
            (0, 300, 60),
            (300, 600, 60),
            (600, 900, 60),
            (900, 1000, 60)
        ]
    );
    // Equal: as many pieces, cut at the starts nearest 250, 500, 750 (ties:
    // the earlier start).
    assert_eq!(
        jspans(&jn(chain.clone(), &[on("n02"), int("n02.max", 300)])),
        vec![
            (0, 200, 60),
            (200, 500, 60),
            (500, 700, 60),
            (700, 1000, 60)
        ]
    );
    // Within the limit: unchanged.
    assert_eq!(
        jspans(&jn(chain, &[on("n02"), int("n02.max", 1000)])),
        vec![(0, 1000, 60)]
    );
    // Every result note is within the limit or an unjoined fragment longer
    // than it, in both modes, on the fixture with overlaps and gaps joined.
    for pieces in [0, 1] {
        for limit in [50, 300, 900] {
            let set = [
                on("a1"),
                int("a1.gap", 200),
                on("a2"),
                on("n02"),
                int("n02.max", limit),
                ch("n02.pieces", pieces),
            ];
            let out = jn(join_fixture(), &set);
            assert!(join_covers(&join_fixture(), &out));
            for o in &out {
                assert!(
                    o.dur <= limit as u64
                        || join_fixture()
                            .iter()
                            .any(|f| f.pitch == o.pitch && f.start == o.start && f.dur == o.dur),
                    "{pieces} {limit}: {o:?}"
                );
            }
        }
    }
}

#[test]
fn join_velocity_similarity_keeps_accents_separate() {
    let chain = |vels: &[u8]| -> Vec<TNote> {
        vels.iter()
            .enumerate()
            .map(|(k, &v)| jf(k as u64 * 100, k as u64 * 100 + 100, 60, v))
            .collect()
    };
    let accents = chain(&[100, 102, 60, 62, 100]);
    let prev = [on("n03"), int("n03.diff", 5)];
    assert_eq!(
        jspans(&jn(accents.clone(), &prev)),
        vec![(0, 200, 60), (200, 400, 60), (400, 500, 60)]
    );
    // Previous fragment vs the chain's start: a slow crescendo.
    let ramp = chain(&[100, 104, 108, 112]);
    assert_eq!(jn(ramp.clone(), &prev).len(), 1);
    assert_eq!(
        jspans(&jn(
            ramp,
            &[on("n03"), int("n03.diff", 5), ch("n03.ref", 1)]
        )),
        vec![(0, 200, 60), (200, 400, 60)]
    );
    // At 126 every join holds (the v0.8 result).
    assert_eq!(jn(accents, &[on("n03"), int("n03.diff", 126)]).len(), 1);
}

#[test]
fn join_nps_target_lowers_the_density_without_deleting_music() {
    // 1/32 staccato (30 of every 60 ticks) for 4 s at 120 BPM: 32 starts a
    // second.
    let spam: Vec<TNote> = (0..128).map(|k| jf(k * 60, k * 60 + 30, 60, 90)).collect();
    let us = |t: u64| t * 500_000 / 960;
    let busiest = |v: &[TNote]| {
        v.iter()
            .map(|n| {
                v.iter()
                    .filter(|m| us(m.start) <= us(n.start) && us(n.start) - us(m.start) < 1_000_000)
                    .count()
            })
            .max()
            .unwrap_or(0)
    };
    assert_eq!(busiest(&spam), 32);
    for target in [1, 4, 16, 24] {
        let set = [on("n04"), int("n04.nps", target), int("n04.gap", 30)];
        let out = jn(spam.clone(), &set);
        assert!(
            busiest(&out) <= target as usize,
            "{target}: {}",
            busiest(&out)
        );
        assert!(join_covers(&spam, &out));
        // A uniform stream is joined evenly: exactly the target per second
        // over its four seconds.
        assert_eq!(out.len(), 4 * target as usize, "{target}");
    }
    // A target above the density, or gaps beyond the largest gap joined:
    // unchanged.
    assert_eq!(
        jn(
            spam.clone(),
            &[on("n04"), int("n04.nps", 64), int("n04.gap", 30)]
        )
        .len(),
        128
    );
    assert_eq!(
        jn(
            spam.clone(),
            &[on("n04"), int("n04.nps", 16), int("n04.gap", 29)]
        )
        .len(),
        128
    );
    // Within Longest result (a gate): no note longer than 90 ticks.
    let out = jn(
        spam.clone(),
        &[
            on("n04"),
            int("n04.nps", 4),
            int("n04.gap", 30),
            on("n02"),
            int("n02.max", 90),
        ],
    );
    assert!(out.iter().all(|n| n.dur <= 90));
    assert!(join_covers(&spam, &out));
    // The window: 500 ms at 16 per second = 8 starts per half second.
    let out = jn(
        spam,
        &[
            on("n04"),
            int("n04.nps", 16),
            fl("n04.window", 500.0),
            int("n04.gap", 30),
        ],
    );
    let half = out
        .iter()
        .map(|n| {
            out.iter()
                .filter(|m| us(m.start) <= us(n.start) && us(n.start) - us(m.start) < 500_000)
                .count()
        })
        .max()
        .unwrap();
    assert!(half <= 8, "{half}");
}

#[test]
fn join_boundary_ties_rejoin_only_pieces_split_at_the_lines() {
    // Two touching quarter notes, the second on beat 2 (repeated notes),
    // and a note tied over the bar line (3,840; 960 PPQN, 4/4).
    let notes = vec![
        jf(0, 960, 60, 90),
        jf(960, 1920, 60, 90),
        jf(3000, 3840, 64, 90),
        jf(3840, 4500, 64, 90),
    ];
    assert_eq!(
        jspans(&jn(notes.clone(), &[])),
        vec![(0, 1920, 60), (3000, 4500, 64)]
    );
    assert_eq!(
        jspans(&jn(notes.clone(), &[on("n05")])),
        vec![(0, 960, 60), (960, 1920, 60), (3000, 4500, 64)]
    );
    for at in [1, 2] {
        assert_eq!(
            jspans(&jn(notes.clone(), &[on("n05"), ch("n05.at", at)])),
            vec![(0, 1920, 60), (3000, 4500, 64)],
            "{at}"
        );
    }
    // A piece split off the beat (an eighth) is not a tie at beats.
    assert_eq!(
        jn(
            vec![jf(0, 480, 60, 90), jf(480, 960, 60, 90)],
            &[on("n05"), ch("n05.at", 1)]
        )
        .len(),
        2
    );
    // Pieces meeting near the line: |3,835 − 3,842| = 7 within the
    // tolerance, each within it of the line.
    let near = vec![jf(3000, 3835, 64, 90), jf(3842, 4500, 64, 90)];
    for (tol, n) in [(10, 1), (7, 1), (6, 2), (0, 2)] {
        assert_eq!(
            jn(near.clone(), &[on("n05"), int("n05.tol", tol)]).len(),
            n,
            "{tol}"
        );
    }
    // Grid lines (1/16 = 240 ticks): at 720 on the grid, at 700 not.
    let grid = [on("n05"), ch("n05.at", 2), int("n05.tol", 0)];
    assert_eq!(
        jn(vec![jf(400, 720, 60, 90), jf(720, 900, 60, 90)], &grid).len(),
        1
    );
    assert_eq!(
        jn(vec![jf(400, 700, 60, 90), jf(700, 900, 60, 90)], &grid).len(),
        2
    );
}

#[test]
fn join_velocity_to_expression_keeps_the_dynamics_as_a_curve() {
    let chain = vec![
        jf(0, 100, 60, 100),
        jf(100, 200, 60, 50),
        jf(200, 300, 60, 80),
    ];
    let r = run_full("join", chain.clone(), &[on("n06")]);
    assert_eq!(jspans(&r.notes), vec![(0, 300, 60)]);
    let pts = |r: &plumspirit_engine::transform::TransformRun| -> Vec<(u64, u16)> {
        r.events.iter().map(|e| (e.tick, e.value)).collect()
    };
    assert_eq!(pts(&r), vec![(0, 100), (100, 50), (200, 80), (300, 127)]);
    assert!(
        r.events
            .iter()
            .all(|e| e.lane == plumspirit_engine::transform::output::Lane::Cc(11) && e.ch == 0)
    );
    assert!(r.message.as_deref().unwrap().contains("Controller events"));
    // Scale 50 %, CC 7 (resting at 100).
    let r = run_full(
        "join",
        chain.clone(),
        &[on("n06"), ch("n06.cc", 1), fl("n06.scale", 50.0)],
    );
    assert_eq!(pts(&r), vec![(0, 50), (100, 25), (200, 40), (300, 100)]);
    assert!(
        r.events
            .iter()
            .all(|e| e.lane == plumspirit_engine::transform::output::Lane::Cc(7))
    );
    // Two joined notes on one channel: the louder curve leads, one point
    // per change, the resting value once neither sounds.
    let two = vec![
        jf(0, 100, 60, 100),
        jf(100, 200, 60, 20),
        jf(0, 100, 64, 40),
        jf(100, 300, 64, 60),
    ];
    let r = run_full("join", two, &[on("n06")]);
    assert_eq!(pts(&r), vec![(0, 100), (100, 60), (300, 127)]);
    // Notes of one fragment get no curve.
    let r = run_full(
        "join",
        vec![jf(0, 100, 60, 90), jf(500, 600, 60, 90)],
        &[on("n06")],
    );
    assert!(r.events.is_empty());
}

#[test]
fn join_cross_track_join_deduplicates_layered_copies() {
    let a = TNote {
        track: 0,
        ..jf(0, 480, 60, 80)
    };
    let b = TNote {
        track: 1,
        ..jf(0, 480, 60, 100)
    };
    let c = Ctx::simple(960);
    let r = join_two(vec![a, b], &[on("n07")], c.clone());
    assert_eq!(jt(&r), vec![(0, 0, 480, 60, 100)]);
    assert!(r.message.as_deref().unwrap().contains("1 duplicate"));
    // The first track's velocity.
    let r = join_two(vec![a, b], &[on("n07"), ch("n07.vel", 1)], c.clone());
    assert_eq!(jt(&r), vec![(0, 0, 480, 60, 80)]);
    // Kept on the active track (the first without one).
    let mut active = c.clone();
    active.active = Some(1);
    let keep = [on("n07"), ch("n07.keep", 1)];
    assert_eq!(
        jt(&join_two(vec![a, b], &keep, active)),
        vec![(1, 0, 480, 60, 100)]
    );
    assert_eq!(
        jt(&join_two(vec![a, b], &keep, c.clone())),
        vec![(0, 0, 480, 60, 100)]
    );
    // Start tolerance; a different length is not a copy.
    let late = TNote { start: 5, ..b };
    assert_eq!(
        join_two(vec![a, late], &[on("n07")], c.clone()).notes.len(),
        2
    );
    assert_eq!(
        join_two(vec![a, late], &[on("n07"), int("n07.tol", 10)], c.clone())
            .notes
            .len(),
        1
    );
    let short = TNote { dur: 470, ..b };
    assert_eq!(
        join_two(vec![a, short], &[on("n07")], c.clone())
            .notes
            .len(),
        2
    );
    // Copies on one track are not this function's.
    let twin = TNote { track: 0, ..b };
    assert_eq!(
        join_two(vec![a, twin], &[on("n07")], c.clone()).notes.len(),
        2
    );
    // Joined first: two fragments on track 0, one note on track 1.
    let frags = vec![
        TNote {
            track: 0,
            ..jf(0, 240, 60, 90)
        },
        TNote {
            track: 0,
            ..jf(240, 480, 60, 90)
        },
        b,
    ];
    assert_eq!(
        jt(&join_two(frags, &[on("n07")], c)),
        vec![(0, 0, 480, 60, 100)]
    );
}

#[test]
fn join_absorb_short_fragments_removes_crumbs() {
    let notes = vec![
        jf(0, 480, 60, 90),
        jf(500, 520, 60, 10),
        jf(600, 1080, 60, 70),
    ];
    let base = [on("n08"), int("n08.short", 60), int("n08.gap", 120)];
    let with = |extra: &[(&'static str, ParamValue)]| {
        let mut v = base.to_vec();
        v.extend(extra.iter().cloned());
        jn(notes.clone(), &v)
    };
    // Equal neighbours: into the previous.
    assert_eq!(jspans(&with(&[])), vec![(0, 520, 60), (600, 1080, 60)]);
    assert_eq!(
        jspans(&with(&[ch("n08.into", 0)])),
        vec![(0, 520, 60), (600, 1080, 60)]
    );
    // Into the next: the crumb gives the joined note no properties.
    let next = with(&[ch("n08.into", 1)]);
    assert_eq!(jspans(&next), vec![(0, 480, 60), (500, 1080, 60)]);
    assert_eq!(next[1].vel, 70);
    // The longer neighbour.
    let mut longer = notes.clone();
    longer[2] = jf(600, 1500, 60, 70);
    assert_eq!(
        jspans(&jn(longer, &base)),
        vec![(0, 480, 60), (500, 1500, 60)]
    );
    // Too far, or not short: the crumb stays.
    assert_eq!(with(&[int("n08.gap", 10)]).len(), 3);
    assert_eq!(with(&[int("n08.short", 20)]).len(), 3);
    // Only the other neighbour within the gap: it takes the crumb.
    assert_eq!(
        jspans(&with(&[ch("n08.into", 1), int("n08.gap", 30)])),
        vec![(0, 520, 60), (600, 1080, 60)]
    );
}

#[test]
fn join_repeated_chords_become_held_chords() {
    let chords = |a: &[u8], b: &[u8], gap: u64| -> Vec<TNote> {
        let mut v: Vec<TNote> = a.iter().map(|&p| jf(0, 240, p, 90)).collect();
        v.extend(b.iter().map(|&p| jf(240 + gap, 480 + gap, p, 90)));
        v
    };
    let ceg = [60, 64, 67];
    assert_eq!(jn(chords(&ceg, &ceg, 60), &[]).len(), 6);
    assert_eq!(
        jspans(&jn(chords(&ceg, &ceg, 60), &[on("n09")])),
        vec![(0, 540, 60), (0, 540, 64), (0, 540, 67)]
    );
    // Beyond the gap, or another chord: unchanged.
    assert_eq!(
        jn(chords(&ceg, &ceg, 60), &[on("n09"), int("n09.gap", 50)]).len(),
        6
    );
    assert_eq!(jn(chords(&ceg, &[60, 65, 69], 60), &[on("n09")]).len(), 6);
    // The same pitch classes (an inversion): the common keys hold.
    assert_eq!(
        jspans(&jn(
            chords(&ceg, &[64, 67, 72], 60),
            &[on("n09"), ch("n09.match", 1)]
        )),
        vec![(0, 240, 60), (0, 540, 64), (0, 540, 67), (300, 540, 72)]
    );
    // The same bass and top: those hold, the inner voice moves.
    assert_eq!(
        jspans(&jn(
            chords(&ceg, &[60, 65, 67], 60),
            &[on("n09"), ch("n09.match", 2)]
        )),
        vec![(0, 540, 60), (0, 240, 64), (0, 540, 67), (300, 540, 65)]
    );
    // Single notes are not chords.
    assert_eq!(jn(chords(&[60], &[60], 60), &[on("n09")]).len(), 2);
    // A rolled chord within the tolerance is one chord.
    let mut rolled = chords(&ceg, &ceg, 60);
    rolled[1].start += 5;
    rolled[1].dur -= 5;
    rolled[2].start += 10;
    rolled[2].dur -= 10;
    assert_eq!(jn(rolled.clone(), &[on("n09")]).len(), 3);
    assert_eq!(jn(rolled, &[on("n09"), int("n09.tol", 4)]).len(), 6);
}

#[test]
fn join_uninterrupted_join_crosses_only_silent_rests() {
    let c4 = vec![jf(0, 400, 60, 90), jf(600, 1000, 60, 90)];
    let c = Ctx::simple(960);
    let run = |extra: Vec<TNote>, set: &[(&'static str, ParamValue)]| {
        let mut v = c4.clone();
        v.extend(extra);
        jt(&join_two(v, set, c.clone()))
            .into_iter()
            .filter(|n| n.3 == 60)
            .map(|n| (n.1, n.2))
            .collect::<Vec<_>>()
    };
    let e4 = |track: u16, start: u64| TNote {
        track,
        ..jf(start, start + 200, 64, 90)
    };
    assert_eq!(run(vec![], &[]), vec![(0, 400), (600, 1000)]);
    assert_eq!(run(vec![], &[on("n10")]), vec![(0, 1000)]);
    // A note starting in the rest (its start included) interrupts.
    assert_eq!(
        run(vec![e4(0, 500)], &[on("n10")]),
        vec![(0, 400), (600, 1000)]
    );
    assert_eq!(
        run(vec![e4(0, 400)], &[on("n10")]),
        vec![(0, 400), (600, 1000)]
    );
    // A note sounding through the rest (started before) does not.
    assert_eq!(run(vec![e4(0, 300)], &[on("n10")]), vec![(0, 1000)]);
    // Of the track, or of any track.
    assert_eq!(run(vec![e4(1, 500)], &[on("n10")]), vec![(0, 1000)]);
    assert_eq!(
        run(vec![e4(1, 500)], &[on("n10"), ch("n10.of", 1)]),
        vec![(0, 400), (600, 1000)]
    );
    // A muted note does not sound, so it does not interrupt.
    let mut muted = e4(0, 500);
    muted.flags = plumspirit_engine::transform::FLAG_MUTED;
    assert_eq!(run(vec![muted], &[on("n10")]), vec![(0, 1000)]);
    // A rest longer than the largest rest stays.
    assert_eq!(
        run(vec![], &[on("n10"), int("n10.rest", 100)]),
        vec![(0, 400), (600, 1000)]
    );
}

#[test]
fn join_per_bar_limit_joins_until_n_fragments_per_bar() {
    // Eight fragments in bar 0 (gaps 280, 80, 380, 30, 180, 430, 60).
    let durs = [200, 400, 100, 450, 300, 50, 420, 200];
    let notes: Vec<TNote> = durs
        .iter()
        .enumerate()
        .map(|(k, &d)| jf(k as u64 * 480, k as u64 * 480 + d, 60, 90))
        .collect();
    assert_eq!(
        jspans(&jn(notes.clone(), &[on("n11")])),
        vec![
            (0, 200, 60),
            (480, 1060, 60),
            (1440, 2450, 60),
            (2880, 3560, 60)
        ]
    );
    assert_eq!(
        jspans(&jn(notes.clone(), &[on("n11"), ch("n11.first", 1)])),
        vec![
            (0, 2220, 60),
            (2400, 2450, 60),
            (2880, 3300, 60),
            (3360, 3560, 60)
        ]
    );
    assert_eq!(jn(notes.clone(), &[on("n11"), int("n11.most", 8)]).len(), 8);
    // Within the gates: velocities 50 apart never join.
    let loud: Vec<TNote> = notes
        .iter()
        .enumerate()
        .map(|(k, n)| TNote {
            vel: if k % 2 == 0 { 40 } else { 90 },
            ..*n
        })
        .collect();
    assert_eq!(
        jn(loud, &[on("n11"), on("n03"), int("n03.diff", 10)]).len(),
        8
    );
    // On the fixture: at most N per chain and bar, nothing deleted.
    for most in [1, 2] {
        let out = jn(join_fixture(), &[on("n11"), int("n11.most", most)]);
        assert!(join_covers(&join_fixture(), &out));
        let mut per: std::collections::BTreeMap<(u32, u8, u32, u8, u8, u64), i64> =
            Default::default();
        for o in &out {
            *per.entry((o.sub, o.ch, o.group, o.flags, o.pitch, o.start / 3840))
                .or_insert(0) += 1;
        }
        assert!(per.values().all(|&c| c <= most), "{most}");
    }
}

#[test]
fn join_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&f| on(f)).collect();
    let a = run_full("join", join_fixture(), &all);
    let b = run_full("join", join_fixture(), &all);
    assert_eq!(a.notes, b.notes);
    assert_eq!(a.events, b.events);
    assert!(a.notes.len() <= join_fixture().len());
    assert!(join_covers(&join_fixture(), &a.notes));
    for f in ALL11 {
        for extra in [
            vec![],
            vec![on("a1"), on("a2"), on("a6"), on("a7"), on("a9")],
            vec![on("a4"), on("a8"), on("a10"), on("a3")],
        ] {
            let mut set = vec![on(f)];
            set.extend(extra);
            let v = run_full("join", join_fixture(), &set);
            assert!(v.notes.len() <= join_fixture().len(), "{f}");
            assert_eq!(v.notes, run_full("join", join_fixture(), &set).notes, "{f}");
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.ch <= 15 && n.dur >= 1),
                "{f}"
            );
            // Joining never moves music to another key.
            let keys = |v: &[TNote]| {
                v.iter()
                    .map(|n| n.pitch)
                    .collect::<std::collections::BTreeSet<_>>()
            };
            assert_eq!(keys(&v.notes), keys(&join_fixture()), "{f}");
        }
    }
    // A Control Sweep by pitch (chains are one key: never split).
    let sweep = [on("n11"), on("m.sweep"), on("m.sweep.per_bar")];
    let a = run_full("join", join_fixture(), &sweep);
    assert_eq!(a.notes, run_full("join", join_fixture(), &sweep).notes);
    assert!(join_covers(&join_fixture(), &a.notes));
}

