#[test]
fn rep_grain_cloud_scatters_seeded_grains() {
    let note = vec![jf(0, 960, 60, 100)];
    let base = [
        on("n05"),
        int("n05.len", 60),
        fl("n05.density", 4.0),
        int("n05.spread", 0),
        fl("n05.overlap", 0.0),
    ];
    assert_eq!(
        rp(note.clone(), &base),
        vec![
            (0, 60, 60, 100),
            (240, 300, 60, 100),
            (480, 540, 60, 100),
            (720, 780, 60, 100)
        ]
    );
    // Pitch spread and scatter: within their bounds, the same for a seed.
    let mut wide = base.to_vec();
    wide.extend([
        int("n05.spread", 3),
        fl("n05.overlap", 50.0),
        fl("n05.density", 16.0),
    ]);
    let a = rp(note.clone(), &wide);
    assert_eq!(a.len(), 16);
    assert_eq!(a, rp(note.clone(), &wide));
    for g in &a {
        assert!((57..=63).contains(&g.2), "{g:?}");
        assert_eq!(g.1 - g.0, 60);
    }
    // Each grain within a quarter of the spacing (15 of 60 ticks) of its
    // place on the grid.
    let mut starts: Vec<u64> = a.iter().map(|g| g.0).collect();
    starts.sort_unstable();
    for (k, s) in starts.iter().enumerate() {
        let grid = k as i64 * 60;
        assert!((*s as i64 - grid).abs() <= 15, "{k}: {s}");
    }
    assert!(a.iter().any(|g| g.2 != 60));
    wide.push(int("n05.seed", 7));
    assert_ne!(rp(note, &wide), a);
}

#[test]
fn rep_doppler_rate_is_densest_at_the_peak() {
    // Ten repeats of 100 ticks; the rate three times higher at the middle.
    let set = [
        ch("len", 11),
        int("len.ticks", 100),
        on("n13"),
        fl("n13.depth", 200.0),
    ];
    let v = rp(vec![jf(0, 1000, 60, 100)], &set);
    assert_eq!(v.len(), 10);
    let lens: Vec<u64> = v.iter().map(|x| x.1 - x.0).collect();
    assert_eq!(v[0].0, 0);
    assert_eq!(v[9].1, 1000);
    for k in 0..5 {
        // Symmetric (within a tick of rounding), shorter toward the peak.
        assert!(lens[k].abs_diff(lens[9 - k]) <= 1, "{lens:?}");
    }
    assert!(lens[0] > lens[2] && lens[2] > lens[4], "{lens:?}");
    assert!(lens[0] >= 2 * lens[4], "{lens:?}");
    // The peak at 20 %: the shortest repeat comes early.
    let mut early = set.to_vec();
    early.push(fl("n13.peak", 20.0));
    let lens: Vec<u64> = rp(vec![jf(0, 1000, 60, 100)], &early)
        .iter()
        .map(|x| x.1 - x.0)
        .collect();
    let shortest = (0..10).min_by_key(|&k| lens[k]).unwrap();
    assert!(shortest <= 3, "{lens:?}");
}

#[test]
fn rep_repeated_voices_repeat_some_voices_of_each_chord() {
    let chord = vec![
        jf(0, 960, 60, 100),
        jf(0, 480, 64, 100),
        jf(0, 480, 67, 100),
    ];
    let count = |v: &[(u64, u64, u8, u8)], p: u8| v.iter().filter(|x| x.2 == p).count();
    // The highest repeats; the others hold to the chord's end.
    let top = rp(chord.clone(), &[on("n07")]);
    assert_eq!(count(&top, 67), 2);
    assert!(top.contains(&(0, 960, 64, 100)) && top.contains(&(0, 960, 60, 100)));
    // … or stay as written.
    let leave = rp(chord.clone(), &[on("n07"), ch("n07.others", 1)]);
    assert!(leave.contains(&(0, 480, 64, 100)));
    // Lowest, inner, all but the lowest.
    let low = rp(chord.clone(), &[on("n07"), ch("n07.voices", 0)]);
    assert_eq!(
        (count(&low, 60), count(&low, 64), count(&low, 67)),
        (4, 1, 1)
    );
    let inner = rp(chord.clone(), &[on("n07"), ch("n07.voices", 2)]);
    assert_eq!(
        (count(&inner, 60), count(&inner, 64), count(&inner, 67)),
        (1, 2, 1)
    );
    let upper = rp(chord.clone(), &[on("n07"), ch("n07.voices", 3)]);
    assert_eq!(
        (count(&upper, 60), count(&upper, 64), count(&upper, 67)),
        (1, 2, 2)
    );
    // A rolled chord within the tolerance is one chord; a single note is
    // its own lowest and highest voice.
    let mut rolled = chord.clone();
    rolled[2].start = 5;
    rolled[2].dur = 475;
    assert_eq!(count(&rp(rolled, &[on("n07")]), 67), 2);
    assert_eq!(rp(vec![jf(0, 480, 60, 100)], &[on("n07")]).len(), 2);
    assert_eq!(
        rp(vec![jf(0, 480, 60, 100)], &[on("n07"), ch("n07.voices", 2)]).len(),
        1
    );
}

#[test]
fn rep_subdivision_ladder_doubles_the_rate_every_step() {
    let bar = vec![jf(0, 3840, 60, 100)];
    // 1, 2, 4, 8 per beat over the bar's four beats.
    let v = rp(bar.clone(), &[on("n08")]);
    assert_eq!(v.len(), 1 + 2 + 4 + 8);
    let lens: Vec<u64> = v.iter().map(|x| x.1 - x.0).collect();
    assert_eq!(lens[0], 960);
    assert_eq!(&lens[1..3], &[480, 480]);
    assert_eq!(lens[14], 120);
    // Capped per beat; stepped every half note or every bar.
    assert_eq!(
        rp(bar.clone(), &[on("n08"), int("n08.most", 4)]).len(),
        1 + 2 + 4 + 4
    );
    assert_eq!(
        rp(bar.clone(), &[on("n08"), ch("n08.every", 1)]).len(),
        2 + 4
    );
    assert_eq!(rp(bar.clone(), &[on("n08"), ch("n08.every", 2)]).len(), 4);
    // Tripled from 2 per beat.
    assert_eq!(
        rp(
            bar,
            &[
                on("n08"),
                int("n08.start", 2),
                int("n08.factor", 3),
                int("n08.most", 64)
            ]
        )
        .len(),
        2 + 6 + 18 + 54
    );
}

#[test]
fn rep_length_cycle_gives_each_note_its_own_rate() {
    let notes = vec![
        jf(0, 960, 60, 100),
        jf(1000, 1960, 62, 100),
        jf(2000, 2960, 64, 100),
    ];
    let v = rp(notes, &[on("n09")]);
    let count = |v: &[(u64, u64, u8, u8)], p: u8| v.iter().filter(|x| x.2 == p).count();
    // 240, 320, 160 ticks: 4, 3, 6 repeats.
    assert_eq!((count(&v, 60), count(&v, 62), count(&v, 64)), (4, 3, 6));
    // Per chord: two notes at one onset share a length.
    let chord = vec![
        jf(0, 960, 60, 100),
        jf(0, 960, 67, 100),
        jf(1000, 1960, 62, 100),
    ];
    let v = rp(chord, &[on("n09"), ch("n09.per", 2)]);
    assert_eq!((count(&v, 60), count(&v, 67), count(&v, 62)), (4, 4, 3));
    // Per beat (960 ticks): the notes on beats 0, 1, 2.
    let beats = vec![
        jf(0, 960, 60, 100),
        jf(960, 1920, 62, 100),
        jf(1920, 2880, 64, 100),
    ];
    let v = rp(beats, &[on("n09"), ch("n09.per", 1)]);
    assert_eq!((count(&v, 60), count(&v, 62), count(&v, 64)), (4, 3, 6));
}

#[test]
fn rep_delayed_tremolo_holds_first() {
    let note = vec![jf(0, 960, 60, 100)];
    assert_eq!(
        rp_spans(&rp(note.clone(), &[on("n10")])),
        vec![(0, 480), (480, 720), (720, 960)]
    );
    // At least 600 ticks.
    assert_eq!(
        rp_spans(&rp(note, &[on("n10"), int("n10.ticks", 600)])),
        vec![(0, 600), (600, 840), (840, 960)]
    );
    // Accelerating into the repeats: their slots shrink.
    let v = rp(
        vec![jf(0, 3840, 60, 100)],
        &[on("n10"), fl("n10.share", 25.0), ch("n10.entry", 1)],
    );
    assert_eq!(v[0], (0, 960, 60, 100));
    let lens: Vec<u64> = v[1..].iter().map(|x| x.1 - x.0).collect();
    assert_eq!(lens.len(), 12);
    assert!(lens.windows(2).all(|w| w[0] >= w[1]), "{lens:?}");
    assert!(lens[0] > lens[11]);
    assert_eq!(v.last().unwrap().1, 3840);
}

#[test]
fn rep_overlapping_repeats_outlast_their_slots() {
    let note = vec![jf(0, 960, 60, 100)];
    assert_eq!(
        rp_spans(&rp(note.clone(), &[on("n14"), fl("n14.overlap", 200.0)])),
        vec![(0, 480), (240, 720), (480, 960), (720, 1200)]
    );
    // On the gate: 50 % × 200 % = the slot.
    assert_eq!(
        rp_spans(&rp(
            note,
            &[fl("gate", 50.0), on("n14"), fl("n14.overlap", 200.0)]
        )),
        vec![(0, 240), (240, 480), (480, 720), (720, 960)]
    );
}

#[test]
fn rep_functions_compose_within_the_preflight() {
    const REP11: [&str; 11] = [
        "n01", "n02", "n03", "n12", "n05", "n13", "n07", "n08", "n09", "n10", "n14",
    ];
    let all: Vec<(&'static str, ParamValue)> = REP11.iter().map(|&f| on(f)).collect();
    // run_full asserts every result within the kernel's estimate.
    let a = run_full("repeat", rep_fixture(), &all);
    assert_eq!(a.notes, run_full("repeat", rep_fixture(), &all).notes);
    for f in REP11 {
        for extra in [
            vec![],
            vec![on("a5"), on("a10"), int("a10.depth", 2)],
            vec![
                on("a1"),
                on("a6"),
                on("a7"),
                on("a8"),
                on("a9"),
                flag("overflow", true),
            ],
            vec![on("n02"), int("n02.echoes", 8), on("n10")],
        ] {
            let mut set = vec![on(f)];
            set.extend(extra);
            let v = run_full("repeat", rep_fixture(), &set);
            assert_eq!(
                v.notes,
                run_full("repeat", rep_fixture(), &set).notes,
                "{f}"
            );
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.dur >= 1),
                "{f}"
            );
        }
    }
    // Controller points above the event bound are refused before the run.
    let t = tool("repeat").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, v) in [on("n12"), ch("len", 11), int("len.ticks", 1)] {
        ps.set(k, v);
    }
    let src = Source::from_notes(vec![jf(0, 1 << 30, 60, 100)], vec![]);
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    assert!(t.kernel(&ps, &b).is_err());
    // A Control Sweep of the overlap by velocity runs per level.
    let sweep = [on("n14"), on("m.sweep"), on("m.sweep.overlap")];
    let a = run_full("repeat", rep_fixture(), &sweep);
    assert_eq!(a.notes, run_full("repeat", rep_fixture(), &sweep).notes);
}

// ================================================================ Group Notes

use plumspirit_engine::model::{GroupInfo, GroupTable};

/// The Group fixture's table: 1 "A" (top) with child 2, linked 3 and 4,
/// 5 locked, 6 temporary, 7 coloured; 8 an unused top-level group.
fn grp_table() -> GroupTable {
    let g = |id: u32, parent: u32| GroupInfo {
        id,
        parent,
        ..GroupInfo::default()
    };
    GroupTable::from_entries(
        vec![
            GroupInfo {
                name: Some("A".into()),
                ..g(1, 0)
            },
            g(2, 1),
            GroupInfo { link: 3, ..g(3, 0) },
            GroupInfo { link: 3, ..g(4, 0) },
            GroupInfo {
                locked: true,
                ..g(5, 0)
            },
            GroupInfo {
                temporary: true,
                ..g(6, 0)
            },
            GroupInfo {
                color: Some([1, 2, 3]),
                ..g(7, 0)
            },
            g(8, 0),
        ],
        9,
    )
    .unwrap()
}

/// Phrases of two tracks (subchannels 0 – 3, channel = subchannel): runs of
/// 4 – 13 notes split by rests, some chords; each phrase in a group of the
/// table (cycled, some ungrouped; group 5's phrase is locked) —
/// deterministic. Returns (selected notes, locked notes).
fn grp_fixture() -> (Vec<TNote>, Vec<TNote>) {
    let mut x: u64 = 0x2545_F491_4F6C_DD1D;
    let mut rnd = |m: u64| {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        x % m.max(1)
    };
    const PHRASE_GROUPS: [u32; 9] = [1, 2, 0, 3, 4, 5, 6, 7, 0];
    let (mut sel, mut locked) = (Vec::new(), Vec::new());
    let mut k = 0usize;
    for track in 0..2u16 {
        let mut t = rnd(960);
        for _ in 0..9 {
            let group = PHRASE_GROUPS[k % PHRASE_GROUPS.len()];
            k += 1;
            let base = 48 + rnd(24) as u8;
            for _ in 0..4 + rnd(10) {
                let chord = 1 + (rnd(4) == 0) as u64 * (1 + rnd(3));
                let dur = 60 + rnd(420);
                for c in 0..chord {
                    let sub = rnd(4) as u32;
                    let n = TNote {
                        start: t,
                        dur,
                        pitch: base + rnd(12) as u8 + 4 * c as u8,
                        vel: 20 + rnd(100) as u8,
                        rel: 10 + rnd(100) as u8,
                        sub,
                        ch: sub as u8,
                        track,
                        group,
                        ..TNote::default()
                    };
                    if group == 5 {
                        locked.push(n);
                    } else {
                        sel.push(n);
                    }
                }
                t += match rnd(4) {
                    0 => dur,
                    1 => dur / 2 + 1,
                    _ => 120 + rnd(240),
                };
            }
            t += 960 + rnd(1920);
        }
    }
    (sel, locked)
}

/// Group on hand-built notes of two tracks (subchannels 0 – 3 each) with
/// `locked` notes and the group table `table`.
fn grp_run_in(
    notes: Vec<TNote>,
    locked: Vec<TNote>,
    table: GroupTable,
    set: &[(&'static str, ParamValue)],
    ctx: Option<Ctx>,
) -> plumspirit_engine::transform::TransformRun {
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(notes, vec![tr(0), tr(1)]);
    src.locked = locked;
    let table = Arc::new(table);
    src.groups = table.clone();
    let t = tool("group").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    ctx.groups = table;
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    // The run keeps the locked notes besides the kernel's result.
    assert!(r.notes.len() as u64 <= est.notes + src.locked.len() as u64);
    r
}

fn grp_run(
    notes: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    grp_run_in(notes, Vec::new(), GroupTable::new(), set, None)
}

/// [`grp_run_in`] on [`grp_fixture`] with [`grp_table`].
fn grp_fixture_run(
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    let (sel, locked) = grp_fixture();
    grp_run_in(sel, locked, grp_table(), set, None)
}

