/// Every field of the result's notes, the message and the new group table
/// (each entry and the next id), hashed.
fn grp_fingerprint(r: &plumspirit_engine::transform::TransformRun) -> (usize, usize, u64) {
    let (n, groups, h) = join_fingerprint(r);
    let mut h = h;
    let mut eat = |w: u64| {
        for b in w.to_le_bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0100_0000_01B3);
        }
    };
    let entries = match &r.groups {
        Some(t) => {
            eat(u64::from(t.next_id()));
            for g in t.entries() {
                eat(u64::from(g.id) | u64::from(g.parent) << 32);
                eat(u64::from(g.link) | u64::from(g.locked) << 32 | u64::from(g.temporary) << 33);
                let c = g.color.map_or(1 << 24, |c| {
                    u64::from(c[0]) | u64::from(c[1]) << 8 | u64::from(c[2]) << 16
                });
                eat(c);
                for b in g.name.as_deref().unwrap_or("\u{0}").bytes() {
                    eat(u64::from(b));
                }
            }
            t.len()
        }
        None => 0,
    };
    (n, groups + entries * 1000, h)
}

