fn skew_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

#[test]
fn skew_new_functions_off_leave_v08_results_unchanged() {
    for (i, s) in skew_v08_settings().iter().enumerate() {
        let r = skew_run(skew_fixture(), 3, &skew_off(s));
        assert_eq!(join_fingerprint(&r), SKEW_V08[i], "setting {i}");
    }
}

/// Neutral settings of the v0.9 functions (the v0.9 path, the v0.8
/// result): a staircase at strength 0, an end amount of 0, both depth
/// velocities 100 %, no overshoot, no stagger — each alone, then together.
fn skew_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n01", vec![on("n01"), fl("n01.strength", 0.0)]),
        ("n03", vec![on("n03"), fl("n03.amount", 0.0)]),
        (
            "n07",
            vec![on("n07"), fl("n07.lo", 100.0), fl("n07.hi", 100.0)],
        ),
        ("n09", vec![on("n09"), fl("n09.overshoot", 0.0)]),
        ("n10", vec![on("n10"), int("n10.shift", 0)]),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn skew_neutral_new_functions_equal_the_v08_results() {
    for (name, extra) in skew_neutral() {
        for (i, s) in skew_v08_settings().iter().enumerate() {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            let r = skew_run(skew_fixture(), 3, &set);
            assert_eq!(join_fingerprint(&r), SKEW_V08[i], "{name}, setting {i}");
        }
    }
}

/// Skew on one track of (start, length, pitch) notes at velocity 100.
fn sk(notes: &[(u64, u64, u8)], set: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    let v = notes.iter().map(|&(s, d, p)| tn(s, d, p, 100)).collect();
    skew_run(v, 1, set).notes
}

/// The note at `pitch` (one per pitch).
fn at(v: &[TNote], pitch: u8) -> TNote {
    let mut m = v.iter().filter(|n| n.pitch == pitch);
    let n = *m.next().unwrap_or_else(|| panic!("no note at {pitch}"));
    assert!(m.next().is_none(), "two notes at {pitch}");
    n
}

/// Twelve whole-bar notes on rows 60 – 71 starting at `t`.
fn skew_column(t: u64) -> Vec<(u64, u64, u8)> {
    (0..12).map(|i| (t, 3840, 60 + i as u8)).collect()
}

#[test]
fn skew_staircase_steps_rows_and_snaps_starts_to_the_grid() {
    // Box 3840 × 12 rows, pivot at the bottom, X skew 100 %: row i moves
    // (i + ½) · 320 ticks; with 4 rows per step every step takes its
    // bottom row's shift, snapped to 1/16 (240) from the bar line.
    let base = [
        fl("amount", 100.0),
        fl("g.pivot_y", 0.0),
        on("n01"),
        ch("n01.grid", 4),
        int("n01.rows", 4),
    ];
    let snap = |x: f64| (x / 240.0 + 0.5).floor() * 240.0;
    for strength in [100.0, 50.0, 25.0] {
        let mut set = base.to_vec();
        set.push(fl("n01.strength", strength));
        let v = sk(&skew_column(0), &set);
        for i in 0..12u8 {
            let plain = (f64::from(i) + 0.5) * 320.0;
            let stair = (f64::from(i / 4 * 4) + 0.5) * 320.0;
            let want = (plain + strength / 100.0 * (snap(stair) - plain)).round() as u64;
            let n = at(&v, 60 + i);
            assert_eq!((n.start, n.dur), (want, 3840), "row {i} at {strength} %");
        }
    }
    let v = sk(&skew_column(0), &base);
    let starts: std::collections::BTreeSet<u64> = v.iter().map(|n| n.start).collect();
    assert_eq!(
        starts.into_iter().collect::<Vec<_>>(),
        vec![240, 1440, 2640]
    );
}

#[test]
fn skew_zigzag_flips_the_shift_with_its_profile_over_time() {
    // Sixteen notes on the top row every 480 ticks from 3840 and one on
    // the bottom row: box 3840 – 11,280 (7,440 wide), 12 rows, pivot at the
    // bottom, amount 50 %: shift = ½ · p((t − 3840) / period + phase) ·
    // h · 7,440.
    let mut notes: Vec<(u64, u64, u8)> = (0..16).map(|j| (3840 + j * 480, 240, 71)).collect();
    notes.push((3840, 30, 60));
    let tri = |x: f64| 1.0 - 4.0 * ((x - x.floor()) - 0.5).abs();
    let saw = |x: f64| 2.0 * (x - x.floor()) - 1.0;
    let sine = |x: f64| (2.0 * std::f64::consts::PI * x).sin();
    let profiles: [&dyn Fn(f64) -> f64; 3] = [&tri, &saw, &sine];
    for (shape, p) in profiles.iter().enumerate() {
        for (period, phase) in [(1920u64, 0.0), (1440, 25.0)] {
            let v = sk(
                &notes,
                &[
                    fl("g.pivot_y", 0.0),
                    on("n02"),
                    int("n02.period", period as i64),
                    fl("n02.phase", phase),
                    ch("n02.shape", shape as u32),
                ],
            );
            let mut top: Vec<u64> = v
                .iter()
                .filter(|n| n.pitch == 71)
                .map(|n| n.start)
                .collect();
            top.sort_unstable();
            let mut want: Vec<u64> = (0..16u64)
                .map(|j| {
                    let x = (j * 480) as f64 / period as f64 + phase / 100.0;
                    let d = 0.5 * p(x) * (11.5 / 12.0) * 7440.0;
                    ((3840 + j * 480) as f64 + d).round() as u64
                })
                .collect();
            want.sort_unstable();
            assert_eq!(top, want, "shape {shape}, period {period}");
            // Lengths stay (± the raster's rounding of both ends).
            assert!(
                v.iter()
                    .all(|n| n.dur.abs_diff(240) <= 1 || n.dur.abs_diff(30) <= 1)
            );
        }
    }
}

#[test]
fn skew_end_skew_changes_lengths_with_height_around_its_anchor() {
    // Rows 60 – 71, one beat from 3840, no start skew, end amount 100 %,
    // pivot in the middle: the length changes by (i − 5.5) · 80 ticks.
    let notes: Vec<(u64, u64, u8)> = (0..12).map(|i| (3840, 960, 60 + i as u8)).collect();
    for (anchor, a) in [(0u32, 0.0), (1, 1.0), (2, 0.5)] {
        let v = sk(
            &notes,
            &[
                fl("amount", 0.0),
                on("n03"),
                fl("n03.amount", 100.0),
                ch("n03.anchor", anchor),
            ],
        );
        for i in 0..12u8 {
            let d = (f64::from(i) - 5.5) * 80.0;
            let s = (3840.0 - a * d).round() as u64;
            let e = (4800.0 + (1.0 - a) * d).round() as u64;
            let n = at(&v, 60 + i);
            assert_eq!((n.start, n.end()), (s, e), "anchor {anchor}, row {i}");
        }
    }
    // A length never drops below one tick.
    let v = sk(
        &notes,
        &[fl("amount", 0.0), on("n03"), fl("n03.amount", -400.0)],
    );
    assert!(v.iter().all(|n| n.dur >= 1));
    assert_eq!(at(&v, 71).dur, 1);
}

/// Notes `(start, pitch, group)` of length 240.
fn skew_units_fixture() -> Vec<TNote> {
    [
        (7680, 60, 1),
        (7680, 64, 2),
        (7680, 67, 1),
        (8940, 62, 2),
        (11520, 72, 1),
        (11520, 76, 2),
        (11520, 79, 2),
        (12480, 74, 1),
    ]
    .iter()
    .map(|&(s, p, g)| TNote {
        group: g,
        ..tn(s, 240, p, 100)
    })
    .collect()
}

#[test]
fn skew_per_unit_skews_each_chord_bar_group_or_phrase_around_its_own_pivot() {
    // Box 7,680 – 12,720 (5,040 wide), rows 60 – 79 (20): with X skew 100 %
    // a note moves (row − unit pivot row) · 5,040 / 20 = 252 per row.
    let shift =
        |v: &[TNote], p: u8| at(v, p).start as i64 - at(&skew_units_fixture(), p).start as i64;
    let w = 252.0;
    let units: [(u32, &[&[u8]]); 4] = [
        // chord (tolerance 30): {60 64 67} {62} {72 76 79} {74}
        (0, &[&[60, 64, 67], &[62], &[72, 76, 79], &[74]]),
        // bar: {60 64 67 62} {72 76 79 74}
        (1, &[&[60, 64, 67, 62], &[72, 76, 79, 74]]),
        // group: 1 = {60 67 72 74}, 2 = {64 62 76 79}
        (2, &[&[60, 67, 72, 74], &[64, 62, 76, 79]]),
        // phrase (rests over a beat split): {60 64 67} {62} {72 76 79 74}
        (3, &[&[60, 64, 67], &[62], &[72, 76, 79, 74]]),
    ];
    for (unit, groups) in units {
        for (pivot, name) in [(0u32, "bottom"), (1, "centre"), (2, "top")] {
            let v = skew_run(
                skew_units_fixture(),
                1,
                &[
                    fl("amount", 100.0),
                    on("n04"),
                    ch("n04.unit", unit),
                    ch("n04.pivot", pivot),
                ],
            )
            .notes;
            for g in groups {
                let lo = f64::from(*g.iter().min().unwrap());
                let hi = f64::from(*g.iter().max().unwrap());
                let row = [lo, (lo + hi + 1.0) / 2.0, hi + 1.0][pivot as usize];
                for &p in *g {
                    let want = ((f64::from(p) + 0.5 - row) * w).round() as i64;
                    assert_eq!(shift(&v, p), want, "unit {unit}, pivot {name}, pitch {p}");
                }
            }
        }
    }
}

#[test]
fn skew_wrap_loops_shifted_notes_around_their_span() {
    // Rows 60 – 71, one every 240 ticks from 3840 (length 120): box 3840 –
    // 6,600 (2,760 wide), pivot at the bottom, X skew 100 %: row i moves
    // (i + ½) · 230 ticks.
    let notes: Vec<(u64, u64, u8)> = (0..12)
        .map(|i| (3840 + 240 * i as u64, 120, 60 + i as u8))
        .collect();
    let shifted = |i: u8| 3840.0 + 240.0 * f64::from(i) + (f64::from(i) + 0.5) * 230.0;
    for (span, n, wrap) in [
        (
            0u32,
            1i64,
            Box::new(|x: f64, _s: f64| 3840.0 + (x - 3840.0).rem_euclid(2760.0))
                as Box<dyn Fn(f64, f64) -> f64>,
        ),
        (
            1,
            1,
            Box::new(|x: f64, _s: f64| 3840.0 + (x - 3840.0).rem_euclid(3840.0)),
        ),
        (
            2,
            1,
            Box::new(|x: f64, s: f64| {
                let a = 3840.0 + ((s - 3840.0) / 960.0).floor() * 960.0;
                a + (x - a).rem_euclid(960.0)
            }),
        ),
        (
            2,
            3,
            Box::new(|x: f64, s: f64| {
                let a = 3840.0 + ((s - 3840.0) / 2880.0).floor() * 2880.0;
                a + (x - a).rem_euclid(2880.0)
            }),
        ),
    ] {
        let v = sk(
            &notes,
            &[
                fl("amount", 100.0),
                fl("g.pivot_y", 0.0),
                on("n05"),
                ch("n05.axis", 0),
                ch("n05.span", span),
                int("n05.n", n),
            ],
        );
        for i in 0..12u8 {
            let s = 3840.0 + 240.0 * f64::from(i);
            let want = wrap(shifted(i), s).round() as u64;
            assert_eq!(
                (at(&v, 60 + i).start, at(&v, 60 + i).dur),
                (want, 120),
                "span {span}×{n}, row {i}"
            );
        }
    }
    // Pitch: a Y skew of 300 % wraps into the note's octave (from the
    // lowest row) or the selection's rows; the starts stay.
    for (span, n, base, len) in [(3u32, 1i64, 60i64, 12i64), (0, 1, 60, 12), (3, 2, 60, 24)] {
        let v = sk(
            &notes,
            &[
                fl("amount", 0.0),
                on("a2"),
                fl("a2.amount", 300.0),
                on("n05"),
                ch("n05.axis", 1),
                ch("n05.span", span),
                int("n05.n", n),
            ],
        );
        let mut got: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.pitch)).collect();
        got.sort_unstable();
        let want: Vec<(u64, u8)> = (0..12u8)
            .map(|i| {
                let s = 3840.0 + 240.0 * f64::from(i);
                let um = (s + 60.0 - 3840.0) / 2760.0;
                let v2 = (f64::from(i) + 0.5) / 12.0 + 3.0 * (um - 0.5);
                let row = (60.0 + v2 * 12.0).floor() as i64;
                (s as u64, (base + (row - base).rem_euclid(len)) as u8)
            })
            .collect();
        assert_eq!(got, want, "span {span}×{n}");
    }
}

/// Song seconds of a tick under [`qnt_stepped_tempo`] (120 BPM, then 60
/// BPM from tick 1,920) and back.
fn stepped_secs(t: f64) -> f64 {
    if t <= 1920.0 {
        t / 1920.0
    } else {
        1.0 + (t - 1920.0) / 960.0
    }
}
fn stepped_tick(s: f64) -> f64 {
    if s <= 1.0 {
        s * 1920.0
    } else {
        1920.0 + (s - 1.0) * 960.0
    }
}

#[test]
fn skew_real_time_slope_moves_notes_by_milliseconds_per_semitone_through_the_tempo_map() {
    let notes = vec![
        tn(2880, 480, 60, 100),
        tn(2880, 480, 62, 100),
        tn(2880, 480, 64, 100),
        tn(1000, 1500, 65, 100),
        tn(800, 300, 67, 100),
    ];
    for (r, ms) in [(0u32, 100.0), (0, -40.0), (1, 100.0)] {
        let set = [
            fl("g.pivot_y", 50.0),
            on("n06"),
            fl("n06.ms", ms),
            ch("n06.ref", r),
        ];
        let v = skew_try(notes.clone(), 1, &set, Some(qnt_stepped_tempo()))
            .unwrap()
            .notes;
        // Box rows 60 – 67 (8); the reference row: the lowest note's
        // centre, or the pivot (the box's middle, 64).
        let refrow = if r == 0 { 60.5 } else { 64.0 };
        for n in &notes {
            let ds = ms / 1000.0 * (f64::from(n.pitch) + 0.5 - refrow);
            let s = stepped_tick(stepped_secs(n.start as f64) + ds);
            let e = stepped_tick(stepped_secs(n.end() as f64) + ds);
            let got = at(&v, n.pitch);
            for (g, w) in [(got.start as f64, s), (got.end() as f64, e)] {
                assert!(
                    (g - w.round()).abs() <= 1.0,
                    "{ms} ms, ref {r}, pitch {}: {g} vs {w}",
                    n.pitch
                );
            }
            // The note keeps its length in seconds.
            let len = stepped_secs(got.end() as f64) - stepped_secs(got.start as f64);
            let len0 = stepped_secs(n.end() as f64) - stepped_secs(n.start as f64);
            assert!((len - len0).abs() < 2.0 / 960.0, "pitch {}", n.pitch);
        }
    }
    // One tempo (120 BPM, no map: 1,920 ticks a second): exact, lengths
    // kept in ticks.
    let v = skew_try(notes.clone(), 1, &[on("n06"), fl("n06.ms", 25.0)], None)
        .unwrap()
        .notes;
    for n in &notes {
        let d = (0.025 * f64::from(n.pitch - 60) * 1920.0).round() as u64;
        let got = at(&v, n.pitch);
        assert_eq!(
            (got.start, got.dur),
            (n.start + d, n.dur),
            "pitch {}",
            n.pitch
        );
    }
}

#[test]
fn skew_shift_depth_scales_velocity_with_the_distance_moved() {
    // Pivot at the bottom, X skew 100 %: row i moves (i + ½) / 12 box
    // widths, the largest 11.5 / 12.
    for (c, f) in [
        (
            Curve::line(0.0, 1.0),
            Box::new(|x: f64| x) as Box<dyn Fn(f64) -> f64>,
        ),
        (Curve::flat(1.0), Box::new(|_x: f64| 1.0)),
    ] {
        let v = sk(
            &skew_column(0),
            &[
                fl("amount", 100.0),
                fl("g.pivot_y", 0.0),
                on("n07"),
                fl("n07.lo", 120.0),
                fl("n07.hi", 40.0),
                curve("n07.curve", c),
            ],
        );
        for i in 0..12u8 {
            let x = (f64::from(i) + 0.5) / 11.5;
            let want = (100.0 * (1.2 + (0.4 - 1.2) * f(x))).round() as u8;
            assert_eq!(at(&v, 60 + i).vel, want, "row {i}");
        }
    }
}

#[test]
fn skew_fit_to_end_lands_the_last_end_on_the_target() {
    let notes = [
        (0, 960, 60),
        (960, 960, 64),
        (1920, 960, 67),
        (1000, 300, 62),
    ];
    let last = |v: &[TNote]| v.iter().map(TNote::end).max().unwrap();
    for (target, extra) in [
        (4000u64, vec![ch("n08.target", 1), int("n08.tick", 4000)]),
        (3000, vec![ch("n08.target", 1), int("n08.tick", 3000)]),
        (3840, vec![ch("n08.target", 2)]),
        (
            5000,
            vec![
                ch("n08.target", 1),
                int("n08.tick", 5000),
                int("g.pos_x", 100),
                fl("g.scale_x", 80.0),
            ],
        ),
        (
            4500,
            vec![
                ch("n08.target", 1),
                int("n08.tick", 4500),
                fl("amount", -20.0),
                fl("g.pivot_y", 100.0),
            ],
        ),
        (
            3500,
            vec![
                ch("n08.target", 1),
                int("n08.tick", 3500),
                on("a2"),
                on("a3"),
            ],
        ),
    ] {
        let mut set = vec![on("n08")];
        set.extend(extra);
        let v = sk(&notes, &set);
        assert_eq!(last(&v), target, "{set:?}");
    }
    // The time selection's end.
    let mut ctx = Ctx::simple(960);
    ctx.time_range = Some((0, 4321));
    let v = skew_try(
        notes.iter().map(|&(s, d, p)| tn(s, d, p, 100)).collect(),
        1,
        &[on("n08"), ch("n08.target", 0)],
        Some(ctx),
    )
    .unwrap()
    .notes;
    assert_eq!(last(&v), 4321);
    // Through the tempo map (Real-time slope sets the direction).
    let v = skew_try(
        notes.iter().map(|&(s, d, p)| tn(s, d, p, 100)).collect(),
        1,
        &[
            on("n08"),
            ch("n08.target", 1),
            int("n08.tick", 3500),
            on("n06"),
        ],
        Some(qnt_stepped_tempo()),
    )
    .unwrap()
    .notes;
    assert!((last(&v) as i64 - 3500).abs() <= 1, "{}", last(&v));
    // Refusals: no time selection; a target the top note cannot come
    // back to; a pivot every note lies on.
    let err = |set: &[(&'static str, ParamValue)]| match skew_try(
        notes.iter().map(|&(s, d, p)| tn(s, d, p, 100)).collect(),
        1,
        set,
        None,
    ) {
        Err(plumspirit_engine::transform::TransformError::Invalid(m)) => m,
        other => panic!("{:?}", other.map(|r| r.notes.len())),
    };
    assert!(err(&[on("n08"), ch("n08.target", 0)]).contains("time selection"));
    assert!(err(&[on("n08"), ch("n08.target", 1), int("n08.tick", 100)]).contains("cannot reach"));
    assert!(err(&[on("n08"), fl("g.scale_x", -100.0)]).contains("Scale X"));
}

#[test]
fn skew_elastic_adds_a_damped_wobble_along_pitch() {
    for (o, d, s) in [(50.0, 40.0, 3i64), (150.0, 0.0, 1), (80.0, 100.0, 7)] {
        let v = sk(
            &skew_column(0),
            &[
                fl("amount", 100.0),
                fl("g.pivot_y", 0.0),
                on("n09"),
                fl("n09.overshoot", o),
                fl("n09.damping", d),
                int("n09.swings", s),
            ],
        );
        for i in 0..12u8 {
            let y = (f64::from(i) + 0.5) / 12.0;
            let h = y + o / 100.0
                * (-5.0 * d / 100.0 * y).exp()
                * (std::f64::consts::PI * s as f64 * y).sin();
            assert_eq!(
                at(&v, 60 + i).start,
                (h * 3840.0).round() as u64,
                "{o} {d} {s}: row {i}"
            );
        }
    }
}

#[test]
fn skew_track_stagger_offsets_each_track_by_its_rank() {
    let notes = vec![
        TNote {
            track: 0,
            ..tn(1000, 480, 70, 100)
        },
        TNote {
            track: 0,
            ..tn(1960, 480, 72, 100)
        },
        TNote {
            track: 1,
            ..tn(1000, 480, 50, 100)
        },
        TNote {
            track: 2,
            ..tn(1480, 480, 60, 100)
        },
        TNote {
            track: 2,
            ..tn(2440, 480, 58, 100)
        },
    ];
    for (order, rank) in [(0u32, [0i64, 1, 2]), (1, [2, 0, 1])] {
        for step in [240i64, -90] {
            let v = skew_run(
                notes.clone(),
                3,
                &[
                    fl("amount", 0.0),
                    on("n10"),
                    int("n10.shift", step),
                    ch("n10.order", order),
                ],
            )
            .notes;
            let mut got: Vec<(u16, u8, i64)> = v
                .iter()
                .map(|n| (n.track, n.pitch, n.start as i64))
                .collect();
            got.sort_unstable();
            let mut want: Vec<(u16, u8, i64)> = notes
                .iter()
                .map(|n| {
                    (
                        n.track,
                        n.pitch,
                        n.start as i64 + rank[usize::from(n.track)] * step,
                    )
                })
                .collect();
            want.sort_unstable();
            assert_eq!(got, want, "order {order}, step {step}");
        }
    }
}

#[test]
fn skew_mirror_copy_adds_the_opposite_skew_at_its_velocity_and_subchannel() {
    // From 3840, pivot in the middle, X skew 100 %: row i moves
    // (i + ½ − 6) · 320 ticks; the copy the other way.
    let v = sk(
        &skew_column(3840),
        &[
            fl("amount", 100.0),
            on("n11"),
            fl("n11.vel", 80.0),
            int("n11.sub", 1),
        ],
    );
    assert_eq!(v.len(), 24);
    for i in 0..12u8 {
        let d = (f64::from(i) + 0.5 - 6.0) * 320.0;
        let mut row: Vec<(u64, u8, u32, u8)> = v
            .iter()
            .filter(|n| n.pitch == 60 + i)
            .map(|n| (n.start, n.vel, n.sub, n.ch))
            .collect();
        row.sort_unstable();
        let mut want = vec![
            ((3840.0 + d).round() as u64, 100, 0, 0),
            ((3840.0 - d).round() as u64, 80, 1, 1),
        ];
        want.sort_unstable();
        assert_eq!(row, want, "row {i}");
    }
}

#[test]
fn skew_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11
        .iter()
        .map(|&f| on(f))
        .chain([ch("n08.target", 1), int("n08.tick", 40_000)])
        .collect();
    let a = skew_run(skew_fixture(), 3, &all);
    assert_eq!(a.notes, skew_run(skew_fixture(), 3, &all).notes);
    assert!(a.notes.len() <= 2 * skew_fixture().len());
    assert!(a.notes.len() > skew_fixture().len());
    for f in ALL11 {
        for extra in [
            vec![],
            vec![on("a1"), on("a2"), on("a6"), on("a7"), on("a9")],
            vec![
                on("a4"),
                on("a8"),
                on("a10"),
                on("a3"),
                on("g.fill"),
                ch("g.raster", 2),
            ],
            vec![on("a5"), ch("g.undefined", 1), on("n06")],
        ] {
            let mut set = vec![on(f), ch("n08.target", 1), int("n08.tick", 40_000)];
            set.extend(extra);
            let v = skew_try(skew_fixture(), 3, &set, None);
            let Ok(v) = v else {
                // Fit may refuse a direction no note can reach the target in.
                assert_eq!(f, "n08");
                continue;
            };
            assert_eq!(v.notes, skew_run(skew_fixture(), 3, &set).notes, "{f}");
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.ch <= 15 && n.dur >= 1),
                "{f}"
            );
        }
    }
    // A Control Sweep (note-level: each level segment is skewed with its
    // value).
    let sweep = [on("n01"), on("m.sweep"), on("m.sweep.stair")];
    let a = skew_run(skew_fixture(), 3, &sweep);
    assert_eq!(a.notes, skew_run(skew_fixture(), 3, &sweep).notes);
    assert_eq!(a.notes.len(), skew_fixture().len());
}

// ================================================================ Distort

/// Runs Distort on hand-built notes of `tracks` track slots (subchannels
/// 0 – 3), checking the preflight bound.
fn distort_try(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
    ctx: Option<Ctx>,
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, (0..tracks).map(tr).collect());
    let t = tool("distort").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate(&src.stats).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

fn distort_run(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    distort_try(notes, tracks, set, None).unwrap()
}

