/// The selection box of `v`: start, width, lowest row, rows.
fn dbox(v: &[TNote]) -> (f64, f64, f64, f64) {
    let t0 = v.iter().map(|n| n.start).min().unwrap();
    let t1 = v.iter().map(TNote::end).max().unwrap();
    let p0 = v.iter().map(|n| n.pitch).min().unwrap();
    let p1 = v.iter().map(|n| n.pitch).max().unwrap();
    (
        t0 as f64,
        (t1 - t0) as f64,
        f64::from(p0),
        f64::from(p1 - p0) + 1.0,
    )
}

/// What the geometry raster (Sample the middle, no shared scale / position)
/// makes of note `n` under the unit-space map `f` of box `b`: (start, end,
/// pitch).
fn raster_mid(
    b: (f64, f64, f64, f64),
    n: &TNote,
    f: &dyn Fn(f64, f64) -> (f64, f64),
) -> (i64, i64, i64) {
    let (t0, w, p0, rows): (f64, f64, f64, f64) = b;
    let v = (f64::from(n.pitch) + 0.5 - p0) / rows;
    let us = (n.start as f64 - t0) / w;
    let ue = (n.end() as f64 - t0) / w;
    let a = t0 + f(us, v).0 * w;
    let e = t0 + f(ue, v).0 * w;
    let row = (p0 + f((us + ue) / 2.0, v).1 * rows).floor() as i64;
    let (s, e) = (a.min(e).round() as i64, a.max(e).round() as i64);
    (s, e.max(s + 1), row)
}

fn distort_expect(
    notes: &[TNote],
    f: &dyn Fn(&TNote, f64, f64) -> (f64, f64),
) -> Vec<(i64, i64, i64)> {
    let b = dbox(notes);
    let mut v: Vec<(i64, i64, i64)> = notes
        .iter()
        .map(|n| raster_mid(b, n, &|u, w| f(n, u, w)))
        .collect();
    v.sort_unstable();
    v
}

fn dsep(v: &[TNote]) -> Vec<(i64, i64, i64)> {
    let mut o: Vec<(i64, i64, i64)> = v
        .iter()
        .map(|n| (n.start as i64, n.end() as i64, i64::from(n.pitch)))
        .collect();
    o.sort_unstable();
    o
}

/// A 16 × 12 grid of 120-tick notes every 240 ticks from bar 1 on rows
/// 60 – 71 (box 3,840 – 7,560: 3,720 × 12).
fn distort_grid() -> Vec<TNote> {
    let mut v = Vec::new();
    for i in 0..16u64 {
        for p in 60..72u8 {
            if (i + u64::from(p)) % 3 == 0 {
                v.push(tn(3840 + i * 240, 120, p, 100));
            }
        }
    }
    v
}

fn dset(extra: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut s = vec![fl("amount", 0.0)];
    s.extend(extra.iter().cloned());
    s
}

#[test]
fn distort_axis_lens_magnifies_a_band_and_compresses_the_rest() {
    let notes = distort_grid();
    for (axis, focus, width, mag) in [
        (0u32, 50.0, 20.0, 200.0),
        (0, 20.0, 30.0, 50.0),
        (1, 70.0, 40.0, 300.0),
        (1, 50.0, 100.0, 800.0),
    ] {
        let lens = |x: f64| -> f64 {
            let (f, w, m): (f64, f64, f64) = (focus / 100.0, width / 100.0, mag / 100.0);
            let (a, b) = ((f - w / 2.0).max(0.0), (f + w / 2.0).min(1.0));
            let (a2, b2) = ((f - m * (f - a)).max(0.0), (f + m * (b - f)).min(1.0));
            if x < a {
                x * a2 / a
            } else if x <= b {
                a2 + (x - a) * (b2 - a2) / (b - a)
            } else {
                b2 + (x - b) * (1.0 - b2) / (1.0 - b)
            }
        };
        let got = distort_run(
            notes.clone(),
            1,
            &dset(&[
                on("n01"),
                ch("n01.axis", axis),
                fl("n01.focus", focus),
                fl("n01.width", width),
                fl("n01.mag", mag),
            ]),
        )
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            if axis == 0 {
                (lens(u), v)
            } else {
                (u, lens(v))
            }
        });
        assert_eq!(dsep(&got), want, "axis {axis}, focus {focus}");
    }
}

/// The v0.8 bulge of `amount` around the box centre (`distort_build`).
fn bulge(amount: f64, u: f64, v: f64) -> (f64, f64) {
    let (dx, dy) = (u - 0.5, v - 0.5);
    let r = (dx * dx + dy * dy).sqrt();
    let f = amount * (1.0 - (r / 0.75).min(1.0)).powi(2);
    (u + dx * f, v + dy * f)
}

#[test]
fn distort_block_mosaic_moves_each_note_by_its_block_centres_motion() {
    // Blocks 1/4 (960) × 4 rows from the box's lowest row; the v0.8 bulge
    // of 80 % sampled at each block's centre moves its notes whole.
    let notes = distort_grid();
    let (t0, w, p0, rows) = dbox(&notes);
    let got = distort_run(
        notes.clone(),
        1,
        &[
            fl("amount", 80.0),
            on("n02"),
            ch("n02.width", 2),
            int("n02.rows", 4),
        ],
    )
    .notes;
    let want = distort_expect(&notes, &|n, u, v| {
        let ct = (n.start / 960 * 960) as f64 + 480.0;
        let cp = (60 + (i64::from(n.pitch) - 60).div_euclid(4) * 4) as f64 + 2.0;
        let (cu, cv) = ((ct - t0) / w, (cp - p0) / rows);
        let (mu, mv) = bulge(0.8, cu, cv);
        (u + mu - cu, v + mv - cv)
    });
    assert_eq!(dsep(&got), want);
    // Lengths stay (± the rounding of both ends).
    assert!(got.iter().all(|n| n.dur.abs_diff(120) <= 1));
}

#[test]
fn distort_region_mask_limits_the_distortion_to_a_feathered_region() {
    let notes = distort_grid();
    for (shape, feather) in [(0u32, 0.0), (1, 0.0), (0, 60.0), (1, 40.0)] {
        let got = distort_run(
            notes.clone(),
            1,
            &[
                fl("amount", 90.0),
                on("n03"),
                ch("n03.shape", shape),
                fl("n03.x", 35.0),
                fl("n03.y", 40.0),
                fl("n03.size", 50.0),
                fl("n03.feather", feather),
            ],
        )
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let (dx, dy) = ((u - 0.35) / 0.25, (v - 0.4) / 0.25);
            let rho = if shape == 1 {
                dx.abs().max(dy.abs())
            } else {
                (dx * dx + dy * dy).sqrt()
            };
            let f = feather / 100.0;
            let m = if rho <= 1.0 - f {
                1.0
            } else if rho >= 1.0 {
                0.0
            } else {
                let x = ((rho - (1.0 - f)) / f).clamp(0.0, 1.0);
                1.0 - x * x * (3.0 - 2.0 * x)
            };
            let (u2, v2) = bulge(0.9, u, v);
            if m < 1.0 {
                (u + m * (u2 - u), v + m * (v2 - v))
            } else {
                (u2, v2)
            }
        });
        assert_eq!(dsep(&got), want, "shape {shape}, feather {feather}");
        // Notes far outside never move.
        let far: Vec<&TNote> = notes.iter().filter(|n| n.start >= 6840).collect();
        for n in far {
            assert!(
                got.iter()
                    .any(|g| (g.start, g.pitch, g.dur) == (n.start, n.pitch, n.dur))
            );
        }
    }
}

#[test]
fn distort_gravity_sag_bows_rows_between_supports() {
    let notes = distort_grid();
    let para = |t: f64| 4.0 * t * (1.0 - t);
    let cat = |t: f64| {
        let c = 2f64.cosh();
        (c - (2.0 * (2.0 * t - 1.0)).cosh()) / (c - 1.0)
    };
    let over_p = |t: f64| t * t;
    let over_c = |t: f64| ((2.0 * t).cosh() - 1.0) / (2f64.cosh() - 1.0);
    for (sag, supports, shape) in [
        (6i64, 0u32, 0u32),
        (-9, 0, 1),
        (5, 1, 0),
        (7, 1, 1),
        (4, 2, 0),
    ] {
        let got = distort_run(
            notes.clone(),
            1,
            &dset(&[
                on("n04"),
                int("n04.sag", sag),
                ch("n04.supports", supports),
                list("n04.points", &[250, 750]),
                ch("n04.shape", shape),
            ]),
        )
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let span = |t: f64| if shape == 0 { para(t) } else { cat(t) };
            let over = |t: f64| if shape == 0 { over_p(t) } else { over_c(t) };
            let s = match supports {
                0 => span(u),
                1 => over((u - 0.5).abs() / 0.5),
                _ => {
                    if u < 0.25 {
                        over((0.25 - u) / 0.25)
                    } else if u > 0.75 {
                        over((u - 0.75) / 0.25)
                    } else {
                        span((u - 0.25) / 0.5)
                    }
                }
            };
            (u, v - sag as f64 * s / 12.0)
        });
        assert_eq!(
            dsep(&got),
            want,
            "sag {sag}, supports {supports}, shape {shape}"
        );
    }
}

#[test]
fn distort_tiles_repeat_the_distortion_per_bar_beats_or_chord() {
    // The same 8-note pattern in bars 1 – 4: tiled per bar or per beats,
    // the result is bar 1's alone, repeated bar by bar.
    let pattern = [
        (0u64, 60u8),
        (480, 64),
        (960, 67),
        (1440, 72),
        (1920, 71),
        (2400, 67),
        (2880, 64),
        (3360, 62),
    ];
    let bars = |from: u64, to: u64| -> Vec<TNote> {
        (from..to)
            .flat_map(|bar| pattern.map(|(t, p)| tn(bar * 3840 + t, 240, p, 100)))
            .collect()
    };
    for (tile, beats) in [(0u32, 4i64), (1, 4), (1, 2)] {
        let set = [
            fl("amount", 80.0),
            on("a5"),
            on("n05"),
            ch("n05.tile", tile),
            int("n05.beats", beats),
        ];
        let got = dsep(&distort_run(bars(1, 5), 1, &set).notes);
        let one = dsep(&distort_run(bars(1, 2), 1, &set).notes);
        let mut want: Vec<(i64, i64, i64)> = (0..4i64)
            .flat_map(|k| {
                one.iter()
                    .map(move |x| (x.0 + k * 3840, x.1 + k * 3840, x.2))
            })
            .collect();
        want.sort_unstable();
        assert_eq!(got, want, "tile {tile}×{beats}");
        assert!(one != dsep(&bars(1, 2)), "the tile is distorted");
    }
    // Chords: each chord bulges inside its own box.
    let chord = |t: u64| [60u8, 64, 67, 71].map(|p| tn(t, 960, p, 100)).to_vec();
    let set = [fl("amount", 80.0), on("n05"), ch("n05.tile", 2)];
    let both: Vec<TNote> = chord(3840).into_iter().chain(chord(11520)).collect();
    let got = dsep(&distort_run(both, 1, &set).notes);
    let mut want = dsep(&distort_run(chord(3840), 1, &set).notes);
    want.extend(dsep(&distort_run(chord(11520), 1, &set).notes));
    want.sort_unstable();
    assert_eq!(got, want);
}

#[test]
fn distort_line_attractor_pulls_rows_toward_the_line() {
    let notes = distort_grid();
    for (s, falloff) in [(50.0, 25.0), (100.0, 60.0), (-40.0, 10.0)] {
        let got = distort_run(
            notes.clone(),
            1,
            &dset(&[on("n06"), fl("n06.strength", s), fl("n06.falloff", falloff)]),
        )
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let y = 0.2 + 0.6 * u;
            let d = (v - y) / (falloff / 100.0);
            (u, v + s / 100.0 * (-d * d).exp() * (y - v))
        });
        assert_eq!(dsep(&got), want, "strength {s}");
    }
}

#[test]
fn distort_taper_squeezes_the_pitch_extent_along_time() {
    let notes = distort_grid();
    for (ts, te) in [(0.0, 80.0), (100.0, 0.0), (50.0, 100.0)] {
        let got = distort_run(
            notes.clone(),
            1,
            &dset(&[on("n07"), fl("n07.start", ts), fl("n07.end", te)]),
        )
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let t = ts / 100.0 + (te - ts) / 100.0 * u.clamp(0.0, 1.0);
            (u, 0.5 + (v - 0.5) * (1.0 - t))
        });
        assert_eq!(dsep(&got), want, "{ts} → {te}");
    }
}

#[test]
fn distort_shatter_moves_seeded_shards_outward() {
    use plumspirit_engine::transform::shared::seeded_stream::{salt_of, stream};
    let notes = distort_grid();
    let b = dbox(&notes);
    for (shards, e, step) in [(8i64, 40.0, 0i64), (8, 80.0, 1), (100, 150.0, -3)] {
        // The shard seeds (n08's own stream) and each note's nearest one
        // (by its centre); the shard moves by explosion × (seed − pivot).
        // Numbered in x order (the shard's subchannel step).
        let mut seeds: Vec<(f64, f64)> = (0..shards as u64)
            .map(|k| {
                let mut r = stream(0, salt_of("distort.n08"), &[k]);
                (r.unit(), r.unit())
            })
            .collect();
        seeds.sort_by(|a, b| a.0.total_cmp(&b.0));
        let shard = |n: &TNote| {
            let cu = ((n.start as f64 + n.end() as f64) / 2.0 - b.0) / b.1;
            let cv = (f64::from(n.pitch) + 0.5 - b.2) / b.3;
            let mut best = (f64::INFINITY, 0usize);
            for (j, s) in seeds.iter().enumerate() {
                let d = (s.0 - cu).powi(2) + (s.1 - cv).powi(2);
                if d < best.0 {
                    best = (d, j);
                }
            }
            best.1
        };
        let got = distort_run(
            notes.clone(),
            1,
            &dset(&[
                on("n08"),
                int("n08.shards", shards),
                fl("n08.explosion", e),
                int("n08.sub", step),
            ]),
        )
        .notes;
        let want = distort_expect(&notes, &|n, u, v| {
            let s = seeds[shard(n)];
            (u + e / 100.0 * (s.0 - 0.5), v + e / 100.0 * (s.1 - 0.5))
        });
        assert_eq!(dsep(&got), want, "{shards} shards at {e} %");
        // Subchannel: the shard index × the step positions (table of 4).
        let mut subs: Vec<(i64, i64, u32)> = got
            .iter()
            .map(|n| (n.start as i64, i64::from(n.pitch), n.sub))
            .collect();
        subs.sort_unstable();
        let mut want_subs: Vec<(i64, i64, u32)> = notes
            .iter()
            .map(|n| {
                let r = raster_mid(b, n, &|u, v| {
                    let s = seeds[shard(n)];
                    (u + e / 100.0 * (s.0 - 0.5), v + e / 100.0 * (s.1 - 0.5))
                });
                (r.0, r.2, (shard(n) as i64 * step).rem_euclid(4) as u32)
            })
            .collect();
        want_subs.sort_unstable();
        assert_eq!(subs, want_subs, "{shards} shards, step {step}");
    }
}

#[test]
fn distort_arc_bend_wraps_the_box_onto_an_arc() {
    let notes = distort_grid();
    for (deg, keep) in [(90.0, 0u32), (-120.0, 0), (180.0, 1), (45.0, 1)] {
        let got = distort_run(
            notes.clone(),
            1,
            &dset(&[on("n09"), fl("n09.angle", deg), ch("n09.keep", keep)]),
        )
        .notes;
        let th: f64 = deg * std::f64::consts::PI / 180.0;
        let r = if keep == 1 {
            1.0 / (2.0 * (th.abs() / 2.0).sin())
        } else {
            1.0 / th.abs()
        };
        let want = distort_expect(&notes, &|_, u, v| {
            let s = th.signum();
            let phi = th.abs() * (u - 0.5);
            let rho = r + s * (v - 0.5);
            (0.5 + rho * phi.sin(), 0.5 - s * r + s * rho * phi.cos())
        });
        assert_eq!(dsep(&got), want, "{deg}°, keep {keep}");
    }
}

#[test]
fn distort_pixel_sort_orders_values_along_each_row() {
    // Row 60: velocities 90 30 60 | gap | 20 80; row 62: 50 40.
    let notes = vec![
        tn(0, 100, 60, 90),
        tn(120, 300, 60, 30),
        tn(480, 50, 60, 60),
        tn(4000, 70, 60, 20),
        tn(4100, 200, 60, 80),
        tn(0, 100, 62, 50),
        tn(200, 100, 62, 40),
    ];
    let vel_row = |v: &[TNote], p: u8| {
        let mut o: Vec<(u64, u8)> = v
            .iter()
            .filter(|n| n.pitch == p)
            .map(|n| (n.start, n.vel))
            .collect();
        o.sort_unstable();
        o.into_iter().map(|x| x.1).collect::<Vec<_>>()
    };
    let r = distort_run(notes.clone(), 1, &dset(&[on("n10")])).notes;
    assert_eq!(vel_row(&r, 60), vec![20, 30, 60, 80, 90]);
    assert_eq!(vel_row(&r, 62), vec![40, 50]);
    assert_eq!(
        dsep(&r).iter().map(|x| (x.0, x.2)).collect::<Vec<_>>(),
        dsep(&notes).iter().map(|x| (x.0, x.2)).collect::<Vec<_>>()
    );
    let r = distort_run(
        notes.clone(),
        1,
        &dset(&[
            on("n10"),
            ch("n10.dir", 1),
            ch("n10.within", 1),
            int("n10.gap", 500),
        ]),
    )
    .notes;
    assert_eq!(vel_row(&r, 60), vec![90, 60, 30, 80, 20]);
    // Lengths: starts stay, lengths sorted within the row.
    let r = distort_run(notes.clone(), 1, &dset(&[on("n10"), ch("n10.by", 1)])).notes;
    let mut row: Vec<(u64, u64)> = r
        .iter()
        .filter(|n| n.pitch == 60)
        .map(|n| (n.start, n.dur))
        .collect();
    row.sort_unstable();
    assert_eq!(
        row,
        vec![(0, 50), (120, 70), (480, 100), (4000, 200), (4100, 300)]
    );
    // Subchannels with their channels, by their place in the table.
    let subs = vec![
        TNote {
            sub: 3,
            ch: 3,
            ..tn(0, 100, 60, 90)
        },
        TNote {
            sub: 1,
            ch: 1,
            ..tn(200, 100, 60, 90)
        },
        TNote {
            sub: 2,
            ch: 2,
            ..tn(400, 100, 60, 90)
        },
    ];
    let r = distort_run(subs, 1, &dset(&[on("n10"), ch("n10.by", 2)])).notes;
    let mut row: Vec<(u64, u32, u8)> = r.iter().map(|n| (n.start, n.sub, n.ch)).collect();
    row.sort_unstable();
    assert_eq!(row, vec![(0, 1, 1), (200, 2, 2), (400, 3, 3)]);
}

#[test]
fn distort_quadrant_shuffle_moves_whole_notes_between_quadrants() {
    let notes = distort_grid();
    for (mode, sx, sy) in [(0u32, 50.0, 50.0), (1, 30.0, 60.0), (2, 40.0, 50.0)] {
        let got = distort_run(
            notes.clone(),
            1,
            &dset(&[
                on("n11"),
                ch("n11.mode", mode),
                fl("n11.x", sx),
                fl("n11.y", sy),
            ]),
        )
        .notes;
        let (sx, sy) = (sx / 100.0, sy / 100.0);
        let quad = |k: usize| {
            let (x0, x1) = if k & 1 == 0 { (0.0, sx) } else { (sx, 1.0) };
            let (y0, y1) = if k & 2 == 0 { (0.0, sy) } else { (sy, 1.0) };
            (x0, x1, y0, y1)
        };
        let b = dbox(&notes);
        let want = distort_expect(&notes, &|n, u, v| {
            let cu = ((n.start as f64 + n.end() as f64) / 2.0 - b.0) / b.1;
            let cv = (f64::from(n.pitch) + 0.5 - b.2) / b.3;
            let k = usize::from(cu >= sx) | usize::from(cv >= sy) << 1;
            let to = match mode {
                0 => 3 - k,
                1 => [2, 0, 3, 1][k],
                _ => k ^ 1,
            };
            let (a0, a1, c0, c1) = quad(k);
            let (t0, t1, d0, d1) = quad(to);
            let u2 = if mode == 2 {
                t0 + (a1 - u) * (t1 - t0) / (a1 - a0)
            } else {
                t0 + (u - a0) * (t1 - t0) / (a1 - a0)
            };
            (u2, d0 + (v - c0) * (d1 - d0) / (c1 - c0))
        });
        assert_eq!(dsep(&got), want, "mode {mode}");
    }
}

#[test]
fn distort_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&f| on(f)).collect();
    let a = distort_run(skew_fixture(), 3, &all);
    assert_eq!(a.notes, distort_run(skew_fixture(), 3, &all).notes);
    assert!(a.notes.len() <= skew_fixture().len());
    for f in ALL11 {
        for extra in [
            vec![],
            vec![on("a1"), on("a2"), on("a5"), on("a8"), on("a10")],
            vec![
                on("a3"),
                on("a4"),
                on("a6"),
                on("a7"),
                on("a9"),
                on("g.fill"),
                ch("g.raster", 2),
            ],
            vec![ch("g.undefined", 2), ch("n05.tile", 2), ch("n10.within", 1)],
        ] {
            let mut set = vec![on(f)];
            set.extend(extra);
            let v = distort_run(skew_fixture(), 3, &set);
            assert_eq!(v.notes, distort_run(skew_fixture(), 3, &set).notes, "{f}");
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.ch <= 15 && n.dur >= 1),
                "{f}"
            );
        }
    }
    let sweep = [on("n04"), on("m.sweep"), on("m.sweep.sag")];
    let a = distort_run(skew_fixture(), 3, &sweep);
    assert_eq!(a.notes, distort_run(skew_fixture(), 3, &sweep).notes);
    assert_eq!(a.notes.len(), skew_fixture().len());
}

// ================================================================ Perspective

/// Runs Perspective on hand-built notes of `tracks` track slots
/// (subchannels 0 – 3), checking the preflight bound.
fn persp_try(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
    ctx: Option<Ctx>,
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, (0..tracks).map(tr).collect());
    let t = tool("perspective").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = ctx.unwrap_or_else(|| Ctx::simple(960));
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate(&src.stats).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

fn persp_run(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    persp_try(notes, tracks, set, None).unwrap()
}

