/// Neutral settings: fog of 100 % both ends, keeping every far note,
/// rectifying the unit square, no curvature, no blur — each alone, then
/// together.
fn persp_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n01",
            vec![on("n01"), fl("n01.near", 100.0), fl("n01.far", 100.0)],
        ),
        ("n03", vec![on("n03"), fl("n03.keep", 100.0)]),
        (
            "n06",
            vec![
                on("n06"),
                ch("n06.from", 1),
                list("n06.corners", &[0, 0, 1000, 0, 1000, 1000, 0, 1000]),
            ],
        ),
        ("n07", vec![on("n07"), fl("n07.curvature", 0.0)]),
        (
            "n11",
            vec![on("n11"), int("n11.time", 0), int("n11.rows", 0)],
        ),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn persp_neutral_new_functions_equal_the_v08_results() {
    for (name, extra) in persp_neutral() {
        for (i, s) in persp_v08_settings().iter().enumerate() {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            let r = persp_run(skew_fixture(), 3, &set);
            assert_eq!(join_fingerprint(&r), PERSP_V08[i], "{name}, setting {i}");
        }
    }
}

/// The default projection (top edge 50 %): the homography of the unit box
/// onto the trapezoid (0, 0) (1, 0) (¾, 1) (¼, 1).
fn h50(u: f64, v: f64) -> (f64, f64) {
    ((u + 0.5 * v) / (1.0 + v), 2.0 * v / (1.0 + v))
}

/// A note's centre row in its box (its depth under [`h50`]).
fn depth50(b: (f64, f64, f64, f64), n: &TNote) -> f64 {
    (f64::from(n.pitch) + 0.5 - b.2) / b.3
}

/// (start, end, pitch, velocity, subchannel), sorted.
fn psv(v: &[TNote]) -> Vec<(i64, i64, i64, u8, u32)> {
    let mut o: Vec<(i64, i64, i64, u8, u32)> = v
        .iter()
        .map(|n| {
            (
                n.start as i64,
                n.end() as i64,
                i64::from(n.pitch),
                n.vel,
                n.sub,
            )
        })
        .collect();
    o.sort_unstable();
    o
}

fn pexp(
    b: (f64, f64, f64, f64),
    n: &TNote,
    f: &dyn Fn(f64, f64) -> (f64, f64),
    vel: u8,
    sub: u32,
) -> (i64, i64, i64, u8, u32) {
    let (s, e, p) = raster_mid(b, n, f);
    (s, e, p, vel, sub)
}

#[test]
fn persp_depth_fog_and_bands_follow_the_projected_depth() {
    let notes = distort_grid();
    let b = dbox(&notes);
    let got = persp_run(
        notes.clone(),
        1,
        &[
            on("n01"),
            fl("n01.near", 120.0),
            fl("n01.far", 20.0),
            on("n02"),
            int("n02.bands", 3),
            list("n02.palette", &[2, 0, 5]),
        ],
    )
    .notes;
    let mut want: Vec<(i64, i64, i64, u8, u32)> = notes
        .iter()
        .map(|n| {
            let d = depth50(b, n);
            let vel = (100.0 * (1.2 + (0.2 - 1.2) * d)).round() as u8;
            let band = ((d * 3.0) as usize).min(2);
            let sub = [2u32, 0, 5][band] % 4;
            pexp(b, n, &h50, vel, sub)
        })
        .collect();
    want.sort_unstable();
    assert_eq!(psv(&got), want);
}

#[test]
fn persp_depth_thinning_keeps_near_notes_and_a_share_of_far_ones() {
    use plumspirit_engine::transform::rng::note_key;
    use plumspirit_engine::transform::shared::seeded_stream::{salt_of, stream};
    let notes = distort_grid();
    let b = dbox(&notes);
    for keep in [0.0, 25.0, 70.0] {
        let got = persp_run(notes.clone(), 1, &[on("n03"), fl("n03.keep", keep)]).notes;
        let mut want: Vec<(i64, i64, i64, u8, u32)> = notes
            .iter()
            .filter(|n| {
                let d = depth50(b, n);
                let p = 1.0 - (1.0 - keep / 100.0) * d;
                stream(0, salt_of("perspective.n03"), &[note_key(n), 0]).unit() < p
            })
            .map(|n| pexp(b, n, &h50, 100, 0))
            .collect();
        want.sort_unstable();
        assert_eq!(psv(&got), want, "keep {keep}");
        assert!(got.len() < notes.len() && !got.is_empty());
    }
}

#[test]
fn persp_floor_reflection_mirrors_across_the_projected_edge() {
    let notes = distort_grid();
    let b = dbox(&notes);
    for (side, gap, fade) in [(0u32, 2i64, 60.0), (1, 0, 0.0), (1, 5, 100.0)] {
        let got = persp_run(
            notes.clone(),
            1,
            &[
                on("n04"),
                ch("n04.side", side),
                int("n04.gap", gap),
                fl("n04.fade", fade),
            ],
        )
        .notes;
        // The mirror row: the projected bottom (v 0) or top (v 1) edge.
        let axis = if side == 0 { 0.0 } else { 1.0 };
        let g = gap as f64 / b.3 * if side == 0 { -1.0 } else { 1.0 };
        let mut want: Vec<(i64, i64, i64, u8, u32)> = Vec::new();
        for n in &notes {
            want.push(pexp(b, n, &h50, 100, 0));
            let cu = ((n.start as f64 + n.end() as f64) / 2.0 - b.0) / b.1;
            let (_, pv) = h50(cu, depth50(b, n));
            let vel = (100.0 * (1.0 - fade / 100.0 * (pv - axis).abs().min(1.0))).round() as u8;
            want.push(pexp(
                b,
                n,
                &|u, v| {
                    let (x, y) = h50(u, v);
                    (x, 2.0 * axis - y + g)
                },
                vel.max(1),
                0,
            ));
        }
        want.sort_unstable();
        assert_eq!(psv(&got), want, "side {side}");
    }
}

#[test]
fn persp_horizon_guides_draw_the_horizon_and_vanishing_lines_once() {
    let notes = distort_grid();
    let b = dbox(&notes);
    let set = [
        on("n05"),
        int("n05.lines", 4),
        int("n05.len", 240),
        int("n05.vel", 127),
    ];
    let got = persp_run(notes.clone(), 1, &set).notes;
    let guides: Vec<&TNote> = got.iter().filter(|n| n.vel == 127).collect();
    assert!(guides.iter().all(|n| n.dur == 240));
    // The horizon: the row of the vanishing point (v = 2 → 60 + 24 = 84),
    // a note every 240 ticks across the box.
    let mut horizon: Vec<u64> = guides
        .iter()
        .filter(|n| n.pitch == 84)
        .map(|n| n.start)
        .collect();
    horizon.sort_unstable();
    let steps = (b.1 / 240.0).ceil() as u64;
    let want: Vec<u64> = (0..=steps)
        .map(|k| ((b.0 + (k as f64 * 240.0).min(b.1)).round()) as u64)
        .collect();
    assert_eq!(horizon, want);
    // Four vanishing lines from the bottom edge (row 60) up to the top
    // edge's image (row 71), each converging toward the box's middle.
    let lines: Vec<&&TNote> = guides.iter().filter(|n| n.pitch != 84).collect();
    assert!(lines.iter().any(|n| n.pitch == 60) && lines.iter().any(|n| n.pitch == 71));
    for k in 0..4 {
        let u = (k as f64 + 0.5) / 4.0;
        for (v, row) in [(0.5 / 12.0, 60u8), (11.5 / 12.0, 71)] {
            let (x, y) = h50(u, v);
            let x = (b.0 + x * b.1).round() as u64;
            assert_eq!((b.2 + y * b.3).floor() as u8, row);
            assert!(
                lines.iter().any(|n| n.pitch == row && n.start == x),
                "line {k} row {row}"
            );
        }
    }
    // Drawn once even when a Control Sweep runs the kernel per level.
    let mut sweep = set.to_vec();
    sweep.extend([
        on("m.sweep"),
        on("m.sweep.focus"),
        on("n11"),
        int("n11.time", 0),
        int("n11.rows", 0),
    ]);
    let swept = persp_run(notes.clone(), 1, &sweep).notes;
    let mut a: Vec<(u64, u8)> = guides.iter().map(|n| (n.start, n.pitch)).collect();
    let mut c: Vec<(u64, u8)> = swept
        .iter()
        .filter(|n| n.vel == 127)
        .map(|n| (n.start, n.pitch))
        .collect();
    a.sort_unstable();
    c.sort_unstable();
    assert_eq!(a, c);
    // A parallel projection has no vanishing point: no guides.
    let flat = persp_run(
        notes.clone(),
        1,
        &[fl("top", 100.0), on("n05"), int("n05.vel", 127)],
    )
    .notes;
    assert!(flat.iter().all(|n| n.vel != 127));
    // Too many guide notes are refused before anything is drawn.
    let long = vec![tn(0, 2_000_000, 60, 100), tn(0, 10, 72, 100)];
    let set = [on("n05"), int("n05.len", 1), int("n05.lines", 32)];
    match persp_try(long, 1, &set, None) {
        Err(plumspirit_engine::transform::TransformError::TooLarge(m)) => {
            assert!(m.contains("Horizon guides"), "{m}")
        }
        other => panic!("{:?}", other.map(|r| r.notes.len())),
    }
}

#[test]
fn persp_rectify_takes_a_trapezoid_back_to_the_box() {
    // Listed corners equal to the default projection's trapezoid: the
    // projection undoes the rectification (notes stay, ± rounding).
    let notes = distort_grid();
    let got = persp_run(
        notes.clone(),
        1,
        &[
            on("n06"),
            ch("n06.from", 1),
            list("n06.corners", &[0, 0, 1000, 0, 750, 1000, 250, 1000]),
        ],
    )
    .notes;
    let mut g: Vec<(i64, u8)> = got.iter().map(|n| (n.start as i64, n.pitch)).collect();
    let mut w: Vec<(i64, u8)> = notes.iter().map(|n| (n.start as i64, n.pitch)).collect();
    g.sort_unstable();
    w.sort_unstable();
    assert_eq!(g.len(), w.len());
    for (a, c) in g.iter().zip(&w) {
        assert!((a.0 - c.0).abs() <= 1 && a.1 == c.1, "{a:?} vs {c:?}");
    }
    // The selection's box: art narrowing from rows 60 – 71 to 64 – 67 is
    // rectified to the full rows on both sides (Top 100 %: no projection).
    // The left quarter spans rows 60 – 71, the right quarter 64 – 67; the
    // last column's notes (velocities 110 / 111) land near the box's
    // bottom and top rows: 64 → ⌊60 + 12 · (4.5 − 4) / 4⌋ = 61, 67 → 70.
    let mut art = Vec::new();
    for i in 0..16u64 {
        let k = (i.saturating_sub(3) * 4 / 9).min(4) as u8;
        let (lo, hi) = (60 + k, 71 - k);
        let vel = if i == 15 { 110 } else { 100 };
        art.push(tn(3840 + i * 240, 120, lo, vel));
        art.push(tn(3840 + i * 240, 120, hi, vel + u8::from(i == 15)));
    }
    let got = persp_run(art, 1, &[fl("top", 100.0), on("n06")]).notes;
    let lo = got.iter().find(|n| n.vel == 110).unwrap().pitch;
    let hi = got.iter().find(|n| n.vel == 111).unwrap().pitch;
    assert_eq!((lo, hi), (61, 70));
}

#[test]
fn persp_curved_horizon_bends_rows_by_their_height() {
    let notes = distort_grid();
    let b = dbox(&notes);
    for c in [30.0, -60.0, 100.0] {
        let got = persp_run(notes.clone(), 1, &[on("n07"), fl("n07.curvature", c)]).notes;
        let mut want: Vec<(i64, i64, i64, u8, u32)> = notes
            .iter()
            .map(|n| {
                pexp(
                    b,
                    n,
                    &|u, v| {
                        let (x, y) = h50(u, v);
                        let k = 2.0 * x - 1.0;
                        (x, y - c / 100.0 * y * k * k)
                    },
                    100,
                    0,
                )
            })
            .collect();
        want.sort_unstable();
        assert_eq!(psv(&got), want, "curvature {c}");
    }
}

#[test]
fn persp_occlusion_leaves_no_overlap_on_a_key_and_only_clips() {
    // Echoes overlap the main projection on shared keys at other depths.
    let notes = distort_grid();
    let base = [on("a10"), int("a10.count", 2), fl("top", 60.0)];
    let open = persp_run(notes.clone(), 1, &base).notes;
    for (wins, key) in [(0u32, 0u32), (1, 0), (0, 1)] {
        let mut set = base.to_vec();
        set.extend([on("n08"), ch("n08.wins", wins), ch("n08.key", key)]);
        let got = persp_run(notes.clone(), 1, &set).notes;
        assert!(got.len() <= open.len());
        // No two notes overlap on one key.
        let mut by_key: std::collections::BTreeMap<(u8, u32), Vec<(u64, u64)>> = Default::default();
        for n in &got {
            by_key
                .entry((n.pitch, if key == 1 { n.sub } else { 0 }))
                .or_default()
                .push((n.start, n.end()));
        }
        for (k, mut v) in by_key {
            v.sort_unstable();
            for w in v.windows(2) {
                assert!(w[0].1 <= w[1].0, "{k:?}: {w:?}");
            }
        }
        // Every note is a part of a note of the open result on its key.
        for n in &got {
            assert!(
                open.iter()
                    .any(|o| o.pitch == n.pitch && o.start <= n.start && n.end() <= o.end()),
                "{n:?}"
            );
        }
    }
    let near = persp_run(notes.clone(), 1, &[base.to_vec(), vec![on("n08")]].concat()).notes;
    let far = persp_run(
        notes,
        1,
        &[base.to_vec(), vec![on("n08"), ch("n08.wins", 1)]].concat(),
    )
    .notes;
    assert_ne!(psv(&near), psv(&far));
}

#[test]
fn persp_stereo_pair_and_drop_shadow_add_offset_copies() {
    let notes = distort_grid();
    let b = dbox(&notes);
    // Stereo: the second eye shifted by separation × depth on subchannel 1.
    let got = persp_run(
        notes.clone(),
        1,
        &[on("n09"), int("n09.sep", 200), int("n09.sub", 1)],
    )
    .notes;
    let mut want: Vec<(i64, i64, i64, u8, u32)> = Vec::new();
    for n in &notes {
        want.push(pexp(b, n, &h50, 100, 0));
        let dt = (200.0 * depth50(b, n)).round() / b.1;
        want.push(pexp(
            b,
            n,
            &|u, v| {
                let (x, y) = h50(u, v);
                (x + dt, y)
            },
            100,
            1,
        ));
    }
    want.sort_unstable();
    assert_eq!(psv(&got), want);
    // Shadow: offset copies at 40 % on subchannel 2, clipped where art
    // notes of the key lie (each keeps its longest free part).
    let set = [
        on("n10"),
        int("n10.x", 90),
        int("n10.y", -1),
        fl("n10.vel", 40.0),
        int("n10.sub", 2),
    ];
    let got = persp_run(notes.clone(), 1, &set).notes;
    let art: Vec<(i64, i64, i64)> = notes.iter().map(|n| raster_mid(b, n, &h50)).collect();
    let mut want: Vec<(i64, i64, i64, u8, u32)> =
        art.iter().map(|a| (a.0, a.1, a.2, 100, 0)).collect();
    for n in &notes {
        let (s, e, p) = raster_mid(b, n, &|u, v| {
            let (x, y) = h50(u, v);
            (x + 90.0 / b.1, y - 1.0 / b.3)
        });
        // Free parts of [s, e) between art notes on row p.
        let mut cover: Vec<(i64, i64)> = art
            .iter()
            .filter(|a| a.2 == p)
            .map(|a| (a.0, a.1))
            .collect();
        cover.sort_unstable();
        let mut best: Option<(i64, i64)> = None;
        let mut at = s;
        for (a, c) in cover {
            if c <= at || a >= e {
                if a >= e {
                    break;
                }
                continue;
            }
            if a > at && best.is_none_or(|(x, y)| a.min(e) - at > y - x) {
                best = Some((at, a.min(e)));
            }
            at = at.max(c);
        }
        if e > at && best.is_none_or(|(x, y)| e - at > y - x) {
            best = Some((at, e));
        }
        if let Some((x, y)) = best {
            want.push((x, y, p, 40, 2));
        }
    }
    want.sort_unstable();
    assert_eq!(psv(&got), want);
}

#[test]
fn persp_depth_of_field_blurs_with_the_distance_from_the_focus() {
    use plumspirit_engine::transform::rng::note_key;
    use plumspirit_engine::transform::shared::seeded_stream::{salt_of, stream};
    let notes = distort_grid();
    let b = dbox(&notes);
    for (focus, bt, br) in [(0.0, 240i64, 2i64), (50.0, 960, 0), (100.0, 0, 6)] {
        let got = persp_run(
            notes.clone(),
            1,
            &[
                on("n11"),
                fl("n11.focus", focus),
                int("n11.time", bt),
                int("n11.rows", br),
            ],
        )
        .notes;
        let mut want: Vec<(i64, i64, i64, u8, u32)> = notes
            .iter()
            .map(|n| {
                let blur = (depth50(b, n) - focus / 100.0).abs();
                let mut r = stream(0, salt_of("perspective.n11"), &[note_key(n), 0]);
                let (a, c) = (r.unit(), r.unit());
                let du = (bt as f64 * blur * (2.0 * a - 1.0)).round() / b.1;
                let dv = (br as f64 * blur * (2.0 * c - 1.0)).round() / b.3;
                pexp(
                    b,
                    n,
                    &|u, v| {
                        let (x, y) = h50(u, v);
                        (x + du, y + dv)
                    },
                    100,
                    0,
                )
            })
            .collect();
        want.sort_unstable();
        assert_eq!(psv(&got), want, "focus {focus}");
    }
}

#[test]
fn persp_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&f| on(f)).collect();
    let a = persp_run(skew_fixture(), 3, &all);
    assert_eq!(a.notes, persp_run(skew_fixture(), 3, &all).notes);
    for f in ALL11 {
        for extra in [
            vec![],
            vec![on("a1"), on("a2"), on("a5"), on("a8"), on("a10")],
            vec![
                on("a3"),
                on("a4"),
                on("a6"),
                on("a7"),
                on("a9"),
                on("g.fill"),
                ch("g.raster", 2),
            ],
            vec![ch("g.undefined", 1), ch("n06.from", 1), ch("n04.side", 1)],
        ] {
            let mut set = vec![on(f)];
            set.extend(extra);
            let v = persp_run(skew_fixture(), 3, &set);
            assert_eq!(v.notes, persp_run(skew_fixture(), 3, &set).notes, "{f}");
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.ch <= 15 && n.dur >= 1),
                "{f}"
            );
        }
    }
    let sweep = [on("n10"), on("m.sweep"), on("m.sweep.shadow_x")];
    let a = persp_run(skew_fixture(), 3, &sweep);
    assert_eq!(a.notes, persp_run(skew_fixture(), 3, &sweep).notes);
}

// ================================================================ Warp

/// Runs Warp on hand-built notes of `tracks` track slots (subchannels
/// 0 – 3), checking the preflight bound.
fn warp_try(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
    aux: Option<Vec<TNote>>,
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(notes, (0..tracks).map(tr).collect());
    if let Some(a) = aux {
        src.aux = Arc::new(vec![a]);
    }
    let t = tool("warp").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate(&src.stats).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

fn warp_run(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    warp_try(notes, tracks, set, None).unwrap()
}

