/// Neutral settings: a contour of scale 0, lengths kept, no noise, the
/// axis below every note, a slope of scale 0, one tempo, a band over every
/// key, a pulse of 0 rows — each alone, then together.
fn shear_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n01", vec![on("n01"), fl("n01.scale", 0.0)]),
        ("n02", vec![on("n02"), ch("n02.mode", 0)]),
        ("n02 amount", vec![on("n02"), fl("n02.amount", 0.0)]),
        ("n03", vec![on("n03"), fl("n03.amp", 0.0)]),
        ("n04", vec![on("n04"), int("n04.axis", 0)]),
        ("n05", vec![on("n05"), fl("n05.scale", 0.0)]),
        ("n06", vec![on("n06")]),
        ("n07", vec![on("n07"), int("n07.lo", 0), int("n07.hi", 127)]),
        ("n08", vec![on("n08"), int("n08.amp", 0)]),
    ];
    let all: Vec<(&'static str, ParamValue)> = each
        .iter()
        .filter(|e| e.0 != "n02 amount")
        .flat_map(|e| e.1.clone())
        .collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn shear_neutral_new_functions_equal_the_v08_results() {
    for (name, extra) in shear_neutral() {
        for (i, s) in shear_v08_settings().iter().enumerate() {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            let r = shear_run(skew_fixture(), 3, &set);
            assert_eq!(join_fingerprint(&r), SHEAR_V08[i], "{name}, setting {i}");
        }
    }
}

/// Shear with a linear profile — row height v shifts by (v − ½) × 40 % of
/// the box width — plus `extra`.
fn lin40(extra: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut s = vec![curve("curve", Curve::line(0.0, 1.0)), fl("amount", 40.0)];
    s.extend(extra.iter().cloned());
    s
}

/// [`lin40`]'s map.
fn lin40_map(u: f64, v: f64) -> (f64, f64) {
    (u + (v.clamp(0.0, 1.0) - 0.5) * (40.0 / 100.0), v)
}

#[test]
fn shear_split_axis_shears_the_rows_below_the_axis_by_the_second_profile() {
    let notes = distort_grid();
    for (axis, amt) in [(66i64, -60.0), (0, -60.0), (72, 80.0), (63, 0.0)] {
        let got = shear_run(
            notes.clone(),
            1,
            &lin40(&[
                on("n04"),
                int("n04.axis", axis),
                curve("n04.curve", Curve::line(1.0, 0.0)),
                fl("n04.amount", amt),
            ]),
        )
        .notes;
        let want = distort_expect(&notes, &|n, u, v| {
            if i64::from(n.pitch) < axis {
                let x = v.clamp(0.0, 1.0);
                (u + ((1.0 - x) - 0.5) * (amt / 100.0), v)
            } else {
                lin40_map(u, v)
            }
        });
        assert_eq!(dsep(&got), want, "axis {axis}");
    }
}

#[test]
fn shear_noise_profile_adds_a_seeded_catmull_rom_curve() {
    use plumspirit_engine::transform::shared::seeded_stream::{salt_of, stream};
    let notes = distort_grid();
    for (rough, amp) in [(30.0, 50.0), (0.0, 100.0), (100.0, 25.0)] {
        let count = 2 + (rough / 100.0 * 62.0_f64).round() as usize;
        let nodes: Vec<f64> = (0..count)
            .map(|k| stream(0, salt_of("shear.n03"), &[k as u64]).unit() - 0.5)
            .collect();
        let got = shear_run(
            notes.clone(),
            1,
            &lin40(&[on("n03"), fl("n03.rough", rough), fl("n03.amp", amp)]),
        )
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let x = v.clamp(0.0, 1.0);
            let s = (x - 0.5) + (amp / 100.0) * catmull_ref(&nodes, x);
            (u + s * (40.0 / 100.0), v)
        });
        assert_eq!(dsep(&got), want, "roughness {rough}, amplitude {amp}");
        assert_ne!(
            dsep(&got),
            distort_expect(&notes, &|_, u, v| lin40_map(u, v))
        );
    }
}

#[test]
fn shear_slope_profile_is_the_integral_of_the_drawn_slope() {
    // Slope 0.2 → 0.8: g(t) = 2 (0.2 + 0.6 t − ½) = 1.2 t − 0.6, so the
    // profile is 0.6 x² − 0.6 x (exact under the trapezoids: g is linear).
    let notes = distort_grid();
    for (scale, base) in [(100.0, false), (-250.0, false), (50.0, true)] {
        let mut set = vec![
            on("n05"),
            curve("n05.curve", Curve::line(0.2, 0.8)),
            fl("n05.scale", scale),
        ];
        if !base {
            set.push(curve("curve", Curve::flat(0.5)));
            set.push(fl("amount", 40.0));
        }
        let set = if base { lin40(&set) } else { set };
        let got = shear_run(notes.clone(), 1, &set).notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let x = v.clamp(0.0, 1.0);
            let b0 = if base { x - 0.5 } else { 0.0 };
            let s = b0 + scale / 100.0 * (0.6 * x * x - 0.6 * x);
            (u + s * (40.0 / 100.0), v)
        });
        assert_eq!(dsep(&got), want, "scale {scale}");
    }
}

#[test]
fn shear_phrase_local_profile_bends_every_phrase_in_its_own_box() {
    // Phrase A: rows 60 – 63 every 240 ticks from 3,840 (box 3,840 – 4,680);
    // phrase B after a rest of 3,000: rows 70 – 75 from 7,680 (7,680 – 9,000).
    let mut notes: Vec<TNote> = (0..4)
        .map(|k| tn(3840 + 240 * k, 120, 60 + k as u8, 100))
        .collect();
    notes.extend((0..6).map(|k| tn(7680 + 240 * k, 120, 70 + k as u8, 100)));
    let shift = |n: &TNote, unit: (f64, f64, f64)| {
        // (width, lowest row, rows): the linear profile over the unit.
        let (w, lo, rows) = unit;
        let x = (f64::from(n.pitch) + 0.5 - lo) / rows;
        (x - 0.5) * 0.4 * w
    };
    let want = |units: &dyn Fn(&TNote) -> (f64, f64, f64)| {
        let mut v: Vec<(i64, i64, i64)> = notes
            .iter()
            .map(|n| {
                let d = shift(n, units(n));
                (
                    (n.start as f64 + d).round() as i64,
                    (n.end() as f64 + d).round() as i64,
                    i64::from(n.pitch),
                )
            })
            .collect();
        v.sort_unstable();
        v
    };
    let got = shear_run(notes.clone(), 1, &lin40(&[on("n10")])).notes;
    assert_eq!(
        dsep(&got),
        want(&|n| if n.pitch < 70 {
            (840.0, 60.0, 4.0)
        } else {
            (1320.0, 70.0, 6.0)
        })
    );
    // A fixed period of 1,920 from the box's start: windows 0 and 2.
    let got = shear_run(
        notes.clone(),
        1,
        &lin40(&[on("n10"), ch("n10.stretch", 1), int("n10.period", 1920)]),
    )
    .notes;
    assert_eq!(
        dsep(&got),
        want(&|n| if n.pitch < 70 {
            (1920.0, 60.0, 4.0)
        } else {
            (1920.0, 70.0, 6.0)
        })
    );
    // Phrases per track: the same notes on two tracks split by pitch.
    let mut two = notes.clone();
    for n in &mut two {
        n.track = u16::from(n.pitch >= 62 && n.pitch < 70);
    }
    let got = shear_run(two.clone(), 2, &lin40(&[on("n10")])).notes;
    let mut w: Vec<(i64, i64, i64)> = two
        .iter()
        .map(|n| {
            let unit = match (n.track, n.pitch < 70) {
                (1, _) => (360.0, 62.0, 2.0),
                (_, true) => (360.0, 60.0, 2.0),
                _ => (1320.0, 70.0, 6.0),
            };
            let d = shift(n, unit);
            (
                (n.start as f64 + d).round() as i64,
                (n.end() as f64 + d).round() as i64,
                i64::from(n.pitch),
            )
        })
        .collect();
    w.sort_unstable();
    assert_eq!(dsep(&got), w);
}

/// Per-column values at `u` (`geometry::col_at`).
fn col_ref(c: &[f64], u: f64) -> f64 {
    let n = c.len();
    let x = (u * n as f64 - 0.5).clamp(0.0, (n - 1) as f64);
    let i = (x.floor() as usize).min(n - 2);
    let t = x - i as f64;
    c[i] + (c[i + 1] - c[i]) * t
}

/// A two-step contour (`a` for the first 512 of 1,024 columns, then `b`)
/// moving-averaged over ±`r` columns, minus its mean.
fn contour_ref(a: f64, b: f64, r: usize) -> Vec<f64> {
    let raw: Vec<f64> = (0..1024).map(|i| if i < 512 { a } else { b }).collect();
    let mut pre = vec![0.0; 1025];
    for i in 0..1024 {
        pre[i + 1] = pre[i] + raw[i];
    }
    let sm: Vec<f64> = (0..1024usize)
        .map(|i| {
            let (s, e) = (i.saturating_sub(r), (i + r + 1).min(1024));
            (pre[e] - pre[s]) / (e - s) as f64
        })
        .collect();
    let mean = sm.iter().sum::<f64>() / 1024.0;
    sm.into_iter().map(|x| x - mean).collect()
}

#[test]
fn shear_contour_follow_rides_the_smoothed_melody_line() {
    // Box 3,840 – 7,560: a reference track at row 72, then 76 from the
    // middle (5,700 = column 512 of 1,024).
    let notes = distort_grid();
    let refs = vec![tn(3840, 1860, 72, 100), tn(5700, 1860, 76, 100)];
    for (smooth, scale) in [(0i64, 100.0), (3, 50.0), (64, -150.0)] {
        let cols = contour_ref(72.0, 76.0, smooth as usize);
        let got = shear_try(
            notes.clone(),
            1,
            &[
                fl("amount", 0.0),
                on("n01"),
                ch("n01.of", 2),
                int("n01.smooth", smooth),
                fl("n01.scale", scale),
            ],
            None,
            Some(vec![refs.clone(), Vec::new()]),
            None,
        )
        .unwrap()
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            (u, v + scale / 100.0 * col_ref(&cols, u) / 12.0)
        });
        assert_eq!(dsep(&got), want, "smoothing {smooth}, scale {scale}");
    }
    // The selection's own top and bottom: long notes 60 + 66, then 63 + 70.
    let sel = vec![
        tn(3840, 1860, 60, 100),
        tn(3840, 1860, 66, 100),
        tn(5700, 1860, 63, 100),
        tn(5700, 1860, 70, 100),
    ];
    for (of, a, b) in [(0u32, 66.0, 70.0), (1, 60.0, 63.0)] {
        let cols = contour_ref(a, b, 0);
        let got = shear_run(
            sel.clone(),
            1,
            &[
                fl("amount", 0.0),
                on("n01"),
                ch("n01.of", of),
                int("n01.smooth", 0),
            ],
        )
        .notes;
        let want = distort_expect(&sel, &|_, u, v| (u, v + col_ref(&cols, u) / 11.0));
        assert_eq!(dsep(&got), want, "contour {of}");
    }
    // No reference notes: no contour, nothing moves.
    let got = shear_run(
        notes.clone(),
        1,
        &[fl("amount", 0.0), on("n01"), ch("n01.of", 2)],
    )
    .notes;
    assert_eq!(dsep(&got), dsep(&notes));
}

#[test]
fn shear_tempo_profile_raises_the_art_with_the_tempo() {
    // 120 BPM, then 180 BPM from the middle of the box (5,700): columns
    // 0 – 511 at 120, 512 – 1,023 at 180 → 120 / mean − 1 = −0.2, +0.2
    // box heights at scale 100 %.
    let notes = distort_grid();
    let mut ctx = Ctx::simple(960);
    ctx.tempo = Some(Arc::new(TempoMap::from_tempos(
        TEMPO_RATE,
        960,
        &[
            (0, TempoValue::Micros(500_000)),
            (5700, TempoValue::Micros(333_333)),
        ],
    )));
    let fast = 60_000_000.0 / 333_333.0;
    let mean = (512.0 * 120.0 + 512.0 * fast) / 1024.0;
    let cols: Vec<f64> = (0..1024)
        .map(|i| if i < 512 { 120.0 } else { fast })
        .collect();
    for (scale, invert) in [(100.0, 0u32), (50.0, 1), (-200.0, 0)] {
        let got = shear_try(
            notes.clone(),
            1,
            &[
                fl("amount", 0.0),
                on("n06"),
                fl("n06.scale", scale),
                ch("n06.invert", invert),
            ],
            Some(ctx.clone()),
            None,
            None,
        )
        .unwrap()
        .notes;
        let sign = if invert == 1 { -1.0 } else { 1.0 };
        let tau: Vec<f64> = cols
            .iter()
            .map(|&x| sign * (scale / 100.0) * (x / mean - 1.0))
            .collect();
        let want = distort_expect(&notes, &|_, u, v| (u, v + col_ref(&tau, u)));
        assert_eq!(dsep(&got), want, "scale {scale}, invert {invert}");
        assert_ne!(dsep(&got), dsep(&notes));
    }
    // One tempo: nothing moves.
    let got = shear_run(notes.clone(), 1, &[fl("amount", 0.0), on("n06")]).notes;
    assert_eq!(dsep(&got), dsep(&notes));
}

#[test]
fn shear_band_limit_fades_the_shear_outside_the_keys() {
    let notes = distort_grid();
    for (lo, hi, feather) in [(63i64, 66i64, 2i64), (70, 64, 0), (0, 127, 5), (65, 65, 48)] {
        let got = shear_run(
            notes.clone(),
            1,
            &lin40(&[
                on("n07"),
                int("n07.lo", lo),
                int("n07.hi", hi),
                int("n07.feather", feather),
            ]),
        )
        .notes;
        let (a, z) = (lo.min(hi), lo.max(hi));
        let want = distort_expect(&notes, &|n, u, v| {
            let r = i64::from(n.pitch);
            let d = if r < a {
                a - r
            } else if r > z {
                r - z
            } else {
                0
            };
            let (u2, v2) = lin40_map(u, v);
            if d == 0 {
                (u2, v2)
            } else {
                let k = (1.0 - d as f64 / (feather as f64 + 1.0)).max(0.0);
                (u + (u2 - u) * k, v + (v2 - v) * k)
            }
        });
        assert_eq!(dsep(&got), want, "band {lo} – {hi}, feather {feather}");
    }
}

/// The onset pulse's row shift at tick `x`: `amp` × the default pulse
/// (1 → 0) over `decay` after the latest onset.
fn pulse_ref(onsets: &[u64], x: f64, amp: f64, decay: f64) -> f64 {
    match onsets.iter().rev().find(|&&o| o as f64 <= x) {
        Some(&o) if x - (o as f64) < decay => amp * (1.0 - (x - o as f64) / decay),
        _ => 0.0,
    }
}

#[test]
fn shear_onset_pulse_kicks_the_rows_after_each_reference_onset() {
    let notes = distort_grid();
    let b = dbox(&notes);
    // Unselected notes of the track (the context): onsets 3,800 and 5,700
    // (a note before the selection pulses into it).
    let ctx_notes = vec![
        tn(3800, 60, 50, 100),
        tn(5700, 30, 50, 100),
        tn(5700, 90, 51, 100),
    ];
    for (amp, decay) in [(6i64, 960i64), (-12, 1500), (48, 240)] {
        let got = shear_try(
            notes.clone(),
            1,
            &[
                fl("amount", 0.0),
                on("n08"),
                int("n08.amp", amp),
                int("n08.decay", decay),
            ],
            None,
            None,
            Some(ctx_notes.clone()),
        )
        .unwrap()
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let x = b.0 + u * b.1;
            (
                u,
                v + pulse_ref(&[3800, 5700], x, amp as f64, decay as f64) / 12.0,
            )
        });
        assert_eq!(dsep(&got), want, "amplitude {amp}, decay {decay}");
        assert_ne!(dsep(&got), dsep(&notes));
    }
    // A subchannel or a track: the reference layer (Source::aux 1).
    for choice in [1u32, 2] {
        let got = shear_try(
            notes.clone(),
            1,
            &[
                fl("amount", 0.0),
                on("n08"),
                ch("n08.ref", choice),
                int("n08.amp", 5),
            ],
            None,
            Some(vec![Vec::new(), vec![tn(4800, 10, 40, 100)]]),
            Some(ctx_notes.clone()),
        )
        .unwrap()
        .notes;
        let want = distort_expect(&notes, &|_, u, v| {
            let x = b.0 + u * b.1;
            (u, v + pulse_ref(&[4800], x, 5.0, 480.0) / 12.0)
        });
        assert_eq!(dsep(&got), want, "reference {choice}");
    }
}

#[test]
fn shear_references_come_from_tracks_subchannels_or_unselected_notes() {
    let mut d = PlumDocument::new_project("s37".into(), Bpm::DEFAULT, 960);
    d.add_track().unwrap();
    // Selected: 3,840 – 7,680 on rows 60 and 61.
    let sel = [rec(3840, 1920, 60), rec(5760, 1920, 61)];
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&sel, true)
        .unwrap();
    // Unselected on track 1 (onset 3,840 + 100) and track 2 (onset 5,760;
    // rows 72 then 76 for the contour).
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(3940, 100, 40)], false)
        .unwrap();
    d.track_mut(1)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(3840, 1920, 72), rec(5760, 1920, 76)], false)
        .unwrap();
    let def = tool("shear").unwrap();
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let run = |set: &[(&'static str, ParamValue)]| -> Result<Vec<TNote>, plumspirit_engine::transform::TransformError> {
        let mut ps = ParamSet::defaults(&(def.spec)().params);
        ps.set("amount", ParamValue::Float(0.0));
        for (k, v) in set {
            ps.set(k, v.clone());
        }
        let src = collect_with(def, &d, &sc, &ps, 1 << 24)?;
        let ctx = Ctx::simple(960);
        let b = BuildCtx { ctx: &ctx, stats: &src.stats, tracks: &src.tracks };
        let k = def.kernel(&ps, &b)?;
        Ok(run_kernel(k.as_ref(), &src, def.boundary(&ps), &Limits::default(), None)?.notes)
    };
    let rows = |v: Vec<TNote>| {
        let mut o: Vec<(u64, u8)> = v.iter().map(|n| (n.start, n.pitch)).collect();
        o.sort_unstable();
        o
    };
    // Track 2's contour 72 | 76 (mean 74): the rows move by −2 and +2
    // (each note's middle lies away from the middle column).
    let got = rows(
        run(&[
            on("n01"),
            ch("n01.of", 2),
            int("n01.track", 2),
            int("n01.smooth", 0),
        ])
        .unwrap(),
    );
    assert_eq!(got, vec![(3840, 58), (5760, 63)]);
    // Pulses of 8 rows over 960 ticks: the unselected note's onset (3,940)
    // lies 860 ticks before the first note's middle (4,800): 8 × (1 − 860 /
    // 960) = 0.83 rows (60.5 → 61.3); track 2's onsets 3,840 / 5,760 lie
    // 960 before both middles: no pulse left.
    let pulse = |choice: u32, num: i64| {
        rows(
            run(&[
                on("n08"),
                ch("n08.ref", choice),
                int("n08.num", num),
                int("n08.amp", 8),
                int("n08.decay", 960),
            ])
            .unwrap(),
        )
    };
    assert_eq!(pulse(0, 0), vec![(3840, 61), (5760, 61)]);
    // Subchannel 0 of the selected track: every note on it (the selected
    // ones too): onsets 3,840, 3,940, 5,760 — middles 4,800 / 6,720 lie
    // 860 after 3,940 and 960 after 5,760: +0.83 row, none.
    assert_eq!(pulse(1, 0), vec![(3840, 61), (5760, 61)]);
    assert_eq!(pulse(2, 2), vec![(3840, 60), (5760, 61)]);
    // Decay 2,000: track 2's onsets lift both middles by 8 × (1 − 960 /
    // 2,000) = 4.16 rows.
    let got = rows(
        run(&[
            on("n08"),
            ch("n08.ref", 2),
            int("n08.num", 2),
            int("n08.amp", 8),
            int("n08.decay", 2000),
        ])
        .unwrap(),
    );
    assert_eq!(got, vec![(3840, 64), (5760, 65)]);
    // A track that does not exist is refused with a sentence (both).
    for set in [
        vec![on("n01"), ch("n01.of", 2), int("n01.track", 9)],
        vec![on("n08"), ch("n08.ref", 2), int("n08.num", 9)],
    ] {
        let e = run(&set).unwrap_err();
        assert!(
            e.user_message().contains("Track 9 does not exist"),
            "{}",
            e.user_message()
        );
    }
}

#[test]
fn shear_slope_lengths_stretch_or_shrink_with_the_shift_between_rows() {
    let notes = distort_grid();
    let b = dbox(&notes);
    for (mode, amount) in [(1u32, 100.0), (2, 100.0), (1, 200.0), (2, 35.0)] {
        let got = shear_run(
            notes.clone(),
            1,
            &lin40(&[on("n02"), ch("n02.mode", mode), fl("n02.amount", amount)]),
        )
        .notes;
        let sign = if mode == 1 { 1.0 } else { -1.0 };
        let want = distort_expect(&notes, &|n, u, v| {
            let us = (n.start as f64 - b.0) / b.1;
            let ue = (n.end() as f64 - b.0) / b.1;
            let up = lin40_map(us, v + 1.0 / 12.0).0;
            let dn = lin40_map(us, v - 1.0 / 12.0).0;
            let dl = (sign * (amount / 100.0) * ((up - dn) / 2.0).abs())
                .max(-((n.dur - 1) as f64) / b.1);
            let lam = (u - us) / (ue - us);
            let (u2, v2) = lin40_map(u, v);
            (u2 + lam * dl, v2)
        });
        assert_eq!(dsep(&got), want, "mode {mode}, amount {amount}");
        // Interior rows: 0.4 / 12 of the box per row (124 ticks); the first
        // column's row 66 (120 ticks long).
        let len = got
            .iter()
            .find(|n| n.pitch == 66 && n.start < 4000)
            .unwrap()
            .dur as f64;
        let want66 = (120.0 + sign * amount / 100.0 * 124.0).max(1.0);
        assert!((len - want66).abs() <= 1.0, "{len} vs {want66}");
    }
}

#[test]
fn shear_strength_copies_step_from_the_full_shear_back_to_the_original() {
    let notes = distort_grid();
    for (copies, step) in [(3i64, -20.0), (1, 50.0), (5, 0.0)] {
        let got = shear_run(
            notes.clone(),
            1,
            &lin40(&[on("n09"), int("n09.copies", copies), fl("n09.vel", step)]),
        )
        .notes;
        let b = dbox(&notes);
        let mut want: Vec<(i64, i64, i64, u8, u32)> = Vec::new();
        for n in &notes {
            want.push(pexp(b, n, &lin40_map, n.vel, n.sub));
            for j in 1..=copies {
                let f = 1.0 - j as f64 / (copies + 1) as f64;
                let vel = (f64::from(n.vel) * (1.0 + j as f64 * (step / 100.0)))
                    .round()
                    .clamp(1.0, 127.0) as u8;
                let part = |u: f64, v: f64| {
                    let (u2, v2) = lin40_map(u, v);
                    (u + (u2 - u) * f, v + (v2 - v) * f)
                };
                want.push(pexp(b, n, &part, vel, n.sub));
            }
        }
        want.sort_unstable();
        assert_eq!(psv(&got), want, "{copies} copies, step {step}");
        assert_eq!(got.len(), notes.len() * (copies as usize + 1));
    }
}

#[test]
fn shear_displacement_colours_band_the_distance_each_note_moved() {
    let notes = distort_grid();
    let b = dbox(&notes);
    let moved = |n: &TNote, f: f64| {
        let v = (f64::from(n.pitch) + 0.5 - b.2) / b.3;
        let us = (n.start as f64 - b.0) / b.1;
        let (u2, v2) = lin40_map(us, v);
        ((u2 - us) * f).hypot((v2 - v) * f)
    };
    let dmax = notes.iter().map(|n| moved(n, 1.0)).fold(0.0, f64::max);
    for (bands, pal, copies) in [
        (3i64, vec![2i64, 0, 3], 0i64),
        (2, vec![1], 0),
        (4, vec![3, 2, 1, 0], 2),
    ] {
        let mut set = lin40(&[
            on("n11"),
            int("n11.bands", bands),
            list("n11.palette", &pal),
        ]);
        if copies > 0 {
            set.extend([on("n09"), int("n09.copies", copies), fl("n09.vel", 0.0)]);
        }
        let got = shear_run(notes.clone(), 1, &set).notes;
        let band = |d: f64| {
            let k = ((d / dmax * bands as f64) as i64).min(bands - 1) as usize;
            pal[k % pal.len()] as u32
        };
        let mut want: Vec<(i64, i64, i64, u8, u32)> = Vec::new();
        for n in &notes {
            want.push(pexp(b, n, &lin40_map, n.vel, band(moved(n, 1.0))));
            for j in 1..=copies {
                let f = 1.0 - j as f64 / (copies + 1) as f64;
                let part = |u: f64, v: f64| {
                    let (u2, v2) = lin40_map(u, v);
                    (u + (u2 - u) * f, v + (v2 - v) * f)
                };
                want.push(pexp(b, n, &part, n.vel, band(moved(n, 1.0) * f)));
            }
        }
        want.sort_unstable();
        assert_eq!(psv(&got), want, "{bands} bands");
    }
}

#[test]
fn shear_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&f| on(f)).collect();
    let a = shear_run(skew_fixture(), 3, &all);
    assert_eq!(a.notes, shear_run(skew_fixture(), 3, &all).notes);
    for f in ALL11 {
        for extra in [
            vec![],
            vec![on("a1"), on("a2"), on("a5"), on("a8"), on("a10")],
            vec![
                on("a3"),
                on("a4"),
                on("a6"),
                on("a7"),
                on("a9"),
                on("g.fill"),
                ch("g.raster", 2),
            ],
            vec![
                ch("g.undefined", 1),
                ch("n01.of", 1),
                ch("n02.mode", 2),
                ch("n10.stretch", 1),
                int("n10.period", 480),
            ],
        ] {
            let mut set = vec![on(f)];
            set.extend(extra);
            let v = shear_run(skew_fixture(), 3, &set);
            assert_eq!(v.notes, shear_run(skew_fixture(), 3, &set).notes, "{f}");
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.ch <= 15 && n.dur >= 1),
                "{f}"
            );
        }
    }
    let sweep = [on("n04"), on("m.sweep"), on("m.sweep.axis")];
    let a = shear_run(skew_fixture(), 3, &sweep);
    assert_eq!(a.notes, shear_run(skew_fixture(), 3, &sweep).notes);
}

// ================================================================ Twirl

/// Runs Twirl on hand-built selected notes of `tracks` track slots
/// (subchannels 0 – 3), checking the preflight bound.
fn twirl_try(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    shear_like_try("twirl", notes, tracks, set)
}

/// [`shear_try`]'s body for any geometry tool id (no context, no aux).
fn shear_like_try(
    id: &str,
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, (0..tracks).map(tr).collect());
    let t = tool(id).unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate(&src.stats).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

fn twirl_run(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    twirl_try(notes, tracks, set).unwrap()
}

