/// Neutral settings: a path that stays at the centre, a local angle of 0,
/// three arms of 180°, no void, a full-circle sector, horizontal bodies,
/// no snap strength, no noise, no tangential amount — each alone, then
/// together.
fn twirl_neutral(cx: f64, cy: f64) -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n01",
            vec![
                on("n01"),
                curve("n01.x", Curve::flat(cx / 100.0)),
                curve("n01.y", Curve::flat(cy / 100.0)),
            ],
        ),
        ("n02", vec![on("n02"), fl("n02.angle", 0.0)]),
        (
            "n03",
            vec![on("n03"), int("n03.arms", 3), fl("n03.width", 180.0)],
        ),
        ("n04", vec![on("n04"), fl("n04.radius", 0.0)]),
        ("n05", vec![on("n05"), fl("n05.width", 360.0)]),
        ("n07", vec![on("n07"), ch("n07.bodies", 1)]),
        ("n08", vec![on("n08"), fl("n08.strength", 0.0)]),
        ("n10", vec![on("n10"), fl("n10.noise", 0.0)]),
        ("n11", vec![on("n11"), fl("n11.amount", 0.0)]),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

