/// Neutral settings: resets at markers when there are none, no
/// modulation depth, a gate at −100 %, a fold at the wave's full height, no
/// travel, no phase per track, no distortion — each alone, then together.
fn wave_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n03",
            vec![on("n03"), ch("n03.at", 3), fl("n03.phase", 0.0)],
        ),
        ("n04", vec![on("n04"), fl("n04.depth", 0.0)]),
        ("n05", vec![on("n05"), fl("n05.threshold", -100.0)]),
        (
            "n07",
            vec![on("n07"), ch("n07.mode", 0), fl("n07.threshold", 100.0)],
        ),
        ("n09", vec![on("n09"), fl("n09.speed", 0.0)]),
        ("n10", vec![on("n10"), fl("n10.phase", 0.0)]),
        ("n11", vec![on("n11"), fl("n11.amount", 0.0)]),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn wave_neutral_new_functions_equal_the_v08_results() {
    for (i, s) in wave_v08_settings().iter().enumerate() {
        for (name, extra) in wave_neutral() {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            let r = wave_run(skew_fixture(), 3, &set);
            assert_eq!(join_fingerprint(&r), WAVE_V08[i], "{name}, setting {i}");
        }
    }
}

/// Any geometry tool on hand-built notes of `tracks` slots in `ctx`, the
/// preflight bound checked.
fn geo_ctx_run(
    id: &str,
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
    ctx: Ctx,
) -> plumspirit_engine::transform::TransformRun {
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, (0..tracks).map(tr).collect());
    let t = tool(id).unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate(&src.stats).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    r
}

/// One generator: wavelength ¼ of the box, amplitude 10 %, phase 0; only
/// the pitch displacement (it reads time) unless `extra` says otherwise.
fn wvset(extra: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut v = vec![
        int("gens", 1),
        fl("len_min", 25.0),
        fl("len_max", 25.0),
        fl("amp_min", 10.0),
        fl("amp_max", 10.0),
        on("a3"),
        list("a3.phases", &[0]),
        fl("sx", 0.0),
        fl("sy", 100.0),
    ];
    v.extend(extra.iter().cloned());
    v
}

/// The generator of [`wvset`] at `pos` (box units) with `base` phase and
/// frequency factor `m` (`Wave9::combine`'s arithmetic).
fn wsin(pos: f64, base: f64, m: Option<f64>) -> f64 {
    let arg = 2.0 * std::f64::consts::PI * pos / 0.25;
    let arg = m.map_or(arg, |m| arg * m);
    0.1 * (arg + 0.0 + base).sin()
}

/// 24 notes every 240 ticks (120 long) on rows 60 – 72 (box 0 – 5,640 ×
/// 13 rows), on `track`.
fn wave_fix(track: u16) -> Vec<TNote> {
    (0..24u64)
        .map(|i| TNote {
            track,
            ..tn(240 * i, 120, 60 + (i % 13) as u8, 100)
        })
        .collect()
}

/// The expected notes of `notes` under the unit map `f` (per note).
fn wexpect(notes: &[TNote], f: &dyn Fn(&TNote, f64, f64) -> (f64, f64)) -> Vec<(i64, i64, i64)> {
    distort_expect(notes, f)
}

fn wrun(notes: Vec<TNote>, tracks: u16, extra: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    wave_run(notes, tracks, &wvset(extra)).notes
}

#[test]
fn wave_base_model_matches_the_single_generator() {
    let notes = wave_fix(0);
    let got = wrun(notes.clone(), 1, &[]);
    let want = wexpect(&notes, &|_, u, v| (u, v + wsin(u, 1.0, None)));
    assert_eq!(dsep(&got), want);
}

#[test]
fn wave_track_phase_offsets_each_tracks_phase_by_its_rank() {
    let mut notes = wave_fix(0);
    // Track 1: the same notes a row lower (its lowest pitch is lower).
    notes.extend(wave_fix(1).into_iter().map(|n| TNote {
        pitch: n.pitch - 1,
        ..n
    }));
    let ph = 120.0 * std::f64::consts::PI / 180.0;
    for (order, rank) in [(0u32, [0.0, 1.0]), (1, [1.0, 0.0])] {
        let got = wrun(
            notes.clone(),
            2,
            &[on("n10"), fl("n10.phase", 120.0), ch("n10.order", order)],
        );
        let want = wexpect(&notes, &|n, u, v| {
            (u, v + wsin(u, ph * rank[usize::from(n.track)] + 1.0, None))
        });
        assert_eq!(dsep(&got), want, "order {order}");
    }
}

/// The phase-reset model: `pos` from the last point of `resets` (or of the
/// bar with `bars`) at or before the point, `ph` added after a reset.
fn reset_model(
    b: (f64, f64, f64, f64),
    resets: &[u64],
    bars: bool,
    ph: f64,
) -> impl Fn(&TNote, f64, f64) -> (f64, f64) + '_ {
    move |_, u, v| {
        let (t0, w, _, _) = b;
        let x = t0 + u * w;
        let r = if bars {
            Some(((x + 1e-9).max(0.0).floor() as u64 / 3840 * 3840) as f64)
        } else {
            let k = resets.partition_point(|&p| p as f64 <= x + 1e-9);
            (k > 0).then(|| resets[k - 1] as f64)
        };
        let (pos, base) = match r {
            Some(r) => ((x - r) / w, 1.0 + ph),
            None => (u, 1.0),
        };
        (u, v + wsin(pos, base, None))
    }
}

#[test]
fn wave_phase_reset_restarts_the_phase_at_bars_chords_phrases_and_onsets() {
    let notes = wave_fix(0);
    let b = dbox(&notes);
    let ph = 90.0 * std::f64::consts::PI / 180.0;
    let reset = |at: u32| {
        wrun(
            notes.clone(),
            1,
            &[on("n03"), ch("n03.at", at), fl("n03.phase", 90.0)],
        )
    };
    // Bars (3,840 ticks).
    assert_eq!(
        dsep(&reset(0)),
        wexpect(&notes, &reset_model(b, &[], true, ph))
    );
    // Chords (every onset here) and the selection's onsets.
    let onsets: Vec<u64> = notes.iter().map(|n| n.start).collect();
    let want = wexpect(&notes, &reset_model(b, &onsets, false, ph));
    assert_eq!(dsep(&reset(2)), want);
    assert_eq!(dsep(&reset(4)), want);
    // Phrases: a rest longer than a beat after the 12th note.
    let gapped: Vec<TNote> = notes
        .iter()
        .map(|n| TNote {
            start: n.start + if n.start >= 2880 { 1920 } else { 0 },
            ..*n
        })
        .collect();
    let got = wrun(
        gapped.clone(),
        1,
        &[on("n03"), ch("n03.at", 1), fl("n03.phase", 90.0)],
    );
    let bg = dbox(&gapped);
    assert_eq!(
        dsep(&got),
        wexpect(&gapped, &reset_model(bg, &[0, 4800], false, ph))
    );
    // Markers (none before the first one: the plain wave there).
    let mut ctx = Ctx::simple(960);
    ctx.markers = Arc::new(vec![1000, 3000]);
    let got = geo_ctx_run(
        "wave",
        notes.clone(),
        1,
        &wvset(&[on("n03"), ch("n03.at", 3), fl("n03.phase", 90.0)]),
        ctx,
    );
    assert_eq!(
        dsep(&got.notes),
        wexpect(&notes, &reset_model(b, &[1000, 3000], false, ph))
    );
}

#[test]
fn wave_phase_reset_reads_a_reference_track_or_refuses_a_missing_one() {
    let mut d = PlumDocument::new_project("s38".into(), Bpm::DEFAULT, 960);
    d.add_track().unwrap();
    let sel: Vec<NoteRecord> = (0..8u64).map(|i| rec(480 * i, 240, 60 + i as u8)).collect();
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&sel, true)
        .unwrap();
    d.track_mut(1)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(1000, 100, 50), rec(2500, 100, 50)], false)
        .unwrap();
    let def = tool("wave").unwrap();
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let run = |num: i64| -> Result<Vec<TNote>, plumspirit_engine::transform::TransformError> {
        let mut ps = ParamSet::defaults(&(def.spec)().params);
        for (k, v) in wvset(&[
            on("n03"),
            ch("n03.at", 4),
            int("n03.ref", num),
            fl("n03.phase", 90.0),
        ]) {
            ps.set(k, v);
        }
        let src = collect_with(def, &d, &sc, &ps, 1 << 24)?;
        let ctx = Ctx::simple(960);
        let b = BuildCtx {
            ctx: &ctx,
            stats: &src.stats,
            tracks: &src.tracks,
        };
        let k = def.kernel(&ps, &b)?;
        Ok(run_kernel(
            k.as_ref(),
            &src,
            def.boundary(&ps),
            &Limits::default(),
            None,
        )?
        .notes)
    };
    let notes: Vec<TNote> = (0..8u64)
        .map(|i| tn(480 * i, 240, 60 + i as u8, 100))
        .collect();
    let b = dbox(&notes);
    let ph = 90.0 * std::f64::consts::PI / 180.0;
    assert_eq!(
        dsep(&run(2).unwrap()),
        wexpect(&notes, &reset_model(b, &[1000, 2500], false, ph))
    );
    let e = run(9).unwrap_err();
    assert!(
        e.user_message().contains("Track 9 does not exist"),
        "{}",
        e.user_message()
    );
}

#[test]
fn wave_synced_wavelength_locks_the_waves_to_beats_bars_or_milliseconds() {
    let notes = wave_fix(0);
    let b = dbox(&notes);
    let synced = |unit: u32, len: f64, q: &dyn Fn(f64) -> f64| {
        let got = wrun(
            notes.clone(),
            1,
            &[on("n01"), ch("n01.unit", unit), fl("n01.len", len)],
        );
        let want = wexpect(&notes, &|_, u, v| {
            let x = b.0 + u * b.1;
            let periods = (q(x) - 0.0) / len;
            let arg = 2.0 * std::f64::consts::PI * periods * 1.0 / 1.0;
            (u, v + 0.1 * (arg + 0.0 + 1.0).sin())
        });
        assert_eq!(dsep(&got), want, "unit {unit}");
    };
    synced(0, 2.0, &|x| x / 960.0);
    synced(1, 0.5, &|x| {
        let bar = ((x + 1e-9).floor() as u64 / 3840) as f64;
        bar + (x - bar * 3840.0) / 3840.0
    });
    synced(2, 700.0, &|x| {
        let t = x.floor();
        let m = |k: f64| k * 500_000.0 / 960.0;
        (m(t) + (x - t) * (m(t + 1.0) - m(t))) / 1000.0
    });
    // Five random generators at harmonics of one beat: a note one beat
    // later is displaced exactly like its twin.
    let twins: Vec<TNote> = (0..8u64)
        .flat_map(|i| [tn(i * 100, 50, 64, 100), tn(i * 100 + 960, 50, 64, 100)])
        .chain([tn(0, 3000, 40, 100), tn(0, 3000, 90, 100)])
        .collect();
    let mut set = vec![int("gens", 5), fl("sx", 0.0), on("n01"), fl("n01.len", 1.0)];
    set.push(fl("amp_max", 30.0));
    let got = wave_run(twins, 1, &set).notes;
    let rows: std::collections::BTreeMap<u64, u8> = got
        .iter()
        .filter(|n| n.dur == 50)
        .map(|n| (n.start, n.pitch))
        .collect();
    for i in 0..8u64 {
        assert_eq!(rows[&(i * 100)], rows[&(i * 100 + 960)], "twin {i}");
    }
}

#[test]
fn wave_travelling_wave_moves_the_pattern_along_pitch_over_time() {
    let notes = wave_fix(0);
    let b = dbox(&notes);
    let got = wrun(
        notes.clone(),
        1,
        &[
            fl("sx", 100.0),
            fl("sy", 0.0),
            on("n09"),
            fl("n09.speed", 3.0),
        ],
    );
    let want = wexpect(&notes, &|_, u, v| {
        let beats = u * b.1 / 960.0;
        let pos = v - 3.0 * beats / b.3;
        (u + wsin(pos, 0.0, None), v)
    });
    assert_eq!(dsep(&got), want);
}

#[test]
fn wave_sample_and_hold_steps_the_displacement() {
    let notes = wave_fix(0);
    let b = dbox(&notes);
    let (h, off) = (960.0, 0.25 * 960.0);
    let got = wrun(
        notes.clone(),
        1,
        &[on("n08"), int("n08.hold", 960), fl("n08.phase", 25.0)],
    );
    let held = |u: f64| {
        let x = b.0 + u * b.1;
        let xq = b.0 + off + ((x - b.0 - off) / h + 1e-9).floor() * h;
        (xq - b.0) / b.1
    };
    let want = wexpect(&notes, &|_, u, v| (u, v + wsin(held(u), 1.0, None)));
    assert_eq!(dsep(&got), want);
    // Notes in one hold cell share their displacement (rows relative to
    // their own pitch).
    let mut moved: Vec<(u64, i64)> = got.iter().map(|n| (n.start, i64::from(n.pitch))).collect();
    moved.sort_unstable();
    let shift: Vec<i64> = moved
        .iter()
        .zip(&notes)
        .map(|(m, n)| m.1 - i64::from(n.pitch))
        .collect();
    // 240-tick notes in cells from 240: notes 1 – 4 share a cell.
    assert!(shift[1..5].windows(2).all(|w| w[0] == w[1]), "{shift:?}");
}

#[test]
fn wave_phase_distortion_bends_the_phase_inside_each_period() {
    let notes = wave_fix(0);
    for (d, pivot) in [(100.0, 20.0), (50.0, 80.0)] {
        let knee = 0.5 + (d / 100.0_f64).clamp(0.0, 1.0) * (pivot / 100.0 - 0.5);
        let got = wrun(
            notes.clone(),
            1,
            &[on("n11"), fl("n11.amount", d), fl("n11.pivot", pivot)],
        );
        let want = wexpect(&notes, &|_, u, v| {
            let a = 2.0 * std::f64::consts::PI * u / 0.25 + 0.0 + 1.0;
            let t = (a / (2.0 * std::f64::consts::PI)).rem_euclid(1.0);
            let t = if t < knee {
                0.5 * t / knee
            } else {
                0.5 + 0.5 * (t - knee) / (1.0 - knee)
            };
            (u, v + 0.1 * (2.0 * std::f64::consts::PI * t).sin())
        });
        assert_eq!(dsep(&got), want, "{d} / {pivot}");
    }
}

#[test]
fn wave_lissajous_runs_x_and_y_at_their_frequency_ratio() {
    let notes = wave_fix(0);
    let phi = 45.0 * std::f64::consts::PI / 180.0;
    let got = wrun(
        notes.clone(),
        1,
        &[
            fl("sx", 100.0),
            on("n06"),
            int("n06.a", 3),
            int("n06.b", 2),
            fl("n06.phase", 45.0),
        ],
    );
    let want = wexpect(&notes, &|_, u, v| {
        (
            u + wsin(v, 0.0, Some(3.0)),
            v + wsin(u, 0.0 + phi, Some(2.0)),
        )
    });
    assert_eq!(dsep(&got), want);
}

#[test]
fn wave_wavefold_folds_rectifies_or_clips_the_wave() {
    let notes = wave_fix(0);
    let t = 0.5 * 0.1;
    let fold = |w: f64, mode: u32| -> f64 {
        match mode {
            1 => w.abs(),
            2 => w.max(0.0),
            3 => w.clamp(-t, t),
            _ => {
                let mut w = w;
                for _ in 0..2 {
                    if w > t {
                        w = 2.0 * t - w;
                    } else if w < -t {
                        w = -2.0 * t - w;
                    } else {
                        break;
                    }
                }
                w.clamp(-t, t)
            }
        }
    };
    for mode in 0..4u32 {
        let got = wrun(
            notes.clone(),
            1,
            &[
                fl("sy", 400.0),
                on("n07"),
                ch("n07.mode", mode),
                fl("n07.threshold", 50.0),
                int("n07.folds", 2),
            ],
        );
        let want = wexpect(&notes, &|_, u, v| {
            (u, v + 4.0 * fold(wsin(u, 1.0, None), mode))
        });
        assert_eq!(dsep(&got), want, "mode {mode}");
    }
}

#[test]
fn wave_gate_keeps_notes_where_the_wave_is_above_or_below_the_threshold() {
    let notes = wave_fix(0);
    let b = dbox(&notes);
    for (thr, below) in [(30.0, 0u32), (-20.0, 1)] {
        let got = wrun(
            notes.clone(),
            1,
            &[
                fl("sy", 0.0),
                on("n05"),
                fl("n05.threshold", thr),
                ch("n05.keep", below),
            ],
        );
        let want: Vec<(i64, i64, i64)> = notes
            .iter()
            .filter(|n| {
                let u = (n.start as f64 - b.0) / b.1;
                let w = (wsin(u, 1.0, None) / 0.1).clamp(-1.0, 1.0);
                if below == 1 {
                    w <= thr / 100.0
                } else {
                    w >= thr / 100.0
                }
            })
            .map(|n| (n.start as i64, n.end() as i64, i64::from(n.pitch)))
            .collect();
        assert!(!want.is_empty() && want.len() < notes.len());
        assert_eq!(dsep(&got), want, "{thr}");
    }
}

#[test]
fn wave_property_modulation_scales_velocity_gate_or_release_by_the_wave() {
    let notes = wave_fix(0);
    let b = dbox(&notes);
    let ph = 90.0 * std::f64::consts::PI / 180.0;
    let factor = |n: &TNote| {
        let (u, _) = ((n.start as f64 - b.0) / b.1, 0.0);
        1.0 + 0.5 * (wsin(u, 1.0 + ph, None) / 0.1).clamp(-1.0, 1.0)
    };
    for prop in 0..3u32 {
        let mut got = wrun(
            notes.clone(),
            1,
            &[
                fl("sy", 0.0),
                on("n04"),
                ch("n04.prop", prop),
                fl("n04.depth", 50.0),
                fl("n04.phase", 90.0),
            ],
        );
        got.sort_by_key(|n| n.start);
        for (g, n) in got.iter().zip(&notes) {
            let f = factor(n);
            match prop {
                0 => assert_eq!(g.vel, (100.0 * f).round().clamp(1.0, 127.0) as u8),
                1 => assert_eq!(g.dur, ((120.0 * f).round() as u64).max(1)),
                _ => assert_eq!(
                    g.rel,
                    (f64::from(n.rel) * f).round().clamp(0.0, 127.0) as u8
                ),
            }
        }
    }
}

#[test]
fn wave_wavy_notes_draw_each_note_as_a_wavy_line() {
    let got = wrun(
        vec![tn(0, 1920, 60, 100)],
        1,
        &[
            fl("sy", 0.0),
            on("n02"),
            int("n02.seg", 60),
            int("n02.amp", 2),
            int("n02.len", 480),
        ],
    );
    let want: Vec<(i64, i64, i64)> = (0..32u64)
        .map(|j| {
            let off = (2.0 * (2.0 * std::f64::consts::PI * (j * 60) as f64 / 480.0).sin()).round();
            ((j * 60) as i64, (j * 60 + 60) as i64, 60 + off as i64)
        })
        .collect();
    assert_eq!(dsep(&got), want);
    // A last piece shorter than the segment.
    let got = wrun(
        vec![tn(0, 130, 60, 100)],
        1,
        &[fl("sy", 0.0), on("n02"), int("n02.seg", 60)],
    );
    let lens: Vec<u64> = {
        let mut v: Vec<(u64, u64)> = got.iter().map(|n| (n.start, n.dur)).collect();
        v.sort_unstable();
        v.iter().map(|x| x.1).collect()
    };
    assert_eq!(lens, vec![60, 60, 10]);
}

#[test]
fn wave_control_sweeps_run_per_note_inside_the_kernel() {
    // The pitch displacement swept over time 0 → 200 %: per note 2·u of
    // its start (selection frame: first to last start).
    let mut notes = wave_fix(0);
    // Track 1 later in time, with n10's track phase: its rank stays 1
    // even though no level holds both tracks.
    notes.extend((0..6u64).map(|i| TNote {
        track: 1,
        ..tn(6000 + 240 * i, 120, 66, 100)
    }));
    let got = wrun(
        notes.clone(),
        2,
        &[
            on("n10"),
            fl("n10.phase", 180.0),
            on("m.sweep"),
            on("m.sweep.sy"),
        ],
    );
    let (s0, s1) = (0.0, 7200.0);
    let want = wexpect(&notes, &|n, u, v| {
        let k = 200.0 * ((n.start as f64 - s0) / (s1 - s0)) / 100.0;
        let base = std::f64::consts::PI * f64::from(n.track) + 1.0;
        (u, v + k * wsin(u, base, None))
    });
    assert_eq!(dsep(&got.clone()), want);
    // Deterministic.
    let again = wrun(
        notes,
        2,
        &[
            on("n10"),
            fl("n10.phase", 180.0),
            on("m.sweep"),
            on("m.sweep.sy"),
        ],
    );
    assert_eq!(dsep(&got), dsep(&again));
}

#[test]
fn wave_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&k| on(k)).collect();
    for extra in [
        vec![],
        vec![on("a4"), on("a5"), on("a6"), ch("a6.mode", 2), on("a10")],
        vec![ch("g.raster", 2), int("g.segments", 3), on("g.fill")],
        vec![
            ch("n01.unit", 2),
            ch("n03.at", 1),
            ch("n07.mode", 3),
            on("a9"),
        ],
    ] {
        let mut set = all.clone();
        set.extend(extra);
        let a = wave_run(skew_fixture(), 3, &set);
        let b = wave_run(skew_fixture(), 3, &set);
        assert_eq!(a.notes, b.notes);
        assert!(!a.notes.is_empty());
    }
}

// ============================================================= Clipping Mask

/// The Clipping Mask fixture: the art (tracks 0 and 1 of [`skew_fixture`],
/// 128 notes), the base track on slot 2 (six notes of 480 – 3,300 ticks per
/// row 40 – 91, velocities 20 – 119, subchannels 0 – 3, channels 4 – 7) and
/// an extra mask layer (three longer notes per row, slot `u16::MAX` as
/// `prepare` reads it). A fixed xorshift,
/// so the fixture never changes.
fn clip_fixture() -> (Vec<TNote>, Vec<TNote>, Vec<TNote>) {
    let art: Vec<TNote> = skew_fixture().into_iter().filter(|n| n.track < 2).collect();
    let mut x: u64 = 0xC11B_3A5C_0000_0007;
    let mut rnd = |m: u64| {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        x % m.max(1)
    };
    let mut base = Vec::new();
    let mut extra = Vec::new();
    for p in 40..92u8 {
        for _ in 0..6 {
            let sub = rnd(4) as u32;
            base.push(TNote {
                start: rnd(8 * 3840 / 60) * 60,
                dur: 480 + rnd(48) * 60,
                pitch: p,
                vel: 20 + rnd(100) as u8,
                rel: 64,
                sub,
                ch: sub as u8 + 4,
                track: 2,
                ..TNote::default()
            });
        }
        for _ in 0..3 {
            extra.push(TNote {
                start: rnd(8 * 3840 / 120) * 120,
                dur: 1920 + rnd(32) * 120,
                pitch: p,
                vel: 90,
                rel: 64,
                track: u16::MAX,
                ..TNote::default()
            });
        }
    }
    base.sort_by_key(|n| (n.start, n.pitch));
    extra.sort_by_key(|n| (n.start, n.pitch));
    (art, base, extra)
}

/// Runs Clipping Mask on `art` (selected, slots 0 – 1) with `base` (slot
/// 2, the destination of the mask's track) and `extra` (the "More mask
/// tracks" layer) in `ctx`. `bound`: the result must stay within the
/// preflight's bound (the v0.9 kernel's; the v0.8 one only declares a
/// typical growth, its output cap bounding the rest).
fn clip_try_in(
    art: Vec<TNote>,
    base: Vec<TNote>,
    extra: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
    ctx: Ctx,
    bound: bool,
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(art, (0..3).map(tr).collect());
    src.aux = Arc::new(vec![base, extra]);
    src.aux_slot = Some(2);
    let t = tool("clip_mask").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate_source(&src).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    if bound {
        assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
        assert!(
            r.notes.len() as u64 <= k.estimate(&src.stats).notes,
            "{} > the statistics' bound",
            r.notes.len()
        );
    }
    Ok(r)
}

/// [`clip_try_in`] on [`clip_fixture`] in `Ctx::simple(960)`.
fn clip_run(
    set: &[(&'static str, ParamValue)],
    bound: bool,
) -> plumspirit_engine::transform::TransformRun {
    let (art, base, extra) = clip_fixture();
    clip_try_in(art, base, extra, set, Ctx::simple(960), bound).unwrap()
}

