/// Every field of a note list (in its sorted order), hashed (FNV-1a).
fn notes_hash(v: &[TNote]) -> u64 {
    let mut o: Vec<JoinFields> = v
        .iter()
        .map(|n| {
            (
                n.start, n.dur, n.pitch, n.vel, n.rel, n.ch, n.sub, n.group, n.track, n.flags,
            )
        })
        .collect();
    o.sort_unstable();
    let mut h: u64 = 0xCBF2_9CE4_8422_2325;
    for f in o {
        for b in format!("{f:?}").bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0100_0000_01B3);
        }
    }
    h
}

/// [`join_fingerprint`] plus the new subtrack's parent slot, note count and
/// [`notes_hash`] (Result to a new subtrack), plus the run's message.
type ClipFp = (
    (usize, usize, u64),
    Option<(u16, usize, u64)>,
    Option<String>,
);

fn clip_fingerprint(r: &plumspirit_engine::transform::TransformRun) -> ClipFp {
    (
        join_fingerprint(r),
        r.new_subtrack
            .as_ref()
            .map(|(p, v)| (*p, v.len(), notes_hash(v))),
        r.message.clone(),
    )
}

