/// [`ClipFp`] with a static message (the recorded constants).
type ClipFpRef = ((usize, usize, u64), Option<(u16, usize, u64)>, &'static str);

fn clip_matches(r: &plumspirit_engine::transform::TransformRun, want: &ClipFpRef) -> bool {
    let (j, sub, msg) = clip_fingerprint(r);
    j == want.0 && sub == want.1 && msg.as_deref() == Some(want.2)
}

fn clip_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

