#[test]
fn clip_marker_mask_uses_marker_sections_chapters_or_the_time_selection() {
    let mut ctx = Ctx::simple(960);
    // 4000 starts a chapter (its start is a marker start too).
    ctx.markers = Arc::new(vec![1000, 3000, 4000, 6000]);
    ctx.chapters = Arc::new(vec![(4000, 5000)]);
    ctx.time_range = Some((500, 800));
    let run = |kind: u32, keep: u32, extra: &[(&'static str, ParamValue)], ctx: &Ctx| {
        let mut s = vec![on("n10"), ch("n10.ranges", kind), ch("n10.keep", keep)];
        s.extend(extra.iter().cloned());
        let r = clip9_in(
            vec![ctn(0, 8000, 60, 100, 0, 0)],
            vec![ctn(0, 8000, 60, 100, 2, 0)],
            Vec::new(),
            &s,
            ctx.clone(),
        );
        let v: Vec<(u64, u64)> = on_slot(&r, 2).iter().map(|x| (x.0, x.1)).collect();
        (v, r.message)
    };
    // Point markers paired: [1000, 3000), [6000, …); the base notes are
    // not read.
    assert_eq!(run(0, 0, &[], &ctx).0, vec![(1000, 3000), (6000, 8000)]);
    assert_eq!(run(0, 1, &[], &ctx).0, vec![(0, 1000), (3000, 6000)]);
    assert_eq!(run(1, 0, &[], &ctx).0, vec![(4000, 5000)]);
    assert_eq!(run(1, 1, &[], &ctx).0, vec![(0, 4000), (5000, 8000)]);
    assert_eq!(run(2, 0, &[], &ctx).0, vec![(500, 800)]);
    // Song ticks → the tools' ticks (an opened clip's shift).
    let mut shifted = ctx.clone();
    shifted.shift = 500;
    assert_eq!(run(1, 0, &[], &shifted).0, vec![(3500, 4500)]);
    // With a shape: the shape inside (or outside) the ranges.
    let rect = [on("n01"), ch("n01.shape", 1), fl("n01.size", 50.0)];
    assert_eq!(run(1, 0, &rect, &ctx).0, vec![(4000, 5000)]);
    assert_eq!(run(1, 1, &rect, &ctx).0, vec![(2000, 4000), (5000, 6000)]);
    // No ranges: nothing clipped, and a sentence says why.
    let (v, msg) = run(0, 0, &[], &Ctx::simple(960));
    assert!(v.is_empty());
    assert_eq!(
        msg.as_deref(),
        Some("0 clipped note piece(s). There are no marker sections to mask with.")
    );
    let (_, msg) = run(2, 0, &[], &Ctx::simple(960));
    assert!(
        msg.unwrap()
            .ends_with("There is no time selection to mask with.")
    );
}

#[test]
fn clip_generated_masks_need_no_base_track_unless_the_result_goes_there() {
    let mut d = PlumDocument::new_project("s38".into(), Bpm::DEFAULT, 960);
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(0, 4000, 60)], true)
        .unwrap();
    let def = tool("clip_mask").unwrap();
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let run = |set: &[(&'static str, ParamValue)]| -> Result<Vec<(u64, u64, u8)>, String> {
        let mut ps = ParamSet::defaults(&(def.spec)().params);
        for (k, v) in set {
            ps.set(k, v.clone());
        }
        let src = collect_with(def, &d, &sc, &ps, 1 << 24).map_err(|e| e.user_message())?;
        let ctx = Ctx::simple(960);
        let b = BuildCtx {
            ctx: &ctx,
            stats: &src.stats,
            tracks: &src.tracks,
        };
        let k = def.kernel(&ps, &b).map_err(|e| e.user_message())?;
        let r = run_kernel(
            k.as_ref(),
            &src,
            def.boundary(&ps),
            &Limits::default(),
            None,
        )
        .map_err(|e| e.user_message())?;
        Ok(on_slot(&r, 0))
    };
    let rect = [on("n01"), ch("n01.shape", 1), fl("n01.size", 50.0)];
    let mut replace = rect.to_vec();
    replace.push(ch("result", 1));
    assert_eq!(run(&replace).unwrap(), vec![(1000, 3000, 60)]);
    let mut add = rect.to_vec();
    add.push(ch("result", 2));
    assert_eq!(run(&add).unwrap(), vec![(0, 4000, 60), (1000, 3000, 60)]);
    // The result to the mask's track, Vice Versa, or a mask read from the
    // base track: refused with the v0.8 sentence.
    for set in [
        rect.to_vec(),
        vec![on("n01"), on("vice"), ch("result", 2)],
        vec![ch("result", 2)],
    ] {
        let e = run(&set).unwrap_err();
        assert!(e.contains("Choose a base (mask) track"), "{e}");
    }
}

#[test]
fn clip_base_property_transfer_gives_pieces_the_overlapped_base_notes_properties() {
    // The mask: [0, 3000) on row 60 from two base notes.
    let base = vec![ctn(0, 1000, 60, 30, 2, 2), ctn(500, 2500, 60, 120, 2, 1)];
    let piece = |art: TNote, extra: &[(&'static str, ParamValue)]| -> TNote {
        let mut s = vec![on("n11")];
        s.extend(extra.iter().cloned());
        let r = clip9(vec![art], base.clone(), &s);
        let v: Vec<TNote> = r.notes.iter().filter(|n| n.track == 2).copied().collect();
        assert_eq!(v.len(), 1);
        v[0]
    };
    let long = ctn(0, 4000, 60, 100, 0, 0);
    // The piece [0, 3000): at its middle 1500 only the second note sounds.
    assert_eq!(piece(long, &[]).vel, 120);
    assert_eq!(piece(long, &[fl("n11.amount", 50.0)]).vel, 110);
    assert_eq!(
        piece(long, &[ch("n11.mode", 1)]).vel,
        (100.0f64 * 120.0 / 127.0).round() as u8
    );
    assert_eq!(piece(long, &[ch("n11.mode", 2)]).vel, 110);
    assert_eq!(
        piece(long, &[ch("n11.mode", 2), fl("n11.amount", 50.0)]).vel,
        105
    );
    let s = piece(long, &[ch("n11.prop", 1)]);
    assert_eq!((s.sub, s.ch, s.vel), (1, 0, 100));
    let c = piece(long, &[ch("n11.prop", 2)]);
    assert_eq!((c.sub, c.ch, c.vel), (0, 1, 100));
    // At 650 both sound: the one that lasts longer; at 250 only the first.
    assert_eq!(piece(ctn(400, 500, 60, 100, 0, 0), &[]).vel, 120);
    assert_eq!(piece(ctn(100, 300, 60, 100, 0, 0), &[]).vel, 30);
    // Amount 50 % of a subchannel: about half the pieces take it, by the
    // seed.
    let art: Vec<TNote> = (0..400u64).map(|i| ctn(i * 10, 5, 60, 100, 0, 0)).collect();
    let base: Vec<TNote> = vec![ctn(0, 4000, 60, 90, 2, 3)];
    let subs = |seed: i64| -> Vec<u32> {
        let r = clip9(
            art.clone(),
            base.clone(),
            &[
                on("n11"),
                ch("n11.prop", 1),
                fl("n11.amount", 50.0),
                int("seed", seed),
            ],
        );
        let mut v: Vec<(u64, u32)> = r
            .notes
            .iter()
            .filter(|n| n.track == 2)
            .map(|n| (n.start, n.sub))
            .collect();
        v.sort_unstable();
        v.into_iter().map(|x| x.1).collect()
    };
    let a = subs(1);
    assert_eq!(a.len(), 400);
    assert!(a.iter().all(|&s| s == 0 || s == 3));
    let taken = a.iter().filter(|&&s| s == 3).count();
    assert!((140..=260).contains(&taken), "{taken}");
    assert_eq!(a, subs(1));
    assert_ne!(a, subs(2));
}

#[test]
fn clip_control_sweeps_run_inside_the_kernel_per_note_or_by_mask_levels() {
    // A per-note value: the outside parts' velocity over time, 0 → 150 %.
    let art: Vec<TNote> = (0..8u64)
        .map(|k| ctn(k * 1000, 500, 60, 100, 0, 0))
        .collect();
    let r = clip9(
        art.clone(),
        vec![ctn(100_000, 10, 90, 90, 2, 0)],
        &[
            ch("result", 2),
            on("n08"),
            ch("n08.mode", 1),
            on("m.sweep"),
            on("m.sweep.outside_velocity"),
        ],
    );
    for (k, n) in art.iter().enumerate() {
        // The selection (velocity 100) and the whole note as its outside
        // part, at 1.5 · k / 7 of the velocity.
        let want = (100.0 * 1.5 * k as f64 / 7.0).round().clamp(1.0, 127.0) as u8;
        let mut vels: Vec<u8> = r
            .notes
            .iter()
            .filter(|x| x.start == n.start && x.dur == 500 && x.track == 0)
            .map(|x| x.vel)
            .collect();
        vels.sort_unstable();
        let mut expect = vec![100, want];
        expect.sort_unstable();
        assert_eq!(vels, expect, "note {k}");
    }
    // A mask parameter: the offset X by levels (64 along time), a mask per
    // level — each art note clipped against the base shifted by its level's
    // value.
    let art: Vec<TNote> = (0..8u64)
        .map(|k| ctn(k * 4000, 4000, 60, 100, 0, 0))
        .collect();
    let base: Vec<TNote> = (0..8u64)
        .map(|k| ctn(k * 4000 + 1000, 500, 60, 90, 2, 0))
        .collect();
    let r = clip9(
        art.clone(),
        base.clone(),
        &[on("n04"), on("m.sweep"), on("m.sweep.offset_x")],
    );
    let mut want: Vec<(u64, u64, u8)> = Vec::new();
    for (k, a) in art.iter().enumerate() {
        let u = k as f64 / 7.0;
        let level = (u * 63.0).round() / 63.0;
        let dx = (-1920.0 + level * 3840.0).round() as i64;
        for b in &base {
            let (s, e) = (
                (b.start as i64 + dx).max(0) as u64,
                (b.end() as i64 + dx).max(0) as u64,
            );
            let (s, e) = (s.max(a.start), e.min(a.end()));
            if s < e {
                want.push((s, e, 60));
            }
        }
    }
    want.sort_unstable();
    assert_eq!(on_slot(&r, 2), want);
    // The art's span stays whole: a1's inversion with a sweep of a function
    // that is off gives the v0.8 result (the platform's levels would split
    // the span).
    let r = clip_run(&[on("a1"), on("m.sweep"), on("m.sweep.fade")], true);
    assert!(clip_matches(&r, &CLIP_V08[5]), "{:?}", clip_fingerprint(&r));
    let r = clip_run(
        &[
            on("a9"),
            int("a9.ticks", 960),
            on("m.sweep"),
            on("m.sweep.transfer"),
        ],
        true,
    );
    assert!(
        clip_matches(&r, &CLIP_V08[13]),
        "{:?}",
        clip_fingerprint(&r)
    );
    // Vice Versa: measured over the base notes (the art).
    let base: Vec<TNote> = (0..5u64)
        .map(|k| ctn(10_000 + k * 1000, 500, 60, 100, 2, 0))
        .collect();
    let r = clip9(
        vec![ctn(0, 100, 30, 100, 0, 0)],
        base.clone(),
        &[
            on("vice"),
            ch("result", 2),
            on("n08"),
            ch("n08.mode", 1),
            on("m.sweep"),
            on("m.sweep.outside_velocity"),
        ],
    );
    for (k, b) in base.iter().enumerate() {
        let want = (100.0 * 1.5 * k as f64 / 4.0).round().clamp(1.0, 127.0) as u8;
        let got = r
            .notes
            .iter()
            .find(|x| x.start == b.start && x.track == 2)
            .unwrap();
        assert_eq!(got.vel, want, "base note {k}");
    }
}

#[test]
fn clip_preflight_counts_the_pieces_exactly_without_tiling() {
    let (art, base, extra) = clip_fixture();
    let tr = |i: u16| SourceTrack {
        id: TrackId(u32::from(i) + 1),
        index: usize::from(i),
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(art, (0..3).map(tr).collect());
    src.aux = Arc::new(vec![base, extra]);
    src.aux_slot = Some(2);
    let t = tool("clip_mask").unwrap();
    for (set, exact) in [
        (vec![on("n04")], true),
        (vec![on("n05"), on("n09")], true),
        (vec![on("n07"), int("n07.threshold", 1)], true),
        (vec![on("n06"), int("n06.period", 1000)], false),
        (vec![on("n08"), ch("result", 1)], false),
    ] {
        let mut ps = ParamSet::defaults(&(t.spec)().params);
        for (k, v) in &set {
            ps.set(k, v.clone());
        }
        let ctx = Ctx::simple(960);
        let b = BuildCtx {
            ctx: &ctx,
            stats: &src.stats,
            tracks: &src.tracks,
        };
        let k = t.kernel(&ps, &b).unwrap();
        let est = k.estimate_source(&src).notes;
        let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
        let n = r.notes.len() as u64;
        assert!(n <= est && n <= k.estimate(&src.stats).notes, "{set:?}");
        if exact {
            assert_eq!(n, est, "{set:?}");
        }
    }
    // The masks counted for one source's preflight never serve another
    // source's run (the same kernel, another selection).
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    ps.set("n04", ParamValue::Bool(true));
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let mut other = src.clone();
    other.notes.truncate(40);
    let est = k.estimate_source(&src);
    let fresh = t.kernel(&ps, &b).unwrap();
    let mut a = Output::new(t.boundary(&ps).within(other.keys), 1 << 20);
    let mut f = Output::new(t.boundary(&ps).within(other.keys), 1 << 20);
    k.run(&other, &mut a).unwrap();
    fresh.run(&other, &mut f).unwrap();
    assert!(est.notes > 0);
    assert_eq!(a.finish().unwrap().0, f.finish().unwrap().0);
}

#[test]
fn clip_tiled_masks_thin_and_fade_by_the_copies_edges() {
    // Copies of [1000, 2000) every 4000: a piece's edge distance is its
    // copy's.
    let base = vec![ctn(1000, 1000, 60, 90, 2, 0)];
    let r = clip9(
        vec![ctn(0, 12_000, 60, 100, 0, 0)],
        base,
        &[
            on("n06"),
            int("n06.period", 4000),
            int("n06.count", 3),
            on("n03"),
            int("n03.width", 1000),
            int("n03.rows", 0),
            fl("n03.floor", 0.0),
        ],
    );
    let got: Vec<(u64, u64, u8)> = {
        let mut v: Vec<(u64, u64, u8)> = r
            .notes
            .iter()
            .filter(|n| n.track == 2)
            .map(|n| (n.start, n.end(), n.vel))
            .collect();
        v.sort_unstable();
        v
    };
    // Middles 500 ticks from their copy's edges → half of 100.
    assert_eq!(
        got,
        vec![(1000, 2000, 50), (5000, 6000, 50), (9000, 10_000, 50)]
    );
}

#[test]
fn clip_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&k| on(k)).collect();
    let mut ctx = Ctx::simple(960);
    ctx.markers = Arc::new(vec![2000, 9000, 15_000, 26_000]);
    ctx.chapters = Arc::new(vec![(9000, 12_000)]);
    for extra in [
        vec![],
        vec![on("a1"), on("a3"), on("a5"), on("a8"), on("a9")],
        vec![
            ch("n01.shape", 3),
            ch("n05.side", 2),
            ch("n06.mirror", 1),
            ch("n10.keep", 1),
        ],
        vec![
            on("vice"),
            ch("result", 2),
            on("a2"),
            on("a10"),
            ch("n11.prop", 1),
        ],
        vec![
            ch("result", 1),
            on("a4"),
            on("a7"),
            ch("n09.rows", 1),
            on("m.sweep"),
            on("m.sweep.shape_size"),
            on("m.sweep.stroke"),
            on("m.sweep.fade"),
        ],
    ] {
        let mut set = all.clone();
        set.extend(extra);
        let (art, base, ex) = clip_fixture();
        let a = clip9_in(art.clone(), base.clone(), ex.clone(), &set, ctx.clone());
        let b = clip9_in(art, base, ex, &set, ctx.clone());
        assert_eq!(a.notes, b.notes);
        assert_eq!(a.new_subtrack, b.new_subtrack);
    }
    // Without the shape and markers, every function reads the base track.
    let set: Vec<(&'static str, ParamValue)> = ALL11
        .iter()
        .filter(|k| **k != "n01" && **k != "n10")
        .map(|&k| on(k))
        .collect();
    let r = clip_run(&set, true);
    assert!(r.notes.len() > 128);
}

