/// Neutral settings of the v0.9 functions (the v0.9 kernel, the v0.8
/// result): palettes of 0 (the note's own colour) for the Markov chain and
/// the phrases, an axiom without letters, a flash of 0 — each alone, then
/// together.
fn sp_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n02", vec![on("n02"), list("n02.palette", &[0])]),
        (
            "n03",
            vec![
                on("n03"),
                text_kv("n03.axiom", "+-"),
                text_kv("n03.rules", "+=-+"),
            ],
        ),
        ("n05", vec![on("n05"), int("n05.flash", 0)]),
        ("n07", vec![on("n07"), list("n07.palette", &[0])]),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

fn text_kv(k: &'static str, v: &str) -> (&'static str, ParamValue) {
    (k, ParamValue::Text(v.to_owned()))
}

#[test]
fn subpaint_neutral_new_functions_equal_the_v08_results() {
    for (i, s) in sp_v08_settings().iter().enumerate() {
        for (name, extra) in sp_neutral() {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            assert_eq!(
                join_fingerprint(&sp_run(&set)),
                SP_V08[i],
                "{name}, setting {i}"
            );
        }
        // A sweep of a function that is off: the v0.9 kernel, the v0.8
        // colours.
        let mut set = s.clone();
        set.extend([on("m.sweep"), on("m.sweep.gens")]);
        assert_eq!(
            join_fingerprint(&sp_run(&set)),
            SP_V08[i],
            "sweep, setting {i}"
        );
    }
}

/// A note of 100 ticks at `start` / `pitch` on subchannel `sub`.
fn tns(start: u64, pitch: u8, sub: u32) -> TNote {
    TNote {
        sub,
        ch: sub as u8,
        ..tn(start, 100, pitch, 100)
    }
}

/// Paint V2 on `notes` (one track, subchannels 0 – 3 cycled) with offset 0
/// (the v0.8 part keeps every colour), then `extra`: (start, pitch, sub)
/// sorted.
fn spx(notes: Vec<TNote>, extra: &[(&'static str, ParamValue)]) -> Vec<(u64, u8, u32)> {
    let mut set = vec![int("offset", 0)];
    set.extend(extra.iter().cloned());
    let r = sp_try(notes, 1, &set).unwrap();
    let mut v: Vec<(u64, u8, u32)> = r.notes.iter().map(|n| (n.start, n.pitch, n.sub)).collect();
    v.sort_unstable();
    v
}

fn subs_of(v: &[(u64, u8, u32)]) -> Vec<u32> {
    v.iter().map(|x| x.2).collect()
}

/// The L-system's string after `iters` rewrites (a plain string oracle).
fn lsys_oracle(axiom: &str, rules: &[(char, &str)], iters: usize) -> String {
    let mut s = axiom.to_owned();
    for _ in 0..iters {
        s = s
            .chars()
            .map(|c| {
                rules
                    .iter()
                    .find(|r| r.0 == c)
                    .map_or(c.to_string(), |r| r.1.to_owned())
            })
            .collect();
    }
    s
}

/// Subchannel positions (A = 0, B = 1, …, cycled over four) of the string's
/// letters, cycled over `n` notes.
fn lsys_subs(s: &str, n: usize) -> Vec<u32> {
    let l: Vec<u32> = s
        .chars()
        .filter(char::is_ascii_uppercase)
        .map(|c| (c as u32 - 'A' as u32) % 4)
        .collect();
    (0..n).map(|j| l[j % l.len()]).collect()
}

#[test]
fn subpaint_lsystem_colours_follow_the_rewritten_string_in_time_order() {
    let notes: Vec<TNote> = (0..10u64).map(|i| tns(100 * i, 60, 0)).collect();
    let fib = [('A', "AB"), ('B', "A")];
    for iters in [1usize, 4, 6] {
        let got = spx(
            notes.clone(),
            &[
                on("n03"),
                text_kv("n03.axiom", "A"),
                text_kv("n03.rules", "A=AB B=A"),
                int("n03.iters", iters as i64),
            ],
        );
        assert_eq!(
            subs_of(&got),
            lsys_subs(&lsys_oracle("A", &fib, iters), 10),
            "{iters}"
        );
    }
    // Arrows, commas, lower case; symbols that are not letters are
    // rewritten but paint nothing.
    let rules = [('A', "A+C"), ('C', "B-"), ('B', "A")];
    let got = spx(
        notes.clone(),
        &[
            on("n03"),
            text_kv("n03.axiom", "a"),
            text_kv("n03.rules", "a->A+C, C->b-; B->A"),
            int("n03.iters", 5),
        ],
    );
    assert_eq!(subs_of(&got), lsys_subs(&lsys_oracle("A", &rules, 5), 10));
    // Time order: two notes at one start go lowest first.
    let pair = vec![tns(0, 62, 0), tns(0, 60, 0), tns(100, 61, 0)];
    let got = spx(
        pair,
        &[
            on("n03"),
            text_kv("n03.axiom", "ABC"),
            text_kv("n03.rules", ""),
            int("n03.iters", 1),
        ],
    );
    assert_eq!(got, vec![(0, 60, 0), (0, 62, 1), (100, 61, 2)]);
    // A malformed rule is refused with a sentence.
    let e = sp_try(notes, 1, &[on("n03"), text_kv("n03.rules", "AB=C")]).unwrap_err();
    assert!(
        e.user_message().contains("L-system rules"),
        "{}",
        e.user_message()
    );
}

#[test]
fn subpaint_markov_colours_walk_the_transition_table() {
    let notes: Vec<TNote> = (0..7u64)
        .map(|i| tns(100 * i, 60 + (5 * i as u8) % 7, 0))
        .collect();
    let cyc = [0, 100, 0, 0, 0, 100, 100, 0, 0];
    let set = |order: u32, first: u32| {
        let mut n = notes.clone();
        n[0].sub = first;
        spx(
            n,
            &[
                on("n02"),
                list("n02.palette", &[1, 2, 3]),
                list("n02.trans", &cyc),
                ch("n02.order", order),
            ],
        )
    };
    // Time order from the first note's own entry: 0, 1, 2, 0, …
    assert_eq!(subs_of(&set(0, 0)), vec![0, 1, 2, 0, 1, 2, 0]);
    assert_eq!(subs_of(&set(0, 2)), vec![2, 0, 1, 2, 0, 1, 2]);
    // Pitch order: the chain runs from the lowest note up.
    let got = set(1, 0);
    let mut by_pitch: Vec<(u8, u32)> = got.iter().map(|x| (x.1, x.2)).collect();
    by_pitch.sort_unstable();
    assert_eq!(
        by_pitch.iter().map(|x| x.1).collect::<Vec<u32>>(),
        vec![0, 1, 2, 0, 1, 2, 0]
    );
    // A row without weights stays.
    let got = spx(
        notes.clone(),
        &[
            on("n02"),
            list("n02.palette", &[1, 2, 3]),
            list("n02.trans", &[0, 0, 0]),
        ],
    );
    assert!(subs_of(&got).iter().all(|&s| s == 0));
    // Weighted: only the allowed transitions, both taken, deterministic.
    let many: Vec<TNote> = (0..300u64).map(|i| tns(10 * i, 60, 0)).collect();
    let w = [
        (
            "n02.trans",
            ParamValue::List(vec![0, 50, 50, 100, 0, 0, 100, 0, 0]),
        ),
        ("n02.palette", ParamValue::List(vec![1, 2, 3])),
        on("n02"),
    ];
    let a = subs_of(&spx(many.clone(), &w));
    assert_eq!(a, subs_of(&spx(many, &w)));
    let mut seen = [0usize; 3];
    for p in a.windows(2) {
        match p[0] {
            0 => assert!(p[1] == 1 || p[1] == 2),
            _ => assert_eq!(p[1], 0),
        }
        if p[0] == 0 {
            seen[p[1] as usize] += 1;
        }
    }
    assert!(seen[1] > 30 && seen[2] > 30, "{seen:?}");
}

/// Three phrases: rising (0 – 300), falling (1000 – 1200), flat and longest
/// (2000 – 2400).
fn sp_phrases() -> Vec<TNote> {
    vec![
        tns(0, 60, 0),
        tns(100, 62, 0),
        tns(200, 64, 0),
        tns(1000, 70, 0),
        tns(1100, 67, 0),
        tns(2000, 65, 0),
        tns(2100, 65, 0),
        tns(2200, 65, 0),
        tns(2300, 65, 0),
    ]
}

#[test]
fn subpaint_phrase_colours_by_index_contour_or_length() {
    let by = |b: u32, pal: &[i64], rest: i64| {
        subs_of(&spx(
            sp_phrases(),
            &[
                on("n07"),
                ch("n07.by", b),
                list("n07.palette", pal),
                int("n07.rest", rest),
            ],
        ))
    };
    let per = |a: u32, b: u32, c: u32| [vec![a; 3], vec![b; 2], vec![c; 4]].concat();
    // Index: numbers 2, 4, 3 → positions 1, 3, 2.
    assert_eq!(by(0, &[2, 4, 3], 480), per(1, 3, 2));
    // Contour: up → first, down → second, flat → third.
    assert_eq!(by(1, &[2, 4, 3], 480), per(1, 3, 2));
    assert_eq!(by(1, &[1, 2], 480), per(0, 1, 0));
    // Length: 300, 200, 400 ticks → ranks 1, 0, 2.
    assert_eq!(by(2, &[1, 2, 3], 480), per(1, 0, 2));
    assert_eq!(by(2, &[1, 4], 480), per(0, 0, 3));
    // A longer split rest makes one phrase.
    assert_eq!(by(0, &[2, 4, 3], 1000), per(1, 1, 1));
}

/// The automaton on a dense `w` × `h` grid (columns of 240 ticks, rows of
/// keys from 60): one generation of `rule` (a plain grid oracle).
fn ca_oracle(g: &[Vec<u32>], rule: usize, eight: bool) -> Vec<Vec<u32>> {
    let (h, w) = (g.len() as i64, g[0].len() as i64);
    let maj = |ids: &[u32], own: Option<u32>| -> u32 {
        let mut best: Option<(usize, u32)> = None;
        let mut ks: Vec<u32> = ids.to_vec();
        ks.sort_unstable();
        ks.dedup();
        for id in ks {
            let c = ids.iter().filter(|&&x| x == id).count();
            let better = match best {
                None => true,
                Some((bc, bid)) => c > bc || (c == bc && Some(id) == own && Some(bid) != own),
            };
            if better {
                best = Some((c, id));
            }
        }
        best.unwrap().1
    };
    let mut out = g.to_vec();
    for r in 0..h {
        for c in 0..w {
            let own = g[r as usize][c as usize];
            let mut ids = Vec::new();
            for dr in -1..=1i64 {
                for dc in -1..=1i64 {
                    if (dr, dc) == (0, 0) || (!eight && dr != 0 && dc != 0) {
                        continue;
                    }
                    let (rr, cc) = (r + dr, c + dc);
                    if (0..h).contains(&rr) && (0..w).contains(&cc) {
                        ids.push(g[rr as usize][cc as usize]);
                    }
                }
            }
            out[r as usize][c as usize] = match rule {
                0 => {
                    ids.push(own);
                    maj(&ids, Some(own))
                }
                1 => {
                    let live: Vec<u32> = ids.into_iter().filter(|&x| x != 0).collect();
                    if own != 0 {
                        if live.len() == 2 || live.len() == 3 {
                            own
                        } else {
                            0
                        }
                    } else if live.len() == 3 {
                        maj(&live, None)
                    } else {
                        0
                    }
                }
                _ => {
                    let nx = (own + 1) % 4;
                    if ids.contains(&nx) { nx } else { own }
                }
            };
        }
    }
    out
}

/// Notes on a grid: row r (pitch 60 + r), column c (start 240·c), colour
/// g[r][c].
fn grid_notes(g: &[Vec<u32>]) -> Vec<TNote> {
    let mut v = Vec::new();
    for (r, row) in g.iter().enumerate() {
        for (c, &s) in row.iter().enumerate() {
            v.push(tns(240 * c as u64, 60 + r as u8, s));
        }
    }
    v
}

fn grid_of(v: &[(u64, u8, u32)], h: usize, w: usize) -> Vec<Vec<u32>> {
    let mut g = vec![vec![0u32; w]; h];
    for &(s, p, sub) in v {
        g[usize::from(p - 60)][(s / 240) as usize] = sub;
    }
    g
}

#[test]
fn subpaint_colour_automaton_matches_a_grid_oracle_for_every_rule() {
    // A pseudo-random 7 × 9 colouring.
    let mut x = 0x9E37_79B9u64;
    let g: Vec<Vec<u32>> = (0..7)
        .map(|_| {
            (0..9)
                .map(|_| {
                    x = x
                        .wrapping_mul(6364136223846793005)
                        .wrapping_add(1442695040888963407);
                    ((x >> 33) % 4) as u32
                })
                .collect()
        })
        .collect();
    for rule in [0usize, 2] {
        for eight in [false, true] {
            for gens in [1usize, 3] {
                let mut want = g.clone();
                for _ in 0..gens {
                    want = ca_oracle(&want, rule, eight);
                }
                let got = spx(
                    grid_notes(&g),
                    &[
                        on("n01"),
                        ch("n01.rule", rule as u32),
                        ch("n01.hood", u32::from(eight)),
                        int("n01.gens", gens as i64),
                    ],
                );
                assert_eq!(
                    grid_of(&got, 7, 9),
                    want,
                    "rule {rule}, eight {eight}, {gens}"
                );
            }
        }
    }
    // Life-like: a blinker (subchannel 2 on the background 0) flips.
    let mut b = vec![vec![0u32; 5]; 5];
    for row in b.iter_mut().take(4).skip(1) {
        row[2] = 2;
    }
    for gens in 1..=2usize {
        let got = spx(
            grid_notes(&b),
            &[on("n01"), ch("n01.rule", 1), int("n01.gens", gens as i64)],
        );
        let mut want = b.clone();
        for _ in 0..gens {
            want = ca_oracle(&want, 1, true);
        }
        assert_eq!(grid_of(&got, 5, 5), want, "{gens}");
    }
    assert_eq!(
        ca_oracle(&b, 1, true)[2],
        vec![0, 2, 2, 2, 0],
        "the oracle's blinker"
    );
    // Two notes in one cell start with their majority (a tie: the smaller).
    let pair = vec![tns(0, 60, 3), tns(0, 60, 1), tns(240, 60, 3)];
    let got = spx(pair, &[on("n01"), int("n01.gens", 1)]);
    assert_eq!(subs_of(&got), vec![1, 1, 3]);
}

#[test]
fn subpaint_reaction_diffusion_matches_a_dense_gray_scott_oracle() {
    use plumspirit_engine::transform::shared::seeded_stream::{salt_of, stream};
    let (h, w, seed) = (24usize, 32usize, 7u64);
    let g = vec![vec![0u32; w]; h];
    // The defaults (a labyrinth), spots, and few steps.
    for (feed, kill, steps) in [(2.9f64, 5.7f64, 400i64), (3.0, 6.2, 300), (2.9, 5.7, 25)] {
        let got = spx(
            grid_notes(&g),
            &[
                int("seed", seed as i64),
                on("n04"),
                fl("n04.feed", feed),
                fl("n04.kill", kill),
                int("n04.steps", steps),
            ],
        );
        // The oracle: the same sums in the same order (the sides above,
        // left, right, below, then the corners; weights 0.2 and 0.05;
        // nothing across the edges).
        let salt = salt_of("subpaint.n04");
        let mut u = vec![vec![1.0f32; w]; h];
        let mut v = vec![vec![0.0f32; w]; h];
        for r in 0..h {
            for c in 0..w {
                if stream(seed, salt, &[(60 + r as u64) / 4, c as u64 / 4]).chance(0.15) {
                    u[r][c] = 0.5;
                    v[r][c] = 0.25;
                }
            }
        }
        let (f, k) = ((feed / 100.0) as f32, (kill / 100.0) as f32);
        let sides = [(-1i64, 0i64), (0, -1), (0, 1), (1, 0)];
        let corners = [(-1i64, -1i64), (-1, 1), (1, -1), (1, 1)];
        for _ in 0..steps {
            let (mut u2, mut v2) = (u.clone(), v.clone());
            for r in 0..h as i64 {
                for c in 0..w as i64 {
                    // A missing neighbour counts as the cell itself.
                    let at = |g: &Vec<Vec<f32>>, &(dr, dc): &(i64, i64)| -> f32 {
                        let (rr, cc) = (r + dr, c + dc);
                        if (0..h as i64).contains(&rr) && (0..w as i64).contains(&cc) {
                            g[rr as usize][cc as usize]
                        } else {
                            g[r as usize][c as usize]
                        }
                    };
                    let sum = |set: &[(i64, i64)], g: &Vec<Vec<f32>>| -> f32 {
                        let x: Vec<f32> = set.iter().map(|d| at(g, d)).collect();
                        x[0] + x[1] + x[2] + x[3]
                    };
                    let (su, cu) = (sum(&sides, &u), sum(&corners, &u));
                    let (sv, cv) = (sum(&sides, &v), sum(&corners, &v));
                    let (uu, vv) = (u[r as usize][c as usize], v[r as usize][c as usize]);
                    let lu = 0.2 * (su - 4.0 * uu) + 0.05 * (cu - 4.0 * uu);
                    let lv = 0.2 * (sv - 4.0 * vv) + 0.05 * (cv - 4.0 * vv);
                    let uvv = uu * vv * vv;
                    u2[r as usize][c as usize] = (uu + lu - uvv + f * (1.0 - uu)).clamp(0.0, 1.0);
                    let nv = (vv + 0.5 * lv + uvv - (f + k) * vv).clamp(0.0, 1.0);
                    v2[r as usize][c as usize] = if nv < 1e-12 { 0.0 } else { nv };
                }
            }
            u = u2;
            v = v2;
        }
        let want: Vec<Vec<u32>> = v
            .iter()
            .map(|row| row.iter().map(|&x| u32::from(x > 0.2)).collect())
            .collect();
        assert_eq!(grid_of(&got, h, w), want, "feed {feed}, kill {kill}");
        // Both colours appear (a pattern, not a flood).
        let ones = want.iter().flatten().filter(|&&x| x == 1).count();
        assert!(ones > 0 && ones < h * w, "{ones}");
    }
}

#[test]
