        assert_eq!(a.notes, b.notes);
        assert_eq!(a.notes.len(), 192);
        let key = |n: &TNote| (n.track, n.start, n.dur, n.pitch, n.vel);
        let mut got: Vec<_> = a.notes.iter().map(key).collect();
        let mut src: Vec<_> = skew_fixture().iter().map(key).collect();
        got.sort_unstable();
        src.sort_unstable();
        assert_eq!(got, src);
