/// Neutral settings of v0.9 functions (the v0.9 path, the v0.8 result): a
/// shrink by nothing, every grid position within any distance, every tempo
/// above 1 BPM, chords of 1 – 1,000 notes, storing a slot — each alone,
/// then together.
fn sel_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n01",
            vec![
                on("n01"),
                ch("n01.mode", 1),
                int("n01.radius", 0),
                int("n01.rows", 0),
            ],
        ),
        (
            "n03",
            vec![on("n03"), list("n03.mask", &[1]), int("n03.tol", 1 << 40)],
        ),
        (
            "n08",
            vec![on("n08"), ch("n08.region", 2), fl("n08.bpm", 1.0)],
        ),
        (
            "n09",
            vec![on("n09"), int("n09.lo", 1), int("n09.hi", 1000)],
        ),
        ("n10", vec![on("n10"), ch("n10.op", 4)]),
    ];
    let all: Vec<(&'static str, ParamValue)> =
        each.iter().flat_map(|(_, s)| s.iter().cloned()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn sel_neutral_functions_take_the_v09_path_and_equal_v08() {
    for (f, neutral) in sel_neutral() {
        for (i, s) in sel_v08_settings().iter().enumerate() {
            let mut set = del_off(s);
            set.extend(neutral.iter().cloned());
            let r = run_full("select", del_fixture(), &set);
            assert_eq!(join_fingerprint(&r), SELECT_V08[i], "{f} setting {i}");
        }
    }
}

/// Runs Select on hand-built notes of one track (subchannels 0 – 3), with
/// `context` as the track's unselected notes, in `ctx`: the whole result
/// (within the kernel's estimate).
fn sel_run(
    notes: Vec<TNote>,
    context: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
    ctx: Ctx,
) -> plumspirit_engine::transform::TransformRun {
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(notes, vec![track]);
    let mut c = context;
    plumspirit_engine::transform::source::sort_time_major(&mut c);
    src.context = Arc::new(c);
    let t = tool("select").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b).unwrap();
    let est = k.estimate_source(&src);
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None).unwrap();
    assert!(r.notes.len() as u64 <= est.notes);
    r
}

/// The selected notes as (start, length, pitch, velocity, subchannel),
/// sorted.
fn sel_got(r: &plumspirit_engine::transform::TransformRun) -> Vec<(u64, u64, u8, u8, u32)> {
    del_kept(r)
}

/// Gap between two spans (0 when they meet or overlap).
fn span_gap(a: &TNote, b: &TNote) -> u64 {
    b.start
        .saturating_sub(a.end())
        .max(a.start.saturating_sub(b.end()))
}

#[test]
fn sel_grow_adds_notes_within_the_radius_and_rows_of_the_result() {
    for seed in 1..=10u64 {
        let notes = del_random(seed * 0xA11, 120, 50, 20, 12000);
        for (rad, rows) in [(0u64, 0i64), (60, 1), (300, 3)] {
            // The result so far: pitches 55 – 60 (a3); grown from the rest.
            let set = [
                on("a3"),
                int("a3.lo", 55),
                int("a3.hi", 60),
                on("n01"),
                int("n01.radius", rad as i64),
                int("n01.rows", rows),
            ];
            let r = sel_run(notes.clone(), Vec::new(), &set, Ctx::simple(960));
            let seed_set: Vec<usize> = (0..notes.len())
                .filter(|&i| (55..=60).contains(&notes[i].pitch))
                .collect();
            let want = del_expect(&notes, |i, x| {
                seed_set.contains(&i)
                    || seed_set.iter().any(|&j| {
                        i64::from(x.pitch).abs_diff(i64::from(notes[j].pitch)) <= rows as u64
                            && span_gap(x, &notes[j]) <= rad
                    })
            });
            assert_eq!(sel_got(&r), want, "seed {seed} radius {rad} rows {rows}");
        }
    }
    // Among the selected notes: the track's unselected notes join.
    let sel = vec![tn(0, 100, 60, 90), tn(1000, 100, 60, 90)];
    let ctx_notes = vec![
        tn(150, 10, 61, 70),
        tn(400, 10, 60, 70),
        tn(1110, 10, 63, 70),
    ];
    let r = sel_run(
        sel,
        ctx_notes,
        &[on("n01"), int("n01.radius", 60), int("n01.rows", 1)],
        Ctx::simple(960),
    );
    let starts: Vec<u64> = sel_got(&r).iter().map(|n| n.0).collect();
    assert_eq!(starts, vec![0, 150, 1000]);
}

#[test]
fn sel_shrink_removes_the_boundary_notes_of_the_result() {
    // A block of 7 rows × 9 cells of 240 ticks: shrinking by one cell and
    // one row leaves the 5 × 7 inside; by two the 3 × 5.
    let notes = del_block(60, 7, 9);
    let run = |rad: i64, rows: i64| {
        sel_got(&sel_run(
            notes.clone(),
            Vec::new(),
            &[
                on("n01"),
                ch("n01.mode", 1),
                int("n01.radius", rad),
                int("n01.rows", rows),
            ],
            Ctx::simple(960),
        ))
    };
    let inside = |d: u64| {
        del_expect(&notes, move |_, n| {
            let (c, r) = (n.start / 240, u64::from(n.pitch - 60));
            c >= d && c + d <= 8 && r >= d && r + d <= 6
        })
    };
    assert_eq!(run(240, 1), inside(1));
    assert_eq!(run(480, 2), inside(2));
    // Rows only: the top and bottom rows go.
    assert_eq!(
        run(0, 1),
        del_expect(&notes, |_, n| n.pitch > 60 && n.pitch < 66)
    );
    // Brute force on random notes: a note stays when the merged spans of
    // the result cover its widened span on every row in reach.
    for seed in 1..=8u64 {
        let notes = del_random(seed * 0x5A1, 160, 60, 6, 3000);
        for (rad, rows) in [(0u64, 1i64), (30, 0), (60, 2)] {
            let r = sel_run(
                notes.clone(),
                Vec::new(),
                &[
                    on("n01"),
                    ch("n01.mode", 1),
                    int("n01.radius", rad as i64),
                    int("n01.rows", rows),
                ],
                Ctx::simple(960),
            );
            let covered_on = |q: i64, a: u64, b: u64| -> bool {
                let mut spans: Vec<(u64, u64)> = notes
                    .iter()
                    .filter(|n| i64::from(n.pitch) == q && n.dur > 0)
                    .map(|n| (n.start, n.end()))
                    .collect();
                spans.sort_unstable();
                let mut reach = a;
                for (s, e) in spans {
                    if s <= reach {
                        reach = reach.max(e);
                    }
                }
                reach >= b
            };
            let want = del_expect(&notes, |_, x| {
                let (a, b) = (x.start.saturating_sub(rad), x.end() + rad);
                a >= b
                    || (x.start >= rad
                        && (i64::from(x.pitch) - rows..=i64::from(x.pitch) + rows)
                            .all(|q| covered_on(q, a, b)))
            });
            assert_eq!(sel_got(&r), want, "seed {seed} radius {rad} rows {rows}");
        }
    }
}

#[test]
fn sel_voice_select_picks_top_bottom_inner_or_a_rank_of_every_chord() {
    let mut notes: Vec<TNote> = [48u8, 55, 60, 64, 67]
        .iter()
        .map(|&p| tn(0, 960, p, 90))
        .collect();
    notes.extend([tn(1920, 480, 62, 90), tn(1925, 480, 69, 90)]);
    notes.push(tn(3840, 480, 40, 90));
    let pick = |voice: u32, rank: i64| -> Vec<u8> {
        let r = sel_run(
            notes.clone(),
            Vec::new(),
            &[on("n02"), ch("n02.voice", voice), int("n02.rank", rank)],
            Ctx::simple(960),
        );
        let mut v: Vec<u8> = r.notes.iter().map(|n| n.pitch).collect();
        v.sort_unstable();
        v
    };
    assert_eq!(pick(0, 1), vec![40, 67, 69]);
    assert_eq!(pick(1, 1), vec![40, 48, 62]);
    assert_eq!(pick(2, 1), vec![55, 60, 64]);
    assert_eq!(pick(3, 2), vec![55, 69]);
}

#[test]
fn sel_metric_select_keeps_notes_near_the_chosen_grid_positions() {
    // 4/4 at 960, 1/8 grid (480): starts every 50 ticks over two bars.
    let notes: Vec<TNote> = (0..154u64).map(|k| tn(k * 50, 40, 60, 90)).collect();
    for (mask, tol) in [(vec![0i64, 1], 10u64), (vec![1, 0, 0, 0], 60), (vec![1], 0)] {
        let r = sel_run(
            notes.clone(),
            Vec::new(),
            &[
                on("n03"),
                ch("n03.grid", 3),
                list("n03.mask", &mask),
                int("n03.tol", tol as i64),
            ],
            Ctx::simple(960),
        );
        // Every grid line with its slot (the bar line is slot 0).
        let want = del_expect(&notes, |_, n| {
            (0..=24u64).any(|k| {
                let line = k * 480;
                let slot = (k % 8) as usize;
                n.start.abs_diff(line) <= tol && mask[slot % mask.len()] == 1 && {
                    // The nearest line (ties: the later one).
                    let near = (n.start + 240) / 480;
                    near == k
                }
            })
        });
        assert_eq!(sel_got(&r), want, "{mask:?} ± {tol}");
    }
}

#[test]
fn sel_interval_select_measures_from_the_previous_onset_of_the_track() {
    // A melody with a chord: 60 → 67 (+7) → 65 (−2) → [64 72] (−1 from
    // 65 to 64; 72 from 65 is +7) → 64 (0 from the nearest, 64).
    let notes = vec![
        tn(0, 100, 60, 90),
        tn(480, 100, 67, 90),
        tn(960, 100, 65, 90),
        tn(1440, 100, 64, 90),
        tn(1440, 100, 72, 90),
        tn(1920, 100, 64, 90),
    ];
    let pick = |lo: i64, hi: i64, dir: u32| -> Vec<(u64, u8)> {
        let r = sel_run(
            notes.clone(),
            Vec::new(),
            &[
                on("n04"),
                int("n04.lo", lo),
                int("n04.hi", hi),
                ch("n04.dir", dir),
            ],
            Ctx::simple(960),
        );
        let mut v: Vec<(u64, u8)> = r.notes.iter().map(|n| (n.start, n.pitch)).collect();
        v.sort_unstable();
        v
    };
    assert_eq!(pick(5, 127, 2), vec![(480, 67), (1440, 72)]);
    assert_eq!(pick(1, 2, 1), vec![(960, 65), (1440, 64)]);
    assert_eq!(pick(1, 2, 0), vec![]);
    assert_eq!(pick(0, 0, 2), vec![(1920, 64)]);
    assert_eq!(pick(0, 127, 0), vec![(480, 67), (1440, 72), (1920, 64)]);
}

#[test]
fn sel_overlap_select_finds_each_kind_of_overlap() {
    for seed in 1..=10u64 {
        let notes = del_random(seed * 0x0E1, 120, 60, 3, 3000);
        for with_ch in [false, true] {
            let key = |n: &TNote| (n.pitch, if with_ch { n.ch } else { 0 });
            let meets = |a: &TNote, b: &TNote| {
                a.dur > 0 && b.dur > 0 && a.start < b.end() && b.start < a.end()
            };
            for kind in 0..4u32 {
                let r = sel_run(
                    notes.clone(),
                    Vec::new(),
                    &[
                        on("n05"),
                        ch("n05.kind", kind),
                        ch("n05.same", u32::from(with_ch)),
                    ],
                    Ctx::simple(960),
                );
                let want = del_expect(&notes, |i, x| match kind {
                    1 => notes.iter().enumerate().any(|(j, y)| {
                        j != i
                            && !y.muted()
                            && key(y) == key(x)
                            && y.dur > x.dur
                            && y.start <= x.start
                            && y.end() >= x.end()
                            && y.end() > x.start
                    }),
                    _ => notes.iter().enumerate().any(|(j, y)| {
                        j != i
                            && meets(x, y)
                            && match kind {
                                0 => key(y) == key(x),
                                2 => true,
                                _ => key(y) == key(x) && y.sub != x.sub,
                            }
                    }),
                });
                assert_eq!(
                    sel_got(&r),
                    want,
                    "seed {seed} kind {kind} channel {with_ch}"
                );
            }
        }
    }
}

#[test]
fn sel_outlier_select_finds_values_beyond_k_robust_deviations() {
    for seed in 1..=8u64 {
        let mut notes = del_random(seed * 0x0071, 150, 55, 12, 20000);
        // A few wrong notes far away.
        for k in [7usize, 40, 99] {
            notes[k].pitch = 110;
            notes[k].vel = 3;
        }
        for (prop, k, w) in [(0u32, 3.0f64, 3000u64), (1, 2.0, 6000), (2, 1.5, 2000)] {
            let r = sel_run(
                notes.clone(),
                Vec::new(),
                &[
                    on("n06"),
                    ch("n06.prop", prop),
                    fl("n06.k", k),
                    int("n06.window", w as i64),
                ],
                Ctx::simple(960),
            );
            let value = |n: &TNote| match prop {
                0 => n.pitch as f64,
                1 => n.vel as f64,
                _ => n.dur as f64,
            };
            let want = del_expect(&notes, |_, x| {
                let mut v: Vec<f64> = notes
                    .iter()
                    .filter(|y| y.start + w / 2 >= x.start && y.start <= x.start + w / 2)
                    .map(value)
                    .collect();
                if v.len() < 4 {
                    return false;
                }
                v.sort_by(f64::total_cmp);
                let q = |num: usize| v[num * (v.len() - 1) / 4];
                let dev = (value(x) - q(2)).abs();
                dev > 0.0 && dev > k * (q(3) - q(1)) / 1.349
            });
            assert_eq!(sel_got(&r), want, "seed {seed} property {prop}");
        }
    }
}

#[test]
fn sel_line_trace_follows_the_nearest_pitch_within_step_and_gap() {
    // A texture: a high line 72 74 76 74 72 and low chords 48/52 below it,
    // plus a far note the line cannot reach.
    let mut notes = Vec::new();
    for (k, p) in [72u8, 74, 76, 74, 72].iter().enumerate() {
        notes.push(tn(k as u64 * 480, 400, *p, 100));
        notes.push(tn(k as u64 * 480, 400, 48, 60));
        notes.push(tn(k as u64 * 480, 400, 52, 60));
    }
    notes.push(tn(9600, 400, 73, 100));
    let trace = |start: u32, step: i64, gap: i64| -> Vec<(u64, u8)> {
        let r = sel_run(
            notes.clone(),
            Vec::new(),
            &[
                on("n07"),
                ch("n07.start", start),
                int("n07.step", step),
                int("n07.gap", gap),
            ],
            Ctx::simple(960),
        );
        let mut v: Vec<(u64, u8)> = r.notes.iter().map(|n| (n.start, n.pitch)).collect();
        v.sort_unstable();
        v
    };
    let high = vec![(0, 72), (480, 74), (960, 76), (1440, 74), (1920, 72)];
    assert_eq!(trace(1, 4, 480), high);
    // The first selected note: the loudest of the first onset (72).
    assert_eq!(trace(0, 4, 480), high);
    assert_eq!(
        trace(2, 4, 480),
        vec![(0, 48), (480, 48), (960, 48), (1440, 48), (1920, 48)]
    );
    // A step of 1 stops the high line at once.
    assert_eq!(trace(1, 1, 480), vec![(0, 72)]);
    // A gap of 10000 reaches the far note.
    assert_eq!(trace(1, 4, 10000).last(), Some(&(9600, 73)));
    // Brute force on random notes.
    for seed in 1..=10u64 {
        let notes = del_random(seed * 0x71CE, 80, 60, 14, 6000);
        let r = sel_run(
            notes.clone(),
            Vec::new(),
            &[
                on("n07"),
                ch("n07.start", 1),
                int("n07.step", 3),
                int("n07.gap", 200),
            ],
            Ctx::simple(960),
        );
        let t0 = notes.iter().map(|n| n.start).min().unwrap();
        let mut c = (0..notes.len())
            .filter(|&i| notes[i].start == t0)
            .max_by_key(|&i| (notes[i].pitch, std::cmp::Reverse(i)))
            .unwrap();
        let mut line = vec![c];
        loop {
            let x = notes[c];
            let next = (0..notes.len())
                .filter(|&j| {
                    notes[j].start > x.start
                        && notes[j].start <= x.end() + 200
                        && notes[j].pitch.abs_diff(x.pitch) <= 3
                })
                .min_by_key(|&j| {
                    (
                        notes[j].start,
                        notes[j].pitch.abs_diff(x.pitch),
                        notes[j].pitch,
                        j,
                    )
                });
            match next {
                Some(j) => {
                    c = j;
                    line.push(j);
                }
                None => break,
            }
        }
        assert_eq!(
            sel_got(&r),
            del_expect(&notes, |i, _| line.contains(&i)),
            "seed {seed}"
        );
    }
}

#[test]
fn sel_region_select_takes_the_cursors_section_chapter_or_tempo() {
    let notes: Vec<TNote> = (0..20u64).map(|k| tn(k * 400, 100, 60, 90)).collect();
    let starts = |r: &plumspirit_engine::transform::TransformRun| -> Vec<u64> {
        let mut v: Vec<u64> = r.notes.iter().map(|n| n.start).collect();
        v.sort_unstable();
        v
    };
    let mut ctx = Ctx::simple(960);
    ctx.markers = Arc::new(vec![1000, 3000, 6000]);
    ctx.cursor = 3500;
    let r = sel_run(notes.clone(), Vec::new(), &[on("n08")], ctx.clone());
    assert_eq!(starts(&r), (8..15).map(|k| k * 400).collect::<Vec<u64>>());
    // Before the first marker: from the song start.
    ctx.cursor = 10;
    let r = sel_run(notes.clone(), Vec::new(), &[on("n08")], ctx.clone());
    assert_eq!(starts(&r), vec![0, 400, 800]);
    // A chapter holding the cursor.
    ctx.chapters = Arc::new(vec![(2000, 2900), (5000, 7000)]);
    ctx.cursor = 5500;
    let r = sel_run(
        notes.clone(),
        Vec::new(),
        &[on("n08"), ch("n08.region", 1)],
        ctx.clone(),
    );
    assert_eq!(starts(&r), vec![5200, 5600, 6000, 6400, 6800]);
    ctx.cursor = 4000;
    let r = sel_run(
        notes.clone(),
        Vec::new(),
        &[on("n08"), ch("n08.region", 1)],
        ctx.clone(),
    );
    assert!(r.notes.is_empty());
    assert!(r.message.as_deref().unwrap().contains("no chapter"));
    // Tempo: 120 BPM before 1920, 60 after.
    let tempo = qnt_stepped_tempo();
    let r = sel_run(
        notes.clone(),
        Vec::new(),
        &[on("n08"), ch("n08.region", 2), fl("n08.bpm", 90.0)],
        tempo.clone(),
    );
    assert_eq!(starts(&r), vec![0, 400, 800, 1200, 1600]);
    let r = sel_run(
        notes.clone(),
        Vec::new(),
        &[on("n08"), ch("n08.region", 3), fl("n08.bpm", 90.0)],
        tempo,
    );
    assert_eq!(r.notes.len(), 15);
}

#[test]
fn sel_chord_size_select_keeps_chords_in_the_size_range() {
    let mut notes = Vec::new();
    for (k, size) in [1u8, 2, 3, 4, 5, 6].iter().enumerate() {
        for v in 0..*size {
            notes.push(tn(k as u64 * 960 + u64::from(v), 480, 50 + v * 3, 90));
        }
    }
    let sizes = |lo: i64, hi: i64| -> Vec<u64> {
        let r = sel_run(
            notes.clone(),
            Vec::new(),
            &[on("n09"), int("n09.lo", lo), int("n09.hi", hi)],
            Ctx::simple(960),
        );
        let mut v: Vec<u64> = r.notes.iter().map(|n| n.start / 960).collect();
        v.sort_unstable();
        v.dedup();
        v
    };
    assert_eq!(sizes(3, 4), vec![2, 3]);
    assert_eq!(sizes(5, 1000), vec![4, 5]);
    assert_eq!(sizes(1, 1), vec![0]);
}

#[test]
fn sel_set_operations_combine_the_result_with_a_stored_slot() {
    use plumspirit_engine::transform::SlotNote;
    let notes: Vec<TNote> = (0..6u64)
        .map(|k| tn(k * 480, 100, 60 + k as u8, 90))
        .collect();
    let slot_note = |n: &TNote| SlotNote {
        track: TrackId(1),
        start: n.start,
        dur: n.dur,
        pitch: n.pitch,
        vel: n.vel,
        sub: n.sub,
        ch: n.ch,
    };
    // Slot 2: notes 2, 3 and one the track does not have here (an unselected
    // note at 5000), slot 1 empty.
    let mut ctx = Ctx::simple(960);
    let outside = tn(5000, 100, 40, 90);
    ctx.selection_slots = Arc::new(vec![
        Vec::new(),
        vec![
            slot_note(&notes[2]),
            slot_note(&notes[3]),
            slot_note(&outside),
        ],
    ]);
    let pitches = |op: u32, slot: i64| -> (Vec<u8>, Option<String>) {
        // The result so far: pitches 63 – 65 (a3).
        let r = sel_run(
            notes.clone(),
            Vec::new(),
            &[
                on("a3"),
                int("a3.lo", 63),
                int("a3.hi", 65),
                on("n10"),
                ch("n10.op", op),
                int("n10.slot", slot),
            ],
            ctx.clone(),
        );
        let mut v: Vec<u8> = r.notes.iter().map(|n| n.pitch).collect();
        v.sort_unstable();
        (v, r.message.clone())
    };
    assert_eq!(pitches(0, 2).0, vec![40, 62, 63, 64, 65]);
    assert_eq!(pitches(1, 2).0, vec![64, 65]);
    assert_eq!(pitches(2, 2).0, vec![63]);
    assert_eq!(pitches(3, 2).0, vec![40, 62, 64, 65]);
    assert_eq!(pitches(4, 2).0, vec![63, 64, 65]);
    let (v, msg) = pitches(0, 1);
    assert_eq!(v, vec![63, 64, 65]);
    assert!(msg.unwrap().contains("slot 1 is empty"));
}

#[test]
fn sel_outline_select_picks_the_outline_or_the_interior() {
    // A 5 × 5 block of one-cell notes with the centre missing.
    let mut notes = Vec::new();
    for r in 0..5u8 {
        for c in 0..5u64 {
            if (r, c) != (2, 2) {
                notes.push(tn(c * 240, 240, 60 + r, 90));
            }
        }
    }
    let pick = |sel: u32, hood: u32| {
        sel_got(&sel_run(
            notes.clone(),
            Vec::new(),
            &[on("n11"), ch("n11.select", sel), ch("n11.hood", hood)],
            Ctx::simple(960),
        ))
    };
    let pos = |n: &TNote| ((n.start / 240) as i64, i64::from(n.pitch) - 60);
    let border = |n: &TNote| {
        let (c, r) = pos(n);
        c == 0 || c == 4 || r == 0 || r == 4
    };
    let side = |n: &TNote| {
        let (c, r) = pos(n);
        (c - 2).abs() + (r - 2).abs() == 1
    };
    let corner = |n: &TNote| {
        let (c, r) = pos(n);
        (c - 2).abs() == 1 && (r - 2).abs() == 1
    };
    assert_eq!(pick(0, 0), del_expect(&notes, |_, n| border(n) || side(n)));
    assert_eq!(
        pick(1, 0),
        del_expect(&notes, |_, n| !(border(n) || side(n)))
    );
    assert_eq!(
        pick(0, 1),
        del_expect(&notes, |_, n| border(n) || side(n) || corner(n))
    );
    assert!(pick(1, 1).is_empty());
}

/// A sweep of the function's own parameter per note: the metric tolerance
/// growing along time selects late off-grid notes the early ones' tolerance
/// misses; an unrelated sweep leaves chord voices whole.
#[test]
fn sel_sweeps_apply_per_note_and_keep_chords_whole() {
    let notes: Vec<TNote> = (0..32u64).map(|k| tn(k * 960 + 100, 50, 60, 90)).collect();
    let mut set = vec![
        on("n03"),
        list("n03.mask", &[1]),
        int("n03.tol", 0),
        on("m.sweep"),
    ];
    for tg in plumspirit_engine::transform::definition::sweep_targets("select") {
        if tg.param == "n03.tol" {
            set.push((tg.on, ParamValue::Bool(true)));
            set.push((tg.graph, ParamValue::Curve(Curve::line(0.0, 1.0))));
        }
    }
    let r = sel_run(notes.clone(), Vec::new(), &set, Ctx::simple(960));
    let got: Vec<u64> = r.notes.iter().map(|n| n.start).collect();
    assert!(!got.contains(&100));
    assert!(got.contains(&(31 * 960 + 100)));
    let chord: Vec<TNote> = (0..5u8)
        .map(|k| tn(u64::from(k), 480, 60 + k, 90))
        .chain([tn(7680, 10, 40, 90)])
        .collect();
    let mut set = vec![on("n02"), on("m.sweep")];
    for tg in plumspirit_engine::transform::definition::sweep_targets("select") {
        if tg.param == "n06.k" {
            set.push((tg.on, ParamValue::Bool(true)));
        }
    }
    let r = sel_run(chord, Vec::new(), &set, Ctx::simple(960));
    let mut p: Vec<u8> = r.notes.iter().map(|n| n.pitch).collect();
    p.sort_unstable();
    assert_eq!(p, vec![40, 64]);
}

/// All eleven new functions with frozen ones: deterministic, every result
/// note one of the pool's.
#[test]
fn sel_all_functions_compose_deterministically() {
    let mut set = vec![on("a3"), int("a3.lo", 30), int("a3.hi", 100)];
    for f in ALL11 {
        set.push(on(f));
    }
    set.extend([
        list("n03.mask", &[1]),
        int("n03.tol", 1 << 30),
        int("n04.lo", 0),
        ch("n08.region", 2),
        fl("n08.bpm", 1.0),
        int("n09.lo", 1),
    ]);
    let a = sel_run(del_fixture(), Vec::new(), &set, Ctx::simple(960));
    let b = sel_run(del_fixture(), Vec::new(), &set, Ctx::simple(960));
    assert_eq!(a.notes, b.notes);
    let src = del_fixture();
    for n in &a.notes {
        assert!(
            src.iter()
                .any(|s| s.start == n.start && s.pitch == n.pitch && s.dur == n.dur)
        );
    }
}

// ======================================================================= Draw

/// A pointer stroke from (tick, pitch) samples, `dt` seconds apart.
fn draw_stroke_dt(pts: &[(u64, f64)], dt: f64) -> Arc<plumspirit_engine::transform::Stroke> {
    Arc::new(plumspirit_engine::transform::Stroke {
        points: pts
            .iter()
            .enumerate()
            .map(
                |(i, &(tick, pitch))| plumspirit_engine::transform::StrokePoint {
                    tick,
                    pitch,
                    t: i as f64 * dt,
                },
            )
            .collect(),
    })
}

/// A pointer stroke from (tick, pitch) samples 0.05 s apart.
fn draw_stroke(pts: &[(u64, f64)]) -> Arc<plumspirit_engine::transform::Stroke> {
    draw_stroke_dt(pts, 0.05)
}

/// Draw's fixture stroke: a wavy line over ~6,600 ticks drawn at a varying
/// speed, which doubles back once (ticks 3,000 → 2,600 → 3,300).
fn draw_fixture_stroke() -> Arc<plumspirit_engine::transform::Stroke> {
    let mut points = Vec::new();
    let mut t = 0.0;
    for k in 0..48u64 {
        let tick = if k < 24 {
            k * 125 + (k % 5) * 11
        } else if k < 28 {
            3000 - (k - 24) * 100
        } else {
            2600 + (k - 28) * 200
        };
        let pitch = 60.0 + 9.0 * (k as f64 / 7.0).sin() + 0.3 * (k % 3) as f64;
        t += 0.01 + 0.002 * (k % 7) as f64;
        points.push(plumspirit_engine::transform::StrokePoint { tick, pitch, t });
    }
    Arc::new(plumspirit_engine::transform::Stroke { points })
}

/// Draw's fixture selection (passes through; the motif of a8): three notes
/// on subchannel 1.
fn draw_fixture_notes() -> Vec<TNote> {
    vec![
        TNote {
            sub: 1,
            ch: 1,
            ..tn(0, 120, 60, 90)
        },
        TNote {
            sub: 1,
            ch: 1,
            ..tn(120, 120, 64, 80)
        },
        TNote {
            sub: 1,
            ch: 1,
            ..tn(240, 240, 67, 100)
        },
    ]
}

/// Runs Draw on a hand-built source: `notes` selected on one track
/// (subchannels 0 – 3, channel = subchannel), `context` its unselected notes,
/// `aux` the prepared layers, with `stroke` in `Ctx::simple(960)` changed by
/// `tweak`; the whole result (within the kernel's estimate).
fn draw_try(
    notes: Vec<TNote>,
    context: Vec<TNote>,
    aux: Vec<Vec<TNote>>,
    stroke: Option<Arc<plumspirit_engine::transform::Stroke>>,
    set: &[(&'static str, ParamValue)],
    tweak: impl FnOnce(&mut Ctx),
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(notes, vec![track]);
    let mut c = context;
    plumspirit_engine::transform::source::sort_time_major(&mut c);
    src.context = Arc::new(c);
    src.aux = Arc::new(aux);
    let t = tool("draw").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = Ctx::simple(960);
    ctx.stroke = stroke;
    tweak(&mut ctx);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate(&src.stats).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

/// Draw on the fixture (its stroke and selection).
fn draw_fix(set: &[(&'static str, ParamValue)]) -> plumspirit_engine::transform::TransformRun {
    draw_try(
        draw_fixture_notes(),
        Vec::new(),
        Vec::new(),
        Some(draw_fixture_stroke()),
        set,
        |_| {},
    )
    .unwrap()
}

