#[test]
fn draw_gate_sweep_sets_each_drawn_notes_length_by_its_time() {
    let st = draw_stroke(&[(0, 62.5), (3840, 62.5)]);
    let gate = plumspirit_engine::transform::definition::sweep_targets("draw")
        .iter()
        .find(|t| t.param == "gate")
        .copied()
        .unwrap();
    let r = draw_only(
        st,
        &[
            ch("step", 4),
            on("m.sweep"),
            (gate.on, ParamValue::Bool(true)),
            (gate.graph, ParamValue::Curve(Curve::line(0.0, 1.0))),
        ],
    );
    // Position k of 17 at u = k / 16: gate 25 % … 200 %.
    let want: Vec<(u64, u8, u64)> = (0..=16u64)
        .map(|k| {
            let u = (k * 240) as f64 / 3840.0;
            let g = (25.0 + u * 175.0) / 100.0;
            (k * 240, 62, ((240.0 * g).round() as u64).max(1))
        })
        .collect();
    assert_eq!(spd(&r.notes), want);
}

#[test]
fn draw_tolerance_sweep_recognizes_the_shape_where_it_is_loose_enough() {
    let pts = shaky_line();
    let st = draw_stroke(&pts);
    let tol = plumspirit_engine::transform::definition::sweep_targets("draw")
        .iter()
        .find(|t| t.param == "n07.tol")
        .copied()
        .unwrap();
    let base = [
        ch("step", 4),
        on("n07"),
        ch("n07.shapes", 2),
        fl("n07.tol", 1.0),
    ];
    let plain = pitches(&draw_only(st.clone(), &[ch("step", 4)]).notes);
    let line = {
        let mut s = base.to_vec();
        s.push(fl("n07.tol", 100.0));
        pitches(&draw_only(st.clone(), &s).notes)
    };
    // A step graph: tolerance 1 % in the first half, 100 % after it.
    let mut s = base.to_vec();
    s.extend([
        on("m.sweep"),
        (tol.on, ParamValue::Bool(true)),
        (
            tol.graph,
            ParamValue::Curve(Curve::new(vec![
                (0.0, 0.0),
                (0.49, 0.0),
                (0.51, 1.0),
                (1.0, 1.0),
            ])),
        ),
    ]);
    let got = pitches(&draw_only(st, &s).notes);
    let n = got.len();
    assert_eq!(n, plain.len());
    for k in 0..n {
        let u = (k * 240) as f64 / ((n - 1) * 240) as f64;
        if u < 0.45 {
            assert_eq!(got[k], plain[k], "position {k}");
        } else if u > 0.55 {
            assert_eq!(got[k], line[k], "position {k}");
        }
    }
    assert_ne!(got, plain);
    assert_ne!(got, line);
}

/// E0422's rule for Draw (its stroke in the context, so the kernel runs):
/// a Control Sweep flat at the parameter's own value changes nothing, with
/// its function on; a sweep of a function that is off changes nothing.
#[test]
fn draw_flat_sweeps_and_sweeps_of_functions_that_are_off_change_nothing() {
    use plumspirit_engine::transform::definition::{Combine, sweep_targets};
    use plumspirit_engine::transform::param::ParamKind;
    let spec = (tool("draw").unwrap().spec)();
    let mut checked = 0;
    for tg in sweep_targets("draw") {
        assert!(matches!(tg.combine, Combine::Replace));
        let ps = spec.params.iter().find(|p| p.key == tg.param).unwrap();
        let lo = tg.range.0.min(tg.range.1);
        let v = match ps.kind {
            ParamKind::Float { .. } => ParamValue::Float(lo),
            _ => ParamValue::Int(lo.round() as i64),
        };
        let owner: &'static str = Box::leak(
            tg.param
                .split('.')
                .next()
                .unwrap()
                .to_string()
                .into_boxed_str(),
        );
        let mut base = vec![(tg.param, v)];
        if tg.param.contains('.') {
            base.push((owner, ParamValue::Bool(true)));
            if owner == "n07" {
                base.push(ch("n07.shapes", 2));
            }
        }
        let a = draw_fix(&base);
        let mut swept = base.clone();
        swept.extend([
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::flat(0.0))),
        ]);
        assert_eq!(
            join_fingerprint(&a),
            join_fingerprint(&draw_fix(&swept)),
            "flat {}",
            tg.param
        );
        checked += 1;
    }
    // Every function alone against every target of another function (off).
    for f in ALL11 {
        let a = draw_fix(&[on(f)]);
        for tg in sweep_targets("draw")
            .iter()
            .filter(|t| t.param.starts_with('n'))
        {
            let owner: &'static str = Box::leak(
                tg.param
                    .split('.')
                    .next()
                    .unwrap()
                    .to_string()
                    .into_boxed_str(),
            );
            if owner == f {
                continue;
            }
            let swept = vec![
                on(f),
                on("m.sweep"),
                (tg.on, ParamValue::Bool(true)),
                (owner, ParamValue::Bool(false)),
            ];
            assert_eq!(
                join_fingerprint(&a),
                join_fingerprint(&draw_fix(&swept)),
                "{f} (sweep {})",
                tg.param
            );
            checked += 1;
        }
    }
    assert!(checked >= 10 + 11 * 4, "{checked}");
}

#[test]
fn draw_results_stay_within_the_estimate_and_are_deterministic() {
    let st = draw_fixture_stroke();
    let heavy = [
        on("a7"),
        ch("a7.mode", 2),
        on("a8"),
        on("a10"),
        on("n04"),
        list("n04.chord", &[0, 3, 7, 10]),
        on("n05"),
        list("n05.lines", &[-2, 2, 4]),
        on("n07"),
        ch("n07.shapes", 1),
        on("n09"),
        on("n10"),
        on("n11"),
    ];
    let a = draw_try(
        draw_fixture_notes(),
        Vec::new(),
        Vec::new(),
        Some(st.clone()),
        &heavy,
        |_| {},
    )
    .unwrap();
    let b = draw_try(
        draw_fixture_notes(),
        Vec::new(),
        Vec::new(),
        Some(st),
        &heavy,
        |_| {},
    )
    .unwrap();
    assert_eq!(join_fingerprint(&a), join_fingerprint(&b));
    assert!(a.notes.len() > 100);
    // Without a stroke: the selection and the hint, whatever is on.
    let none = draw_try(
        draw_fixture_notes(),
        Vec::new(),
        Vec::new(),
        None,
        &heavy,
        |_| {},
    )
    .unwrap();
    assert_eq!(none.notes.len(), 3);
    assert!(
        none.message
            .as_deref()
            .unwrap()
            .contains("Drag in the Piano Roll")
    );
}

