/// Paint's fixture selection (passes through; a6's stamp): three notes on
/// subchannel 1.
fn brush_fixture_notes() -> Vec<TNote> {
    draw_fixture_notes()
}

/// Runs the Note Brush (`paint`) on a hand-built source: `notes` selected on
/// one track (subchannels 0 – 3, channel = subchannel), `context` its
/// unselected notes, `aux` the prepared layers (other visible tracks, one
/// slot each from 1), with `stroke` in `Ctx::simple(960)` changed by
/// `tweak`; the whole result (within the kernel's estimate for this
/// source).
fn brush_try(
    notes: Vec<TNote>,
    context: Vec<TNote>,
    aux: Vec<Vec<TNote>>,
    stroke: Option<Arc<plumspirit_engine::transform::Stroke>>,
    set: &[(&'static str, ParamValue)],
    tweak: impl FnOnce(&mut Ctx),
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let track = |index: usize, insert_only: bool| SourceTrack {
        id: TrackId(index as u32 + 1),
        index,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only,
        frame: 0,
    };
    let mut tracks = vec![track(0, false)];
    for i in 0..aux.len() {
        tracks.push(track(i + 1, true));
    }
    let mut src = Source::from_notes(notes, tracks);
    let mut c = context;
    plumspirit_engine::transform::source::sort_time_major(&mut c);
    src.context = Arc::new(c);
    src.aux = Arc::new(aux);
    let t = tool("paint").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = Ctx::simple(960);
    ctx.stroke = stroke;
    tweak(&mut ctx);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate_source(&src).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

/// Paint on the fixture (Draw's stroke, which doubles back, and the
/// selection).
fn brush_fix(set: &[(&'static str, ParamValue)]) -> plumspirit_engine::transform::TransformRun {
    brush_try(
        brush_fixture_notes(),
        Vec::new(),
        Vec::new(),
        Some(draw_fixture_stroke()),
        set,
        |_| {},
    )
    .unwrap()
}

