/// The settings with every new function's switch off.
fn brush_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

#[test]
fn brush_new_functions_off_leave_v08_results_unchanged() {
    let got: Vec<(usize, usize, u64)> = brush_v08_settings()
        .iter()
        .map(|s| join_fingerprint(&brush_fix(&brush_off(s))))
        .collect();
    assert_eq!(got.len(), BRUSH_V08.len());
    for (i, (g, w)) in got.iter().zip(BRUSH_V08).enumerate() {
        assert_eq!(g, w, "setting {i}");
    }
}

/// Neutral settings of v0.9 functions (the v0.9 path, the v0.8 result): a
/// one-cell pattern that paints, stamps turned by 0° at their size, the
/// dither at 100 %, the chromatic scale's rows — each alone, then together.
fn brush_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n04",
            vec![on("n04"), list("n04.pattern", &[1]), int("n04.width", 1)],
        ),
        (
            "n07",
            vec![on("n07"), fl("n07.rot", 0.0), fl("n07.scale", 0.0)],
        ),
        ("n08", vec![on("n08"), fl("n08.level", 100.0)]),
        (
            "n09",
            vec![on("n09"), ch("n09.key", 5), ch("n09.scale", 19)],
        ),
    ];
    let all: Vec<(&'static str, ParamValue)> =
        each.iter().flat_map(|(_, s)| s.iter().cloned()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn brush_neutral_functions_take_the_v09_path_and_equal_v08() {
    for (f, neutral) in brush_neutral() {
        for (i, s) in brush_v08_settings().iter().enumerate() {
            let mut set = brush_off(s);
            set.extend(neutral.iter().cloned());
            assert_eq!(
                join_fingerprint(&brush_fix(&set)),
                BRUSH_V08[i],
                "{f} setting {i}"
            );
        }
    }
}

/// The Note Brush on a stroke with nothing selected: what it paints.
fn brush_only(
    st: Arc<plumspirit_engine::transform::Stroke>,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    brush_try(Vec::new(), Vec::new(), Vec::new(), Some(st), set, |_| {}).unwrap()
}

/// The cells (column of 240 ticks, key) of `notes`, sorted.
fn brush_cells(notes: &[TNote]) -> Vec<(u64, u8)> {
    let mut v: Vec<(u64, u8)> = notes.iter().map(|n| (n.start / 240, n.pitch)).collect();
    v.sort_unstable();
    v
}

/// A box outline of unselected notes (cells of 240 ticks): rows 60 and 66
/// across columns 0 – 9, columns 0 and 9 on rows 61 – 65; its interior is
/// columns 1 – 8 × rows 61 – 65 (40 cells). `top` replaces the top row.
fn brush_box(top: &[(u64, u64)]) -> Vec<TNote> {
    let mut v = vec![tn(0, 2400, 60, 70)];
    for &(s, d) in top {
        v.push(tn(s, d, 66, 70));
    }
    for p in 61..=65 {
        v.push(tn(0, 240, p, 70));
        v.push(tn(2160, 240, p, 70));
    }
    v
}

#[test]
fn brush_fill_bucket_fills_the_enclosed_region_and_leaves_open_or_large_ones() {
    let st = draw_stroke(&[(600, 63.5), (900, 63.5)]);
    let fill = |top: &[(u64, u64)], extra: &[(&'static str, ParamValue)]| {
        let mut set = vec![ch("step", 4), on("n02")];
        set.extend(extra.iter().cloned());
        brush_try(
            Vec::new(),
            brush_box(top),
            Vec::new(),
            Some(st.clone()),
            &set,
            |_| {},
        )
        .unwrap()
    };
    let interior: Vec<(u64, u8)> = (1..=8u64)
        .flat_map(|c| (61..=65u8).map(move |r| (c, r)))
        .collect();
    let mut want = interior.clone();
    want.sort_unstable();
    let r = fill(&[(0, 2400)], &[]);
    assert_eq!(brush_cells(&r.notes), want);
    assert!(r.notes.iter().all(|n| n.dur == 240 && n.vel == 100));
    assert!(r.erase.is_empty());
    assert!(
        r.message
            .as_deref()
            .unwrap()
            .contains("Filled 1 region(s), 40 cell(s)")
    );
    // A one-cell gap in the top row (ticks 960 – 1200): open, unless the
    // boundary gap closes it.
    let gap = [(0u64, 960u64), (1200, 1200)];
    let open = fill(&gap, &[]);
    assert!(open.notes.is_empty());
    assert!(open.message.as_deref().unwrap().contains("not enclosed"));
    assert!(
        fill(&gap, &[int("n02.gap", 239)]).notes.is_empty(),
        "a 240-tick gap stays open below 240"
    );
    assert_eq!(brush_cells(&fill(&gap, &[int("n02.gap", 240)]).notes), want);
    // More cells than allowed: not filled.
    let big = fill(&[(0, 2400)], &[int("n02.most", 39)]);
    assert!(big.notes.is_empty());
    assert!(big.message.as_deref().unwrap().contains("Most cells"));
    assert_eq!(fill(&[(0, 2400)], &[int("n02.most", 40)]).notes.len(), 40);
    // Whole rows: one note per row of the region.
    let rows = fill(&[(0, 2400)], &[ch("n02.fill", 1)]);
    assert_eq!(
        spd(&rows.notes),
        (61..=65u8).map(|p| (240, p, 1920)).collect::<Vec<_>>()
    );
    // A stroke on the outline only: nothing.
    let on_wall = brush_try(
        Vec::new(),
        brush_box(&[(0, 2400)]),
        Vec::new(),
        Some(draw_stroke(&[(100, 60.5), (2300, 60.5)])),
        &[ch("step", 4), on("n02")],
        |_| {},
    )
    .unwrap();
    assert!(on_wall.notes.is_empty());
    // The flood equals a brute-force flood of the cell grid.
    let walls: Vec<TNote> = brush_box(&[(0, 2400)]);
    let is_wall = |c: i64, r: i64| {
        walls.iter().any(|n| {
            i64::from(n.pitch) == r && n.start < (c as u64 + 1) * 240 && n.end() > c as u64 * 240
        })
    };
    let mut seen = std::collections::BTreeSet::new();
    let mut q = vec![(2i64, 63i64)];
    seen.insert((2, 63));
    while let Some((c, r)) = q.pop() {
        for (dc, dr) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
            let (nc, nr) = (c + dc, r + dr);
            assert!((0..=9).contains(&nc) && (60..=66).contains(&nr), "leaked");
            if !is_wall(nc, nr) && seen.insert((nc, nr)) {
                q.push((nc, nr));
            }
        }
    }
    let brute: Vec<(u64, u8)> = seen.into_iter().map(|(c, r)| (c as u64, r as u8)).collect();
    assert_eq!(brute, want);
}

/// n03's dice (the kernel's seeded stream per cell).
fn brush_soft_roll(seed: u64, col: u64, row: i64) -> f64 {
    use plumspirit_engine::transform::rng::{Rng, hash};
    Rng::for_index(seed, 0xBA17_0003, hash(&[col, row as u64])).unit()
}

#[test]
fn brush_soft_brush_paints_discs_whose_density_falls_off_by_the_hardness() {
    // One painted cell (column 10, row 70).
    let st = draw_stroke(&[(2400, 70.5)]);
    let disc = |r: i64, h: f64| -> Vec<(u64, u8)> {
        let mut v = Vec::new();
        for dy in -r..=r {
            for dx in -r..=r {
                let d = ((dx * dx + dy * dy) as f64).sqrt();
                if d > r as f64 {
                    continue;
                }
                let (col, row) = ((10 + dx) as u64, 70 + dy);
                let hh = h / 100.0;
                if d > hh * r as f64 {
                    let p = (r as f64 - d) / (r as f64 * (1.0 - hh));
                    if brush_soft_roll(1, col, row) >= p {
                        continue;
                    }
                }
                v.push((col, row as u8));
            }
        }
        v.sort_unstable();
        v
    };
    let soft = |r: i64, h: f64| {
        brush_cells(
            &brush_only(
                st.clone(),
                &[
                    ch("step", 4),
                    on("n03"),
                    int("n03.radius", r),
                    fl("n03.hard", h),
                ],
            )
            .notes,
        )
    };
    // Hard: the whole disc (49 cells within radius 4).
    assert_eq!(soft(4, 100.0).len(), 49);
    assert_eq!(soft(4, 100.0), disc(4, 100.0));
    for (r, h) in [(4, 50.0), (8, 0.0), (12, 30.0), (1, 0.0)] {
        assert_eq!(soft(r, h), disc(r, h), "radius {r} hardness {h}");
    }
    // The density falls off: inner ring fuller than the outer ring.
    let s = soft(12, 0.0);
    let ring = |a: f64, b: f64| {
        let mut n = (0, 0);
        for dy in -12i64..=12 {
            for dx in -12i64..=12 {
                let d = ((dx * dx + dy * dy) as f64).sqrt();
                if d >= a && d < b {
                    n.1 += 1;
                    if s.binary_search(&((10 + dx) as u64, (70 + dy) as u8))
                        .is_ok()
                    {
                        n.0 += 1;
                    }
                }
            }
        }
        n.0 as f64 / n.1 as f64
    };
    assert!(ring(0.0, 4.0) > ring(4.0, 8.0) && ring(4.0, 8.0) > ring(8.0, 12.0));
    assert!(s.contains(&(10, 70)), "the centre is always painted");
    // Two strokes' discs agree where they overlap (the dice are the cell's).
    let two = brush_cells(
        &brush_only(
            draw_stroke(&[(2400, 70.5), (2640, 70.5)]),
            &[
                ch("step", 4),
                on("n03"),
                int("n03.radius", 6),
                fl("n03.hard", 0.0),
            ],
        )
        .notes,
    );
    let one = soft(6, 0.0);
    for c in &one {
        assert!(two.binary_search(c).is_ok(), "{c:?}");
    }
}

#[test]
fn brush_pattern_brush_paints_the_tiles_of_the_cells_it_passes() {
    // A 3-wide tile of two rows (bottom row first): 1 0 1 / 0 1 0.
    let st = draw_stroke(&[(0, 62.5), (2399, 62.5)]);
    let r = brush_only(
        st,
        &[
            ch("step", 4),
            on("n04"),
            list("n04.pattern", &[1, 0, 1, 0, 1, 0]),
            int("n04.width", 3),
        ],
    );
    // Columns 0 – 9 on row 62: tiles at columns 0, 3, 6, 9 (rows 62 – 63).
    let mut want = Vec::new();
    for ox in [0u64, 3, 6, 9] {
        want.extend([(ox, 62u8), (ox + 2, 62), (ox + 1, 63)]);
    }
    want.sort_unstable();
    assert_eq!(brush_cells(&r.notes), want);
    // Every painted cell is a 1 of its tile.
    let pat = [1, 0, 1, 0, 1, 0];
    for (c, p) in brush_cells(&r.notes) {
        let (x, y) = (c % 3, (p as u64 - 62) % 2);
        assert_eq!(pat[(y * 3 + x) as usize], 1);
    }
    // An all-zero pattern paints nothing.
    let none = brush_only(
        draw_stroke(&[(0, 62.5), (2399, 62.5)]),
        &[ch("step", 4), on("n04"), list("n04.pattern", &[0, 0])],
    );
    assert!(none.notes.is_empty());
}

#[test]
fn brush_dither_brush_keeps_the_cells_below_the_bayer_threshold() {
    // The footprint: a hard disc of radius 3 round column 10, row 70.
    let st = draw_stroke(&[(2400, 70.5)]);
    let run = |level: f64, matrix: u32| {
        brush_cells(
            &brush_only(
                st.clone(),
                &[
                    ch("step", 4),
                    on("n03"),
                    int("n03.radius", 3),
                    fl("n03.hard", 100.0),
                    on("n08"),
                    fl("n08.level", level),
                    ch("n08.matrix", matrix),
                ],
            )
            .notes,
        )
    };
    let disc: Vec<(u64, u8)> = {
        let mut v = Vec::new();
        for dy in -3i64..=3 {
            for dx in -3i64..=3 {
                if dx * dx + dy * dy <= 9 {
                    v.push(((10 + dx) as u64, (70 + dy) as u8));
                }
            }
        }
        v.sort_unstable();
        v
    };
    // Bayer 2 × 2 [[0, 2], [3, 1]] at 50 %: thresholds 1/8 and 3/8 pass —
    // the cells whose column and row have the same parity.
    let want: Vec<(u64, u8)> = disc
        .iter()
        .copied()
        .filter(|&(c, r)| c % 2 == u64::from(r) % 2)
        .collect();
    assert_eq!(run(50.0, 0), want);
    assert_eq!(run(100.0, 0), disc);
    assert!(run(0.0, 2).is_empty());
    // 4 × 4 at 25 %: values 0 – 3 of the matrix, a quarter of each tile.
    let b4 = |x: u64, y: u64| -> u64 {
        let b2 = [[0u64, 2], [3, 1]];
        4 * b2[(y % 2) as usize][(x % 2) as usize]
            + b2[((y / 2) % 2) as usize][((x / 2) % 2) as usize]
    };
    let want4: Vec<(u64, u8)> = disc
        .iter()
        .copied()
        .filter(|&(c, r)| b4(c % 4, u64::from(r) % 4) < 4)
        .collect();
    assert_eq!(run(25.0, 1), want4);
}

#[test]
fn brush_scale_rows_paint_only_the_keys_of_the_scale() {
    let st = draw_stroke(&[(0, 59.5), (2879, 72.5)]);
    let plain = brush_only(st.clone(), &[ch("step", 4)]);
    let major = [0u8, 2, 4, 5, 7, 9, 11];
    let r = brush_only(st.clone(), &[ch("step", 4), on("n09")]);
    let want: Vec<(u64, u8, u64)> = spd(&plain.notes)
        .into_iter()
        .filter(|n| major.contains(&(n.1 % 12)))
        .collect();
    assert_eq!(spd(&r.notes), want);
    assert!(r.notes.len() < plain.notes.len());
    assert_eq!(
        r.message.as_deref().unwrap(),
        format!("{} painted note(s).", want.len())
    );
    // Chord tones off the scale are skipped too (D minor: no F#).
    let chord = brush_only(
        st,
        &[
            ch("step", 4),
            on("a3"),
            list("a3.chord", &[0, 1, 4]),
            on("n09"),
            ch("n09.key", 2),
            ch("n09.scale", 1),
        ],
    );
    let dminor = [2u8, 4, 5, 7, 9, 10, 0];
    assert!(!chord.notes.is_empty());
    assert!(chord.notes.iter().all(|n| dminor.contains(&(n.pitch % 12))));
}

/// The editing fixture: a stroke along key 62 over columns 0 – 7 (ticks 0 –
/// 1,919); selected notes, the track's unselected notes, an Onion Skin
/// track's notes (slot 1).
fn brush_edit_fixture() -> (
    Arc<plumspirit_engine::transform::Stroke>,
    Vec<TNote>,
    Vec<TNote>,
    Vec<Vec<TNote>>,
) {
    let st = draw_stroke(&[(0, 62.5), (1919, 62.5)]);
    let sel = vec![tn(480, 100, 62, 100), tn(480, 100, 70, 100)];
    let ctx = vec![
        tn(960, 240, 62, 90),
        TNote {
            sub: 1,
            ch: 1,
            ..tn(1200, 100, 62, 90)
        },
        tn(3000, 100, 62, 90),
        tn(240, 100, 63, 90),
    ];
    let aux = vec![vec![TNote {
        track: 1,
        ..tn(720, 240, 62, 80)
    }]];
    (st, sel, ctx, aux)
}

fn brush_edit(set: &[(&'static str, ParamValue)]) -> plumspirit_engine::transform::TransformRun {
    let (st, sel, ctx, aux) = brush_edit_fixture();
    let mut s = vec![ch("step", 4)];
    s.extend(set.iter().cloned());
    brush_try(sel, ctx, aux, Some(st), &s, |_| {}).unwrap()
}

/// (start, length, key, velocity, subchannel, slot) sorted.
fn brush_rows(v: &[TNote]) -> Vec<(u64, u64, u8, u8, u32, u16)> {
    let mut o: Vec<_> = v
        .iter()
        .map(|n| (n.start, n.dur, n.pitch, n.vel, n.sub, n.track))
        .collect();
    o.sort_unstable();
    o
}

#[test]
fn brush_eraser_removes_the_notes_under_the_stroke_by_owner_colour_and_rows() {
    let (_, sel, ctx, aux) = brush_edit_fixture();
    // Brute force: under columns 0 – 7, on keys 62 ± rows.
    let under = |n: &TNote, rows: i64| {
        let lo = 62 - rows / 2;
        let hi = 62 + (rows - 1 - rows / 2);
        (lo..=hi).contains(&i64::from(n.pitch)) && n.start < 1920
    };
    for (who, rows) in [(1u32, 1i64), (2, 1), (0, 1), (1, 3), (0, 3)] {
        let r = brush_edit(&[on("n01"), ch("n01.erase", who), int("n01.rows", rows)]);
        let whose = |n: &TNote| match who {
            0 => true,
            1 => n.track == 0,
            _ => n.track == 0 && n.sub == 0,
        };
        let kept: Vec<TNote> = sel
            .iter()
            .copied()
            .filter(|n| !(under(n, rows) && whose(n)))
            .collect();
        assert_eq!(brush_rows(&r.notes), brush_rows(&kept), "{who} {rows}");
        let mut gone: Vec<TNote> = ctx
            .iter()
            .chain(aux.iter().flatten())
            .copied()
            .filter(|n| under(n, rows) && whose(n))
            .collect();
        gone.sort_by_key(|n| (n.track, n.start, n.pitch));
        let mut got = r.erase.clone();
        got.sort_by_key(|n| (n.track, n.start, n.pitch));
        assert_eq!(got, gone, "{who} {rows}");
        assert!(r.message.as_deref().unwrap().contains("removed"));
    }
}

#[test]
fn brush_smudge_drags_notes_along_the_stroke_by_strength_and_distance() {
    // A rightward stroke along key 62 (row centre 62.5) over columns 0 – 20.
    let st = draw_stroke(&[(0, 62.5), (4800, 62.5)]);
    let ctx = vec![
        tn(1200, 100, 62, 90),
        tn(1200, 100, 64, 90),
        tn(1200, 100, 66, 90),
        tn(1200, 100, 67, 90),
        tn(5040, 100, 62, 90),
        tn(6000, 100, 62, 90),
    ];
    let sel = vec![tn(2400, 100, 61, 100)];
    let r = brush_try(
        sel,
        ctx,
        Vec::new(),
        Some(st),
        &[
            ch("step", 4),
            on("n05"),
            fl("n05.strength", 50.0),
            int("n05.radius", 4),
        ],
        |_| {},
    )
    .unwrap();
    // Each moves radius × strength × (1 − d / radius) cells right, d its
    // distance (in cells) from the stroke: 0 → 2 cells, 2 → 1, 4 → 0; the
    // note past the end (column 21, 1 cell away) 1.5 cells.
    let want = vec![
        (1200 + 480, 100, 62, 90, 0, 0),
        (1200 + 240, 100, 64, 90, 0, 0),
        (2400 + 360, 100, 61, 100, 0, 0),
        (5040 + 360, 100, 62, 90, 0, 0),
    ];
    let mut want = want;
    want.sort_unstable();
    assert_eq!(brush_rows(&r.notes), want);
    assert_eq!(r.erase.len(), 3, "the moved unselected notes");
    // An upward stroke drags by rows.
    let up = brush_try(
        vec![tn(2400, 100, 62, 100), tn(2400 + 960, 100, 62, 100)],
        Vec::new(),
        Vec::new(),
        Some(draw_stroke(&[(2400, 60.0), (2400, 70.0)])),
        &[
            ch("step", 4),
            on("n05"),
            fl("n05.strength", 50.0),
            int("n05.radius", 4),
        ],
        |_| {},
    )
    .unwrap();
    assert_eq!(
        spd(&up.notes),
        vec![(2400, 64, 100), (3360, 62, 100)],
        "on the stroke: 2 rows up; 4 cells away: still"
    );
    // Strength 0: nothing moves.
    let still = brush_edit(&[on("n05"), fl("n05.strength", 0.0)]);
    assert!(still.erase.is_empty());
    assert_eq!(
        brush_rows(&still.notes),
        brush_rows(&brush_edit_fixture().1)
    );
}

#[test]
fn brush_recolour_brush_changes_subchannels_without_adding_notes() {
    let (_, sel, ctx, _) = brush_edit_fixture();
    for (colour, only) in [(2i64, 1u32), (5, 1), (3, 0)] {
        let r = brush_edit(&[on("n06"), int("n06.colour", colour), ch("n06.only", only)]);
        let sub = (colour % 4) as u32;
        let paint = |n: &TNote| {
            let mut m = *n;
            if i64::from(m.pitch) == 62 && m.start < 1920 && (only == 0 || m.track == 0) {
                m.sub = sub;
            }
            m
        };
        // The selection recoloured in place (channels kept), the other
        // notes under the stroke removed and written recoloured.
        let mut want: Vec<TNote> = sel.iter().map(paint).collect();
        let (_, _, _, aux) = brush_edit_fixture();
        for n in ctx.iter().chain(aux.iter().flatten()) {
            let m = paint(n);
            if m != *n {
                want.push(m);
            }
        }
        assert_eq!(brush_rows(&r.notes), brush_rows(&want), "{colour} {only}");
        // Channels are the notes' own (only the note at 1,200 is on 1).
        assert!(r.notes.iter().all(|n| n.ch == u8::from(n.start == 1200)));
        let n_aux = if only == 0 { 1 } else { 0 };
        assert_eq!(r.erase.len(), want.len() - 2, "{colour} {only}");
        assert!(r.erase.iter().filter(|n| n.track == 1).count() == n_aux);
    }
}

#[test]
fn brush_length_brush_extends_or_trims_notes_to_where_the_stroke_ends() {
    let notes = vec![
        tn(240, 100, 62, 100),
        tn(480, 3000, 62, 100),
        tn(2500, 100, 62, 100),
        tn(240, 100, 70, 100),
        tn(0, 100, 62, 100),
    ];
    let run = |pts: &[(u64, f64)], mode: u32| {
        spd(&brush_try(
            notes.clone(),
            Vec::new(),
            Vec::new(),
            Some(draw_stroke(pts)),
            &[ch("step", 4), on("n10"), ch("n10.mode", mode)],
            |_| {},
        )
        .unwrap()
        .notes)
    };
    // Rightward to tick 1,900: the end of its cell is 1,920.
    let right = [(0u64, 62.5), (1900, 62.5)];
    assert_eq!(
        run(&right, 0),
        vec![
            (0, 62, 1920),
            (240, 62, 1680),
            (240, 70, 100),
            (480, 62, 3000),
            (2500, 62, 100)
        ]
    );
    assert_eq!(
        run(&right, 1),
        vec![
            (0, 62, 100),
            (240, 62, 100),
            (240, 70, 100),
            (480, 62, 1440),
            (2500, 62, 100)
        ]
    );
    // Leftward, ending in column 0: the end is 240.
    let left = [(1900u64, 62.5), (0, 62.5)];
    assert_eq!(
        run(&left, 0),
        vec![
            (0, 62, 240),
            (240, 62, 100),
            (240, 70, 100),
            (480, 62, 3000),
            (2500, 62, 100)
        ]
    );
}

#[test]
fn brush_velocity_brush_sets_adds_or_scales_velocities() {
    let vels = |amount: i64, mode: u32| -> Vec<u8> {
        let r = brush_edit(&[on("n11"), int("n11.vel", amount), ch("n11.mode", mode)]);
        let mut v: Vec<(u64, u8, u8)> = r.notes.iter().map(|n| (n.start, n.pitch, n.vel)).collect();
        v.sort_unstable();
        v.into_iter().map(|x| x.2).collect()
    };
    // Selected (480, 62) and (480, 70), then the unselected (960, 62) and
    // (1200, 62) under the stroke (90); (480, 70) is off the stroke.
    assert_eq!(vels(30, 0), vec![30, 100, 30, 30]);
    assert_eq!(vels(-20, 1), vec![80, 100, 70, 70]);
    assert_eq!(vels(50, 2), vec![127, 100, 127, 127]);
    assert_eq!(vels(-50, 2), vec![50, 100, 45, 45]);
    assert_eq!(vels(-127, 0), vec![1, 100, 1, 1]);
    // The Onion Skin track's notes keep theirs.
    let r = brush_edit(&[on("n11"), int("n11.vel", 30)]);
    assert!(r.notes.iter().all(|n| n.track == 0));
}

#[test]
fn brush_stamp_transform_turns_and_scales_each_stamp_a_step_more() {
    // The stamp: two notes a cell apart; three cells on key 70.
    let sel = vec![tn(0, 120, 60, 100), tn(240, 120, 60, 100)];
    let st = draw_stroke(&[(0, 70.5), (719, 70.5)]);
    let run = |rot: f64, scale: f64| {
        let r = brush_try(
            sel.clone(),
            Vec::new(),
            Vec::new(),
            Some(st.clone()),
            &[
                ch("step", 4),
                on("a6"),
                int("a6.every", 1),
                on("n07"),
                fl("n07.rot", rot),
                fl("n07.scale", scale),
            ],
            |_| {},
        )
        .unwrap();
        let mut v = spd(&r.notes);
        v.retain(|n| n.1 != 60);
        v
    };
    // 90° per stamp: (1, 0) → (0, 1) → (−1, 0).
    let mut want = vec![
        (0, 70, 120),
        (240, 70, 120),
        (240, 70, 120),
        (240, 71, 120),
        (480, 70, 120),
        (240, 70, 120),
    ];
    want.sort_unstable();
    assert_eq!(run(90.0, 0.0), want);
    // +50 % per stamp: the second note 1, 1.5, 2.25 cells on, lengths ×.
    let mut want = vec![
        (0, 70, 120),
        (240, 70, 120),
        (240, 70, 180),
        (240 + 360, 70, 180),
        (480, 70, 270),
        (480 + 540, 70, 270),
    ];
    want.sort_unstable();
    assert_eq!(run(0.0, 50.0), want);
    // Without the shape stamp (a6) there is nothing to turn.
    let plain = brush_only(st.clone(), &[ch("step", 4)]);
    let turned = brush_only(st, &[ch("step", 4), on("n07"), fl("n07.rot", 45.0)]);
    assert_eq!(join_fingerprint(&plain), join_fingerprint(&turned));
}

#[test]
fn brush_functions_compose_in_their_declared_order() {
    // Fill (n02) → dither (n08, 2 × 2 at 50 %) → scale rows (n09, C major):
    // the interior cells of the box on the checker, on the scale's keys.
    let r = brush_try(
        Vec::new(),
        brush_box(&[(0, 2400)]),
        Vec::new(),
        Some(draw_stroke(&[(600, 63.5)])),
        &[
            ch("step", 4),
            on("n02"),
            on("n08"),
            ch("n08.matrix", 0),
            on("n09"),
        ],
        |_| {},
    )
    .unwrap();
    let major = [0u8, 2, 4, 5, 7, 9, 11];
    let mut want: Vec<(u64, u8)> = (1..=8u64)
        .flat_map(|c| (61..=65u8).map(move |p| (c, p)))
        .filter(|&(c, p)| c % 2 == u64::from(p) % 2 && major.contains(&(p % 12)))
        .collect();
    want.sort_unstable();
    assert_eq!(brush_cells(&r.notes), want);
    // Eraser (n01) before recolour (n06): a removed note is not recoloured;
    // the eraser takes the brush colour's notes, the recolour the rest.
    let e = brush_edit(&[
        on("n01"),
        ch("n01.erase", 2),
        on("n06"),
        int("n06.colour", 3),
        ch("n06.only", 0),
    ]);
    assert_eq!(e.notes.len(), 1 + 2, "(480, 70) and two recoloured copies");
    assert!(
        e.notes
            .iter()
            .filter(|n| n.pitch == 62)
            .all(|n| n.sub == 3 && (n.start == 1200 || n.track == 1))
    );
    assert!(
        e.message
            .as_deref()
            .unwrap()
            .contains("2 removed, 2 recoloured")
    );
    // Soft disc (n03) → pattern tiles (n04): the tiles of the disc's cells.
    let r = brush_only(
        draw_stroke(&[(2400, 70.5)]),
        &[
            ch("step", 4),
            on("n03"),
            int("n03.radius", 1),
            fl("n03.hard", 100.0),
            on("n04"),
            list("n04.pattern", &[1, 0, 0, 0]),
            int("n04.width", 2),
        ],
    );
    // Disc cells (10, 70), (9, 70), (11, 70), (10, 69), (10, 71) → tiles
    // with origins (8|10, 68|70) → their bottom-left cells.
    assert_eq!(brush_cells(&r.notes), vec![(8, 70), (10, 68), (10, 70)]);
}

/// Runs the Note Brush on track 0 of `d` as the app does (the source
/// collected with the stroke in the context, so `paint_prepare` reads
/// around it).
fn brush_in_doc(
    d: &PlumDocument,
    st: Arc<plumspirit_engine::transform::Stroke>,
    set: &[(&'static str, ParamValue)],
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let t = tool("paint").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = Ctx::simple(960);
    ctx.stroke = Some(st);
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let src = plumspirit_engine::transform::run::collect_in(t, d, &sc, &ps, 1 << 24, Some(&ctx))?;
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)
}

#[test]
fn brush_edits_apply_in_one_undo_step_and_undo_exactly() {
    let notes = vec![
        vec![
            (480u64, 240u64, 62u8),
            (960, 240, 62),
            (3000, 100, 62),
            (480, 480, 70),
        ],
        vec![(720, 240, 62), (720, 240, 50)],
        vec![(720, 240, 62)],
    ];
    let mut d = draw_doc(&notes);
    d.project_mut().onion.mode = plumspirit_engine::model::OnionMode::Next;
    let before = doc_notes(&d);
    let st = draw_stroke(&[(0, 62.5), (1919, 62.5)]);
    // The eraser on every visible track: track 0's and track 1's notes on
    // key 62 under the stroke; track 2 is not visible.
    let r = brush_in_doc(
        &d,
        st.clone(),
        &[ch("step", 4), on("n01"), ch("n01.erase", 0)],
    )
    .unwrap();
    assert_eq!(r.erase.len(), 3);
    let mut h = History::default();
    plumspirit_engine::transform::run::commit(&mut h, &mut d, &r, "Note Brush").unwrap();
    let after = doc_notes(&d);
    let content = |v: Vec<(usize, u64, u64, u8, bool)>| -> Vec<(usize, u64, u64, u8)> {
        v.into_iter().map(|n| (n.0, n.1, n.2, n.3)).collect()
    };
    assert_eq!(
        content(after.clone()),
        vec![
            (0, 480, 480, 70),
            (0, 3000, 100, 62),
            (1, 720, 240, 50),
            (2, 720, 240, 62)
        ]
    );
    assert_eq!(h.undo_len(), 1);
    h.undo(&mut d).unwrap();
    assert_eq!(content(doc_notes(&d)), content(before.clone()));
    h.redo(&mut d).unwrap();
    assert_eq!(doc_notes(&d), after);
    // The velocity brush on the active track: the unselected notes under the
    // stroke rewritten (selected after Apply), one undo step.
    let mut d = draw_doc(&notes);
    let r = brush_in_doc(&d, st, &[ch("step", 4), on("n11"), int("n11.vel", 33)]).unwrap();
    assert_eq!(r.erase.len(), 2);
    let mut h = History::default();
    plumspirit_engine::transform::run::commit(&mut h, &mut d, &r, "Note Brush").unwrap();
    let mut vel: Vec<(u64, u8, u8, bool)> = d
        .track(0)
        .unwrap()
        .notes
        .iter()
        .map(|n| {
            (
                n.start_tick,
                n.attrs.pitch(),
                n.attrs.velocity(),
                n.selected,
            )
        })
        .collect();
    vel.sort_unstable();
    assert_eq!(
        vel,
        vec![
            (480, 62, 33, true),
            (480, 70, 100, false),
            (960, 62, 33, true),
            (3000, 62, 100, false)
        ]
    );
    assert_eq!(h.undo_len(), 1);
    h.undo(&mut d).unwrap();
    assert_eq!(
        content(doc_notes(&d)),
        content(draw_doc(&notes).pipe_notes())
    );
}

/// [`doc_notes`] as a method (readability in the undo test).
trait PipeNotes {
    fn pipe_notes(&self) -> Vec<(usize, u64, u64, u8, bool)>;
}

impl PipeNotes for PlumDocument {
    fn pipe_notes(&self) -> Vec<(usize, u64, u64, u8, bool)> {
        doc_notes(self)
    }
}

#[test]
fn brush_prepare_reads_the_notes_around_the_stroke_as_far_as_the_brush_reaches() {
    // Unselected notes on key 62 at columns 12, 30 and 600; the stroke over
    // columns 0 – 7.
    let d = draw_doc(&[vec![(2880, 100, 62), (7200, 100, 62), (144_000, 100, 62)]]);
    let st = draw_stroke(&[(0, 62.5), (1919, 62.5)]);
    let t = tool("paint").unwrap();
    let src = |set: &[(&'static str, ParamValue)]| {
        let mut ps = ParamSet::defaults(&(t.spec)().params);
        for (k, val) in set {
            ps.set(k, val.clone());
        }
        let mut ctx = Ctx::simple(960);
        ctx.stroke = Some(st.clone());
        let sc = [TrackScope {
            index: 0,
            all: false,
            content: None,
        }];
        plumspirit_engine::transform::run::collect_in(t, &d, &sc, &ps, 1 << 24, Some(&ctx)).unwrap()
    };
    // Painting reads nothing; an editing brush the stroke's cells; a soft
    // disc of radius 6 six cells further; a fill as far as its cells.
    assert!(src(&[ch("step", 4)]).context.is_empty());
    assert_eq!(src(&[ch("step", 4), on("n11")]).context.len(), 0);
    assert_eq!(
        src(&[ch("step", 4), on("n11"), on("n03"), int("n03.radius", 6)])
            .context
            .len(),
        1
    );
    assert_eq!(
        src(&[ch("step", 4), on("n02"), int("n02.most", 100)])
            .context
            .len(),
        2
    );
    assert_eq!(
        src(&[ch("step", 4), on("n02"), int("n02.most", 1000)])
            .context
            .len(),
        3
    );
    // Without a stroke nothing is read.
    let ps = {
        let mut ps = ParamSet::defaults(&(t.spec)().params);
        ps.set("n11", ParamValue::Bool(true));
        ps
    };
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let s = plumspirit_engine::transform::run::collect_in(t, &d, &sc, &ps, 1 << 24, None).unwrap();
    assert!(s.context.is_empty());
}

// ---- Note Brush: Control Sweeps per painted cell (V09-0143)

#[test]
fn brush_gate_sweep_sets_each_painted_cells_length_by_its_time() {
    let st = draw_stroke(&[(0, 62.5), (3840, 62.5)]);
    let gate = plumspirit_engine::transform::definition::sweep_targets("paint")
        .iter()
        .find(|t| t.param == "gate")
        .copied()
        .unwrap();
    let r = brush_only(
        st,
        &[
            ch("step", 4),
            on("m.sweep"),
            (gate.on, ParamValue::Bool(true)),
            (gate.graph, ParamValue::Curve(Curve::line(0.0, 1.0))),
        ],
    );
    // Cell k of 17 at u = k / 16: gate 25 % … 200 %.
    let want: Vec<(u64, u8, u64)> = (0..=16u64)
        .map(|k| {
            let u = (k * 240) as f64 / 3840.0;
            let g = (25.0 + u * 175.0) / 100.0;
            (k * 240, 62, ((240.0 * g).round() as u64).max(1))
        })
        .collect();
    assert_eq!(spd(&r.notes), want);
}

#[test]
fn brush_recolour_sweep_colours_each_note_by_its_covering_cell() {
    // A step graph: colour 0 in the first half of the stroke, 3 after it.
    let st = draw_stroke(&[(0, 62.5), (3840, 62.5)]);
    let tg = plumspirit_engine::transform::definition::sweep_targets("paint")
        .iter()
        .find(|t| t.param == "n06.colour")
        .copied()
        .unwrap();
    let notes: Vec<TNote> = (0..16u64)
        .map(|k| TNote {
            sub: 1,
            ch: 1,
            ..tn(k * 240 + 10, 100, 62, 90)
        })
        .collect();
    let r = brush_try(
        notes,
        Vec::new(),
        Vec::new(),
        Some(st),
        &[
            ch("step", 4),
            on("n06"),
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (
                tg.graph,
                ParamValue::Curve(Curve::new(vec![
                    (0.0, 0.0),
                    (0.49, 0.0),
                    (0.51, 1.0),
                    (1.0, 1.0),
                ])),
            ),
        ],
        |_| {},
    )
    .unwrap();
    let mut v: Vec<(u64, u32)> = r.notes.iter().map(|n| (n.start, n.sub)).collect();
    v.sort_unstable();
    for (s, sub) in v {
        let u = (s / 240 * 240) as f64 / 3840.0;
        if u < 0.45 {
            assert_eq!(sub, 0, "{s}");
        } else if u > 0.55 {
            assert_eq!(sub, 3, "{s}");
        }
    }
}

/// E0422's rule for the Note Brush (its stroke in the context, so the
/// kernel runs): a Control Sweep flat at the parameter's own value changes
/// nothing, with its function on; a sweep of a function that is off changes
/// nothing.
#[test]
fn brush_flat_sweeps_and_sweeps_of_functions_that_are_off_change_nothing() {
    use plumspirit_engine::transform::definition::{Combine, sweep_targets};
    use plumspirit_engine::transform::param::ParamKind;
    let spec = (tool("paint").unwrap().spec)();
    let fix = |set: &[(&'static str, ParamValue)]| {
        let (st, sel, ctx, aux) = brush_edit_fixture();
        let _ = st;
        let mut s = set.to_vec();
        s.push(on("a6"));
        brush_try(sel, ctx, aux, Some(draw_fixture_stroke()), &s, |_| {}).unwrap()
    };
    let mut checked = 0;
    assert_eq!(sweep_targets("paint").len(), 10);
    for tg in sweep_targets("paint") {
        assert!(matches!(tg.combine, Combine::Replace));
        let ps = spec.params.iter().find(|p| p.key == tg.param).unwrap();
        let lo = tg.range.0.min(tg.range.1);
        let v = match ps.kind {
            ParamKind::Float { .. } => ParamValue::Float(lo),
            _ => ParamValue::Int(lo.round() as i64),
        };
        let owner: &'static str = Box::leak(
            tg.param
                .split('.')
                .next()
                .unwrap()
                .to_string()
                .into_boxed_str(),
        );
        let mut base = vec![(tg.param, v)];
        if tg.param.contains('.') {
            base.push((owner, ParamValue::Bool(true)));
        }
        let a = fix(&base);
        let mut swept = base.clone();
        swept.extend([
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::flat(0.0))),
        ]);
        assert_eq!(
            join_fingerprint(&a),
            join_fingerprint(&fix(&swept)),
            "flat {}",
            tg.param
        );
        checked += 1;
    }
    // Every function alone against every target of another function (off).
    for f in ALL11 {
        let a = fix(&[on(f)]);
        for tg in sweep_targets("paint")
            .iter()
            .filter(|t| t.param.starts_with('n'))
        {
            let owner: &'static str = Box::leak(
                tg.param
                    .split('.')
                    .next()
                    .unwrap()
                    .to_string()
                    .into_boxed_str(),
            );
            if owner == f {
                continue;
            }
            let swept = vec![
                on(f),
                on("m.sweep"),
                (tg.on, ParamValue::Bool(true)),
                (owner, ParamValue::Bool(false)),
            ];
            assert_eq!(
                join_fingerprint(&a),
                join_fingerprint(&fix(&swept)),
                "{f} (sweep {})",
                tg.param
            );
            checked += 1;
        }
    }
    assert!(checked >= 10 + 11 * 6, "{checked}");
}

#[test]
fn brush_results_stay_within_the_estimate_and_are_deterministic() {
    let st = draw_fixture_stroke();
    let heavy = [
        on("a1"),
        on("a3"),
        on("a4"),
        on("a10"),
        on("n03"),
        int("n03.radius", 3),
        on("n04"),
        list("n04.pattern", &[1, 1, 0, 1, 0, 1]),
        int("n04.width", 3),
        on("n08"),
        on("n09"),
    ];
    let go = |s: Option<Arc<plumspirit_engine::transform::Stroke>>| {
        brush_try(
            brush_fixture_notes(),
            Vec::new(),
            Vec::new(),
            s,
            &heavy,
            |_| {},
        )
        .unwrap()
    };
    let (a, b) = (go(Some(st.clone())), go(Some(st)));
    assert_eq!(join_fingerprint(&a), join_fingerprint(&b));
    assert!(a.notes.len() > 1000, "{}", a.notes.len());
    // The stamp transform's turns and the editing brushes stay within theirs.
    let (est, sel, ctx, aux) = brush_edit_fixture();
    for set in [
        vec![
            on("a6"),
            int("a6.every", 1),
            on("n07"),
            fl("n07.rot", 33.0),
            fl("n07.scale", 20.0),
        ],
        vec![
            on("n01"),
            on("n05"),
            on("n06"),
            ch("n06.only", 0),
            on("n10"),
            ch("n10.scope", 0),
            on("n11"),
        ],
    ] {
        let r = brush_try(
            sel.clone(),
            ctx.clone(),
            aux.clone(),
            Some(est.clone()),
            &set,
            |_| {},
        );
        assert!(r.is_ok());
    }
    // Without a stroke: the selection and the hint, whatever is on.
    let none = go(None);
    assert_eq!(none.notes.len(), 3);
    assert!(
        none.message
            .as_deref()
            .unwrap()
            .contains("Drag in the Piano Roll")
    );
}

// ============================================================= Snap to Scale

/// Snap to Scale's fixture (960 PPQN, 4/4, bars of 3,840): chords with
/// out-of-scale tones, runs up and down, short passing notes and a second
/// subchannel, over three bars.
fn snap_fixture() -> Vec<TNote> {
    let mut v = Vec::new();
    let mut add = |s: u64, d: u64, p: u8, sub: u32| {
        v.push(TNote {
            sub,
            ch: sub as u8,
            ..tn(s, d, p, 90)
        })
    };
    // Bar 1: C E G# at 0; a rising run every 240 from 960.
    for p in [60, 64, 68] {
        add(0, 960, p, 0);
    }
    for (k, p) in [61u8, 63, 66, 68, 70, 73].iter().enumerate() {
        add(960 + 240 * k as u64, 240, *p, 0);
    }
    // Bar 2: D F# A at 3,840; a falling run; two 60-tick passing notes.
    for p in [62, 66, 69] {
        add(3840, 960, p, 0);
    }
    for (k, p) in [75u8, 73, 70, 68, 66, 65].iter().enumerate() {
        add(4800 + 240 * k as u64, 240, *p, 0);
    }
    add(6240, 60, 61, 0);
    add(6300, 60, 63, 0);
    // Bar 3: Bb D F at 7,680 and a line on subchannel 1.
    for p in [58, 62, 65] {
        add(7680, 960, p, 0);
    }
    for (k, p) in [54u8, 56, 61, 66, 70, 71, 75].iter().enumerate() {
        add(8640 + 240 * k as u64, 180, *p, 1);
    }
    plumspirit_engine::transform::source::sort_time_major(&mut v);
    v
}

/// Runs Snap to Scale on a hand-built source: `notes` selected on one track
/// (subchannels 0 – 3, channel = subchannel), `context` its unselected
/// notes, `aux` the prepared layers, in `Ctx::simple(960)` changed by
/// `tweak`; the whole result (within the kernel's estimate).
fn snap_try(
    notes: Vec<TNote>,
    context: Vec<TNote>,
    aux: Vec<Vec<TNote>>,
    set: &[(&'static str, ParamValue)],
    tweak: impl FnOnce(&mut Ctx),
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let mut src = Source::from_notes(notes, vec![track]);
    let mut c = context;
    plumspirit_engine::transform::source::sort_time_major(&mut c);
    src.context = Arc::new(c);
    src.aux = Arc::new(aux);
    let t = tool("snap_scale").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = Ctx::simple(960);
    tweak(&mut ctx);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate_source(&src).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

/// Snap to Scale on the fixture.
fn snap_fix(set: &[(&'static str, ParamValue)]) -> plumspirit_engine::transform::TransformRun {
    snap_try(snap_fixture(), Vec::new(), Vec::new(), set, |_| {}).unwrap()
}

