fn snap_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

