/// Neutral settings (the v0.9 path, the v0.8 result): no passing notes
/// (shorter than 0, weak beats snapped), listed cents of 0, an empty
/// palette, an approach window of 0 — each alone, then together. (A
/// reference no class reaches is not neutral: its summary says so.)
fn snap_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n02",
            vec![on("n02"), int("n02.short", 0), ch("n02.weak", 0)],
        ),
        (
            "n03",
            vec![on("n03"), ch("n03.tuning", 3), list("n03.cents", &[0])],
        ),
        ("n07", vec![on("n07"), list("n07.palette", &[])]),
        ("n08", vec![on("n08"), int("n08.window", 0)]),
    ];
    let all: Vec<(&'static str, ParamValue)> =
        each.iter().flat_map(|(_, s)| s.iter().cloned()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn snap_neutral_functions_take_the_v09_path_and_equal_v08() {
    for (f, neutral) in snap_neutral() {
        for (i, s) in snap_v08_settings().iter().enumerate() {
            let mut set = snap_off(s);
            set.extend(neutral.iter().cloned());
            assert_eq!(
                join_fingerprint(&snap_fix(&set)),
                SNAP_V08[i],
                "{f} setting {i}"
            );
        }
    }
}

/// Snap to Scale on `notes` (subchannel 0): the result.
fn snap_on(notes: &[(u64, u64, u8)], set: &[(&'static str, ParamValue)]) -> Vec<TNote> {
    let v: Vec<TNote> = notes.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    snap_try(v, Vec::new(), Vec::new(), set, |_| {})
        .unwrap()
        .notes
}

/// The nearest key of `mask` (down on a tie), as the v0.8 rule without its
/// advanced functions.
fn snap_nearest(p: i64, mask: u16) -> i64 {
    let ok = |q: i64| mask & (1 << q.rem_euclid(12)) != 0;
    let (mut up, mut dn) = (p, p);
    while !ok(up) {
        up += 1;
    }
    while !ok(dn) {
        dn -= 1;
    }
    if up - p < p - dn { up } else { dn }
}

/// A scale's pitch-class mask by its menu index on root `root`
/// (the engine's own table).
fn snap_mask(root: usize, scale: usize) -> u16 {
    plumspirit_engine::transform::theory::Scale::new(root, scale).mask()
}

#[test]
fn snap_scale_detection_fits_each_window_by_brute_force_and_snaps_to_it() {
    // Bar 1: D major material (F#, C#, B…) with an out-of-key G#; bar 2: A
    // minor material with a D#; bar 3: F major with an E♭.
    let mut notes: Vec<(u64, u64, u8)> = Vec::new();
    for (k, p) in [62u8, 66, 69, 61, 64, 71, 67, 68].iter().enumerate() {
        notes.push((k as u64 * 480, 480, *p));
    }
    for (k, p) in [69u8, 72, 76, 71, 74, 69, 63, 69].iter().enumerate() {
        notes.push((3840 + k as u64 * 480, 480, *p));
    }
    for (k, p) in [65u8, 69, 72, 70, 67, 64, 63, 65].iter().enumerate() {
        notes.push((7680 + k as u64 * 480, if k == 7 { 960 } else { 480 }, *p));
    }
    // The brute force: every candidate's total length on its keys; ties by
    // the root's length, fewer classes, menu order, lower root.
    let brute = |ns: &[(u64, u64, u8)], cands: &[usize]| -> (usize, usize) {
        let mut w = [0u64; 12];
        for &(_, d, p) in ns {
            w[usize::from(p % 12)] += d;
        }
        let mut best = None;
        for &si in cands {
            for root in 0..12 {
                let m = snap_mask(root, si);
                let fit: u64 = (0..12).filter(|pc| m & 1 << pc != 0).map(|pc| w[pc]).sum();
                let key = (
                    fit,
                    w[root],
                    -i64::from(m.count_ones()),
                    -(si as i64),
                    -(root as i64),
                );
                if best
                    .as_ref()
                    .is_none_or(|b: &((u64, u64, i64, i64, i64), _)| key > b.0)
                {
                    best = Some((key, (root, si)));
                }
            }
        }
        best.unwrap().1
    };
    let bars: Vec<&[(u64, u64, u8)]> = vec![&notes[0..8], &notes[8..16], &notes[16..24]];
    let found: Vec<(usize, usize)> = bars.iter().map(|b| brute(b, &[0, 1])).collect();
    assert_eq!(
        found,
        vec![(2, 0), (9, 1), (5, 0)],
        "D major, A minor, F major"
    );
    let r = snap_on(&notes, &[on("n01"), ch("n01.window", 1)]);
    let mut got: Vec<(u64, u8)> = r.iter().map(|n| (n.start, n.pitch)).collect();
    got.sort_unstable();
    let mut want: Vec<(u64, u8)> = Vec::new();
    for (b, f) in bars.iter().zip(&found) {
        let m = snap_mask(f.0, f.1);
        for &(s, _, p) in b.iter() {
            want.push((s, snap_nearest(i64::from(p), m) as u8));
        }
    }
    want.sort_unstable();
    assert_eq!(got, want);
    // The whole selection: one scale for all (the brute force over all).
    let whole = brute(&notes, &[0, 1]);
    let r = snap_on(&notes, &[on("n01")]);
    let m = snap_mask(whole.0, whole.1);
    for n in &r {
        let src = notes.iter().find(|x| x.0 == n.start).unwrap();
        assert_eq!(i64::from(n.pitch), snap_nearest(i64::from(src.2), m));
    }
    // Every 2 bars: bars 1 – 2 together, bar 3 alone; all modes / scales.
    for cands in [1u32, 2] {
        let list: Vec<usize> = if cands == 1 {
            vec![0, 4, 5, 6, 7, 1, 8]
        } else {
            (0..19).collect()
        };
        let r = snap_on(
            &notes,
            &[
                on("n01"),
                ch("n01.cands", cands),
                ch("n01.window", 2),
                int("n01.bars", 2),
            ],
        );
        let w1 = brute(&notes[0..16], &list);
        let w2 = brute(&notes[16..24], &list);
        for n in &r {
            let (i, src) = notes.iter().enumerate().find(|x| x.1.0 == n.start).unwrap();
            let f = if i < 16 { w1 } else { w2 };
            assert_eq!(
                i64::from(n.pitch),
                snap_nearest(i64::from(src.2), snap_mask(f.0, f.1)),
                "candidates {cands} note {i}"
            );
        }
    }
    let msg = snap_try(
        notes.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect(),
        Vec::new(),
        Vec::new(),
        &[on("n01"), ch("n01.window", 1)],
        |_| {},
    )
    .unwrap()
    .message
    .unwrap();
    assert!(msg.contains("Detected D Major"), "{msg}");
}

#[test]
fn snap_passing_tolerance_leaves_short_notes_and_weak_beats() {
    // C major; C# (out) at a beat (long), at a beat (short), off the beat.
    let notes = [
        (0u64, 480u64, 61u8),
        (960, 60, 61),
        (1200, 480, 61),
        (1920, 480, 63),
    ];
    let r = snap_on(&notes, &[on("n02"), int("n02.short", 120)]);
    assert_eq!(
        spd(&r),
        vec![
            (0, 60, 480),
            (960, 61, 60),
            (1200, 60, 480),
            (1920, 62, 480)
        ]
    );
    let r = snap_on(
        &notes,
        &[on("n02"), int("n02.short", 120), ch("n02.weak", 1)],
    );
    assert_eq!(
        spd(&r),
        vec![
            (0, 60, 480),
            (960, 61, 60),
            (1200, 61, 480),
            (1920, 62, 480)
        ]
    );
}

/// The pitch-bend value for `cents` at a range of `range` semitones.
fn snap_bend(cents: f64, range: f64) -> i64 {
    (8192.0 + cents / 100.0 / range * 8192.0)
        .round()
        .clamp(0.0, 16383.0) as i64
}

#[test]
fn snap_tuning_bends_each_note_by_its_interval_and_finds_free_channels() {
    use plumspirit_engine::transform::output::Lane;
    let cents = |num: f64, den: f64, semis: f64| 1200.0 * (num / den).log2() - 100.0 * semis;
    // C major: C, then E and G together (one channel), then a D.
    let notes = [
        (0u64, 960u64, 60u8),
        (960, 960, 64),
        (960, 960, 67),
        (1920, 960, 62),
    ];
    let v: Vec<TNote> = notes.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    let set = [on("n03"), ch("n03.tuning", 0), int("n03.range", 2)];
    let r = snap_try(v.clone(), Vec::new(), Vec::new(), &set, |_| {}).unwrap();
    let pb: Vec<(u64, i64)> = r
        .events
        .iter()
        .filter(|e| e.lane == Lane::PitchBend)
        .map(|e| (e.tick, i64::from(e.value)))
        .collect();
    // Keep: one channel — E and G at 960 need different bends: one point
    // per tick and channel, G's (the later) wins and the summary counts
    // the conflict; D's at 1,920, the centre after the last note.
    let e3 = snap_bend(cents(5.0, 4.0, 4.0), 2.0);
    let g5 = snap_bend(cents(3.0, 2.0, 7.0), 2.0);
    let d2 = snap_bend(cents(9.0, 8.0, 2.0), 2.0);
    assert_eq!(e3, 7631);
    assert_eq!(pb, vec![(960, g5), (1920, d2), (2880, 8192)]);
    assert!(
        r.message
            .as_deref()
            .unwrap()
            .contains("overlap a differently tuned note")
    );
    // The range (RPN 0) once before the first bend on the channel.
    let mut cc: Vec<(u64, u8, i64)> = r
        .events
        .iter()
        .filter_map(|e| match e.lane {
            Lane::Cc(c) => Some((e.tick, c, i64::from(e.value))),
            _ => None,
        })
        .collect();
    cc.sort_unstable();
    assert_eq!(
        cc,
        vec![(956, 101, 0), (957, 100, 0), (958, 6, 2), (959, 38, 0)]
    );
    // Allocate: G moves to the next free channel (1), each channel bends
    // for its own notes.
    let mut set2 = set.to_vec();
    set2.push(ch("n03.channels", 1));
    let r = snap_try(v.clone(), Vec::new(), Vec::new(), &set2, |_| {}).unwrap();
    let chans: Vec<(u64, u8, u8)> = {
        let mut x: Vec<(u64, u8, u8)> = r.notes.iter().map(|n| (n.start, n.pitch, n.ch)).collect();
        x.sort_unstable();
        x
    };
    assert_eq!(
        chans,
        vec![(0, 60, 0), (960, 64, 0), (960, 67, 1), (1920, 62, 0)]
    );
    let mut pb: Vec<(u8, u64, i64)> = r
        .events
        .iter()
        .filter(|e| e.lane == Lane::PitchBend)
        .map(|e| (e.ch, e.tick, i64::from(e.value)))
        .collect();
    pb.sort_unstable();
    assert_eq!(
        pb,
        vec![
            (0, 960, e3),
            (0, 1920, d2),
            (0, 2880, 8192),
            (1, 960, g5),
            (1, 1920, 8192)
        ]
    );
    // An unselected (untuned) note sounding on channel 1 keeps G off it.
    let r = snap_try(
        v.clone(),
        vec![TNote {
            ch: 1,
            ..tn(900, 200, 40, 90)
        }],
        Vec::new(),
        &set2,
        |_| {},
    )
    .unwrap();
    assert!(r.notes.iter().any(|n| n.pitch == 67 && n.ch == 2));
    // Pythagorean, listed cents and 24-TET (listed cents to quarter tones).
    for (tuning, cents_list, want) in [
        (2u32, vec![0i64], snap_bend(cents(81.0, 64.0, 4.0), 2.0)),
        (3, vec![0, 0, 0, 0, -30], snap_bend(-30.0, 2.0)),
        (1, vec![0, 0, 0, 0, -30], snap_bend(-50.0, 2.0)),
        (1, vec![0, 0, 0, 0, -20], 8192),
    ] {
        let r = snap_try(
            vec![tn(0, 960, 64, 90)],
            Vec::new(),
            Vec::new(),
            &[
                on("n03"),
                ch("n03.tuning", tuning),
                list("n03.cents", &cents_list),
                int("n03.range", 2),
            ],
            |_| {},
        )
        .unwrap();
        let first = r
            .events
            .iter()
            .find(|e| e.lane == Lane::PitchBend)
            .map_or(8192, |e| i64::from(e.value));
        assert_eq!(first, want, "tuning {tuning}");
    }
}

#[test]
fn snap_voice_aware_snap_avoids_unisons_and_keeps_the_spacing_when_asked() {
    // C major: F and F# together — v0.8 sends F# down onto F.
    let plain = snap_on(&[(0, 960, 65), (0, 960, 66)], &[]);
    assert_eq!(pitches(&plain), vec![65, 65]);
    let r = snap_on(&[(0, 960, 65), (0, 960, 66)], &[on("n04")]);
    assert_eq!(pitches(&r), vec![65, 67]);
    let r = snap_on(
        &[(0, 960, 65), (0, 960, 66)],
        &[on("n04"), ch("n04.unisons", 1)],
    );
    assert_eq!(pitches(&r), vec![65, 65]);
    // C major pentatonic: F# and A# (4 apart). Smallest movement: G, A (2
    // apart); keep the spacing: E, A (5 apart, the least change, then the
    // least movement, down first).
    let pent = [ch("scale", 9), on("n04")];
    let r = snap_on(&[(0, 960, 66), (0, 960, 70)], &pent);
    assert_eq!(pitches(&r), vec![67, 69]);
    let mut sp = pent.to_vec();
    sp.push(ch("n04.prefer", 1));
    let r = snap_on(&[(0, 960, 66), (0, 960, 70)], &sp);
    assert_eq!(pitches(&r), vec![64, 69]);
    // Brute force over every choice on random chords: no new unison, and
    // the least total movement among the choices without one.
    let mut seed = 7u64;
    for _ in 0..60 {
        let mut ps: Vec<u8> = Vec::new();
        for _ in 0..4 {
            seed = seed
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            ps.push(55 + (seed >> 59) as u8);
        }
        ps.sort_unstable();
        ps.dedup();
        let notes: Vec<(u64, u64, u8)> = ps.iter().map(|&p| (0, 960, p)).collect();
        let got = pitches(&snap_on(&notes, &[on("n04")]));
        let m = snap_mask(0, 0);
        let cands: Vec<Vec<i64>> = ps
            .iter()
            .map(|&p| {
                let p = i64::from(p);
                if m & 1 << p.rem_euclid(12) != 0 {
                    vec![p]
                } else {
                    vec![p - 1, p + 1]
                        .into_iter()
                        .filter(|q| m & 1 << q.rem_euclid(12) != 0)
                        .collect()
                }
            })
            .collect();
        let mut best: Option<i64> = None;
        let mut stack: Vec<Vec<i64>> = vec![vec![]];
        while let Some(pre) = stack.pop() {
            if pre.len() == ps.len() {
                let distinct = pre.windows(2).all(|w| w[1] > w[0]);
                if distinct {
                    let cost: i64 = pre
                        .iter()
                        .zip(&ps)
                        .map(|(t, &p)| (t - i64::from(p)).abs())
                        .sum();
                    best = Some(best.map_or(cost, |b: i64| b.min(cost)));
                }
                continue;
            }
            for &c in &cands[pre.len()] {
                let mut x = pre.clone();
                x.push(c);
                stack.push(x);
            }
        }
        if let Some(b) = best {
            let mut g: Vec<i64> = got.iter().map(|&x| i64::from(x)).collect();
            g.sort_unstable();
            assert!(g.windows(2).all(|w| w[1] > w[0]), "{ps:?} -> {got:?}");
            let cost: i64 = g
                .iter()
                .zip(&ps)
                .map(|(t, &p)| (t - i64::from(p)).abs())
                .sum();
            assert_eq!(cost, b, "{ps:?} -> {got:?}");
        }
    }
}

#[test]
fn snap_reference_scale_takes_the_classes_the_reference_plays_often_enough() {
    // Reference: D E F# A B (D major pentatonic), F# only once, per bar
    // different (bar 2: C D E G A).
    let mut refs: Vec<TNote> = Vec::new();
    for p in [62u8, 62, 64, 64, 66, 69, 69, 71, 71] {
        refs.push(tn(0, 100, p, 80));
    }
    for p in [60u8, 62, 64, 67, 69] {
        refs.push(tn(3840, 100, p, 80));
    }
    let notes = [
        (0u64, 480u64, 65u8),
        (480, 480, 67),
        (3840, 480, 65),
        (4320, 480, 71),
    ];
    let run = |set: &[(&'static str, ParamValue)]| {
        let v: Vec<TNote> = notes.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
        let mut s = vec![on("n05")];
        s.extend(set.iter().cloned());
        pitches(
            &snap_try(v, Vec::new(), vec![refs.clone()], &s, |_| {})
                .unwrap()
                .notes,
        )
    };
    let mask_of = |ps: &[u8]| ps.iter().fold(0u16, |m, &p| m | 1 << (p % 12));
    // Whole range, at least once: D E F# G A B C → classes of all refs.
    let all = mask_of(&[62, 64, 66, 69, 71, 60, 67]);
    let want: Vec<u8> = notes
        .iter()
        .map(|&(_, _, p)| snap_nearest(i64::from(p), all) as u8)
        .collect();
    assert_eq!(run(&[]), want);
    // At least twice: D E A B only (F# once, C / G once).
    let twice = mask_of(&[62, 64, 69, 71]);
    let want: Vec<u8> = notes
        .iter()
        .map(|&(_, _, p)| snap_nearest(i64::from(p), twice) as u8)
        .collect();
    assert_eq!(run(&[int("n05.least", 2)]), want);
    // Per bar.
    let b1 = mask_of(&[62, 64, 66, 69, 71]);
    let b2 = mask_of(&[60, 62, 64, 67, 69]);
    let want: Vec<u8> = notes
        .iter()
        .map(|&(s, _, p)| snap_nearest(i64::from(p), if s < 3840 { b1 } else { b2 }) as u8)
        .collect();
    assert_eq!(run(&[ch("n05.window", 1)]), want);
}

#[test]
fn snap_metric_hierarchy_snaps_strong_positions_to_chord_tones() {
    // C major, grid of a quarter: D on beats → C (tie down) or chord tone;
    // D off the beat stays (in the scale).
    let notes = [
        (0u64, 240u64, 62u8),
        (240, 240, 62),
        (960, 240, 65),
        (1200, 240, 61),
    ];
    let r = snap_on(&notes, &[on("n06")]);
    assert_eq!(pitches(&r), vec![60, 62, 64, 60]);
    // Degree triad per bar (on its lowest note, F → F A C): D5 on a beat
    // → C5; F# off the beat → the scale (F, down on the tie).
    let notes = [(0u64, 240u64, 65u8), (960, 240, 74), (1200, 240, 66)];
    let r = snap_on(&notes, &[on("n06"), ch("n06.chord", 1)]);
    assert_eq!(pitches(&r), vec![65, 72, 65]);
    // With D the lowest (D F A): D stays.
    let notes = [(0u64, 240u64, 65u8), (960, 240, 62), (1200, 240, 66)];
    let r = snap_on(&notes, &[on("n06"), ch("n06.chord", 1)]);
    assert_eq!(pitches(&r), vec![65, 62, 65]);
    // A chord list per bar: Am, then G.
    let notes = [(0u64, 240u64, 62u8), (3840, 240, 64)];
    let r = snap_on(
        &notes,
        &[
            on("n06"),
            ch("n06.chord", 2),
            ("n06.chords", ParamValue::Text("Am G".into())),
        ],
    );
    assert_eq!(pitches(&r), vec![60, 62]);
}

#[test]
fn snap_move_distance_colours_paint_corrected_notes_by_distance() {
    // C major pentatonic: F (1 to E), F# (1 to G), A# (1 to A); a6-free:
    // the whole scale C D E G A; B → A (2) or C (1).
    let notes = [
        (0u64, 240u64, 60u8),
        (240, 240, 65),
        (480, 240, 71),
        (720, 240, 70),
    ];
    let v: Vec<TNote> = notes
        .iter()
        .map(|&(s, d, p)| TNote {
            ch: 3,
            ..tn(s, d, p, 90)
        })
        .collect();
    let r = snap_try(
        v,
        Vec::new(),
        Vec::new(),
        &[ch("scale", 9), on("n07"), list("n07.palette", &[2, 1])],
        |_| {},
    )
    .unwrap();
    let mut got: Vec<(u64, u8, u32, u8)> = r
        .notes
        .iter()
        .map(|n| (n.start, n.pitch, n.sub, n.ch))
        .collect();
    got.sort_unstable();
    assert_eq!(
        got,
        vec![
            (0, 60, 0, 3),
            (240, 64, 2, 3),
            (480, 72, 2, 3),
            (720, 69, 2, 3)
        ]
    );
    // Distance 2 (C major pentatonic: F# → G is 1; use D# in C major
    // pentatonic → D (1)… a two-key move: B♭ in C major with a down rule).
    let r = snap_try(
        vec![tn(0, 240, 70, 90)],
        Vec::new(),
        Vec::new(),
        &[
            ch("scale", 9),
            on("a3"),
            ch("a3.dir", 0),
            on("n07"),
            list("n07.palette", &[2, 1]),
        ],
        |_| {},
    )
    .unwrap();
    assert_eq!((r.notes[0].pitch, r.notes[0].sub), (72, 1));
}

#[test]
fn snap_approach_keep_spares_chromatic_notes_leading_into_the_scale() {
    // C# then D within the window (kept), C# with D too late (snapped), D#
    // then D a semitone down (kept), F# then G off the selection's track.
    let notes = [
        (0u64, 100u64, 61u8),
        (120, 100, 62),
        (960, 100, 61),
        (1400, 100, 62),
        (1920, 100, 63),
        (2000, 100, 62),
    ];
    let r = snap_on(&notes, &[on("n08"), int("n08.window", 240)]);
    assert_eq!(
        spd(&r).iter().map(|x| x.1).collect::<Vec<_>>(),
        vec![61, 62, 60, 62, 63, 62]
    );
    let r = snap_on(&notes, &[on("n08"), int("n08.window", 1000)]);
    assert_eq!(
        spd(&r).iter().map(|x| x.1).collect::<Vec<_>>(),
        vec![61, 62, 61, 62, 63, 62]
    );
}

#[test]
fn snap_chord_progression_snaps_to_each_bar_beat_or_length_chord() {
    let chords = ("n09.chords", ParamValue::Text("Am F C G".into()));
    let am = 1u16 << 9 | 1 << 0 | 1 << 4;
    let f = 1u16 << 5 | 1 << 9 | 1 << 0;
    let c = 1u16 << 0 | 1 << 4 | 1 << 7;
    let g = 1u16 << 7 | 1 << 11 | 1 << 2;
    let prog = [am, f, c, g];
    let notes: Vec<(u64, u64, u8)> = (0..8u64)
        .map(|k| (k * 960, 240, 62 + (k % 3) as u8))
        .collect();
    for (per, len, chord_of) in [
        (
            0u32,
            1920i64,
            Box::new(|t: u64| prog[(t / 3840 % 4) as usize]) as Box<dyn Fn(u64) -> u16>,
        ),
        (1, 1920, Box::new(|t: u64| prog[(t / 960 % 4) as usize])),
        (2, 1920, Box::new(|t: u64| prog[(t / 1920 % 4) as usize])),
    ] {
        let r = snap_on(
            &notes,
            &[
                on("n09"),
                chords.clone(),
                ch("n09.per", per),
                int("n09.len", len),
            ],
        );
        let want: Vec<u8> = notes
            .iter()
            .map(|&(s, _, p)| snap_nearest(i64::from(p), chord_of(s)) as u8)
            .collect();
        assert_eq!(pitches(&r), want, "per {per}");
    }
    let e = snap_try(
        vec![tn(0, 100, 60, 90)],
        Vec::new(),
        Vec::new(),
        &[on("n09"), ("n09.chords", ParamValue::Text("Am Xq".into()))],
        |_| {},
    )
    .err()
    .unwrap();
    assert!(e.user_message().contains("“Xq” is not a chord name"));
}

#[test]
fn snap_directional_scales_follow_the_lines_direction() {
    // A melodic minor: F# G# going up stay (A B C D E F# G#); F# G#
    // going down become F / G (natural minor; F# → F or G: tie → down).
    let up = snap_on(
        &[(0, 240, 64), (240, 240, 66), (480, 240, 68), (720, 240, 69)],
        &[on("n10")],
    );
    assert_eq!(pitches(&up), vec![64, 66, 68, 69]);
    let down = snap_on(
        &[(0, 240, 69), (240, 240, 68), (480, 240, 66), (720, 240, 64)],
        &[on("n10")],
    );
    assert_eq!(pitches(&down), vec![69, 67, 65, 64]);
    // Bebop dominant on G: F# allowed going down only.
    let set = [on("n10"), ch("n10.rule", 2), ch("n10.key", 7)];
    let down = snap_on(&[(0, 240, 67), (240, 240, 66), (480, 240, 65)], &set);
    assert_eq!(pitches(&down), vec![67, 66, 65]);
    let up = snap_on(&[(0, 240, 65), (240, 240, 66), (480, 240, 67)], &set);
    assert_eq!(pitches(&up), vec![65, 65, 67]);
    // Bebop major on C: G# allowed going down only.
    let set = [on("n10"), ch("n10.rule", 1), ch("n10.key", 0)];
    assert_eq!(
        pitches(&snap_on(
            &[(0, 240, 69), (240, 240, 68), (480, 240, 67)],
            &set
        )),
        vec![69, 68, 67]
    );
    assert_eq!(
        pitches(&snap_on(
            &[(0, 240, 67), (240, 240, 68), (480, 240, 69)],
            &set
        )),
        vec![67, 67, 69]
    );
}

#[test]
fn snap_chord_shift_moves_each_chord_as_a_block() {
    // C major: C# F G# → C E G (−1, all three on keys).
    let r = snap_on(&[(0, 960, 61), (0, 960, 65), (0, 960, 68)], &[on("n11")]);
    assert_eq!(pitches(&r), vec![60, 64, 67]);
    // D# G A#: −1 / +1 give two, +2 three (F A C) within 2; within 1: −1.
    let ch3 = [(0u64, 960u64, 63u8), (0, 960, 67), (0, 960, 70)];
    assert_eq!(pitches(&snap_on(&ch3, &[on("n11")])), vec![65, 69, 72]);
    assert_eq!(
        pitches(&snap_on(&ch3, &[on("n11"), int("n11.shift", 1)])),
        vec![62, 66, 69]
    );
    // Brute force over random chords: the count on keys is the best within
    // the limit, the shift the smallest (down first) reaching it, the shape
    // kept.
    let m = snap_mask(0, 0);
    let mut seed = 11u64;
    for _ in 0..80 {
        let mut ps: Vec<u8> = Vec::new();
        for _ in 0..3 {
            seed = seed
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            ps.push(50 + (seed >> 58) as u8);
        }
        let notes: Vec<(u64, u64, u8)> = ps.iter().map(|&p| (0, 960, p)).collect();
        let got = snap_on(&notes, &[on("n11"), int("n11.shift", 3)]);
        let count = |s: i64| {
            ps.iter()
                .filter(|&&p| m & 1 << (i64::from(p) + s).rem_euclid(12) != 0)
                .count()
        };
        let mut best = (count(0), 0i64);
        for d in 1..=3 {
            for s in [-d, d] {
                if count(s) > best.0 {
                    best = (count(s), s);
                }
            }
        }
        let mut want: Vec<u8> = ps.iter().map(|&p| (i64::from(p) + best.1) as u8).collect();
        want.sort_unstable();
        let mut g = pitches(&got);
        g.sort_unstable();
        assert_eq!(g, want, "{ps:?}");
    }
}

#[test]
fn snap_functions_compose_in_their_declared_order() {
    // A reference (n05, D major pentatonic) then a progression (n09): the
    // progression wins; a passing note (n02) stays inside an n11 chord.
    let refs: Vec<TNote> = [62u8, 64, 66, 69, 71]
        .iter()
        .map(|&p| tn(0, 100, p, 80))
        .collect();
    let v = vec![tn(0, 480, 65, 90), tn(480, 480, 61, 90)];
    let r = snap_try(
        v.clone(),
        Vec::new(),
        vec![refs.clone()],
        &[
            on("n05"),
            on("n09"),
            ("n09.chords", ParamValue::Text("C".into())),
        ],
        |_| {},
    )
    .unwrap();
    assert_eq!(pitches(&r.notes), vec![64, 60]);
    let chord = vec![tn(0, 960, 61, 90), tn(0, 960, 65, 90), tn(0, 60, 68, 90)];
    let r = snap_try(
        chord,
        Vec::new(),
        Vec::new(),
        &[on("n02"), int("n02.short", 120), on("n11")],
        |_| {},
    )
    .unwrap();
    let mut got: Vec<u8> = r.notes.iter().map(|n| n.pitch).collect();
    got.sort_unstable();
    assert_eq!(got, vec![60, 64, 68], "C# F move by −1; the short G# stays");
    // n04 and n11 both on: n11's block shift decides (F F# down a
    // semitone: E F, both on keys), not n04's voicing (F G).
    let r = snap_on(&[(0, 960, 65), (0, 960, 66)], &[on("n04"), on("n11")]);
    let mut g = pitches(&r);
    g.sort_unstable();
    assert_eq!(g, vec![64, 65]);
}

/// Runs Snap to Scale on track 0 of `d` (all its notes selected) as the
/// app does (`snap_prepare` reads the reference).
fn snap_in_doc(
    d: &PlumDocument,
    set: &[(&'static str, ParamValue)],
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let t = tool("snap_scale").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let ctx = Ctx::simple(960);
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let src = plumspirit_engine::transform::run::collect_in(t, d, &sc, &ps, 1 << 24, Some(&ctx))?;
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)
}

#[test]
fn snap_prepare_reads_the_reference_track_or_subchannel() {
    let mut d = draw_doc(&[vec![], vec![(0, 100, 62), (100, 100, 64), (200, 100, 66)]]);
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&[rec(0, 480, 65), rec(480, 480, 61)], true)
        .unwrap();
    // Track 2 plays D E F#: F → E (tie with F#: down), C# → D.
    let r = snap_in_doc(&d, &[on("n05"), int("n05.num", 2)]).unwrap();
    assert_eq!(pitches(&r.notes), vec![64, 62]);
    // Missing tracks and subchannels are refused with a sentence.
    for (set, says) in [
        (vec![on("n05"), int("n05.num", 9)], "track 9 does not exist"),
        (
            vec![on("n05"), ch("n05.ref", 1), int("n05.num", 5)],
            "no subchannel at position 5",
        ),
    ] {
        let e = snap_in_doc(&d, &set).err().unwrap();
        assert!(e.user_message().contains(says), "{}", e.user_message());
    }
}

// ---- Snap to Scale: Control Sweeps per note (V09-0143)

#[test]
fn snap_passing_sweep_takes_each_notes_own_threshold() {
    // C# notes of 100 ticks over two bars; the threshold 0 → 480 by time:
    // early notes snap, late ones stay.
    let tg = plumspirit_engine::transform::definition::sweep_targets("snap_scale")
        .iter()
        .find(|t| t.param == "n02.short")
        .copied()
        .unwrap();
    let notes: Vec<(u64, u64, u8)> = (0..16u64).map(|k| (k * 480, 100, 61)).collect();
    let r = snap_on(
        &notes,
        &[
            on("n02"),
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::line(0.0, 1.0))),
        ],
    );
    let got = pitches(&r);
    assert_eq!(got.first(), Some(&60));
    assert_eq!(got.last(), Some(&61));
    let flip = got.iter().position(|&p| p == 61).unwrap();
    assert!(got[flip..].iter().all(|&p| p == 61), "{got:?}");
}

/// E0422's rule for Snap to Scale: a sweep flat at the parameter's own
/// value changes nothing (its function on); a sweep of a function that is
/// off changes nothing.
#[test]
fn snap_flat_sweeps_and_sweeps_of_functions_that_are_off_change_nothing() {
    use plumspirit_engine::transform::definition::{Combine, sweep_targets};
    use plumspirit_engine::transform::param::ParamKind;
    let spec = (tool("snap_scale").unwrap().spec)();
    let mut checked = 0;
    assert_eq!(sweep_targets("snap_scale").len(), 10);
    for tg in sweep_targets("snap_scale") {
        assert!(matches!(tg.combine, Combine::Replace));
        let ps = spec.params.iter().find(|p| p.key == tg.param).unwrap();
        let lo = tg.range.0.min(tg.range.1);
        let v = match ps.kind {
            ParamKind::Float { .. } => ParamValue::Float(lo),
            _ => ParamValue::Int(lo.round() as i64),
        };
        let owner: &'static str = Box::leak(
            tg.param
                .split('.')
                .next()
                .unwrap()
                .to_string()
                .into_boxed_str(),
        );
        let mut base = vec![(tg.param, v)];
        base.push((owner, ParamValue::Bool(true)));
        let a = snap_fix(&base);
        let mut swept = base.clone();
        swept.extend([
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::flat(0.0))),
        ]);
        assert_eq!(
            join_fingerprint(&a),
            join_fingerprint(&snap_fix(&swept)),
            "flat {}",
            tg.param
        );
        checked += 1;
    }
    for f in ALL11 {
        let a = snap_fix(&[on(f)]);
        for tg in sweep_targets("snap_scale")
            .iter()
            .filter(|t| t.param.starts_with('n'))
        {
            let owner: &'static str = Box::leak(
                tg.param
                    .split('.')
                    .next()
                    .unwrap()
                    .to_string()
                    .into_boxed_str(),
            );
            if owner == f {
                continue;
            }
            let swept = vec![
                on(f),
                on("m.sweep"),
                (tg.on, ParamValue::Bool(true)),
                (owner, ParamValue::Bool(false)),
            ];
            assert_eq!(
                join_fingerprint(&a),
                join_fingerprint(&snap_fix(&swept)),
                "{f} (sweep {})",
                tg.param
            );
            checked += 1;
        }
    }
    assert!(checked >= 10 + 11 * 7, "{checked}");
}

#[test]
fn snap_results_keep_every_note_and_are_deterministic() {
    let heavy = [
        on("n01"),
        ch("n01.window", 1),
        on("n02"),
        on("n03"),
        ch("n03.channels", 1),
        on("n04"),
        on("n06"),
        on("n07"),
        on("n08"),
        on("n10"),
    ];
    let a = snap_fix(&heavy);
    let b = snap_fix(&heavy);
    assert_eq!(join_fingerprint(&a), join_fingerprint(&b));
    assert_eq!(a.notes.len(), snap_fixture().len());
    // Lengths and starts never change.
    let mut x: Vec<(u64, u64)> = a.notes.iter().map(|n| (n.start, n.dur)).collect();
    let mut y: Vec<(u64, u64)> = snap_fixture().iter().map(|n| (n.start, n.dur)).collect();
    x.sort_unstable();
    y.sort_unstable();
    assert_eq!(x, y);
}

// ======================================================================= Flip

/// Flip's fixture: Snap to Scale's (chords, runs, passing notes, a second
/// subchannel, three bars).
fn flip_fixture() -> Vec<TNote> {
    snap_fixture()
}

/// Runs Flip on a hand-built source: `notes` selected on one track
/// (subchannels 0 – 3, channel = subchannel), in `Ctx::simple(960)` changed
/// by `tweak`; the whole result (within the kernel's estimate).
fn flip_try(
    notes: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
    tweak: impl FnOnce(&mut Ctx),
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track]);
    let t = tool("flip").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = Ctx::simple(960);
    tweak(&mut ctx);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate_source(&src).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

fn flip_fix(set: &[(&'static str, ParamValue)]) -> plumspirit_engine::transform::TransformRun {
    flip_try(flip_fixture(), set, |_| {}).unwrap()
}

/// Settings of the v0.8 Flip (the axes, each frozen function, its choices
/// and combinations).
fn flip_v08_settings() -> Vec<Vec<(&'static str, ParamValue)>> {
    vec![
        vec![],
        vec![ch("axis", 1)],
        vec![ch("axis", 2)],
        vec![on("a1"), list("a1.pivot", &[300, 64])],
        vec![on("a1"), ch("axis", 2), list("a1.pivot", &[750, 55])],
        vec![on("a2")],
        vec![on("a3")],
        vec![on("a4")],
        vec![on("a5"), ch("axis", 2)],
        vec![on("a6"), ch("axis", 1), ch("a6.key", 2), ch("a6.scale", 1)],
        vec![on("a7")],
        vec![on("a8")],
        vec![on("a9"), ch("axis", 2)],
        vec![on("a10"), fl("a10.amount", 0.3), ch("axis", 2)],
        vec![on("a4"), on("a5"), on("a3"), ch("axis", 1)],
        vec![on("a6"), on("a10"), ch("axis", 2)],
        vec![on("a7"), on("a8"), on("a4")],
        vec![on("a1"), on("a9"), on("a2")],
    ]
}

/// Prints [`join_fingerprint`] of Flip for every [`flip_v08_settings`]
