fn flip_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

#[test]
fn flip_new_functions_off_leave_v08_results_unchanged() {
    for (i, s) in flip_v08_settings().iter().enumerate() {
        assert_eq!(
            join_fingerprint(&flip_fix(&flip_off(s))),
            FLIP_V08[i],
            "setting {i}"
        );
    }
}

/// Neutral settings (the v0.9 path, the v0.8 result): the centre mirrored
/// without a grid (v0.8's span reversal), ticks instead of seconds, no
/// colour pairs, a rectangle round the whole selection — each alone, then
/// together.
fn flip_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n03",
            vec![on("n03"), ch("n03.anchor", 2), ch("n03.snap", 0)],
        ),
        ("n06", vec![on("n06"), ch("n06.in", 1)]),
        ("n07", vec![on("n07"), list("n07.pairs", &[])]),
        (
            "n08",
            vec![
                on("n08"),
                ch("n08.region", 1),
                fl("n08.cx", 50.0),
                fl("n08.cy", 50.0),
                fl("n08.size", 200.0),
            ],
        ),
    ];
    let all: Vec<(&'static str, ParamValue)> =
        each.iter().flat_map(|(_, s)| s.iter().cloned()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn flip_neutral_functions_take_the_v09_path_and_equal_v08() {
    for (f, neutral) in flip_neutral() {
        for (i, s) in flip_v08_settings().iter().enumerate() {
            let mut set = flip_off(s);
            set.extend(neutral.iter().cloned());
            assert_eq!(
                join_fingerprint(&flip_fix(&set)),
                FLIP_V08[i],
                "{f} setting {i}"
            );
        }
    }
}

/// A note as (start, pitch, length).
type Spd = (u64, u8, u64);

/// Flip on `notes` (start, length, pitch; velocity 90, subchannel 0): the
/// result as (start, pitch, length) in time order.
fn flip_on(notes: &[(u64, u64, u8)], set: &[(&'static str, ParamValue)]) -> Vec<(u64, u8, u64)> {
    let v: Vec<TNote> = notes.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    spd(&flip_try(v, set, |_| {}).unwrap().notes)
}

#[test]
fn flip_mirror_append_keeps_the_original_and_adds_the_image_after_before_or_on_it() {
    // Box 1,440 – 2,880: the images 2,400 and 1,440, shifted by the span.
    let v = [(1440, 480, 60), (2400, 480, 64)];
    let base = [(1440, 60, 480), (2400, 64, 480)];
    for (place, shift) in [(0u32, 1440i64), (1, -1440), (2, 0)] {
        let r = flip_on(&v, &[on("n01"), ch("n01.place", place)]);
        let mut want = base.to_vec();
        want.push(((2400 + shift) as u64, 60, 480));
        want.push(((1440 + shift) as u64, 64, 480));
        want.sort_unstable();
        assert_eq!(r, want, "placement {place}");
    }
    // The copy's velocity.
    let notes: Vec<TNote> = v.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    let r = flip_try(notes, &[on("n01"), fl("n01.vel", 50.0)], |_| {}).unwrap();
    let mut vels: Vec<u8> = r.notes.iter().map(|n| n.vel).collect();
    vels.sort_unstable();
    assert_eq!(vels, vec![45, 45, 90, 90]);
}

#[test]
fn flip_half_mirror_replaces_the_other_half_with_the_kept_halfs_mirror() {
    let v = [(0, 240, 60), (240, 240, 64), (480, 240, 67), (720, 240, 72)];
    // Upper half kept (centre 66): 67 / 72 and their mirrors 65 / 60.
    assert_eq!(
        flip_on(&v, &[on("n02"), ch("n02.keep", 0)]),
        vec![
            (480, 65, 240),
            (480, 67, 240),
            (720, 60, 240),
            (720, 72, 240)
        ]
    );
    // Lower: 60 / 64 and 72 / 68.
    assert_eq!(
        flip_on(&v, &[on("n02"), ch("n02.keep", 1)]),
        vec![(0, 60, 240), (0, 72, 240), (240, 64, 240), (240, 68, 240)]
    );
    // Left of 480: the first two and their spans reversed (720, 480).
    assert_eq!(
        flip_on(&v, &[on("n02"), ch("n02.keep", 2)]),
        vec![(0, 60, 240), (240, 64, 240), (480, 64, 240), (720, 60, 240)]
    );
    // Right: 67 / 72 and their images at 240 / 0.
    assert_eq!(
        flip_on(&v, &[on("n02"), ch("n02.keep", 3)]),
        vec![(0, 72, 240), (240, 67, 240), (480, 67, 240), (720, 72, 240)]
    );
    // Around the pivot (key 64): 64 is its own image (once), 67 → 61,
    // 72 → 56.
    assert_eq!(
        flip_on(
            &v,
            &[
                on("n02"),
                ch("n02.axis", 1),
                on("a1"),
                list("a1.pivot", &[500, 64])
            ]
        ),
        vec![
            (240, 64, 240),
            (480, 61, 240),
            (480, 67, 240),
            (720, 56, 240),
            (720, 72, 240)
        ]
    );
}

#[test]
fn flip_mirror_anchor_mirrors_the_start_end_or_centre_on_the_grid_or_not() {
    // Box 960 – 2,160 (pivot 1,560).
    let v = [(960, 240, 60), (1680, 480, 62)];
    let cases: [(u32, u32, [Spd; 2]); 6] = [
        // Start: 3,120 − start.
        (0, 0, [(1440, 62, 480), (2160, 60, 240)]),
        // End: the new end at 3,120 − end.
        (1, 0, [(480, 62, 480), (1680, 60, 240)]),
        // Centre: v0.8 (the span reversed).
        (2, 0, [(960, 62, 480), (1920, 60, 240)]),
        // On the 1/16 grid (240).
        (0, 1, [(1440, 62, 480), (2160, 60, 240)]),
        (1, 1, [(480, 62, 480), (1680, 60, 240)]),
        // The centre on the grid: 2,040 → 2,160 (start 2,040); 1,200 stays.
        (2, 1, [(960, 62, 480), (2040, 60, 240)]),
    ];
    for (anchor, snap, want) in cases {
        let r = flip_on(
            &v,
            &[on("n03"), ch("n03.anchor", anchor), ch("n03.snap", snap)],
        );
        assert_eq!(r, want.to_vec(), "anchor {anchor} snap {snap}");
    }
    // Off the grid: box 1,000 – 2,180 (pivot 1,590); the mirrored point
    // snaps to 240.
    let v = [(1000, 240, 60), (1700, 480, 62)];
    let r = |a: u32| flip_on(&v, &[on("n03"), ch("n03.anchor", a), ch("n03.snap", 1)]);
    // Start: 2,180 → 2,160, 1,480 → 1,440.
    assert_eq!(r(0), vec![(1440, 62, 480), (2160, 60, 240)]);
    // End: 1,940 → 1,920 (start 1,680), 1,000 → 960 (start 480).
    assert_eq!(r(1), vec![(480, 62, 480), (1680, 60, 240)]);
    // Centre: 2,060 → 2,160 (start 2,040), 1,240 → 1,200 (start 960).
    assert_eq!(r(2), vec![(960, 62, 480), (2040, 60, 240)]);
}

#[test]
fn flip_glide_reflection_repeats_every_half_period_with_odd_copies_flipped() {
    // Keys 60 – 64 (axis 62), period 960: copies 480 apart.
    let v = [(0, 240, 60), (240, 240, 64)];
    let r = flip_on(
        &v,
        &[
            on("n04"),
            int("n04.period", 960),
            int("n04.copies", 3),
            int("n04.offset", 3),
        ],
    );
    // The selection's own time flip (v0.8, axis Time) stays off the copies'
    // path: in copies mode the selection is kept.
    assert_eq!(
        r,
        vec![
            (0, 60, 240),
            (240, 64, 240),
            (480, 67, 240),
            (720, 63, 240),
            (960, 60, 240),
            (1200, 64, 240),
            (1440, 67, 240),
            (1680, 63, 240),
        ]
    );
}

#[test]
fn flip_angled_mirror_reflects_onsets_across_a_line_of_any_angle() {
    let v = [(0, 240, 60), (480, 240, 64), (720, 240, 72)];
    // 0°: the horizontal line through the middle — a key mirror (60 ↔ 72).
    assert_eq!(
        flip_on(&v, &[on("n05"), fl("n05.angle", 0.0)]),
        vec![(0, 72, 240), (480, 68, 240), (720, 60, 240)]
    );
    // 0° offset 100 %: the line on the top edge — 2·72 − key.
    assert_eq!(
        flip_on(
            &v,
            &[on("n05"), fl("n05.angle", 0.0), fl("n05.offset", 100.0)]
        ),
        vec![(0, 84, 240), (480, 80, 240), (720, 72, 240)]
    );
    // 90°: the vertical line — onsets mirrored in the box 0 – 960.
    assert_eq!(
        flip_on(&v, &[on("n05"), fl("n05.angle", 90.0)]),
        vec![(240, 72, 240), (480, 64, 240), (960, 60, 240)]
    );
    // 45°: the box's diagonal = v0.8's diagonal flip.
    assert_eq!(
        flip_on(&v, &[on("n05"), fl("n05.angle", 45.0)]),
        flip_on(&v, &[on("a2")])
    );
}

#[test]
fn flip_real_time_mirror_reverses_in_seconds_across_a_tempo_change() {
    // 120 BPM, 60 BPM from tick 960: the box 0 – 1,920 is 0 – 1.5 s.
    let v: Vec<TNote> = [(0, 480, 60), (960, 960, 62)]
        .iter()
        .map(|&(s, d, p)| tn(s, d, p, 90))
        .collect();
    let tempo = |c: &mut Ctx| {
        c.tempo = Some(Arc::new(TempoMap::from_tempos(
            TEMPO_RATE,
            960,
            &[
                (0, TempoValue::Micros(500_000)),
                (960, TempoValue::Micros(1_000_000)),
            ],
        )));
    };
    let r = flip_try(v.clone(), &[on("n06")], tempo).unwrap();
    // 0 – 0.25 s → 1.25 – 1.5 s (ticks 1,680 – 1,920); 0.5 – 1.5 s → 0 – 1 s
    // (ticks 0 – 1,440).
    assert_eq!(spd(&r.notes), vec![(0, 62, 1440), (1680, 60, 240)]);
    // In ticks: v0.8.
    let r = flip_try(v.clone(), &[on("n06"), ch("n06.in", 1)], tempo).unwrap();
    assert_eq!(spd(&r.notes), vec![(0, 62, 960), (1440, 60, 480)]);
    // Without a tempo change seconds = ticks.
    let a = flip_try(v.clone(), &[on("n06")], |_| {}).unwrap();
    let b = flip_try(v, &[], |_| {}).unwrap();
    assert_eq!(spd(&a.notes), spd(&b.notes));
}

#[test]
fn flip_colour_pairs_swap_the_images_subchannels() {
    let v = vec![
        TNote {
            sub: 0,
            ..tn(0, 240, 60, 90)
        },
        TNote {
            sub: 1,
            ..tn(240, 240, 64, 90)
        },
        TNote {
            sub: 3,
            ..tn(480, 240, 67, 90)
        },
    ];
    let r = flip_try(
        v.clone(),
        &[on("n07"), list("n07.pairs", &[0, 2, 1, 3])],
        |_| {},
    )
    .unwrap();
    let mut got: Vec<(u64, u32, u8)> = r.notes.iter().map(|n| (n.start, n.sub, n.ch)).collect();
    got.sort_unstable();
    // 0 → 2, 1 → 3, 3 → 1; channels kept.
    assert_eq!(got, vec![(0, 1, 0), (240, 3, 0), (480, 2, 0)]);
    // With Mirror append only the images change colour.
    let r = flip_try(
        v,
        &[on("n07"), list("n07.pairs", &[0, 2]), on("n01")],
        |_| {},
    )
    .unwrap();
    let mut subs: Vec<u32> = r.notes.iter().map(|n| n.sub).collect();
    subs.sort_unstable();
    assert_eq!(subs, vec![0, 1, 1, 2, 3, 3]);
}

#[test]
fn flip_region_flips_only_the_notes_inside_in_their_own_box() {
    // Selection box 0 – 960 × 60 – 66; a centred region half its size.
    let v = [(0, 240, 60), (360, 240, 63), (480, 240, 63), (720, 240, 66)];
    let reg = |kind: u32, size: f64| {
        vec![
            on("n08"),
            ch("n08.region", kind),
            fl("n08.cx", 50.0),
            fl("n08.cy", 50.0),
            fl("n08.size", size),
        ]
    };
    // A rectangle of 100 % holds all four: v0.8.
    assert_eq!(flip_on(&v, &reg(1, 100.0)), flip_on(&v, &[]));
    // The ellipse leaves the corners (0, 60) and (720, 66): the middle two
    // flip in their own box 360 – 720.
    assert_eq!(
        flip_on(&v, &reg(0, 100.0)),
        vec![(0, 60, 240), (360, 63, 240), (480, 63, 240), (720, 66, 240)]
    );
    let notes: Vec<TNote> = v.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    let r = flip_try(notes.clone(), &reg(0, 100.0), |_| {}).unwrap();
    assert_eq!(
        r.message.as_deref(),
        Some("Region flip: 2 note(s) inside the region flipped.")
    );
    // Moved off the notes: nothing flips, and the summary says so.
    let mut far = reg(1, 10.0);
    far.push(fl("n08.cx", 100.0));
    far.push(fl("n08.cy", 0.0));
    let r = flip_try(notes, &far, |_| {}).unwrap();
    assert_eq!(
        spd(&r.notes),
        vec![(0, 60, 240), (360, 63, 240), (480, 63, 240), (720, 66, 240)]
    );
    assert_eq!(
        r.message.as_deref(),
        Some("Region flip: no note lies inside the region.")
    );
}

#[test]
fn flip_recursive_mirror_mirrors_halves_inside_halves() {
    // Box 0 – 1,920 × 60 – 72.
    let v = [(0, 240, 60), (480, 480, 64), (1680, 240, 72)];
    let r = |depth: i64, axis: u32| {
        flip_on(
            &v,
            &[on("n09"), int("n09.depth", depth), ch("n09.axis", axis)],
        )
    };
    // Depth 1 in time = v0.8's time flip.
    assert_eq!(r(1, 0), flip_on(&v, &[]));
    // Depth 2 in time: 0 → 1,680 (right half) → 960; 480 → 960 → 1,440;
    // 1,680 → 0 (left half) → 720.
    assert_eq!(
        r(2, 0),
        vec![(720, 72, 240), (960, 60, 240), (1440, 64, 480)]
    );
    // Depth 2 in pitch: 60 → 72 → 66, 64 → 68 → 70, 72 → 60 → 66.
    assert_eq!(r(2, 1), vec![(0, 66, 240), (480, 70, 480), (1680, 66, 240)]);
    // Alternating, depth 2: time then pitch = v0.8's Both.
    assert_eq!(r(2, 2), flip_on(&v, &[ch("axis", 2)]));
}

#[test]
fn flip_swing_flip_mirrors_the_timing_inside_each_grid_pair() {
    // Long-short in two beat-long pairs (grid 1/8): short-long. Pitch flip
    // only, so the timing is the swing flip's alone.
    let v = [
        (0, 640, 60),
        (640, 320, 62),
        (960, 640, 60),
        (1600, 320, 62),
    ];
    let r = flip_on(&v, &[ch("axis", 1), on("n10"), ch("n10.grid", 3)]);
    let t: Vec<(u64, u64)> = r.iter().map(|x| (x.0, x.2)).collect();
    assert_eq!(t, vec![(0, 320), (320, 640), (960, 320), (1280, 640)]);
    // Twice = the original timing.
    let back: Vec<(u64, u64, u8)> = r.iter().map(|&(s, p, d)| (s, d, p)).collect();
    let again = flip_on(&back, &[ch("axis", 1), on("n10"), ch("n10.grid", 3)]);
    let t: Vec<(u64, u64)> = again.iter().map(|x| (x.0, x.2)).collect();
    assert_eq!(t, vec![(0, 640), (640, 320), (960, 640), (1600, 320)]);
}

#[test]
fn flip_moving_axis_follows_the_path_across_the_span() {
    let v = [(0, 240, 60), (960, 240, 72)];
    // Axis 66 + (path − 0.5) · 12: 60 at the start, 69.6 at 0.8.
    let r = flip_on(
        &v,
        &[
            ch("axis", 1),
            on("n11"),
            curve("n11.path", Curve::line(0.0, 1.0)),
            int("n11.range", 12),
        ],
    );
    assert_eq!(r, vec![(0, 60, 240), (960, 67, 240)]);
    // A flat path at the middle = v0.8's pitch flip.
    assert_eq!(
        flip_on(
            &v,
            &[
                ch("axis", 1),
                on("n11"),
                curve("n11.path", Curve::flat(0.5))
            ]
        ),
        flip_on(&v, &[ch("axis", 1)])
    );
}

#[test]
fn flip_functions_compose_in_their_declared_order() {
    // n08's region (the first two notes) → the mirror → n07's colours → n01's
    // copies after the region's box.
    let v = vec![
        tn(0, 240, 60, 90),
        tn(240, 240, 62, 90),
        tn(1680, 240, 64, 90),
    ];
    let r = flip_try(
        v,
        &[
            on("n08"),
            ch("n08.region", 1),
            fl("n08.cx", 0.0),
            fl("n08.cy", 50.0),
            fl("n08.size", 100.0),
            on("n07"),
            list("n07.pairs", &[0, 1]),
            on("n01"),
        ],
        |_| {},
    )
    .unwrap();
    let mut got: Vec<(u64, u8, u32)> = r.notes.iter().map(|n| (n.start, n.pitch, n.sub)).collect();
    got.sort_unstable();
    assert_eq!(
        got,
        vec![
            (0, 60, 0),
            (240, 62, 0),
            (480, 62, 1),
            (720, 60, 1),
            (1680, 64, 0)
        ]
    );
}

// ---- Flip: Control Sweeps per note

#[test]
fn flip_append_velocity_sweep_takes_each_notes_own_value() {
    let tg = plumspirit_engine::transform::definition::sweep_targets("flip")
        .iter()
        .find(|t| t.param == "n01.vel")
        .copied()
        .unwrap();
    // Images in subchannel 1 (n07), on the originals (overlay).
    let v: Vec<TNote> = (0..8u64).map(|k| tn(k * 480, 240, 60, 90)).collect();
    let r = flip_try(
        v,
        &[
            ch("axis", 1),
            on("n01"),
            ch("n01.place", 2),
            on("n07"),
            list("n07.pairs", &[0, 1]),
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::line(0.0, 1.0))),
        ],
        |_| {},
    )
    .unwrap();
    let mut copies: Vec<(u64, u8)> = r
        .notes
        .iter()
        .filter(|n| n.sub == 1)
        .map(|n| (n.start, n.vel))
        .collect();
    copies.sort_unstable();
    assert_eq!(copies.len(), 8);
    assert!(copies.windows(2).all(|w| w[0].1 <= w[1].1), "{copies:?}");
    assert!(copies[0].1 <= 2, "{copies:?}");
    assert!(copies[7].1 >= 110, "{copies:?}");
}

/// E0422's rule for Flip: a sweep flat at the parameter's own value
/// changes nothing (its function on); a sweep of a function that is off
/// changes nothing (on the v0.8 settings too).
#[test]
fn flip_flat_sweeps_and_sweeps_of_functions_that_are_off_change_nothing() {
    use plumspirit_engine::transform::definition::{Combine, sweep_targets};
    use plumspirit_engine::transform::param::ParamKind;
    let spec = (tool("flip").unwrap().spec)();
    let mut checked = 0;
    assert_eq!(sweep_targets("flip").len(), 10);
    let owner = |p: &str| -> &'static str {
        Box::leak(p.split('.').next().unwrap().to_string().into_boxed_str())
    };
    for tg in sweep_targets("flip") {
        assert!(matches!(tg.combine, Combine::Replace));
        let ps = spec.params.iter().find(|p| p.key == tg.param).unwrap();
        let lo = tg.range.0.min(tg.range.1);
        let v = match ps.kind {
            ParamKind::Float { .. } => ParamValue::Float(lo),
            _ => ParamValue::Int(lo.round() as i64),
        };
        let base = vec![(tg.param, v), (owner(tg.param), ParamValue::Bool(true))];
        let a = flip_fix(&base);
        let mut swept = base.clone();
        swept.extend([
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::flat(0.0))),
        ]);
        assert_eq!(
            join_fingerprint(&a),
            join_fingerprint(&flip_fix(&swept)),
            "flat {}",
            tg.param
        );
        checked += 1;
    }
    for f in ALL11 {
        let a = flip_fix(&[on(f)]);
        for tg in sweep_targets("flip") {
            let o = owner(tg.param);
            if o == f {
                continue;
            }
            let swept = vec![
                on(f),
                on("m.sweep"),
                (tg.on, ParamValue::Bool(true)),
                (o, ParamValue::Bool(false)),
            ];
            assert_eq!(
                join_fingerprint(&a),
                join_fingerprint(&flip_fix(&swept)),
                "{f} (sweep {})",
                tg.param
            );
            checked += 1;
        }
    }
    // The v0.8 settings with a sweep of an off function: the v0.9 kernel,
    // the v0.8 result.
    let tg = sweep_targets("flip")[7];
    for (i, s) in flip_v08_settings().iter().enumerate() {
        let mut set = flip_off(s);
        set.extend([on("m.sweep"), (tg.on, ParamValue::Bool(true))]);
        assert_eq!(
            join_fingerprint(&flip_fix(&set)),
            FLIP_V08[i],
            "setting {i}"
        );
        checked += 1;
    }
    assert!(checked >= 10 + 11 * 8 + 18, "{checked}");
}

#[test]
fn flip_results_are_deterministic_and_within_the_estimate() {
    let heavy = [
        on("n01"),
        on("n03"),
        ch("n03.snap", 1),
        on("n04"),
        on("n06"),
        on("n07"),
        on("n08"),
        on("n10"),
        on("n11"),
    ];
    let a = flip_fix(&heavy);
    let b = flip_fix(&heavy);
    assert_eq!(join_fingerprint(&a), join_fingerprint(&b));
    // Replace mode keeps the count (n02 aside); copies mode adds.
    for f in ["n03", "n05", "n06", "n07", "n08", "n09", "n10", "n11"] {
        assert_eq!(flip_fix(&[on(f)]).notes.len(), flip_fixture().len(), "{f}");
    }
    assert_eq!(flip_fix(&[on("n01")]).notes.len(), 2 * flip_fixture().len());
    assert_eq!(flip_fix(&[on("n04")]).notes.len(), 5 * flip_fixture().len());
    assert!(flip_fix(&[on("n02")]).notes.len() <= 2 * flip_fixture().len());
}

// ================================================================= Duplicate

/// Duplicate's fixture: Flip's (Snap to Scale's: chords, runs, passing
/// notes, a second subchannel, three bars).
fn dup_fixture() -> Vec<TNote> {
    flip_fixture()
}

/// The four tracks of Duplicate's hand-built sources: slot 0 selected
/// (subchannels 0 – 3, channel = subchannel), slots 1 – 3 the following
/// tracks as destinations (insert only; subchannels 10 – 11 on slot 1).
fn dup_tracks(dest: usize) -> Vec<SourceTrack> {
    let mut v = vec![SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    }];
    for i in 1..=dest {
        v.push(SourceTrack {
            id: TrackId(i as u32 + 1),
            index: i,
            content: None,
            revision: 0,
            subs: if i == 1 {
                vec![(10, 4), (11, 5)]
            } else {
                vec![(0, 0)]
            },
            all: false,
            insert_only: true,
            frame: 0,
        });
    }
    v
}

/// Runs Duplicate on a hand-built source: `notes` selected on slot 0,
/// `prep` filling the prepared parts of the source (routes, layers,
/// events), in `Ctx::simple(960)` changed by `tweak`; the whole result
/// (within the kernel's estimates).
fn dup_try_with(
    notes: Vec<TNote>,
    tracks: Vec<SourceTrack>,
    set: &[(&'static str, ParamValue)],
    prep: impl FnOnce(&mut Source),
    tweak: impl FnOnce(&mut Ctx),
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let mut src = Source::from_notes(notes, tracks);
    prep(&mut src);
    let t = tool("duplicate").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = Ctx::simple(960);
    tweak(&mut ctx);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate_source(&src).notes;
    let bound = k.estimate(&src.stats).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    assert!(est <= bound, "{est} > {bound}");
    Ok(r)
}

fn dup_try(
    notes: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
    tweak: impl FnOnce(&mut Ctx),
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    dup_try_with(notes, dup_tracks(0), set, |_| {}, tweak)
}

fn dup_fix(set: &[(&'static str, ParamValue)]) -> plumspirit_engine::transform::TransformRun {
    dup_try(dup_fixture(), set, |_| {}).unwrap()
}

