/// Duplicate's functions by id (n06 is retired; n12 took its place).
const DUP11: [&str; 11] = [
    "n01", "n02", "n03", "n04", "n05", "n12", "n07", "n08", "n09", "n10", "n11",
];

fn dup_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in DUP11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

fn dup_text(k: &'static str, v: &str) -> (&'static str, ParamValue) {
    (k, ParamValue::Text(v.to_owned()))
}

#[test]
fn dup_new_functions_off_leave_v08_results_unchanged() {
    for (i, s) in dup_v08_settings().iter().enumerate() {
        assert_eq!(
            join_fingerprint(&dup_fix(&dup_off(s))),
            DUP_V08[i],
            "setting {i}"
        );
    }
}

/// Neutral settings (the v0.9 path, the v0.8 result): no rotation, one
/// chord everywhere (no transposition), notes only, every note kept — each
/// alone, then together.
fn dup_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n04", vec![on("n04"), int("n04.rotate", 0)]),
        (
            "n07",
            vec![on("n07"), dup_text("n07.chords", "C"), ch("n07.fit", 0)],
        ),
        ("n08", vec![on("n08"), ch("n08.include", 0)]),
        ("n09", vec![on("n09"), fl("n09.keep", 100.0)]),
    ];
    let all: Vec<(&'static str, ParamValue)> =
        each.iter().flat_map(|(_, s)| s.iter().cloned()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn dup_neutral_functions_take_the_v09_path_and_equal_v08() {
    for (f, neutral) in dup_neutral() {
        for (i, s) in dup_v08_settings().iter().enumerate() {
            let mut set = dup_off(s);
            set.extend(neutral.iter().cloned());
            assert_eq!(
                join_fingerprint(&dup_fix(&set)),
                DUP_V08[i],
                "{f} setting {i}"
            );
        }
    }
}

/// Duplicate on `notes` (start, length, pitch; velocity 90, subchannel 0):
/// the result as (start, pitch, length) in time order.
fn dup_on(notes: &[(u64, u64, u8)], set: &[(&'static str, ParamValue)]) -> Vec<(u64, u8, u64)> {
    let v: Vec<TNote> = notes.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    spd(&dup_try(v, set, |_| {}).unwrap().notes)
}

/// `base` and `extra` together, in time order.
fn dup_with(base: &[(u64, u8, u64)], extra: &[(u64, u8, u64)]) -> Vec<(u64, u8, u64)> {
    let mut v = base.to_vec();
    v.extend_from_slice(extra);
    v.sort_unstable();
    v
}

/// Two notes in one beat (span 480 → one copy 480 later at the v0.8
/// defaults).
const DUP2: &[(u64, u64, u8)] = &[(0, 240, 60), (240, 240, 62)];
const DUP2_SPD: &[(u64, u8, u64)] = &[(0, 60, 240), (240, 62, 240)];

#[test]
fn dup_to_tracks_layers_copies_on_each_target_with_subchannels_by_position() {
    let v = vec![
        tn(0, 240, 60, 90),
        TNote {
            sub: 1,
            ch: 1,
            ..tn(240, 240, 62, 90)
        },
    ];
    let prep = |s: &mut Source| s.routes = Arc::new(vec![(0, 1), (0, 2)]);
    let r = dup_try_with(
        v.clone(),
        dup_tracks(2),
        &[on("n01"), int("n01.count", 2), on("a3"), int("a3.step", 12)],
        prep,
        |_| {},
    )
    .unwrap();
    // The originals stay on slot 0; slots 1 and 2 get two layers each at
    // the selection's own time, a3's step by layer.
    assert_eq!(on_slot(&r, 0), vec![(0, 240, 60), (240, 480, 62)]);
    for slot in [1, 2] {
        assert_eq!(
            on_slot(&r, slot),
            vec![(0, 240, 72), (0, 240, 84), (240, 480, 74), (240, 480, 86)],
            "slot {slot}"
        );
    }
    // Subchannels by position on the target's table (slot 1: 10, 11),
    // channels kept; slot 2 has one subchannel.
    let mut subs: Vec<(u16, u32, u8)> = r
        .notes
        .iter()
        .filter(|n| n.track > 0)
        .map(|n| (n.track, n.sub, n.ch))
        .collect();
    subs.sort_unstable();
    subs.dedup();
    assert_eq!(subs, vec![(1, 10, 0), (1, 11, 1), (2, 0, 0), (2, 0, 1)]);
    // Without routes nothing is pasted (the preparation refuses first).
    let r = dup_try_with(v, dup_tracks(2), &[on("n01")], |_| {}, |_| {}).unwrap();
    assert_eq!(r.notes.len(), 2);
}

#[test]
fn dup_to_tracks_prepares_next_listed_and_subtracks_and_applies_in_one_undo_step() {
    let mut d = PlumDocument::new_project("dup".into(), Bpm::DEFAULT, 960);
    let mut h = History::default();
    h.apply(
        &mut d,
        Operation::AddSubtracks {
            parent: 0,
            count: 2,
        },
    )
    .unwrap();
    h.apply(&mut d, Operation::AddTrack).unwrap();
    assert_eq!(d.track_count(), 4);
    let v = vec![rec(0, 240, 60), rec(240, 240, 64)];
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&v, true)
        .unwrap();
    let t = tool("duplicate").unwrap();
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let go = |d: &PlumDocument, set: &[(&'static str, ParamValue)]| {
        let mut ps = ParamSet::defaults(&(t.spec)().params);
        for (k, val) in set {
            ps.set(k, val.clone());
        }
        let src = collect_with(t, d, &sc, &ps, 1 << 20)?;
        let ctx = Ctx::simple(960);
        let b = BuildCtx {
            ctx: &ctx,
            stats: &src.stats,
            tracks: &src.tracks,
        };
        let k = t.kernel(&ps, &b)?;
        run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)
    };
    let indices = |r: &plumspirit_engine::transform::TransformRun| -> Vec<usize> {
        let mut v: Vec<usize> = r
            .notes
            .iter()
            .map(|n| r.tracks[usize::from(n.track)].index)
            .collect();
        v.sort_unstable();
        v.dedup();
        v
    };
    // Next tracks at offsets 1 and 3: tracks 1 and 3.
    let r = go(&d, &[on("n01"), list("n01.tracks", &[1, 3])]).unwrap();
    assert_eq!(indices(&r), vec![0, 1, 3]);
    // Listed: track 4 (index 3); track 9 does not exist.
    let r = go(
        &d,
        &[on("n01"), ch("n01.targets", 1), list("n01.tracks", &[4, 9])],
    )
    .unwrap();
    assert_eq!(indices(&r), vec![0, 3]);
    // Subtracks: 1 and 2 (track 3 is top level).
    let r = go(&d, &[on("n01"), ch("n01.targets", 2)]).unwrap();
    assert_eq!(indices(&r), vec![0, 1, 2]);
    // Nothing to paste onto: a sentence.
    let e = go(&d, &[on("n01"), list("n01.tracks", &[7])]).unwrap_err();
    assert!(e.user_message().starts_with("To tracks:"), "{e:?}");
    // Apply: one undo step; undo restores every track.
    let before = d.state_fingerprint();
    plumspirit_engine::transform::run::commit(&mut h, &mut d, &r, "Duplicate").unwrap();
    assert_eq!(d.track(1).unwrap().notes.len(), 2);
    assert_eq!(d.track(2).unwrap().notes.len(), 2);
    assert_eq!(d.track(0).unwrap().notes.len(), 2);
    h.undo(&mut d).unwrap();
    assert_eq!(d.state_fingerprint(), before);
}

#[test]
fn dup_canon_adds_entries_in_augmentation_diminution_inversion_or_retrograde() {
    let set = |kind: u32, f: f64| {
        vec![
            on("n02"),
            ch("n02.kind", kind),
            fl("n02.factor", f),
            int("n02.delay", 960),
            int("n02.entries", 2),
        ]
    };
    // Augmentation ×2 per entry around the selection's start, entry k at
    // k · 960.
    assert_eq!(
        dup_on(DUP2, &set(0, 200.0)),
        dup_with(
            DUP2_SPD,
            &[
                (960, 60, 480),
                (1440, 62, 480),
                (1920, 60, 960),
                (2880, 62, 960)
            ]
        )
    );
    // Diminution by the same factor: ×½, ×¼.
    assert_eq!(
        dup_on(DUP2, &set(1, 200.0)),
        dup_with(
            DUP2_SPD,
            &[
                (960, 60, 120),
                (1080, 62, 120),
                (1920, 60, 60),
                (1980, 62, 60)
            ]
        )
    );
    // Inversion around the first note (60): 62 → 58.
    assert_eq!(
        dup_on(DUP2, &set(2, 100.0)),
        dup_with(
            DUP2_SPD,
            &[
                (960, 60, 240),
                (1200, 58, 240),
                (1920, 60, 240),
                (2160, 58, 240)
            ]
        )
    );
    // Retrograde: the span reversed (0 – 480), then delayed.
    assert_eq!(
        dup_on(DUP2, &set(3, 100.0)),
        dup_with(
            DUP2_SPD,
            &[
                (960, 62, 240),
                (1200, 60, 240),
                (1920, 62, 240),
                (2160, 60, 240)
            ]
        )
    );
}

#[test]
fn dup_at_positions_pastes_at_markers_bars_reference_changes_or_listed_ticks() {
    // Listed ticks: the selection's own start (0) is left out.
    let r = dup_on(
        DUP2,
        &[
            on("n03"),
            ch("n03.at", 3),
            list("n03.ticks", &[3840, 0, 960]),
        ],
    );
    assert_eq!(
        r,
        dup_with(
            DUP2_SPD,
            &[
                (960, 60, 240),
                (1200, 62, 240),
                (3840, 60, 240),
                (4080, 62, 240)
            ]
        )
    );
    // Markers, in the tools' ticks (song tick − shift).
    let v: Vec<TNote> = DUP2.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    let r = dup_try(v.clone(), &[on("n03"), ch("n03.at", 0)], |c| {
        c.markers = Arc::new(vec![2000, 5000]);
        c.shift = 1000;
    })
    .unwrap();
    assert_eq!(
        spd(&r.notes),
        dup_with(
            DUP2_SPD,
            &[
                (1000, 60, 240),
                (1240, 62, 240),
                (4000, 60, 240),
                (4240, 62, 240)
            ]
        )
    );
    let e = dup_try(v.clone(), &[on("n03"), ch("n03.at", 0)], |_| {}).unwrap_err();
    assert!(e.user_message().contains("no markers"), "{e:?}");
    // Every bar the time selection touches (4/4 at 960: bars of 3,840).
    let r = dup_try(v.clone(), &[on("n03"), ch("n03.at", 1)], |c| {
        c.time_range = Some((5000, 11_520));
    })
    .unwrap();
    let starts: Vec<u64> = spd(&r.notes).iter().map(|x| x.0).collect();
    assert_eq!(starts, vec![0, 240, 3840, 4080, 7680, 7920]);
    let e = dup_try(v.clone(), &[on("n03"), ch("n03.at", 1)], |_| {}).unwrap_err();
    assert!(e.user_message().contains("time selection"), "{e:?}");
    // The reference's chord changes: C E at 0 and an octave up at 1,920
    // (the same classes), F at 3,840.
    let refs = vec![
        tn(0, 960, 60, 90),
        tn(0, 960, 64, 90),
        tn(1920, 960, 72, 90),
        tn(1920, 960, 76, 90),
        tn(3840, 960, 65, 90),
    ];
    let r = dup_try_with(
        v,
        dup_tracks(0),
        &[on("n03"), ch("n03.at", 2)],
        |s| s.aux = Arc::new(vec![refs]),
        |_| {},
    )
    .unwrap();
    // 0 is the selection's own start: one copy, at 3,840.
    assert_eq!(
        spd(&r.notes),
        dup_with(DUP2_SPD, &[(3840, 60, 240), (4080, 62, 240)])
    );
}

#[test]
fn dup_pitch_rotation_cycles_the_motif_per_copy_and_keeps_the_rhythm() {
    let v = [(0, 240, 60), (240, 240, 62), (480, 480, 64)];
    // Span 960: copies at 960 and 1,920.
    let r = dup_on(
        &v,
        &[
            on("a1"),
            int("a1.count", 2),
            on("n04"),
            int("n04.rotate", 1),
        ],
    );
    assert_eq!(
        r,
        vec![
            (0, 60, 240),
            (240, 62, 240),
            (480, 64, 480),
            (960, 62, 240),
            (1200, 64, 240),
            (1440, 60, 480),
            (1920, 64, 240),
            (2160, 60, 240),
            (2400, 62, 480),
        ]
    );
    // −1 per copy = 2 per copy here (three notes).
    let a = dup_on(
        &v,
        &[
            on("a1"),
            int("a1.count", 2),
            on("n04"),
            int("n04.rotate", -1),
        ],
    );
    let b = dup_on(
        &v,
        &[
            on("a1"),
            int("a1.count", 2),
            on("n04"),
            int("n04.rotate", 2),
        ],
    );
    assert_eq!(a, b);
}

#[test]
fn dup_along_a_path_places_copies_by_spacing_and_the_paths_height() {
    let r = dup_on(
        &[(0, 240, 60)],
        &[
            on("n05"),
            curve("n05.path", Curve::line(0.0, 1.0)),
            int("n05.range", 12),
            int("n05.spacing", 960),
            int("n05.copies", 4),
        ],
    );
    // Copy k at k · 960, k / 4 of the way up 12 keys.
    assert_eq!(
        r,
        vec![
            (0, 60, 240),
            (960, 63, 240),
            (1920, 66, 240),
            (2880, 69, 240),
            (3840, 72, 240)
        ]
    );
    // An arch returns to the start.
    let r = dup_on(
        &[(0, 240, 60)],
        &[
            on("n05"),
            curve(
                "n05.path",
                Curve::new(vec![(0.0, 0.0), (0.5, 1.0), (1.0, 0.0)]),
            ),
            int("n05.range", 10),
            int("n05.copies", 2),
        ],
    );
    assert_eq!(r, vec![(0, 60, 240), (1920, 70, 240), (3840, 60, 240)]);
}

#[test]
fn dup_harmonic_sequence_moves_each_copy_along_the_root_motion() {
    let base = [on("a1"), int("a1.count", 3), on("n12")];
    let pitches = |extra: &[(&'static str, ParamValue)]| -> Vec<u8> {
        let mut s = base.to_vec();
        s.extend_from_slice(extra);
        dup_on(&[(0, 240, 60)], &s).iter().map(|x| x.1).collect()
    };
    // Chromatic fifths: +7 per copy.
    assert_eq!(pitches(&[ch("n12.motion", 0)]), vec![60, 67, 74, 81]);
    // Fourths up, thirds down, chromatic.
    assert_eq!(pitches(&[ch("n12.motion", 1)]), vec![60, 65, 70, 75]);
    assert_eq!(pitches(&[ch("n12.motion", 2)]), vec![60, 57, 54, 51]);
    assert_eq!(pitches(&[ch("n12.motion", 3)]), vec![60, 61, 62, 63]);
    // In C major: four degrees per copy (C G D A), thirds down by degrees
    // (C A F D).
    assert_eq!(
        pitches(&[ch("n12.motion", 0), ch("n12.within", 1)]),
        vec![60, 67, 74, 81]
    );
    assert_eq!(
        pitches(&[ch("n12.motion", 2), ch("n12.within", 1)]),
        vec![60, 57, 53, 50]
    );
    // In A minor (key 9, natural minor): A E B F.
    assert_eq!(
        dup_on(
            &[(0, 240, 57)],
            &[
                on("a1"),
                int("a1.count", 3),
                on("n12"),
                ch("n12.within", 1),
                ch("n12.key", 9),
                ch("n12.scale", 1)
            ]
        )
        .iter()
        .map(|x| x.1)
        .collect::<Vec<u8>>(),
        vec![57, 64, 71, 77]
    );
}

#[test]
fn dup_progression_fit_transposes_or_snaps_each_copy_to_its_bars_chord() {
    // Bars of 3,840; copies one and two bars later (n11).
    let v = [(0, 240, 60), (240, 240, 62), (480, 240, 64)];
    let base = [
        on("n11"),
        list("n11.offsets", &[3840, 7680]),
        on("n07"),
        dup_text("n07.chords", "C F G"),
    ];
    let r = dup_on(&v, &base);
    // Bar 1 (F): +5; bar 2 (G): −5 (the nearer of +7 and −5).
    let bars: Vec<Vec<u8>> = [0u64, 3840, 7680]
        .iter()
        .map(|&b| {
            r.iter()
                .filter(|x| x.0 >= b && x.0 < b + 3840)
                .map(|x| x.1)
                .collect()
        })
        .collect();
    assert_eq!(
        bars,
        vec![vec![60, 62, 64], vec![65, 67, 69], vec![55, 57, 59]]
    );
    // Snap: to the nearest tone of the chord of each note's bar (ties go
    // down): F A C → 60 60 65, G B D → 59 62 62.
    let mut snap = base.to_vec();
    snap.push(ch("n07.fit", 1));
    let r = dup_on(&v, &snap);
    let bars: Vec<Vec<u8>> = [0u64, 3840, 7680]
        .iter()
        .map(|&b| {
            r.iter()
                .filter(|x| x.0 >= b && x.0 < b + 3840)
                .map(|x| x.1)
                .collect()
        })
        .collect();
    assert_eq!(
        bars,
        vec![vec![60, 62, 64], vec![60, 60, 65], vec![59, 62, 62]]
    );
    // A word that is no chord: a sentence.
    let notes: Vec<TNote> = v.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    let e = dup_try(notes, &[on("n07"), dup_text("n07.chords", "C Xq")], |_| {}).unwrap_err();
    assert!(e.user_message().contains("“Xq” is not a chord"), "{e:?}");
}

#[test]
fn dup_copy_controllers_writes_the_spans_points_with_every_copy() {
    use plumspirit_engine::transform::output::{Lane, TEvent};
    let ev = |lane: Lane, tick: u64, value: u16| TEvent {
        track: 0,
        lane,
        ch: 0,
        tick,
        value,
    };
    let points = vec![
        ev(Lane::Cc(7), 0, 100),
        ev(Lane::Cc(11), 120, 64),
        ev(Lane::PitchBend, 240, 9000),
    ];
    let v: Vec<TNote> = DUP2.iter().map(|&(s, d, p)| tn(s, d, p, 90)).collect();
    let run = |set: &[(&'static str, ParamValue)]| {
        let p = points.clone();
        dup_try_with(
            v.clone(),
            dup_tracks(1),
            set,
            move |s| {
                s.aux_events = Arc::new(p);
                s.routes = Arc::new(vec![(0, 1)]);
            },
            |_| {},
        )
        .unwrap()
    };
    let got = |r: &plumspirit_engine::transform::TransformRun| -> Vec<(u16, u64, u16)> {
        r.events
            .iter()
            .map(|e| (e.track, e.tick, e.value))
            .collect()
    };
    // Controllers (not the bend): with both copies, 480 and 960 later.
    let r = run(&[on("a1"), int("a1.count", 2), on("n08")]);
    assert!(r.events.iter().all(|e| e.track == 0));
    let mut ticks: Vec<(u64, u16)> = r.events.iter().map(|e| (e.tick, e.value)).collect();
    ticks.sort_unstable();
    assert_eq!(ticks, vec![(480, 100), (600, 64), (960, 100), (1080, 64)]);
    // With pitch bend; only listed controllers.
    let r = run(&[on("n08"), ch("n08.include", 2), list("n08.ccs", &[7])]);
    let mut ticks: Vec<(u64, u16)> = r.events.iter().map(|e| (e.tick, e.value)).collect();
    ticks.sort_unstable();
    assert_eq!(ticks, vec![(480, 100), (720, 9000)]);
    // Notes only: none.
    assert!(run(&[on("n08"), ch("n08.include", 0)]).events.is_empty());
    // On the copies' tracks (n01's layers at the selection's time).
    let r = run(&[on("n01"), on("n08")]);
    assert_eq!(got(&r), vec![(1, 0, 100), (1, 120, 64)]);
}

#[test]
fn dup_copy_controllers_reads_the_tracks_points_in_the_selections_span() {
    use plumspirit_engine::model::{RawEvent, RawKind};
    let mut d = PlumDocument::new_project("dup".into(), Bpm::DEFAULT, 960);
    let v = vec![rec(960, 240, 60), rec(1200, 240, 64)];
    d.track_mut(0)
        .unwrap()
        .notes
        .insert_sorted_batch(&v, true)
        .unwrap();
    for (tick, status, data) in [
        (0, 0xB0, [7, 1]),
        (960, 0xB0, [7, 100]),
        (1000, 0xE1, [0, 64]),
        (1100, 0xB0, [121, 0]),
        (1300, 0xB2, [10, 30]),
        (1440, 0xB0, [7, 5]),
    ] {
        d.track_mut(0)
            .unwrap()
            .events
            .push(RawEvent {
                tick,
                anchor: 0,
                kind: RawKind::Channel { status, data },
            })
            .unwrap();
    }
    let t = tool("duplicate").unwrap();
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    ps.set("n08", ParamValue::Bool(true));
    ps.set("n08.include", ParamValue::Choice(2));
    let src = collect_with(t, &d, &sc, &ps, 1 << 20).unwrap();
    let got: Vec<(u64, u8, u16)> = src
        .aux_events
        .iter()
        .map(|e| (e.tick, e.ch, e.value))
        .collect();
    // [960, 1440): CC 7, the bend on channel 2 (8192), CC 10 on channel 3;
    // CC 121 (a mode message) and the points outside are left.
    assert_eq!(got, vec![(960, 0, 100), (1000, 1, 8192), (1300, 2, 30)]);
}

#[test]
fn dup_thinning_cascade_keeps_a_share_fewer_per_copy() {
    // Eight notes, velocities 10 … 80, one per 240; copies 1 – 3 at
    // 1,920 · k keep 4, 2, 1.
    let v: Vec<TNote> = (0..8u64)
        .map(|i| tn(240 * i, 240, 60 + i as u8, 10 + 10 * i as u8))
        .collect();
    let per_copy = |by: u32| -> Vec<Vec<u64>> {
        let r = dup_try(
            v.clone(),
            &[
                on("a1"),
                int("a1.count", 3),
                on("n09"),
                fl("n09.keep", 50.0),
                ch("n09.by", by),
            ],
            |_| {},
        )
        .unwrap();
        (1..=3u64)
            .map(|k| {
                let mut s: Vec<u64> = r
                    .notes
                    .iter()
                    .filter(|n| n.start >= 1920 * k && n.start < 1920 * (k + 1))
                    .map(|n| (n.start - 1920 * k) / 240)
                    .collect();
                s.sort_unstable();
                s
            })
            .collect()
    };
    // Loudest: the last notes.
    assert_eq!(per_copy(1), vec![vec![4, 5, 6, 7], vec![6, 7], vec![7]]);
    // Evenly spaced: every other note, every fourth, the first.
    assert_eq!(per_copy(2), vec![vec![0, 2, 4, 6], vec![0, 4], vec![0]]);
    // Outline on single notes = evenly spaced (every note is a top).
    assert_eq!(per_copy(0), per_copy(2));
    // Outline on chords: the tops first, then the bottoms, inner last.
    let chords: Vec<TNote> = (0..4u64)
        .flat_map(|i| [60u8, 64, 67].map(|p| tn(480 * i, 480, p, 90)))
        .collect();
    let r = dup_try(
        chords,
        &[on("n09"), fl("n09.keep", 50.0), ch("n09.by", 0)],
        |_| {},
    )
    .unwrap();
    let mut copy: Vec<u8> = r
        .notes
        .iter()
        .filter(|n| n.start >= 1920)
        .map(|n| n.pitch)
        .collect();
    copy.sort_unstable();
    // Twelve notes, six kept: the four tops and two bottoms.
    assert_eq!(copy, vec![60, 60, 67, 67, 67, 67]);
}

#[test]
fn dup_stutter_repeats_the_first_notes_before_each_copy() {
    let v = [(0, 240, 60), (240, 240, 62), (480, 240, 64), (720, 240, 65)];
    // Fragment: the first two notes (480 long), twice; the step grows by
    // 960, so copy 1 starts at 1,920 after its stutter at 960 and 1,440.
    let r = dup_on(&v, &[on("n10"), int("n10.notes", 2), int("n10.times", 2)]);
    let starts: Vec<(u64, u8)> = r.iter().map(|x| (x.0, x.1)).collect();
    assert_eq!(
        starts,
        vec![
            (0, 60),
            (240, 62),
            (480, 64),
            (720, 65),
            (960, 60),
            (1200, 62),
            (1440, 60),
            (1680, 62),
            (1920, 60),
            (2160, 62),
            (2400, 64),
            (2640, 65)
        ]
    );
    // At listed offsets the copies keep their place; the stutter goes
    // before.
    let r = dup_on(
        &v,
        &[
            on("n10"),
            int("n10.notes", 1),
            int("n10.times", 2),
            on("n11"),
            list("n11.offsets", &[3840]),
        ],
    );
    let starts: Vec<u64> = r.iter().map(|x| x.0).collect();
    assert_eq!(
        starts,
        vec![0, 240, 480, 720, 3360, 3600, 3840, 4080, 4320, 4560]
    );
}

#[test]
fn dup_offset_list_places_copy_k_at_the_kth_offset() {
    assert_eq!(
        dup_on(
            DUP2,
            &[
                on("n11"),
                list("n11.offsets", &[1920, 720]),
                on("a4"),
                fl("a4.decay", 50.0)
            ]
        ),
        dup_with(
            DUP2_SPD,
            &[
                (720, 60, 240),
                (960, 62, 240),
                (1920, 60, 240),
                (2160, 62, 240)
            ]
        )
    );
    // Copy k keeps its index for the per-copy changes: the first offset's
    // copy decays once, the second's twice.
    let v: Vec<TNote> = DUP2.iter().map(|&(s, d, p)| tn(s, d, p, 80)).collect();
    let r = dup_try(
        v,
        &[
            on("n11"),
            list("n11.offsets", &[1920, 720]),
            on("a4"),
            fl("a4.decay", 50.0),
        ],
        |_| {},
    )
    .unwrap();
    let mut sv: Vec<(u64, u8)> = r.notes.iter().map(|n| (n.start, n.vel)).collect();
    sv.sort_unstable();
    assert_eq!(
        sv,
        vec![
            (0, 80),
            (240, 80),
            (720, 20),
            (960, 20),
            (1920, 40),
            (2160, 40)
        ]
    );
}

#[test]
fn dup_functions_compose_in_their_declared_order() {
    // n11's copies → n01's tracks → n04's rotation → n12's sequence → n09's
    // share.
    let v = vec![tn(0, 240, 60, 90), tn(240, 240, 64, 80)];
    let r = dup_try_with(
        v,
        dup_tracks(1),
        &[
            on("n11"),
            list("n11.offsets", &[960, 1920]),
            on("n01"),
            on("n04"),
            int("n04.rotate", 1),
            on("n12"),
            ch("n12.motion", 3),
            on("n09"),
            fl("n09.keep", 50.0),
            ch("n09.by", 1),
        ],
        |s| s.routes = Arc::new(vec![(0, 1)]),
        |_| {},
    )
    .unwrap();
    // Copy 1 at 960 on slot 1, rotated (64 60) and +1: keeps one note of
    // two, the loudest (the first: 65); copy 2 at 1,920, rotated twice (60
    // 64) and +2: keeps round(½ · ½ · 2) = 1, the first again (62).
    assert_eq!(on_slot(&r, 0), vec![(0, 240, 60), (240, 480, 64)]);
    assert_eq!(on_slot(&r, 1), vec![(960, 1200, 65), (1920, 2160, 62)]);
}

// ---- Duplicate: Control Sweeps per note

#[test]
fn dup_path_copies_sweep_takes_each_notes_own_count() {
    let tg = plumspirit_engine::transform::definition::sweep_targets("duplicate")
        .iter()
        .find(|t| t.param == "n05.copies")
        .copied()
        .unwrap();
    // Eight notes 480 apart; copies 1 → 16 along the selection.
    let v: Vec<TNote> = (0..8u64).map(|k| tn(k * 480, 240, 60, 90)).collect();
    let r = dup_try(
        v,
        &[
            on("n05"),
            curve("n05.path", Curve::flat(0.0)),
            int("n05.spacing", 100_000),
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::line(0.0, 1.0))),
        ],
        |_| {},
    )
    .unwrap();
    // Each note's copies: the notes at its start + k · 100,000.
    let counts: Vec<usize> = (0..8u64)
        .map(|k| {
            r.notes
                .iter()
                .filter(|n| n.start % 100_000 == k * 480 && n.start >= 100_000)
                .count()
        })
        .collect();
    assert!(counts.windows(2).all(|w| w[0] <= w[1]), "{counts:?}");
    assert_eq!(counts[0], 1, "{counts:?}");
    assert!(counts[7] >= 14, "{counts:?}");
}

/// E0422's rule for Duplicate: a sweep flat at the parameter's own value
/// changes nothing (its function on); a sweep of a function that is off
/// changes nothing (on the v0.8 settings too).
#[test]
fn dup_flat_sweeps_and_sweeps_of_functions_that_are_off_change_nothing() {
    use plumspirit_engine::transform::definition::{Combine, sweep_targets};
    use plumspirit_engine::transform::param::ParamKind;
    let spec = (tool("duplicate").unwrap().spec)();
    let mut checked = 0;
    assert_eq!(sweep_targets("duplicate").len(), 10);
    let owner = |p: &str| -> &'static str {
        Box::leak(p.split('.').next().unwrap().to_string().into_boxed_str())
    };
    for tg in sweep_targets("duplicate") {
        assert!(matches!(tg.combine, Combine::Replace));
        let ps = spec.params.iter().find(|p| p.key == tg.param).unwrap();
        let lo = tg.range.0.min(tg.range.1);
        let v = match ps.kind {
            ParamKind::Float { .. } => ParamValue::Float(lo),
            _ => ParamValue::Int(lo.round() as i64),
        };
        let base = vec![(tg.param, v), (owner(tg.param), ParamValue::Bool(true))];
        let a = dup_fix(&base);
        let mut swept = base.clone();
        swept.extend([
            on("m.sweep"),
            (tg.on, ParamValue::Bool(true)),
            (tg.graph, ParamValue::Curve(Curve::flat(0.0))),
        ]);
        assert_eq!(
            join_fingerprint(&a),
            join_fingerprint(&dup_fix(&swept)),
            "flat {}",
            tg.param
        );
        checked += 1;
    }
    for f in DUP11 {
        let a = dup_fix(&[on(f)]);
        for tg in sweep_targets("duplicate") {
            let o = owner(tg.param);
            if o == f {
                continue;
            }
            let swept = vec![
                on(f),
                on("m.sweep"),
                (tg.on, ParamValue::Bool(true)),
                (o, ParamValue::Bool(false)),
            ];
            assert_eq!(
                join_fingerprint(&a),
                join_fingerprint(&dup_fix(&swept)),
                "{f} (sweep {})",
                tg.param
            );
            checked += 1;
        }
    }
    // The v0.8 settings with a sweep of an off function: the v0.9 kernel,
    // the v0.8 result.
    let tg = sweep_targets("duplicate")[7];
    for (i, s) in dup_v08_settings().iter().enumerate() {
        let mut set = dup_off(s);
        set.extend([on("m.sweep"), (tg.on, ParamValue::Bool(true))]);
        assert_eq!(join_fingerprint(&dup_fix(&set)), DUP_V08[i], "setting {i}");
        checked += 1;
    }
    assert!(checked >= 10 + 11 * 9 + 18, "{checked}");
}

/// The lazy viewport preview: per-note functions keep the kernel
/// pointwise and its notes equal the whole run; the others make it a
/// whole-source run.
#[test]
fn dup_previews_per_note_where_every_function_on_works_per_note() {
    let t = tool("duplicate").unwrap();
    let src = Source::from_notes(dup_fixture(), dup_tracks(0));
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let kernel = |set: &[(&'static str, ParamValue)]| {
        let mut ps = ParamSet::defaults(&(t.spec)().params);
        for (k, v) in set {
            ps.set(k, v.clone());
        }
        t.kernel(&ps, &b).unwrap()
    };
    let point = [
        vec![],
        vec![on("n02")],
        vec![on("n03")],
        vec![on("n05")],
        vec![on("n07")],
        vec![on("n08"), ch("n08.include", 0)],
        vec![on("n11")],
        vec![on("n12")],
        vec![on("n02"), ch("n02.kind", 3), on("n12"), on("a7"), on("a1")],
    ];
    for set in &point {
        let k = kernel(set);
        let p = k.as_point().unwrap_or_else(|| panic!("{set:?}"));
        // The per-note rule over every note = the run.
        let mut out = Output::new(t.boundary(&ParamSet::defaults(&(t.spec)().params)), 1 << 20);
        for n in &src.notes {
            p.map(n, &mut out);
        }
        let (mut lazy, _) = out.finish().unwrap();
        let mut full = run_kernel(
            k.as_ref(),
            &src,
            t.boundary(&ParamSet::defaults(&(t.spec)().params)),
            &Limits::default(),
            None,
        )
        .unwrap()
        .notes;
        lazy.sort_unstable();
        full.sort_unstable();
        assert_eq!(lazy, full, "{set:?}");
        // The source window of every output reaches back to its note.
        for n in &src.notes {
            let mut one = Output::new(t.boundary(&ParamSet::defaults(&(t.spec)().params)), 1 << 20);
            p.map(n, &mut one);
            for o in &one.notes {
                let (a, z) = p.source_window(o.start, o.end());
                assert!(n.start <= z && n.end() >= a, "{set:?} {n:?} → {o:?}");
            }
        }
    }
    for set in [
        vec![on("n01")],
        vec![on("n02"), ch("n02.kind", 2)],
        vec![on("n03"), ch("n03.at", 2)],
        vec![on("n04")],
        vec![on("n08")],
        vec![on("n09")],
        vec![on("n10")],
    ] {
        assert!(kernel(&set).as_point().is_none(), "{set:?}");
    }
}

#[test]
fn dup_results_are_deterministic_and_within_the_estimate() {
    let heavy = [
        on("n02"),
        int("n02.entries", 3),
        on("n04"),
        on("n07"),
        on("n09"),
        on("n10"),
        on("n12"),
        on("a3"),
        on("a9"),
    ];
    let a = dup_fix(&heavy);
    let b = dup_fix(&heavy);
    assert_eq!(join_fingerprint(&a), join_fingerprint(&b));
    let n = dup_fixture().len();
    // One copy at the defaults; the providers' counts.
    assert_eq!(dup_fix(&[on("n04")]).notes.len(), 2 * n);
    assert_eq!(
        dup_fix(&[on("n02"), int("n02.entries", 3)]).notes.len(),
        4 * n
    );
    assert_eq!(dup_fix(&[on("n05")]).notes.len(), 9 * n);
    assert_eq!(dup_fix(&[on("n11")]).notes.len(), 4 * n);
    assert_eq!(dup_fix(&[on("n03")]).notes.len(), 3 * n);
    // Stutter: the first four notes twice more.
    assert_eq!(dup_fix(&[on("n10")]).notes.len(), 2 * n + 8);
    assert!(dup_fix(&[on("n09")]).notes.len() < 2 * n);
}

// ============================================================= Score Stretch

/// Score Stretch's fixture: Flip's (chords, runs, passing notes, a second
/// subchannel, three bars).
fn stretch_fixture() -> Vec<TNote> {
    flip_fixture()
}

/// Runs Score Stretch on a hand-built source: `notes` selected on one track
/// (subchannels 0 – 3, channel = subchannel), in `Ctx::simple(960)` changed
/// by `tweak`; the whole result (within the kernel's estimate).
fn stretch_try(
    notes: Vec<TNote>,
    set: &[(&'static str, ParamValue)],
    tweak: impl FnOnce(&mut Ctx),
) -> Result<plumspirit_engine::transform::TransformRun, plumspirit_engine::transform::TransformError>
{
    let track = SourceTrack {
        id: TrackId(1),
        index: 0,
        content: None,
        revision: 0,
        subs: vec![(0, 0), (1, 1), (2, 2), (3, 3)],
        all: false,
        insert_only: false,
        frame: 0,
    };
    let src = Source::from_notes(notes, vec![track]);
    let t = tool("stretch").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let mut ctx = Ctx::simple(960);
    tweak(&mut ctx);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    let est = k.estimate_source(&src).notes;
    let r = run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?;
    assert!(r.notes.len() as u64 <= est, "{} > {est}", r.notes.len());
    Ok(r)
}

fn stretch_fix(set: &[(&'static str, ParamValue)]) -> plumspirit_engine::transform::TransformRun {
    stretch_try(stretch_fixture(), set, |_| {}).unwrap()
}

