/// Neutral settings: no coupling, no tidal strength or length stretch, no
/// accretion turns or infall, an escape velocity no note exceeds, no
/// potential gain, no dilation — each alone, then together.
fn gravity_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n01", vec![on("n01"), fl("n01.coupling", 0.0)]),
        (
            "n03",
            vec![on("n03"), fl("n03.tidal", 0.0), fl("n03.length", 0.0)],
        ),
        (
            "n04",
            vec![on("n04"), fl("n04.turns", 0.0), fl("n04.infall", 0.0)],
        ),
        ("n05", vec![on("n05"), int("n05.vel", 127)]),
        ("n06", vec![on("n06"), fl("n06.gain", 0.0)]),
        ("n11", vec![on("n11"), fl("n11.dilation", 0.0)]),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

