// ============================================================== Kaleidoscope

fn kal_run(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    shear_like_try("kaleidoscope", notes, tracks, set).unwrap()
}

