/// Neutral settings (the v0.9 kernel, the v0.8 result): no turns, no delay,
/// thinning "None", a zero transposition, one ring of a1's sectors, no
/// broken sector, every sector filled — each alone, then together; and
/// Control Sweeps of functions that are off.
fn kal_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n02", vec![on("n02"), fl("n02.turns", 0.0)]),
        ("n03", vec![on("n03"), int("n03.delay", 0)]),
        ("n04", vec![on("n04"), ch("n04.mode", 2)]),
        ("n05", vec![on("n05"), list("n05.semis", &[0])]),
        (
            "n06",
            vec![on("n06"), int("n06.rings", 1), list("n06.sectors", &[])],
        ),
        ("n08", vec![on("n08"), int("n08.count", 0)]),
        ("n10", vec![on("n10"), list("n10.pattern", &[1])]),
        (
            "sweeps of functions that are off",
            vec![
                on("m.sweep"),
                on("m.sweep.cell_width"),
                on("m.sweep.local_sectors"),
                on("m.sweep.ring_spacing"),
            ],
        ),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn kal_neutral_new_functions_equal_the_v08_results() {
    for (i, s) in kal_v08_settings().iter().enumerate() {
        for (name, extra) in kal_neutral() {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            let r = kal_run(skew_fixture(), 3, &set);
            assert_eq!(join_fingerprint(&r), KAL_V08[i], "{name}, setting {i}");
        }
    }
}

/// Notes (start, length, pitch, velocity) on track slot 0 of three.
fn kal_notes(v: &[(u64, u64, u8, u8)]) -> Vec<TNote> {
    v.iter()
        .map(|&(s, d, p, vel)| TNote {
            start: s,
            dur: d,
            pitch: p,
            vel,
            rel: 64,
            ..TNote::default()
        })
        .collect()
}

fn kal_spd(v: &[(u64, u64, u8)], set: &[(&'static str, ParamValue)]) -> Vec<(u64, u8, u64)> {
    let n: Vec<(u64, u64, u8, u8)> = v.iter().map(|&(s, d, p)| (s, d, p, 100)).collect();
    spd(&kal_run(kal_notes(&n), 3, set).notes)
}

/// A point-symmetric pair: C at the start, F♯ a bar and a half later (the
/// box 0 – 1,920 × 60 – 66).
const KAL_PAIR: &[(u64, u64, u8)] = &[(0, 480, 60), (1440, 480, 66)];
/// Three notes without point symmetry (the box 0 – 1,440 × 60 – 64).
const KAL_THREE: &[(u64, u64, u8)] = &[(0, 480, 60), (480, 240, 64), (960, 480, 62)];

#[test]
fn kal_wallpaper_groups_tile_cells_with_the_groups_operations() {
    // v0.8's two sectors: the pair maps onto itself.
    assert_eq!(
        kal_spd(KAL_PAIR, &[]),
        vec![(0, 60, 480), (0, 60, 480), (1440, 66, 480), (1440, 66, 480)]
    );
    let wall = |g: u32, rt: i64, rp: i64| {
        vec![
            on("n01"),
            ch("n01.group", g),
            int("n01.width", 1920),
            int("n01.height", 7),
            int("n01.rt", rt),
            int("n01.rp", rp),
        ]
    };
    // p1: translations only — three cells in time, two in pitch.
    let mut want = Vec::new();
    for r in 0..2u8 {
        for i in 0..3u64 {
            want.push((1920 * i, 60 + 7 * r, 480));
            want.push((1440 + 1920 * i, 66 + 7 * r, 480));
        }
    }
    want.sort_unstable();
    assert_eq!(kal_spd(KAL_PAIR, &wall(0, 3, 2)), want);
    // pm: the cell mirrored in time.
    assert_eq!(
        kal_spd(KAL_PAIR, &wall(2, 1, 1)),
        vec![(0, 60, 480), (0, 66, 480), (1440, 60, 480), (1440, 66, 480)]
    );
    // pg: the glide — mirrored in time, half a cell up.
    let v = kal_spd(KAL_THREE, &wall(3, 1, 1));
    assert_eq!(v.len(), 6);
    // p4 and p6m: 4 and 12 operations per cell.
    assert_eq!(kal_spd(KAL_PAIR, &wall(9, 3, 2)).len(), 2 * 4 * 6);
    let hex = kal_spd(KAL_PAIR, &wall(16, 2, 1));
    assert!(hex.len() <= 2 * 12 * 2 && !hex.is_empty(), "{}", hex.len());
}

#[test]
fn kal_spinning_mandala_turns_with_time() {
    // One note: the box is the note, its middle at half the box — half a
    // turn × 0.5 = a quarter turn: the note stands on end (one tick at the
    // centre).
    let c = [(840, 240, 63)];
    assert_eq!(kal_spd(&c, &[]), vec![(840, 63, 240), (840, 63, 240)]);
    assert_eq!(
        kal_spd(&c, &[on("n02"), fl("n02.turns", 0.5)]),
        vec![(960, 63, 1), (960, 63, 1)]
    );
}

#[test]
fn kal_sector_delay_unfolds_sector_by_sector() {
    assert_eq!(
        kal_spd(KAL_PAIR, &[on("n03"), int("n03.delay", 240)]),
        vec![
            (0, 60, 480),
            (240, 60, 480),
            (1440, 66, 480),
            (1680, 66, 480)
        ]
    );
}

#[test]
fn kal_sector_thinning_keeps_the_original_count_or_the_outline() {
    // Interleave: note k keeps copy k mod 2 (the first and the last note
    // themselves, the middle one its mirror image).
    let v = kal_spd(KAL_THREE, &[on("n04")]);
    assert_eq!(v, vec![(0, 60, 480), (720, 60, 240), (960, 62, 480)]);
    let all = kal_spd(KAL_THREE, &[]);
    assert_eq!(all.len(), 6);
    // Outline: a chord's middle note is dropped.
    let chord = [(0, 480, 60), (0, 480, 64), (0, 480, 67), (960, 480, 62)];
    assert_eq!(kal_spd(&chord, &[]).len(), 8);
    let v = kal_spd(&chord, &[on("n04"), ch("n04.mode", 1)]);
    assert_eq!(v.len(), 6);
    assert!(!v.iter().any(|x| x.0 == 0 && x.1 == 64), "{v:?}");
}

#[test]
fn kal_sector_transposition_moves_each_sector() {
    assert_eq!(
        kal_spd(KAL_PAIR, &[on("n05"), list("n05.semis", &[0, 5])]),
        vec![(0, 60, 480), (0, 65, 480), (1440, 66, 480), (1440, 71, 480)]
    );
}

#[test]
fn kal_mandala_rings_layer_rings_of_their_own_sector_counts() {
    let set = [
        on("n06"),
        int("n06.rings", 2),
        list("n06.sectors", &[2, 4]),
        fl("n06.spacing", 25.0),
    ];
    let v = kal_spd(KAL_PAIR, &set);
    assert_eq!(v.len(), 2 * (2 + 4));
    // Ring 1, sector 0: C pushed out by 25 % along 45°: 0.25 / √2 of the box
    // in time (339.4 ticks) and in rows (1.74 rows).
    assert!(v.contains(&(339, 61, 480)), "{v:?}");
    // Ring 0 is v0.8's.
    assert!(v.contains(&(0, 60, 480)) && v.contains(&(1440, 66, 480)));
}

#[test]
fn kal_diatonic_symmetry_mirrors_on_beats_and_stays_in_the_key() {
    // The centre: the beat at 960 and D (62, the lower of D and E nearest
    // D♯); every copy in C major.
    assert_eq!(
        kal_spd(KAL_PAIR, &[on("n07"), ch("n07.at", 1)]),
        vec![(0, 57, 480), (0, 60, 480), (1440, 64, 480), (1440, 65, 480)]
    );
    // Bar lines: the centre moves to bar line 0 (the mirror images fall
    // before the selection — the tick policy's business); every pitch is
    // in C major.
    let v = kal_spd(KAL_PAIR, &[on("n07")]);
    assert!(!v.is_empty());
    assert!(
        v.iter()
            .all(|x| [0u8, 2, 4, 5, 7, 9, 11].contains(&(x.1 % 12))),
        "{v:?}"
    );
}

#[test]
fn kal_symmetry_breaking_perturbs_seeded_sectors() {
    let base = kal_spd(KAL_THREE, &[on("a1"), int("a1.n", 6)]);
    let broken = |count: i64, amount: f64, seed: i64| {
        kal_spd(
            KAL_THREE,
            &[
                on("a1"),
                int("a1.n", 6),
                on("n08"),
                int("n08.count", count),
                fl("n08.amount", amount),
                int("n08.seed", seed),
            ],
        )
    };
    assert_eq!(broken(0, 100.0, 1), base);
    assert_eq!(broken(3, 0.0, 1), base);
    let a = broken(2, 100.0, 1);
    assert_ne!(a, base);
    assert_eq!(a, broken(2, 100.0, 1));
    assert_ne!(a, broken(2, 100.0, 987_654));
    // Two of six sectors broken: the four others' copies are untouched.
    let same = a.iter().filter(|x| base.contains(x)).count();
    assert!(same >= 4 * 3, "{same}");
}

#[test]
fn kal_seam_cleanup_merges_doubled_notes_on_the_mirrors() {
    let notes = kal_notes(&[(0, 480, 60, 100), (1440, 480, 66, 50)]);
    let r = kal_run(notes.clone(), 3, &[]);
    assert_eq!(r.notes.len(), 4);
    // The first of each doubled pair is kept (by start, then emission: C's
    // copies come first).
    let r = kal_run(notes.clone(), 3, &[on("n09"), int("n09.width", 0)]);
    let mut v: Vec<(u64, u8, u8)> = r.notes.iter().map(|n| (n.start, n.pitch, n.vel)).collect();
    v.sort_unstable();
    assert_eq!(v, vec![(0, 60, 100), (1440, 66, 100)]);
    let r = kal_run(
        notes,
        3,
        &[on("n09"), int("n09.width", 0), ch("n09.keep", 1)],
    );
    let mut v: Vec<(u64, u8, u8)> = r.notes.iter().map(|n| (n.start, n.pitch, n.vel)).collect();
    v.sort_unstable();
    assert_eq!(v, vec![(0, 60, 75), (1440, 66, 75)]);
}

#[test]
fn kal_sector_pattern_fills_only_some_sectors() {
    assert_eq!(
        kal_spd(KAL_THREE, &[on("n10")]),
        vec![(0, 60, 480), (480, 64, 240), (960, 62, 480)]
    );
    assert_eq!(
        kal_spd(KAL_THREE, &[on("n10"), list("n10.pattern", &[0, 1])]),
        vec![(0, 62, 480), (720, 60, 240), (960, 64, 480)]
    );
}

#[test]
fn kal_local_mandalas_turn_around_each_chord() {
    let m = [(0, 480, 60), (0, 480, 64), (1920, 960, 72), (1920, 960, 79)];
    let local = kal_spd(&m, &[on("n11"), int("n11.sectors", 2)]);
    assert_eq!(
        local,
        vec![
            (0, 60, 480),
            (0, 60, 480),
            (0, 64, 480),
            (0, 64, 480),
            (1920, 72, 960),
            (1920, 72, 960),
            (1920, 79, 960),
            (1920, 79, 960)
        ]
    );
    assert_ne!(kal_spd(&m, &[]), local);
    // Bars: one mandala per bar (here both chords' bars).
    let bars = kal_spd(&m, &[on("n11"), ch("n11.unit", 1), int("n11.sectors", 4)]);
    assert_eq!(bars.len(), 4 * 4);
}

#[test]
fn kal_functions_compose_deterministically_within_the_preflight() {
    let all: Vec<(&'static str, ParamValue)> = ALL11.iter().map(|&f| on(f)).collect();
    let a = kal_run(skew_fixture(), 3, &all);
    assert_eq!(a.notes, kal_run(skew_fixture(), 3, &all).notes);
    for f in ALL11 {
        for extra in [
            vec![],
            vec![on("a1"), on("a2"), on("a5"), on("a8"), on("a10")],
            vec![
                on("a3"),
                on("a4"),
                on("a6"),
                on("a7"),
                on("a9"),
                on("g.fill"),
            ],
            vec![
                ch("g.raster", 2),
                ch("n04.mode", 1),
                ch("n07.at", 1),
                ch("n09.keep", 1),
                ch("n11.unit", 2),
                ch("n01.group", 16),
            ],
        ] {
            let mut set = vec![on(f)];
            set.extend(extra);
            let v = kal_run(skew_fixture(), 3, &set);
            assert_eq!(v.notes, kal_run(skew_fixture(), 3, &set).notes, "{f}");
            assert!(
                v.notes
                    .iter()
                    .all(|n| (1..=127).contains(&n.vel) && n.ch <= 15 && n.dur >= 1),
                "{f}"
            );
        }
    }
    let sweep = [on("n02"), on("m.sweep"), on("m.sweep.turns")];
    let a = kal_run(skew_fixture(), 3, &sweep);
    assert_eq!(a.notes, kal_run(skew_fixture(), 3, &sweep).notes);
    let rings = [on("n06"), on("m.sweep"), on("m.sweep.rings")];
    assert!(kal_run(skew_fixture(), 3, &rings).notes.len() > 384);
}

// ===================================================================== Orbit

fn orb_run(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    shear_like_try("orbit", notes, tracks, set).unwrap()
}

