#[test]
fn wt_the_source_region_limits_the_notes_the_warp_takes() {
    let notes = t3d_fixture();
    let (t0, w, _, _) = t3d_box(&notes);
    let set = [
        fl("crop_left", 50.0),
        fl("scale_y", 40.0),
        int("shift_y", 5),
    ];
    let got = wt(notes.clone(), &set);
    assert_eq!(got.len(), notes.len());
    let half = t0 + w / 2.0;
    let (kept, moved): (Vec<&TNote>, Vec<&TNote>) = notes
        .iter()
        .partition(|n| (n.start as f64 + n.dur as f64 / 2.0) < half);
    for n in kept {
        assert!(
            got.iter()
                .any(|o| o.start == n.start && o.pitch == n.pitch && o.dur == n.dur),
            "{n:?}"
        );
    }
    assert!(
        moved
            .iter()
            .any(|n| !got.iter().any(|o| o.start == n.start && o.pitch == n.pitch))
    );
}

