/// Neutral settings (the v0.9 kernel, the v0.8 result): a zero dynamics
/// depth, a zero counter phase, thinning that keeps everything, elliptic
/// amplitudes equal to the amplitude with no offset, no growth — each alone,
/// then together; and Control Sweeps of functions that are off.
fn pf_neutral(
    s: &[(&'static str, ParamValue)],
) -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let amp = s
        .iter()
        .find(|(k, _)| *k == "amp")
        .map_or(25.0, |(_, v)| match v {
            ParamValue::Float(f) => *f,
            _ => 25.0,
        });
    let each = vec![
        ("n03", vec![on("n03"), fl("n03.depth", 0.0)]),
        ("n12", vec![on("n12"), fl("n12.phase", 0.0)]),
        ("n06", vec![on("n06"), fl("n06.keep", 100.0)]),
        (
            "n07",
            vec![
                on("n07"),
                fl("n07.x", amp),
                fl("n07.y", amp),
                fl("n07.offset", 0.0),
            ],
        ),
        ("n08", vec![on("n08"), fl("n08.growth", 0.0)]),
        (
            "sweeps of functions that are off",
            vec![on("m.sweep"), on("m.sweep.decay"), on("m.sweep.duty")],
        ),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn pf_neutral_new_functions_equal_the_v08_results() {
    for (i, s) in pf_v08_settings().iter().enumerate() {
        for (name, extra) in pf_neutral(s) {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            let r = pf_run(skew_fixture(), 3, &set);
            assert_eq!(join_fingerprint(&r), PF_V08[i], "{name}, setting {i}");
        }
    }
}

/// Notes (start, length, pitch) at velocity 64 on track slot 0, subchannel 0.
fn pf_notes(v: &[(u64, u64, u8)]) -> Vec<TNote> {
    v.iter()
        .map(|&(s, d, p)| TNote {
            start: s,
            dur: d,
            pitch: p,
            vel: 64,
            rel: 64,
            ..TNote::default()
        })
        .collect()
}

/// Twelve notes of 240 ticks across two bars and two octaves, two bars into
/// the song (scaled copies stay after tick 0).
fn pf_art() -> Vec<TNote> {
    pf_notes(
        &(0..12u64)
            .map(|k| (7680 + k * 610, 240, 48 + ((k * 7) % 25) as u8))
            .collect::<Vec<_>>(),
    )
}

/// v0.8's triangle pulse (0 → 1 → −1 → 0 over 2π).
fn pf_tri(x: f64) -> f64 {
    let t = (x / std::f64::consts::TAU).rem_euclid(1.0);
    if t < 0.25 {
        4.0 * t
    } else if t < 0.75 {
        2.0 - 4.0 * t
    } else {
        4.0 * t - 4.0
    }
}

/// The selection's box: t0, width, p0, rows.
fn pf_box(v: &[TNote]) -> (f64, f64, f64, f64) {
    let t0 = v.iter().map(|n| n.start).min().unwrap() as f64;
    let t1 = v.iter().map(|n| n.start + n.dur).max().unwrap() as f64;
    let p0 = f64::from(v.iter().map(|n| n.pitch).min().unwrap());
    let p1 = f64::from(v.iter().map(|n| n.pitch).max().unwrap());
    (t0, t1 - t0, p0, p1 - p0 + 1.0)
}

/// A note's middle in unit coordinates of the box and its radial distance
/// (1 at a corner).
fn pf_mid(b: (f64, f64, f64, f64), n: &TNote) -> (f64, f64, f64) {
    let mu = ((n.start + n.start + n.dur) as f64 / 2.0 - b.0) / b.1;
    let mv = (f64::from(n.pitch) + 0.5 - b.2) / b.3;
    let r = ((mu - 0.5).powi(2) + (mv - 0.5).powi(2)).sqrt() / std::f64::consts::FRAC_1_SQRT_2;
    (mu, mv, r)
}

/// Where the shared raster places `n` scaled by (sx, sy) about the box's
/// centre (Sample at the middle): start, length, row.
fn pf_place(b: (f64, f64, f64, f64), n: &TNote, sx: f64, sy: f64) -> (i64, i64, i64) {
    let x = |t: f64| b.0 + b.1 * (0.5 + ((t - b.0) / b.1 - 0.5) * sx);
    let (a, e) = (
        x(n.start as f64).round(),
        x((n.start + n.dur) as f64).round(),
    );
    let v = (f64::from(n.pitch) + 0.5 - b.2) / b.3;
    let row = (b.2 + b.3 * (0.5 + (v - 0.5) * sy)).floor();
    (a.min(e) as i64, ((e - a).abs() as i64).max(1), row as i64)
}

/// `got` equals the model's places `want` (±1 tick at the ends).
fn pf_match(got: &[TNote], mut want: Vec<(i64, i64, i64)>, what: &str) {
    let mut g: Vec<(i64, i64, i64)> = got
        .iter()
        .map(|n| (n.start as i64, n.dur as i64, i64::from(n.pitch)))
        .collect();
    g.sort_unstable_by_key(|x| (x.2, x.0));
    want.sort_unstable_by_key(|x| (x.2, x.0));
    assert_eq!(g.len(), want.len(), "{what}: {g:?} vs {want:?}");
    for (a, b) in g.iter().zip(&want) {
        assert!(
            a.2 == b.2 && (a.0 - b.0).abs() <= 1 && (a.1 - b.1).abs() <= 2,
            "{what}: {a:?} vs {b:?}"
        );
    }
}

/// The model of every note of `art` under per-note scales `f(n, mu, mv, r)`.
fn pf_model(
    art: &[TNote],
    f: impl Fn(&TNote, f64, f64, f64) -> Option<(f64, f64)>,
) -> Vec<(i64, i64, i64)> {
    let b = pf_box(art);
    art.iter()
        .filter_map(|n| {
            let (mu, mv, r) = pf_mid(b, n);
            f(n, mu, mv, r).map(|(sx, sy)| pf_place(b, n, sx, sy))
        })
        .collect()
}

#[test]
fn pf_the_v09_kernel_matches_the_pulse_model() {
    // The model itself against v0.8 (default triangle, 4 cycles, 25 %).
    let art = pf_art();
    let tau = std::f64::consts::TAU;
    let want = pf_model(&art, |_, mu, _, _| {
        let s = 1.0 + 0.25 * pf_tri(tau * 4.0 * mu);
        Some((s, s))
    });
    pf_match(&pf_run(art.clone(), 1, &[]).notes, want.clone(), "v0.8");
    pf_match(
        &pf_run(art, 1, &[on("n08"), fl("n08.growth", 0.0)]).notes,
        want,
        "v0.9 neutral",
    );
}

#[test]
fn pf_tempo_locked_cycles_count_the_songs_beats_or_bars() {
    let tau = std::f64::consts::TAU;
    // Notes of 240 ticks on beats 16, 17, 19, 22, 23 (960 ticks a beat): the
    // middle is always an eighth of a beat in — the same phase for every
    // note (a triangle at 1/8 = 0.5): one scale 1.125.
    let beats = pf_notes(&[
        (15360, 240, 60),
        (16320, 240, 64),
        (18240, 240, 55),
        (21120, 240, 70),
        (22080, 240, 62),
    ]);
    let set = [on("n01"), ch("n01.unit", 0), fl("n01.cycles", 1.0)];
    let want = pf_model(&beats, |_, _, _, _| Some((1.125, 1.125)));
    pf_match(&pf_run(beats.clone(), 1, &set).notes, want, "per beat");
    // Without it the phase follows the selection (scales differ).
    let v08 = pf_model(&beats, |_, mu, _, _| {
        let s = 1.0 + 0.25 * pf_tri(tau * 4.0 * mu);
        Some((s, s))
    });
    pf_match(&pf_run(beats.clone(), 1, &[]).notes, v08, "v0.8");
    // Per bar, two cycles a bar: notes on bar lines (3,840 ticks) are 1/32
    // of a bar in at their middle — phase 1/16, a triangle of 0.25.
    let bars = pf_notes(&[(11520, 240, 60), (15360, 240, 66), (23040, 240, 58)]);
    let set = [on("n01"), ch("n01.unit", 1), fl("n01.cycles", 2.0)];
    let want = pf_model(&bars, |_, _, _, _| Some((1.0625, 1.0625)));
    pf_match(&pf_run(bars, 1, &set).notes, want, "per bar");
    // Polyrhythmic layers keep their ratios: layers 2 and 3 at 1 cycle a
    // beat → 1 and 1.5 cycles a beat.
    let set = [
        on("n01"),
        fl("n01.cycles", 1.0),
        on("a7"),
        list("a7.cycles", &[2, 3]),
    ];
    let want = pf_model(&beats, |n, _, _, _| {
        let m = (n.start + 120) as f64 / 960.0;
        let w = (pf_tri(tau * m) + pf_tri(tau * 1.5 * m)) / 2.0;
        let s = 1.0 + 0.25 * w;
        Some((s, s))
    });
    pf_match(&pf_run(beats, 1, &set).notes, want, "layers");
}

#[test]
fn pf_counter_phase_rings_pulse_the_inside_against_the_outside() {
    let art = pf_art();
    let tau = std::f64::consts::TAU;
    let set = [
        on("n12"),
        fl("n12.split", 40.0),
        fl("n12.phase", 180.0),
        fl("amp", 60.0),
    ];
    let want = pf_model(&art, |_, mu, _, r| {
        let ph = if r < 0.4 { std::f64::consts::PI } else { 0.0 };
        let s = 1.0 + 0.6 * pf_tri(tau * 4.0 * mu + ph);
        Some((s, s))
    });
    assert!(art.iter().any(|n| pf_mid(pf_box(&art), n).2 < 0.4));
    pf_match(&pf_run(art, 1, &set).notes, want, "counter phase");
}

#[test]
fn pf_pulse_width_moves_the_square_duty_across_the_selection() {
    let art = pf_art();
    let set = [
        on("n09"),
        fl("n09.start", 20.0),
        fl("n09.end", 80.0),
        fl("amp", 50.0),
    ];
    let want = pf_model(&art, |_, mu, _, _| {
        let d = 0.2 + 0.6 * mu.clamp(0.0, 1.0);
        let w = if (4.0 * mu).rem_euclid(1.0) < d {
            1.0
        } else {
            -1.0
        };
        let s = 1.0 + 0.5 * w;
        Some((s, s))
    });
    pf_match(&pf_run(art, 1, &set).notes, want, "duty");
}

#[test]
fn pf_ratchet_growth_adds_a_step_per_completed_cycle() {
    let art = pf_art();
    // Amplitude 0: only the growth — cycle k (of 4 across the selection)
    // scaled by 1 + 0.15 k.
    let set = [on("n08"), fl("n08.growth", 15.0), fl("amp", 0.0)];
    let want = pf_model(&art, |_, mu, _, _| {
        let s = 1.0 + 0.15 * (4.0 * mu).floor();
        Some((s, s))
    });
    pf_match(&pf_run(art, 1, &set).notes, want, "ratchet");
}

#[test]
fn pf_elliptic_pulse_gives_time_and_pitch_their_own_amplitudes_and_phase() {
    let art = pf_art();
    let tau = std::f64::consts::TAU;
    let set = [
        on("n07"),
        fl("n07.x", 0.0),
        fl("n07.y", 100.0),
        fl("n07.offset", 90.0),
    ];
    let want = pf_model(&art, |_, mu, _, _| {
        let sy = 1.0 + pf_tri(tau * 4.0 * mu + std::f64::consts::FRAC_PI_2);
        Some((1.0, sy))
    });
    pf_match(&pf_run(art, 1, &set).notes, want, "elliptic");
}

#[test]
fn pf_strobe_and_thinning_keep_their_shares_of_the_cycle() {
    let art = pf_art();
    let tau = std::f64::consts::TAU;
    // Strobe: kept while the cycle is in its first half (4 cycles).
    let set = [on("n10"), fl("n10.duty", 50.0), fl("n10.phase", 0.0)];
    let want = pf_model(&art, |_, mu, _, _| {
        ((4.0 * mu).rem_euclid(1.0) < 0.5).then(|| {
            let s = 1.0 + 0.25 * pf_tri(tau * 4.0 * mu);
            (s, s)
        })
    });
    assert!(want.len() < art.len() && !want.is_empty());
    pf_match(&pf_run(art.clone(), 1, &set).notes, want, "strobe");
    // Thinning a square pulse: every contracted note is at the smallest
    // point — none kept at 0 %, all at 100 %, the expanded ones always.
    let sq = [on("a5"), fl("amp", 50.0)];
    let expanded = art
        .iter()
        .filter(|n| (4.0 * pf_mid(pf_box(&art), n).0).rem_euclid(1.0) < 0.5)
        .count();
    for (keep, count) in [(0.0, expanded), (100.0, art.len())] {
        let mut set = sq.to_vec();
        set.extend([on("n06"), fl("n06.keep", keep)]);
        assert_eq!(
            pf_run(art.clone(), 1, &set).notes.len(),
            count,
            "keep {keep}"
        );
    }
    // A triangle at 30 %: the deeper the contraction the fewer kept,
    // deterministic.
    let set = [on("n06"), fl("n06.keep", 30.0), fl("amp", 80.0)];
    let a = pf_run(art.clone(), 1, &set).notes;
    assert!(a.len() < art.len());
    assert_eq!(a, pf_run(art, 1, &set).notes);
}

#[test]
fn pf_dynamics_and_colours_follow_the_pulse_phase() {
    let art = pf_art();
    let tau = std::f64::consts::TAU;
    let b = pf_box(&art);
    // Velocity × (1 + depth · w).
    let set = [on("n03"), ch("n03.target", 0), fl("n03.depth", 100.0)];
    let out = pf_run(art.clone(), 1, &set).notes;
    let mut got: Vec<(u64, u8)> = out.iter().map(|n| (n.start, n.vel)).collect();
    got.sort_unstable();
    let mut want: Vec<(u64, u8)> = art
        .iter()
        .map(|n| {
            let (mu, _, _) = pf_mid(b, n);
            let w = pf_tri(tau * 4.0 * mu);
            let s = 1.0 + 0.25 * w;
            let start = pf_place(b, n, s, s).0 as u64;
            (start, (64.0 * (1.0 + w)).round().clamp(1.0, 127.0) as u8)
        })
        .collect();
    want.sort_unstable();
    for (g, w) in got.iter().zip(&want) {
        assert!(
            (g.0 as i64 - w.0 as i64).abs() <= 1 && g.1 == w.1,
            "{g:?} {w:?}"
        );
    }
    // Gate: the length × (1 + depth · w) before the scale.
    let set = [on("n03"), ch("n03.target", 1), fl("n03.depth", 50.0)];
    let want = pf_model(&art, |_, mu, _, _| {
        let s = 1.0 + 0.25 * pf_tri(tau * 4.0 * mu);
        Some((s, s))
    });
    let gated: Vec<(i64, i64, i64)> = art
        .iter()
        .map(|n| {
            let (mu, _, _) = pf_mid(b, n);
            let w = pf_tri(tau * 4.0 * mu);
            let s = 1.0 + 0.25 * w;
            let mut m = *n;
            m.dur = (240.0 * (1.0 + 0.5 * w)).round() as u64;
            pf_place(b, &m, s, s)
        })
        .collect();
    assert_ne!(gated, want);
    pf_match(&pf_run(art.clone(), 1, &set).notes, gated, "gate");
    // Colours: subchannel position = the band of the phase (4 bands a
    // cycle), or the palette's entry.
    for (palette, map) in [(vec![], [0u32, 1, 2, 3]), (vec![3, 1], [3, 1, 3, 1])] {
        let set = [
            on("n11"),
            int("n11.bands", 4),
            list("n11.palette", &palette),
        ];
        let out = pf_run(art.clone(), 1, &set).notes;
        let mut got: Vec<(u64, u32)> = out.iter().map(|n| (n.start, n.sub)).collect();
        got.sort_unstable();
        let mut want: Vec<(u64, u32)> = art
            .iter()
            .map(|n| {
                let (mu, _, _) = pf_mid(b, n);
                let s = 1.0 + 0.25 * pf_tri(tau * 4.0 * mu);
                let band = (((4.0 * mu).rem_euclid(1.0)) * 4.0) as usize;
                (pf_place(b, n, s, s).0 as u64, map[band.min(3)])
            })
            .collect();
        want.sort_unstable();
        for (g, w) in got.iter().zip(&want) {
            assert!(
                (g.0 as i64 - w.0 as i64).abs() <= 1 && g.1 == w.1,
                "{palette:?}: {g:?} {w:?}"
            );
        }
    }
}

#[test]
fn pf_quantized_pulse_moves_notes_in_whole_steps() {
    let art = pf_art();
    let b = pf_box(&art);
    let base = [fl("amp", 150.0)];
    // Octaves: every pitch moved by a multiple of 12, some moved.
    let mut set = base.to_vec();
    set.extend([on("n05"), ch("n05.step", 1)]);
    let out = pf_run(art.clone(), 1, &set).notes;
    let tau = std::f64::consts::TAU;
    let mut moved = 0;
    for n in &art {
        let (mu, _, _) = pf_mid(b, n);
        let s = 1.0 + 1.5 * pf_tri(tau * 4.0 * mu);
        let start = pf_place(b, n, s, s).0;
        let o = out
            .iter()
            .find(|o| {
                (o.start as i64 - start).abs() <= 1
                    && o.dur > 0
                    && (i64::from(o.pitch) - i64::from(n.pitch)) % 12 == 0
            })
            .unwrap_or_else(|| panic!("{n:?} not moved by octaves"));
        moved += usize::from(o.pitch != n.pitch);
    }
    assert!(moved > 0);
    // The key's degrees: C major only.
    let mut set = base.to_vec();
    set.extend([
        on("n05"),
        ch("n05.step", 2),
        ch("n05.key", 0),
        ch("n05.scale", 0),
    ]);
    let out = pf_run(art.clone(), 1, &set).notes;
    assert_eq!(out.len(), art.len());
    assert!(
        out.iter()
            .all(|n| [0, 2, 4, 5, 7, 9, 11].contains(&(n.pitch % 12))),
        "{:?}",
        pitches(&out)
    );
}

/// Runs Pulse Field on track 1's `art` of a document whose track 2 holds
/// `other` (through the platform's collection and `prepare`).
fn pf_doc(
    art: &[(u64, u64, u8)],
    other: &[(u64, u64, u8)],
    set: &[(&'static str, ParamValue)],
) -> Result<Vec<TNote>, plumspirit_engine::transform::TransformError> {
    let mut d = PlumDocument::new_project("pf".into(), Bpm::DEFAULT, 960);
    d.add_track().unwrap();
    for (k, notes) in [(0usize, art), (1, other)] {
        let mut v: Vec<NoteRecord> = notes.iter().map(|&(s, l, p)| rec(s, l, p)).collect();
        v.sort_by_key(|r| r.start_tick);
        d.track_mut(k)
            .unwrap()
            .notes
            .insert_sorted_batch(&v, true)
            .unwrap();
    }
    let t = tool("pulse_field").unwrap();
    let mut ps = ParamSet::defaults(&(t.spec)().params);
    for (k, val) in set {
        ps.set(k, val.clone());
    }
    let sc = [TrackScope {
        index: 0,
        all: false,
        content: None,
    }];
    let src = collect_with(t, &d, &sc, &ps, 1 << 24)?;
    let ctx = Ctx::simple(960);
    let b = BuildCtx {
        ctx: &ctx,
        stats: &src.stats,
        tracks: &src.tracks,
    };
    let k = t.kernel(&ps, &b)?;
    Ok(run_kernel(k.as_ref(), &src, t.boundary(&ps), &Limits::default(), None)?.notes)
}

#[test]
fn pf_onset_trigger_fires_the_envelope_at_every_reference_onset() {
    use plumspirit_engine::transform::TransformError;
    // Onsets at 7,680 and 9,600 on track 2; a decay of 480 with the falling
    // envelope 1 → 0: a note whose middle is 120 ticks after an onset is
    // pulsed by 0.75 (scale 1 + 0.25 · 0.75), one past the decay not at all.
    let art = [
        (7680, 240, 60),
        (8560, 240, 64),
        (9480, 240, 67),
        (10680, 240, 62),
    ];
    let drums = [(7680, 60, 36), (9600, 60, 36)];
    let set = [
        on("n02"),
        ch("n02.ref", 0),
        int("n02.num", 2),
        int("n02.decay", 480),
    ];
    let out = pf_doc(&art, &drums, &set).unwrap();
    let notes = pf_notes(&art);
    let want = pf_model(&notes, |n, _, _, _| {
        let mid = (n.start + 120) as f64;
        let last = if mid >= 9600.0 { 9600.0 } else { 7680.0 };
        let x = (mid - last) / 480.0;
        let w = if x < 1.0 { 1.0 - x } else { 0.0 };
        let s = 1.0 + 0.25 * w;
        Some((s, s))
    });
    pf_match(&out, want, "onset trigger");
    // A missing reference is refused with a sentence.
    for (r, num, what) in [
        (0, 9, "track 9 does not exist"),
        (1, 5, "no subchannel at position 5"),
    ] {
        let set = [on("n02"), ch("n02.ref", r), int("n02.num", num)];
        match pf_doc(&art, &drums, &set) {
            Err(TransformError::Invalid(m)) => {
                assert!(
                    m.starts_with("Onset trigger: ") && m.contains(what) && m.ends_with('.'),
                    "{m}"
                )
            }
            other => panic!("expected a refusal, got {:?}", other.map(|v| v.len())),
        }
    }
}

#[test]
fn pf_every_function_together_stays_valid_bounded_and_deterministic() {
    let all = [
        on("n01"),
        on("n03"),
        on("n05"),
        ch("n05.step", 2),
        on("n06"),
        on("n07"),
        on("n08"),
        on("n09"),
        on("n10"),
        on("n11"),
        on("n12"),
        on("a1"),
        on("a7"),
        on("a8"),
        on("a10"),
    ];
    let a = pf_run(skew_fixture(), 3, &all);
    assert!(!a.notes.is_empty());
    assert!(
        a.notes
            .iter()
            .all(|n| (1..=127).contains(&n.vel) && n.dur >= 1 && n.ch <= 15)
    );
    assert_eq!(a.notes, pf_run(skew_fixture(), 3, &all).notes);
    // Each function alone changes the default result.
    let base = pf_run(skew_fixture(), 3, &[]).notes;
    for (k, extra) in [
        ("n01", vec![on("n01")]),
        ("n03", vec![on("n03")]),
        ("n05", vec![on("n05"), ch("n05.step", 1), fl("amp", 150.0)]),
        ("n06", vec![on("n06")]),
        ("n07", vec![on("n07")]),
        ("n08", vec![on("n08")]),
        ("n09", vec![on("n09")]),
        ("n10", vec![on("n10")]),
        ("n11", vec![on("n11")]),
        ("n12", vec![on("n12")]),
    ] {
        assert_ne!(pf_run(skew_fixture(), 3, &extra).notes, base, "{k}");
    }
    // A Control Sweep of the amplitude acts per note.
    let sw = [on("m.sweep"), on("m.sweep.amplitude")];
    let s = pf_run(skew_fixture(), 3, &sw).notes;
    assert_ne!(s, base);
    assert_eq!(s, pf_run(skew_fixture(), 3, &sw).notes);
}

// ============================================================ Particle Burst

fn pb_run(
    notes: Vec<TNote>,
    tracks: u16,
    set: &[(&'static str, ParamValue)],
) -> plumspirit_engine::transform::TransformRun {
    shear_like_try("particle_burst", notes, tracks, set).unwrap()
}

fn pb_off(s: &[(&'static str, ParamValue)]) -> Vec<(&'static str, ParamValue)> {
    let mut set = s.to_vec();
    for k in ALL11 {
        set.push((k, ParamValue::Bool(false)));
    }
    set
}

