/// Neutral settings (the v0.9 kernel, the v0.8 result): every position
/// emits, no emission duration, no trail, no attraction, no wind, no
/// turbulence — each alone, then together; and Control Sweeps of functions
/// that are off.
fn pb_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        ("n01", vec![on("n01"), list("n01.pattern", &[1])]),
        ("n02", vec![on("n02"), int("n02.duration", 0)]),
        ("n04", vec![on("n04"), int("n04.length", 0)]),
        ("n05", vec![on("n05"), fl("n05.strength", 0.0)]),
        (
            "n06",
            vec![on("n06"), fl("n06.time", 0.0), fl("n06.pitch", 0.0)],
        ),
        ("n11", vec![on("n11"), fl("n11.amount", 0.0)]),
        (
            "sweeps of functions that are off",
            vec![on("m.sweep"), on("m.sweep.restitution"), on("m.sweep.size")],
        ),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

#[test]
fn pb_neutral_new_functions_equal_the_v08_results() {
    for (i, s) in pb_v08_settings().iter().enumerate() {
        for (name, extra) in pb_neutral() {
            let mut set = s.clone();
            set.extend(extra.iter().cloned());
            let r = pb_run(skew_fixture(), 3, &set);
            assert_eq!(join_fingerprint(&r), PB_V08[i], "{name}, setting {i}");
        }
    }
}

/// Eight notes of 240 ticks, a beat apart from bar 3, rising by thirds.
fn pb_art() -> Vec<TNote> {
    pf_notes(
        &(0..8u64)
            .map(|k| (7680 + k * 960, 240, 50 + 3 * k as u8))
            .collect::<Vec<_>>(),
    )
}

/// The fragments of a run (the anchors, 240 ticks long, left out).
fn pb_frags(v: &[TNote]) -> Vec<TNote> {
    v.iter().filter(|n| n.dur != 240).copied().collect()
}

/// Where v0.8 lands a fragment of `n` flying at angle `a` a distance `d`
/// (unit of the box), moved by (dx, dy): its start and row.
fn pb_land(b: (f64, f64, f64, f64), n: &TNote, a: f64, d: f64, dx: f64, dy: f64) -> (i64, i64) {
    let u = (n.start as f64 - b.0) / b.1;
    let v = (f64::from(n.pitch) + 0.5 - b.2) / b.3;
    let x = (u + a.cos() * d + dx).max(-1.0);
    let y = (v + a.sin() * d + dy).clamp(-1.0, 2.0);
    (
        (b.0 + x * b.1).round() as i64,
        (b.2 + y * b.3).floor() as i64,
    )
}

/// The default cone's six angles (60° about 0).
fn pb_angles() -> Vec<f64> {
    let w = std::f64::consts::PI / 3.0;
    (0..6).map(|j| -w / 2.0 + w * f64::from(j) / 5.0).collect()
}

fn pb_places(v: &[TNote]) -> Vec<(i64, i64)> {
    let mut o: Vec<(i64, i64)> = v
        .iter()
        .map(|n| (n.start as i64, i64::from(n.pitch)))
        .collect();
    o.sort_unstable();
    o
}

fn pb_same(got: Vec<(i64, i64)>, mut want: Vec<(i64, i64)>, what: &str) {
    want.sort_unstable();
    assert_eq!(got.len(), want.len(), "{what}: {got:?} vs {want:?}");
    for (g, w) in got.iter().zip(&want) {
        assert!(
            (g.0 - w.0).abs() <= 1 && g.1 == w.1,
            "{what}: {g:?} vs {w:?}"
        );
    }
}

#[test]
fn pb_the_landing_model_and_wind_shapes_and_implosion_place_the_fragments() {
    let art = pb_art();
    let b = pf_box(&art);
    let model = |dx: f64, dy: f64| -> Vec<(i64, i64)> {
        art.iter()
            .flat_map(|n| pb_angles().into_iter().map(move |a| (n, a)))
            .map(|(n, a)| pb_land(b, n, a, 0.12, dx, dy))
            .collect()
    };
    // v0.8 against the model.
    pb_same(
        pb_places(&pb_frags(&pb_run(art.clone(), 1, &[]).notes)),
        model(0.0, 0.0),
        "v0.8",
    );
    // n06: a full flight drifts by the wind (of the box).
    let set = [on("n06"), fl("n06.time", 50.0), fl("n06.pitch", -20.0)];
    pb_same(
        pb_places(&pb_frags(&pb_run(art.clone(), 1, &set).notes)),
        model(0.5, -0.2),
        "wind",
    );
    // n10: a ring of 30 % — six particles at 2πj / 6.
    let set = [on("n10"), ch("n10.shape", 0), fl("n10.size", 30.0)];
    let ring: Vec<(i64, i64)> = art
        .iter()
        .flat_map(|n| {
            (0..6).map(move |j| {
                pb_land(
                    b,
                    n,
                    std::f64::consts::TAU * f64::from(j) / 6.0,
                    0.3,
                    0.0,
                    0.0,
                )
            })
        })
        .collect();
    pb_same(
        pb_places(&pb_frags(&pb_run(art.clone(), 1, &set).notes)),
        ring,
        "ring",
    );
    // Every shape stays deterministic and distinct.
    let shapes: Vec<Vec<(i64, i64)>> = (0..4)
        .map(|sh| {
            let set = [on("n10"), ch("n10.shape", sh)];
            pb_places(&pb_frags(&pb_run(art.clone(), 1, &set).notes))
        })
        .collect();
    for i in 0..4 {
        for j in i + 1..4 {
            assert_ne!(shapes[i], shapes[j], "shapes {i} {j}");
        }
    }
    // n09: the particles converge on the note — every fragment before its
    // emitter (at the start, or ending before it).
    for (arrival, slack) in [(0, 0i64), (1, -60)] {
        let set = [
            on("n09"),
            fl("n09.radius", 20.0),
            ch("n09.arrival", arrival),
        ];
        let out = pb_frags(&pb_run(art.clone(), 1, &set).notes);
        assert_eq!(out.len(), 48);
        let mut starts: Vec<i64> = out.iter().map(|n| n.start as i64).collect();
        starts.sort_unstable();
        let want: Vec<i64> = {
            let mut w: Vec<i64> = art
                .iter()
                .flat_map(|n| pb_angles().into_iter().map(move |a| (n, a)))
                .map(|(n, a)| {
                    let u = (n.start as f64 - b.0) / b.1;
                    let x = (u - a.cos().abs() * 0.2 + slack as f64 / b.1).max(-1.0);
                    (b.0 + x * b.1).round() as i64
                })
                .collect();
            w.sort_unstable();
            w
        };
        for (g, w) in starts.iter().zip(&want) {
            assert!((g - w).abs() <= 1, "arrival {arrival}: {g} vs {w}");
        }
    }
}

#[test]
fn pb_metric_emitters_and_emission_duration_choose_when_particles_fly() {
    // Notes on every beat; the pattern 1 0 0 0 on quarter notes: only the
    // downbeats (bars 3 and 4 start at 7,680 and 11,520) emit.
    let art = pb_art();
    let set = [
        on("n01"),
        ch("n01.grid", 2),
        list("n01.pattern", &[1, 0, 0, 0]),
    ];
    let out = pb_run(art.clone(), 1, &set).notes;
    assert_eq!(out.len(), 8 + 2 * 6);
    let b = pf_box(&art);
    let downbeats: Vec<(i64, i64)> = art
        .iter()
        .filter(|n| n.start % 3840 == 0)
        .flat_map(|n| pb_angles().into_iter().map(move |a| (n, a)))
        .map(|(n, a)| pb_land(b, n, a, 0.12, 0.0, 0.0))
        .collect();
    pb_same(pb_places(&pb_frags(&out)), downbeats, "downbeats");
    let base = pb_frags(&pb_run(art.clone(), 1, &[]).notes);
    // n02: 960 ticks at 4 a beat — five emissions, 240 ticks apart, the
    // first v0.8's.
    let set = [on("n02"), int("n02.duration", 960), fl("n02.rate", 4.0)];
    let out = pb_frags(&pb_run(art.clone(), 1, &set).notes);
    assert_eq!(out.len(), 5 * 48);
    let first: Vec<(i64, i64)> = pb_places(&base);
    let got = pb_places(&out);
    assert!(first.iter().all(|p| got.contains(p)));
    // Emission e is the first one 240·e ticks later (no jitter: the same
    // angles).
    for &(st, row) in &first {
        for e in 1..5i64 {
            assert!(
                got.iter()
                    .any(|p| (p.0 - (st + 240 * e)).abs() <= 1 && p.1 == row),
                "({st}, {row}) emission {e}"
            );
        }
    }
}

#[test]
fn pb_floor_bounce_trails_colours_and_scale_landing() {
    let art = pb_art();
    // Gravity drops every particle below the floor (key 52): none lands
    // under it — they hit it and bounce along it at the restitution.
    let fall = [on("a6"), fl("a6.g", 100.0)];
    let set = [
        on("a6"),
        fl("a6.g", 100.0),
        on("n03"),
        int("n03.floor", 52),
        fl("n03.restitution", 50.0),
        int("n03.bounces", 2),
    ];
    let dropped = pb_frags(&pb_run(art.clone(), 1, &fall).notes);
    assert!(dropped.iter().any(|n| n.pitch < 52));
    let out = pb_frags(&pb_run(art.clone(), 1, &set).notes);
    let from_above = art.iter().filter(|n| n.pitch >= 52).count();
    assert!(out.iter().filter(|n| n.pitch < 52).count() <= 6 * (art.len() - from_above));
    let on_floor: Vec<&TNote> = out.iter().filter(|n| n.pitch == 52).collect();
    assert!(on_floor.iter().any(|n| n.vel == 32) && on_floor.iter().any(|n| n.vel == 16));
    // n04: four trail notes of 60 ticks behind each particle.
    let set = [on("n04"), int("n04.length", 240), int("n04.density", 4)];
    let out = pb_run(art.clone(), 1, &set).notes;
    assert_eq!(out.len(), 8 + 48 * 5);
    assert!(out.iter().filter(|n| n.dur == 60 && n.vel < 64).count() >= 48 * 3);
    // n07: by direction through four positions — the cone about 0 lies in
    // the first and the last band; by age (every flight complete) the last.
    let set = [
        on("n07"),
        ch("n07.by", 2),
        list("n07.palette", &[0, 1, 2, 3]),
    ];
    let subs: std::collections::BTreeSet<u32> = pb_frags(&pb_run(art.clone(), 1, &set).notes)
        .iter()
        .map(|n| n.sub)
        .collect();
    assert_eq!(subs, [0, 3].into_iter().collect());
    let set = [on("n07"), ch("n07.by", 0)];
    assert!(
        pb_frags(&pb_run(art.clone(), 1, &set).notes)
            .iter()
            .all(|n| n.sub == 3)
    );
    // n08: every fragment on C major.
    let set = [
        on("n08"),
        ch("n08.key", 0),
        ch("n08.scale", 0),
        fl("dist", 30.0),
    ];
    let out = pb_frags(&pb_run(art.clone(), 1, &set).notes);
    assert!(
        out.iter()
            .all(|n| [0, 2, 4, 5, 7, 9, 11].contains(&(n.pitch % 12)))
    );
}

