/// Neutral settings (the v0.9 kernel, the v0.8 result): no turns or drift,
/// no streak, no symmetry, a fade that keeps the field, thinning far above
/// any cell's count, a contour field and obstacles without references —
/// each alone, then together; and Control Sweeps of functions that are off.
fn fld_neutral() -> Vec<(&'static str, Vec<(&'static str, ParamValue)>)> {
    let each = vec![
        (
            "n02",
            vec![on("n02"), fl("n02.turns", 0.0), fl("n02.drift", 0.0)],
        ),
        ("n06", vec![on("n06"), fl("n06.streak", 0.0)]),
        ("n07", vec![on("n07"), ch("n07.symmetry", 0)]),
        (
            "n09",
            vec![on("n09"), curve("n09.fade", Curve::line(1.0, 1.0))],
        ),
        ("n11", vec![on("n11"), int("n11.most", 1000)]),
        ("n01", vec![on("n01")]),
        ("n05", vec![on("n05")]),
        (
            "sweeps of functions that are off",
            vec![
                on("m.sweep"),
                on("m.sweep.layers"),
                on("m.sweep.path_width"),
            ],
        ),
    ];
    let all: Vec<(&'static str, ParamValue)> = each.iter().flat_map(|e| e.1.clone()).collect();
    let mut v = each;
    v.push(("all", all));
    v
}

